/* Tests, Cluster, Gebiete (Fe). Quelle bleibt Doku-Fix (Befund), hier nur Kopie.
   Automatisch aus Doku-Fix v268 gezogen am 25.11.2026 (werkzeug/daten-holen.py). */
window.PK_TESTS={"tests":{"bbs":{"name":"Berg Balance Scale","was":"Gleichgewicht im Sitzen und Stehen","einheit":"Punkte von 56","kurz":"14 Aufgaben im Sitzen und Stehen, zum Beispiel Aufstehen, Stehen mit geschlossenen Augen, Gegenstand aufheben und Einbeinstand. Jede Aufgabe wird von 0 bis 4 bewertet.","ziel":"Gleichgewicht und Sturzrisiko einschätzen und im Verlauf vergleichen.","norm":["Höchstwert 56. Ältere Erwachsene: Grenzwerte für erhöhtes Sturzrisiko je nach Studie 45 bis 51; allein kein sicherer Sturzprädiktor (Lima 2018).","Gesunde Ältere, Mittelwert: 60–69 J. 55; 70–79 J. 53–54; 80–89 J. 50–53 (Steffen 2002).","Parkinson: 47 trennt Stürzer von Nicht-Stürzern (Leddy 2011). Chronischer Schlaganfall: 49 für mehrfache Stürze, LR+ 2,8 (Beninato 2009).","Echte Veränderung beim Einzelnen ab etwa 5 bis 7 Punkten, bedeutsame Verbesserung ab 7 Punkten (Godi 2013)."],"normQuelle":"Q109","durch":"14 Aufgaben im Sitzen und Stehen, jede mit 0 bis 4 bewertet, Summe 0 bis 56. Material: Stoppuhr, Stuhl mit und ohne Armlehnen, Stufe oder Hocker, Lineal, Schuh. Dauer 15 bis 20 Minuten. Die Aufgaben im Einzelnen und die Bewertung stehen im Originalbogen, die Datenbankseite beschreibt sie nicht.","pos":"Auffällig, wenn der Wert unter dem alters- oder diagnosebezogenen Grenzwert liegt (Ältere je nach Studie 45 bis 51, Parkinson 47).","mess":{"reliab":"Intrarater ICC 0,98, Interrater ICC 0,97 (Metaanalyse, 11 Studien, Downs 2013); chronischer Schlaganfall Test-Retest ICC 0,99 (Alghadir 2018)","mdc":"MDC95 2,8 bis 6,6 Punkte je nach Ausgangswert (Downs 2013); Schlaganfall stationär 6 Punkte (MDC90, Stevenson 2001); chronischer Schlaganfall 2,7 (Alghadir 2018); Parkinson 5 (Steffen 2008)","mcid":"7 Punkte bei Gleichgewichtsstörungen (Godi 2013)","grenzwert":"Ältere: Grenzwerte 45 bis 51 je nach Studie, als alleiniger Sturzprädiktor unzureichend (systematische Übersicht, Lima 2018). Parkinson: 47 für Stürzer (Leddy 2011). Chronischer Schlaganfall: 49 für mehrfache Stürze, LR+ 2,8 (Beninato 2009)."},"evidenz":"stark","quellen":["Downs S et al. 2013, The Berg Balance Scale has high intra- and inter-rater reliability but absolute reliability varies across the scale: a systematic review. J Physiother – https://pubmed.ncbi.nlm.nih.gov/23663794/","Berg KO et al. 1992, Measuring balance in the elderly: validation of an instrument. Can J Public Health – https://pubmed.ncbi.nlm.nih.gov/1468055/","Lima CA et al. 2018, The Berg Balance Scale as a clinical screening tool to predict fall risk in older adults: a systematic review. Physiotherapy – https://pubmed.ncbi.nlm.nih.gov/29945726/","Leddy AL et al. 2011, Functional gait assessment and balance evaluation system test in Parkinson disease. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/21071506/","Beninato M et al. 2009, Falls and clinical assessment tools in people with stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19520733/","Godi M et al. 2013, Comparison of reliability, validity, and responsiveness of the Mini-BESTest and Berg Balance Scale. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/23023812/","Stevenson TJ 2001, Detecting change in patients with stroke using the Berg Balance Scale. Aust J Physiother – https://pubmed.ncbi.nlm.nih.gov/11552860/","Alghadir AH et al. 2018, Reliability, validity, and responsiveness of three scales for measuring balance in chronic stroke. BMC Neurol – https://pubmed.ncbi.nlm.nih.gov/30213258/","Steffen T, Seney M 2008, Test-retest reliability and minimal detectable change in people with parkinsonism. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18356292/","Steffen TM et al. 2002, Age- and gender-related test performance in community-dwelling elderly people. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/11856064/"]},"fga":{"name":"Functional Gait Assessment","was":"Gleichgewicht beim Gehen","einheit":"Punkte von 30","kurz":"Zehn Gehaufgaben, zum Beispiel enger Gang, rückwärts gehen, Gehen mit geschlossenen Augen und Hindernis. Weiterentwicklung des Dynamic Gait Index.","ziel":"Dynamisches Gleichgewicht beim Gehen erfassen, auch bei geringeren Einschränkungen.","norm":["Höchstwert 30, höher = besser. Gesunde Erwachsene, Mittelwert: 40–49 J. 28,9; 50–59 J. 28,4; 60–69 J. 27,1; 70–79 J. 24,9; 80–89 J. 20,8 (Walker 2007).","Sturzrisiko: ≤ 22 bei älteren Erwachsenen, Sens 100 %, Spez 72 % (Wrisley 2010). Parkinson: ≤ 15 für Stürzer (Leddy 2011)."],"normQuelle":"Q110","durch":"Zehn Gehaufgaben, jede mit 0 bis 3 bewertet (3 = normales Gehen). Markierte Strecke 6 m lang und 30 cm breit, Hindernis 23 cm hoch (zwei gestapelte Schuhkartons), Treppe mit beidseitigem Handlauf, Stoppuhr. Hilfsmittel erlaubt, keine körperliche Hilfe durch eine Person. Der Untersucher geht mindestens einen halben Schritt hinter dem Patienten. Dauer 5 bis 20 Minuten.","pos":"Auffällig, wenn der Wert bei Älteren 22 oder weniger, bei Parkinson 15 oder weniger beträgt.","mess":{"reliab":"Interrater ICC 0,93 bei Gesunden (Walker 2007); vestibuläre Störungen Interrater 0,86, Intrarater 0,74 (Wrisley 2004); Parkinson Test-Retest 0,91, Interrater über 0,93 (Leddy 2011)","grenzwert":"Ältere: ≤ 22 sagt Stürze vorher, Sens 100 %, Spez 72 %, LR+ 3,6, LR– 0 (Wrisley 2010, n = 35). Parkinson: 15 für Stürzer (Leddy 2011)."},"evidenz":"mäßig","quellen":["Walker ML et al. 2007, Reference group data for the functional gait assessment. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17785375/","Wrisley DM, Kumar NA 2010, Functional gait assessment: concurrent, discriminative, and predictive validity in community-dwelling older adults. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/20360052/","Wrisley DM et al. 2004, Reliability, internal consistency, and validity of data obtained with the functional gait assessment. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/15449976/","Leddy AL et al. 2011, Functional gait assessment and balance evaluation system test: reliability, validity, sensitivity, and specificity in Parkinson disease. Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC3017321/"]},"abc":{"name":"Activities-specific Balance Confidence Scale (ABC)","was":"Vertrauen in das eigene Gleichgewicht","einheit":"Prozent","kurz":"Fragebogen: Der Patient schätzt in Prozent ein, wie sicher er bei alltäglichen Tätigkeiten ist, ohne das Gleichgewicht zu verlieren.","ziel":"Vertrauen ins eigene Gleichgewicht und Sturzangst erkennen.","norm":["0 bis 100 %, höher = mehr Sicherheit. Unter 67 %: Sturzrisiko bei älteren Erwachsenen (Lajoie 2004).","Parkinson: unter 69 % erhöhtes Risiko wiederholter Stürze im Folgejahr (Mak 2009); über 80 % geringeres Sturzrisiko (Mak & Pang 2009).","Chronischer Schlaganfall: ab etwa 81 spricht gegen mehrfache Stürze, LR+ 3,6 (Beninato 2009).","Echte Veränderung bei Parkinson ab 13 Prozentpunkten (Steffen 2008)."],"normQuelle":"Q111","durch":"16 Alltagssituationen. Jede beginnt mit der Frage, wie sicher der Patient ist, nicht das Gleichgewicht zu verlieren oder unsicher zu werden. Antwort von 0 bis 100 %. Gesamtwert = Summe geteilt durch 16. Interview wird empfohlen, Dauer 5 bis 10 Minuten. Manche Patienten antworten nach ihrer üblichen Aktivität statt nach ihrer Sicherheit, dann auf die Frage zurückführen.","pos":"Auffällig, wenn der Wert bei Parkinson unter 69 % oder bei chronischem Schlaganfall unter etwa 81 % liegt.","mess":{"reliab":"Chronischer Schlaganfall Test-Retest ICC 0,85, Cronbach α 0,94 (Botner 2005)","mdc":"Parkinson 13 Prozentpunkte (MDC95, Steffen 2008)","grenzwert":"Parkinson: < 69 erhöhtes Risiko wiederholter Stürze im Folgejahr, Sens 93 % (Mak 2009). Chronischer Schlaganfall: 81,1 für mehrfache Stürze, LR+ 3,6, LR– 0 (Beninato 2009, n = 27)."},"evidenz":"mäßig","quellen":["Powell LE, Myers AM 1995, The Activities-specific Balance Confidence (ABC) Scale. J Gerontol A Biol Sci Med Sci – https://pubmed.ncbi.nlm.nih.gov/7814786/","Mak MK, Pang MY 2009, Fear of falling is independently associated with recurrent falls in Parkinson's disease: a 1-year prospective study. J Neurol – https://pubmed.ncbi.nlm.nih.gov/19479166/","Mak MK, Pang MY 2009, Balance confidence and functional mobility are independently associated with falls in Parkinson's disease. J Neurol – https://pubmed.ncbi.nlm.nih.gov/19240961/","Beninato M et al. 2009, Falls and clinical assessment tools in people with stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19520733/","Botner EM et al. 2005, Measurement properties of the ABC Scale among individuals with stroke. Disabil Rehabil – https://pubmed.ncbi.nlm.nih.gov/15824045/","Lajoie Y, Gallagher SP 2004, Predicting falls within the elderly community. Arch Gerontol Geriatr – https://pubmed.ncbi.nlm.nih.gov/14599700/","Steffen T, Seney M 2008, Test-retest reliability and minimal detectable change in people with parkinsonism. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18356292/"]},"t10":{"name":"10-Meter-Gehtest","was":"Gehgeschwindigkeit","einheit":"m/s","kurz":"Der Patient geht eine Strecke von zehn Metern, in angenehmem oder schnellem Tempo. Gemessen wird die Zeit, daraus ergibt sich die Gehgeschwindigkeit.","ziel":"Gehgeschwindigkeit als einfachen, aussagekräftigen Wert dokumentieren.","norm":["Gesunde Erwachsene, angenehmes Tempo, Mittelwert (Bohannon & Andrews 2011, Metaanalyse 23 111 Personen): Männer 20–59 J. 1,36–1,43 m/s; 60–69 J. 1,34; 70–79 J. 1,26; 80+ J. 0,97.","Frauen: 20–59 J. 1,31–1,39; 60–69 J. 1,24; 70–79 J. 1,13; 80+ J. 0,94. Aktualisierung mit 51 248 Personen bestätigt die Spanne von 0,97 bis 1,40 m/s (Andrews 2023).","Schlaganfall: < 0,4 m/s Haushaltsgeher; 0,4–0,8 eingeschränkter Gemeindegeher; > 0,8 Gemeindegeher (Perry 1995, Bowden 2008). Nach gemessener Alltagsaktivität eher 0,49 und 0,93 m/s (Fulk 2017).","Bedeutsame Verbesserung: ab 0,10 m/s bei Älteren (Perera 2006), ab 0,16 m/s im subakuten Schlaganfall (Tilson 2010)."],"normQuelle":"Q112","durch":"Gehstrecke 10 m (die Seite nennt 6 bis 12 m). Vor der Messstrecke gibt es einen Anlauf, der nicht mitgezählt wird. Zwei Durchgänge im angenehmen Tempo, zwei im schnellen, je Tempo wird gemittelt. Geschwindigkeit = Strecke geteilt durch Zeit. Hilfsmittel erlaubt, bei jeder Messung gleich dokumentieren. Der Untersucher geht mindestens einen halben Schritt hinter dem Patienten. Dauer bis 5 Minuten.","mess":{"reliab":"Chronischer Schlaganfall ICC 0,94 bis 0,99 (Flansbjer 2005); gesunde Ältere ICC 0,95 bis 0,97 (Steffen 2002)","mdc":"Parkinson 0,18 m/s angenehm, 0,25 m/s schnell (MDC95, Steffen 2008); chronischer Schlaganfall 0,2 m/s angenehm, 0,1 m/s schnell (MDC95, Hiengkaew 2012)","mcid":"Ältere und subakuter Schlaganfall: kleine Veränderung etwa 0,05 m/s, deutliche etwa 0,10 m/s (Perera 2006); subakuter Schlaganfall 0,16 m/s (Tilson 2010)","grenzwert":"Schlaganfall: < 0,4 m/s Haushaltsgeher, 0,4 bis 0,8 eingeschränkter, > 0,8 m/s uneingeschränkter Gemeindegeher (Perry 1995, bestätigt Bowden 2008); nach Schrittzählern eher 0,49 und 0,93 m/s (Fulk 2017)"},"evidenz":"stark","quellen":["Bohannon RW, Williams Andrews A 2011, Normal walking speed: a descriptive meta-analysis. Physiotherapy – https://pubmed.ncbi.nlm.nih.gov/21820535/","Andrews AW et al. 2023, Normal gait speed varies by age and sex but not by geographical region: a systematic review. J Physiother – https://pubmed.ncbi.nlm.nih.gov/36528509/","Perera S et al. 2006, Meaningful change and responsiveness in common physical performance measures in older adults. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/16696738/","Tilson JK et al. 2010, Meaningful gait speed improvement during the first 60 days poststroke: minimal clinically important difference. Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC2816032/","Flansbjer UB et al. 2005, Reliability of gait performance tests in men and women with hemiparesis after stroke. J Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/15788341/","Perry J et al. 1995, Classification of walking handicap in the stroke population. Stroke – https://pubmed.ncbi.nlm.nih.gov/7762050/","Bowden MG et al. 2008, Validation of a speed-based classification system poststroke. Neurorehabil Neural Repair – https://pmc.ncbi.nlm.nih.gov/articles/PMC2587153/","Fulk GD et al. 2017, Predicting Home and Community Walking Activity Poststroke. Stroke – https://pubmed.ncbi.nlm.nih.gov/28057807/","Hiengkaew V et al. 2012, Minimal detectable changes of BBS, FMA, TUG, gait speeds and 2-minute walk test in chronic stroke. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/22502805/","Steffen T, Seney M 2008, Test-retest reliability and minimal detectable change in people with parkinsonism. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18356292/"]},"t6":{"name":"6-Minuten-Gehtest","was":"Gehstrecke, Ausdauer","einheit":"Meter","kurz":"Der Patient geht sechs Minuten in eigenem Tempo so weit wie möglich. Gemessen wird die Strecke.","ziel":"Gehausdauer erfassen. Der Test kommt zuletzt, weil er anstrengt.","norm":["Mehr Strecke = besser. Gesunde Erwachsene, Mittelwert (McKay 2017): 20–59 J. Männer 736 m, Frauen 674 m; ab 60 J. Männer 599 m, Frauen 550 m.","Gemeindewohnende Ältere (Steffen 2002), Männer / Frauen: 60–69 J. 572 / 538 m; 70–79 J. 527 / 471 m; 80–89 J. 417 / 392 m.","Chronischer Schlaganfall: unter 331,65 m erhöhtes Sturzrisiko (Regan 2020).","Echte Veränderung nach Schlaganfall ab etwa 54 m (Fulk 2008); deutliche Verbesserung ab etwa 50 m (Perera 2006)."],"normQuelle":"Q113","durch":"So weit wie möglich in 6 Minuten gehen, im eigenen Tempo, auf standardisierter Strecke mit standardisierter Anweisung (ATS: 30 m mit Markierung alle 3 m, Wendepunkte mit Hütchen). Stehpausen sind erlaubt, die Uhr läuft weiter, Anzahl und Dauer der Pausen notieren. Hilfsmittel erlaubt und dokumentieren. Nur die vorgegebenen zeitgebundenen Rückmeldungen geben. Der Untersucher geht mindestens einen halben Schritt hinter dem Patienten. Wer nicht gehen kann, aber wieder gehen soll, erhält 0.","mess":{"reliab":"Subakuter Schlaganfall ICC 0,973 (Fulk 2008); chronischer Schlaganfall ICC 0,94 bis 0,99 (Flansbjer 2005); gesunde Ältere ICC 0,95 bis 0,97 (Steffen 2002)","mdc":"Schlaganfall 54,1 m (MDC90, Fulk 2008); Parkinson 82 m (MDC95, Steffen 2008)","mcid":"Ältere und subakuter Schlaganfall: kleine Veränderung etwa 20 m, deutliche etwa 50 m (Perera 2006)","grenzwert":"Chronischer Schlaganfall: unter 331,65 m erhöhtes Sturzrisiko, AUC 0,70 (Regan 2020)"},"evidenz":"stark","quellen":["Fulk GD et al. 2008, Clinometric properties of the six-minute walk test in individuals undergoing rehabilitation poststroke. Physiother Theory Pract – https://pubmed.ncbi.nlm.nih.gov/18569856/","Perera S et al. 2006, Meaningful change and responsiveness in common physical performance measures in older adults. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/16696738/","Regan E et al. 2020, The six-minute walk test as a fall risk screening tool in community programs for persons with stroke. Top Stroke Rehabil – https://pmc.ncbi.nlm.nih.gov/articles/PMC7108500/","McKay MJ et al. 2017, Reference values for developing responsive functional outcome measures across the lifespan. Neurology – https://pubmed.ncbi.nlm.nih.gov/28330961/","Steffen TM et al. 2002, Age- and gender-related test performance in community-dwelling elderly people. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/11856064/","Flansbjer UB et al. 2005, Reliability of gait performance tests in men and women with hemiparesis after stroke. J Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/15788341/","Steffen T, Seney M 2008, Test-retest reliability and minimal detectable change in people with parkinsonism. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18356292/"]},"sts5":{"name":"5-mal Aufstehen vom Stuhl (5xSTS)","was":"Transfer Sitz zu Stand","einheit":"Sekunden","kurz":"Der Patient steht so schnell wie möglich fünfmal von einem Stuhl auf, ohne die Arme zu benutzen. Gemessen wird die Zeit.","ziel":"Beinkraft und den Transfer vom Sitzen zum Stand einschätzen.","norm":["Weniger Zeit = besser. Gesunde Erwachsene, Mittelwert (Bohannon 2007): 19–49 J. 6,2 s; 50–59 J. 7,1; 60–69 J. 8,1; 70–79 J. 10,0; 80–89 J. 10,6.","Ältere, Obergrenze für durchschnittliche Leistung (Bohannon 2006, Metaanalyse): 60–69 J. 11,4 s; 70–79 J. 12,6 s; 80–89 J. 14,8 s. Langsamer gilt als unterdurchschnittlich.","Über 15 s: wiederholte Stürze ab 65 J. wahrscheinlicher (Buatois 2008). Parkinson: über 16 s (Duncan 2011). Chronischer Schlaganfall: über 12 s (Mong 2010).","Verbesserung um mehr als 2,3 s gilt als spürbar (vestibuläre Störungen, Meretta 2006)."],"normQuelle":"Q114","durch":"Freistehender Standardstuhl mit Armlehnen und Rückenlehne, Sitzhöhe 43 bis 45 cm, nicht an die Wand gestellt, bei Wiederholungen derselbe Stuhl. Arme vor der Brust verschränkt (nach Schlaganfall darf der betroffene Arm seitlich liegen). Start mit „Go“, fünfmal vollständig aufstehen und wieder hinsetzen. Die Zeit endet, wenn das Gesäß nach der fünften Wiederholung den Stuhl berührt. Vorher ein Übungsversuch.","pos":"Auffällig, wenn die Zeit über dem Altersgrenzwert liegt (zum Beispiel über 12,6 s mit 70 bis 79 Jahren) oder bei Parkinson über 16 s.","mess":{"reliab":"Chronischer Schlaganfall Intra-, Inter- und Test-Retest ICC 0,97 bis 0,999 (Mong 2010); Parkinson Interrater 0,99, Test-Retest 0,76 (Duncan 2011)","mcid":"Vestibuläre Störungen: Verbesserung über 2,3 s geht mit spürbarer Besserung einher, OR 4,67 (Meretta 2006)","grenzwert":"Parkinson 16,0 s für Stürzer, Sens 75 %, Spez 68 % (Duncan 2011); chronischer Schlaganfall 12 s trennt von gesunden Älteren, Sens 83 %, Spez 75 % (Mong 2010)"},"evidenz":"mäßig","quellen":["Bohannon RW 2006, Reference values for the five-repetition sit-to-stand test: a descriptive meta-analysis of data from elders. Percept Mot Skills – https://pubmed.ncbi.nlm.nih.gov/17037663/","Duncan RP et al. 2011, Five times sit-to-stand test performance in Parkinson's disease. Arch Phys Med Rehabil – https://pmc.ncbi.nlm.nih.gov/articles/PMC3250986/","Mong Y et al. 2010, 5-repetition sit-to-stand test in subjects with chronic stroke: reliability and validity. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/20298832/","Meretta BM et al. 2006, The five times sit to stand test: responsiveness to change and concurrent validity in adults undergoing vestibular rehabilitation. J Vestib Res – https://pubmed.ncbi.nlm.nih.gov/17538213/","Buatois S et al. 2008, Five times sit to stand test is a predictor of recurrent falls in healthy community-living subjects aged 65 and older. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/18808608/"]},"tug":{"name":"Timed Up and Go","was":"Mobilität, Sturzrisiko","einheit":"Sekunden","kurz":"Der Patient steht von einem Stuhl auf, geht drei Meter, dreht um, geht zurück und setzt sich. Gemessen wird die Zeit.","ziel":"Alltagsmobilität und Sturzrisiko einschätzen.","norm":["Weniger Zeit = besser. Gemeindewohnende Ältere, Mittelwert (Steffen 2002): 60–69 J. 8 s; 70–79 J. 9 s; 80–89 J. Männer 10 s, Frauen 11 s.","Ältere: ab 13,5 s erhöhtes Sturzrisiko; der Test bestätigt eher, als dass er ausschließt (Sens 31 %, Spez 74 %; Barry 2014). Nicht allein zur Sturzeinschätzung nutzen.","Parkinson: über 11,5 s (Nocera 2013) bzw. ab 16 s (Mak & Pang 2009).","Echte Veränderung ab etwa 3 bis 3,5 s (Schlaganfall, Parkinson)."],"normQuelle":"Q115","durch":"Patient sitzt mit dem Rücken an der Lehne (Stuhl mit Armlehnen, Sitzhöhe 44 bis 47 cm, frei stehend). Auf „Go“ aufstehen, 3 m in bequemem und sicherem Tempo gehen, umdrehen, zurückgehen und hinsetzen. Die Zeit läuft vom Kommando bis zum Sitzen. Ein Übungsdurchgang, bei jeder Messung dieselbe Gehhilfe.","pos":"Auffällig, wenn die Zeit über dem diagnosebezogenen Grenzwert liegt (Ältere 13,5 s, Parkinson 11,5 s).","mess":{"reliab":"Gesunde Ältere ICC 0,95 bis 0,97 (Steffen 2002); chronischer Schlaganfall ICC 0,98 (Alghadir 2018); Parkinson ICC 0,80 (Huang 2011)","mdc":"Parkinson 3,5 s (Huang 2011); chronischer Schlaganfall 3,2 s (Alghadir 2018)","grenzwert":"Ältere ≥ 13,5 s: gepoolt Sens 31 %, Spez 74 % (Metaanalyse, 10 Studien, Barry 2014); Parkinson 11,5 s (Nocera 2013, n = 2097), ≥ 16 s OR 3,86 (Mak & Pang 2009)"},"evidenz":"stark","quellen":["Podsiadlo D, Richardson S 1991, The timed Up & Go: a test of basic functional mobility for frail elderly persons. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/1991946/","Barry E et al. 2014, Is the Timed Up and Go test a useful predictor of risk of falls in community dwelling older adults: a systematic review and meta-analysis. BMC Geriatr – https://pmc.ncbi.nlm.nih.gov/articles/PMC3924230/","Shumway-Cook A et al. 2000, Predicting the probability for falls in community-dwelling older adults using the Timed Up & Go Test. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/10960937/","Nocera JR et al. 2013, Using the Timed Up & Go test in a clinical setting to predict falling in Parkinson's disease. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/23473700/","Mak MK, Pang MY 2009, Balance confidence and functional mobility are independently associated with falls in Parkinson's disease. J Neurol – https://pubmed.ncbi.nlm.nih.gov/19240961/","Huang SL et al. 2011, Minimal detectable change of the TUG and the dynamic gait index in people with Parkinson disease. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/20947672/","Alghadir AH et al. 2018, Reliability, validity, and responsiveness of three scales for measuring balance in chronic stroke. BMC Neurol – https://pubmed.ncbi.nlm.nih.gov/30213258/","Steffen TM et al. 2002, Age- and gender-related test performance in community-dwelling elderly people. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/11856064/"]},"dgi":{"name":"Dynamic Gait Index","was":"Gehen bei wechselnden Anforderungen","einheit":"Punkte von 24","kurz":"Gehen bei acht wechselnden Anforderungen, zum Beispiel Tempowechsel, Kopfdrehen, Hindernis und Treppe.","ziel":"Gehsicherheit bei alltagsnahen Anforderungen und Sturzrisiko einschätzen.","norm":["Höchstwert 24, höher = besser. Gesunde bis etwa 60 J. meist am Höchstwert, ab 70 J. deutlicher Abfall (Vereeck 2008). Mittelwert nach Dekade: Dekade 3 und 4: 24,0; 5 und 6: 23,9; 7: 23,2; 8: 22,0.","19 oder weniger: Stürze wahrscheinlicher (vestibuläre Störungen, Whitney 2000). Schlaganfall: Median 13 (Lin 2010).","Echte Veränderung ab etwa 2 bis 3 Punkten (Schlaganfall, Parkinson)."],"normQuelle":"Q116","durch":"Acht Gehaufgaben auf markierter Strecke von 6,1 m (20 Fuß), jede mit 0 bis 3 bewertet (3 = keine Gangstörung): Gehen, Tempowechsel, Kopfdrehungen waagerecht und senkrecht, Hindernis übersteigen und umgehen, Drehen, Treppe. Material: Schuhkarton, zwei gleich große Hindernisse, Treppe. Dauer 10 bis 15 Minuten.","pos":"Auffällig, wenn der Wert 19 oder weniger beträgt.","mess":{"reliab":"Chronischer Schlaganfall Test-Retest und Interrater ICC 0,96 (Jonsdottir 2007), Test-Retest 0,98 (Alghadir 2018); Parkinson 0,84 (Huang 2011)","mdc":"Parkinson 2,9 Punkte (Huang 2011); chronischer Schlaganfall 1,9 (Alghadir 2018)","grenzwert":"≤ 19: 2,58-fach höhere Chance für Stürze in den letzten 6 Monaten, vestibuläre Störungen (Whitney 2000, n = 247)"},"evidenz":"stark","quellen":["Whitney SL et al. 2000, The dynamic gait index relates to self-reported fall history in individuals with vestibular dysfunction. J Vestib Res – https://pubmed.ncbi.nlm.nih.gov/10939685/","Jonsdottir J, Cattaneo D 2007, Reliability and validity of the dynamic gait index in persons with chronic stroke. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/17964880/","Huang SL et al. 2011, Minimal detectable change of the TUG and the dynamic gait index in people with Parkinson disease. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/20947672/","Alghadir AH et al. 2018, Reliability, validity, and responsiveness of three scales for measuring balance in chronic stroke. BMC Neurol – https://pubmed.ncbi.nlm.nih.gov/30213258/","Vereeck L et al. 2008, Clinical assessment of balance: normative data, and gender and age effects. Int J Audiol – https://pubmed.ncbi.nlm.nih.gov/18236239/","Lin JH et al. 2010, Psychometric comparisons of 3 functional ambulation measures for patients with stroke. Stroke – https://pubmed.ncbi.nlm.nih.gov/20671244/"]},"fmal":{"name":"Fugl-Meyer-Assessment, untere Extremität","was":"Motorische Funktion Bein","einheit":"Punkte von 34","kurz":"Standardisierte Prüfung der motorischen Funktion des Beins: Reflexe, Bewegungsmuster, Koordination und Geschwindigkeit.","ziel":"Motorische Funktion und Erholung des Beins nach Schlaganfall beschreiben.","norm":["Höchstwert 34 (untere Extremität), je Item 0 bis 2. Normwerte und Schweregradgrenzen sind nicht festgelegt.","Echte Veränderung ab 4 Punkten (Hiengkaew 2012), klinisch bedeutsam ab 6 Punkten (chronischer Schlaganfall, Pandian 2016)."],"normQuelle":"Q118","durch":"Beobachtung der Bewegungen nach Protokoll. Je Item 0 = kann nicht ausführen, 1 = führt teilweise aus, 2 = führt vollständig aus. Obere und untere Extremität können getrennt geprüft werden. Material: Tennisball, kleiner runder Behälter, Reflexhammer. Etwa 30 Minuten, Kurzversionen unter 10 Minuten. Das Handbuch vorher lesen, die Einzelaufgaben stehen dort.","mess":{"reliab":"Interrater ICC 0,96 gesamt (Sanford 1993)","mdc":"4 Punkte (MDC95, chronischer Schlaganfall, Hiengkaew 2012)","mcid":"6 Punkte, chronischer Schlaganfall, Sens 87 bis 90 %, Spez 91 bis 94 % (Pandian 2016)"},"evidenz":"mäßig","quellen":["Sanford J et al. 1993, Reliability of the Fugl-Meyer assessment for testing motor performance in patients following stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/8316578/","Hiengkaew V et al. 2012, Minimal detectable changes of BBS, FMA, TUG, gait speeds and 2-minute walk test in chronic stroke. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/22502805/","Pandian S et al. 2016, Minimal clinically important difference of the lower-extremity Fugl-Meyer assessment in chronic stroke. Top Stroke Rehabil – https://pubmed.ncbi.nlm.nih.gov/27086865/","Gladstone DJ et al. 2002, The Fugl-Meyer assessment of motor recovery after stroke: a critical review of its measurement properties. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/12234086/"]},"fmao":{"name":"Fugl-Meyer-Assessment, obere Extremität","was":"Motorische Funktion Arm","einheit":"Punkte von 66","kurz":"Standardisierte Prüfung der motorischen Funktion von Arm und Hand: Reflexe, Bewegungsmuster, Koordination und Geschwindigkeit.","ziel":"Motorische Funktion und Erholung von Arm und Hand nach Schlaganfall beschreiben.","norm":["Höchstwert 66 (obere Extremität), je Item 0 bis 2. Normwerte und Schweregradgrenzen sind nicht festgelegt.","Klinisch bedeutsame Veränderung: chronischer Schlaganfall 4,25 bis 7,25 Punkte (Page 2012); subakut 9 bis 10 Punkte (Arya 2011). Echte Veränderung ab etwa 3 Punkten (See 2013)."],"normQuelle":"Q118","durch":"Beobachtung der Bewegungen nach Protokoll. Je Item 0 = kann nicht ausführen, 1 = führt teilweise aus, 2 = führt vollständig aus. Obere und untere Extremität können getrennt geprüft werden. Material: Tennisball, kleiner runder Behälter, Reflexhammer. Etwa 30 Minuten, Kurzversionen unter 10 Minuten. Das Handbuch vorher lesen, die Einzelaufgaben stehen dort.","mess":{"reliab":"Interrater ICC 0,97 obere Extremität (Sanford 1993); Inter- und Intrarater 0,98 bis 0,99 mit standardisiertem Vorgehen (See 2013)","mdc":"3,2 Punkte (See 2013)","mcid":"Chronisch, leicht bis mäßig betroffen: 4,25 bis 7,25 Punkte (Page 2012); subakut: 9 bis 10 Punkte (Arya 2011)"},"evidenz":"stark","quellen":["Page SJ et al. 2012, Clinically important differences for the upper-extremity Fugl-Meyer Scale in people with minimal to moderate impairment due to chronic stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/22282773/","Arya KN et al. 2011, Estimating the minimal clinically important difference of an upper extremity recovery measure in subacute stroke patients. Top Stroke Rehabil – https://pubmed.ncbi.nlm.nih.gov/22120029/","See J et al. 2013, A standardized approach to the Fugl-Meyer assessment and its implications for clinical trials. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/23774125/","Sanford J et al. 1993, Reliability of the Fugl-Meyer assessment for testing motor performance in patients following stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/8316578/"]},"fr":{"name":"Functional Reach Test","was":"Gleichgewicht, Reichweite im Stand","einheit":"cm","kurz":"Der Patient streckt im Stand den Arm nach vorn, ohne einen Schritt zu machen. Gemessen wird, wie weit er reicht.","ziel":"Stabilitätsgrenzen im Stand abschätzen. Der Test ist schnell durchführbar.","norm":["Größere Reichweite = besser. Alter und Körpergröße beeinflussen den Wert (Duncan 1990).","Ältere Männer: Reichweite bis 15 cm vierfaches, 15 bis 25 cm doppeltes Risiko für wiederholte Stürze; nicht reichen können etwa achtfaches Risiko (Duncan 1992).","Parkinson: unter 31,75 cm (Dibble & Lange 2006); Mittelwert 33,5 cm (Lim 2005). Subakuter Schlaganfall: Mittelwert 25,6 cm (Outermans 2010)."],"normQuelle":"Q117","durch":"Der Patient steht seitlich nah an der Wand, ohne sie zu berühren. Der wandnahe Arm ist 90° angehoben, die Hand zur Faust geschlossen. Startwert am Köpfchen des 3. Mittelhandknochens am Maßstab ablesen. Dann so weit wie möglich nach vorn reichen, ohne einen Schritt zu machen. Die Differenz ist die Reichweite. Zwei Übungsdurchgänge, drei Testdurchgänge, gemittelt. Die abgewandelte Version (MFRT) wird im Sitzen nach vorn, rechts und links gemessen.","pos":"Auffällig, wenn die Reichweite bei älteren Erwachsenen 25 cm (10 Zoll) oder weniger beträgt.","mess":{"reliab":"ICC 0,81 über Tage (Duncan 1990); Parkinson im häuslichen Umfeld ICC 0,64 bis 0,88 (Lim 2005)","grenzwert":"Ältere Männer: ≤ 15 cm (6 Zoll) OR 4,0 und 15 bis 25 cm (6 bis 10 Zoll) OR 2,0 für wiederholte Stürze, nicht reichen können OR 8,1 (Duncan 1992)"},"evidenz":"mäßig","quellen":["Duncan PW et al. 1990, Functional reach: a new clinical measure of balance. J Gerontol – https://pubmed.ncbi.nlm.nih.gov/2229941/","Duncan PW et al. 1992, Functional reach: predictive validity in a sample of elderly male veterans. J Gerontol – https://pubmed.ncbi.nlm.nih.gov/1573190/","Lim LI et al. 2005, Measuring gait and gait-related activities in Parkinson's patients own home environment. Parkinsonism Relat Disord – https://pubmed.ncbi.nlm.nih.gov/15619458/","Dibble LE, Lange M 2006, Predicting falls in individuals with Parkinson disease: a reconsideration of clinical balance measures. J Neurol Phys Ther – https://pubmed.ncbi.nlm.nih.gov/16796770/"]},"sis":{"name":"Stroke Impact Scale","was":"Teilhabe und Alltag","einheit":"Punkte","kurz":"Fragebogen, in dem der Patient die Folgen des Schlaganfalls selbst einschätzt, zum Beispiel Kraft, Handfunktion, Alltag, Gedächtnis, Stimmung und Teilhabe.","ziel":"Die Sicht des Patienten auf Alltag und Teilhabe erfassen.","norm":["Jeder Bereich 0 bis 100, höhere Werte = weniger Beeinträchtigung.","Schlaganfall unter 28 Tagen, Mittelwert (Duncan 2002): Kraft 61,9; Gedächtnis 77,8; Emotion 74,3; Kommunikation 81,0; Alltag 66,5; Mobilität 60,2; Handfunktion 55,9; Teilhabe 58,9.","Chronisch, im Mittel 18 Monate (Huang 2010): Kraft 40,7; Gedächtnis 81,5; Emotion 59,6; Kommunikation 89,7; Alltag 67,4; Mobilität 79,3; Handfunktion 29,6; Teilhabe 47,9.","Echte Veränderung beim Einzelnen erst ab großen Sprüngen: Kraft 24, Alltag 17, Mobilität 15, Handfunktion 26 Punkte (Lin 2010)."],"normQuelle":"Q119","durch":"Fragebogen zum Selbstausfüllen (Selbstbericht), 59 Items, jedes auf einer 5-stufigen Skala nach erlebter Schwierigkeit. Die Bereichswerte werden auf 0 bis 100 umgerechnet. Der Patient muss einem 3-stufigen Auftrag folgen können, sonst gibt es eine Version für Angehörige. Dauer 15 bis 20 Minuten. Die Kurzform SIS-16 erfasst die körperliche Seite der letzten 2 Wochen.","mess":{"reliab":"Test-Retest ICC 0,70 bis 0,92 je Bereich, Emotion 0,57 (Duncan 1999)","mdc":"Einzelner Patient (MDC95): Kraft 24,0; Alltag 17,3; Mobilität 15,1; Handfunktion 25,9 Punkte (Lin 2010)","mcid":"Gruppenwerte: Kraft 9,2; Alltag 5,9; Mobilität 4,5; Handfunktion 17,8 Punkte (Lin 2010)"},"evidenz":"mäßig","quellen":["Duncan PW et al. 1999, The stroke impact scale version 2.0. Evaluation of reliability, validity, and sensitivity to change. Stroke – https://pubmed.ncbi.nlm.nih.gov/10512918/","Lin KC et al. 2010, Minimal detectable change and clinically important difference of the Stroke Impact Scale in stroke patients. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/20053950/","Duncan PW et al. 2003, Stroke Impact Scale-16: A brief assessment of physical function. Neurology – https://pubmed.ncbi.nlm.nih.gov/12552047/"]},"arat":{"name":"Action Research Arm Test","was":"Arm- und Handfunktion","einheit":"Punkte von 57","kurz":"Der Patient greift, hält und bewegt standardisierte Gegenstände, zum Beispiel Würfel, Becher und Kugel. Dazu kommen grobe Armbewegungen.","ziel":"Arm- und Handfunktion bei gezielten Aufgaben erfassen.","norm":["Höchstwert 57, höher = bessere Funktion der oberen Extremität. Chronischer Schlaganfall, Aufnahme: Mittelwert 29,2 (van der Lee 2001).","Drei Monate nach Schlaganfall Mittelwert 39,5 (Beebe & Lang 2009).","Veränderung über etwa 6 Punkte liegt außerhalb des Messfehlers (van der Lee 2001); früh nach Schlaganfall gelten 12 bis 17 Punkte als bedeutsam (Lang 2008)."],"normQuelle":"Q120","durch":"19 Aufgaben in vier Teilen: Greifen, Halten, Pinzettengriff, grobe Bewegung. Je Aufgabe 3 = normal, 2 = vollständig, aber auffällig langsam oder mit großer Mühe, 1 = teilweise, 0 = nichts möglich. Zeitlimit überschritten oder Kontakt zur Stuhllehne verloren: 2 statt 3. Material: Testkit mit Holzblöcken, Murmeln, Gläsern und weiteren Teilen. Dauer 5 bis 15 Minuten. Das Protokoll von Yozbatiran 2008 beschreibt die Durchführung genau.","mess":{"reliab":"Inter- und Intrarater ICC 0,92 bis 0,97 (Nijland 2010)","mdc":"Übereinstimmungsgrenzen bei stabilen chronischen Patienten −5,7 bis 6,2 Punkte (van der Lee 2001)","mcid":"Früh nach Schlaganfall: 12 Punkte (dominante Seite betroffen) bzw. 17 Punkte (nicht dominante Seite) (Lang 2008)"},"evidenz":"mäßig","quellen":["Yozbatiran N et al. 2008, A standardized approach to performing the action research arm test. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/17704352/","van der Lee JH et al. 2001, The responsiveness of the Action Research Arm test and the Fugl-Meyer Assessment scale in chronic stroke patients. J Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/11482350/","Lang CE et al. 2008, Estimating minimal clinically important differences of upper-extremity measures early after stroke. Arch Phys Med Rehabil – https://pmc.ncbi.nlm.nih.gov/articles/PMC2819021/","Nijland R et al. 2010, A comparison of two validated tests for upper limb function after stroke: WMFT and ARAT. J Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/20603702/","Beebe JA, Lang CE 2009, Active range of motion predicts upper extremity function 3 months after stroke. Stroke – https://pmc.ncbi.nlm.nih.gov/articles/PMC2718540/"]},"bbt":{"name":"Box and Blocks Test","was":"Gezielter Griff","einheit":"Blöcke in 60 s","kurz":"Der Patient setzt in 60 Sekunden so viele Holzklötze wie möglich über eine Trennwand in das andere Fach.","ziel":"Grobe Greifgeschicklichkeit der Hand messen, Seitenvergleich möglich.","norm":["Anzahl Würfel in 60 s, mehr = besser. Mittelwert (Mathiowetz 1985, 628 Gesunde, 20 bis 94 J.), rechte / linke Hand. Männer: 40–44 J. 83,0 / 80,0; 50–54 J. 79,0 / 77,0; 60–64 J. 71,3 / 70,5; 70–74 J. 66,3 / 64,3; ab 75 J. 63,0 / 61,3.","Frauen: 40–44 J. 81,1 / 79,7; 50–54 J. 77,7 / 74,3; 60–64 J. 76,1 / 73,6; 70–74 J. 68,6 / 68,3; ab 75 J. 65,0 / 63,6.","Echte Veränderung nach Schlaganfall ab etwa 6 Würfeln an der betroffenen Hand (Chen 2009)."],"normQuelle":"Q121","durch":"Der Patient sitzt am Tisch vor einer Box, die durch eine Trennwand in zwei Fächer geteilt ist. In einem Fach liegen 150 Holzwürfel (2,5 cm). In 60 Sekunden so viele Würfel wie möglich einzeln über die Trennwand ins andere Fach bringen. Die Hand muss die Trennwand überqueren. Mehrere gleichzeitig transportierte Würfel zählen als einer. Der Untersucher sitzt gegenüber. Jede Hand wird einzeln gemessen.","mess":{"reliab":"Schlaganfall Test-Retest ICC 0,85 bis 0,98 (Chen 2009)","mdc":"Kleinste echte Veränderung 5,5 Würfel (stärker betroffene Hand), 7,8 Würfel (weniger betroffene Hand) (Chen 2009)"},"evidenz":"mäßig","quellen":["Mathiowetz V et al. 1985, Adult norms for the Box and Block Test of manual dexterity. Am J Occup Ther – https://pubmed.ncbi.nlm.nih.gov/3160243/","Chen HM et al. 2009, Test-retest reproducibility and smallest real difference of 5 hand function tests in patients with stroke. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/19261767/"]},"nhpt":{"name":"9-Loch-Steckbrett-Test","was":"Feinmotorik der Hand","einheit":"Sekunden","kurz":"Der Patient steckt neun Stifte nacheinander in die Löcher eines Bretts und nimmt sie wieder heraus. Gemessen wird die Zeit.","ziel":"Feinmotorik und Fingergeschick messen.","norm":["Zeit in Sekunden, weniger = schneller. Gesunde Erwachsene, Mittelwert, rechte / linke Hand (Grice 2003). Männer: 21–25 J. 16,4 / 17,5; 41–45 J. 18,5 / 18,5; 61–65 J. 20,9 / 21,6; ab 71 J. 25,8 / 26,0.","Frauen: 21–25 J. 16,0 / 17,2; 41–45 J. 16,5 / 17,6; 61–65 J. 19,0 / 20,3; ab 71 J. 22,5 / 24,1.","Parkinson, Mittelwert 31,4 s dominante, 32,2 s nicht dominante Hand (Earhart 2011). Multiple Sklerose: über 33,3 s deutliche bis schwere Handfunktionsstörung (Lamers 2015, nach Feys 2017).","Multiple Sklerose: 20 % langsamer gilt als bedeutsame Verschlechterung (Kragt 2006)."],"normQuelle":"Q122","durch":"Die Stifte einzeln aus dem Behälter nehmen und so schnell wie möglich in die Löcher stecken, danach einzeln herausnehmen und in den Behälter zurücklegen. Das Brett liegt in der Körpermitte, der Behälter auf der Seite der getesteten Hand. Nur die getestete Hand arbeitet, die andere darf den Brettrand halten. Die Zeit läuft ab Berühren des ersten Stifts bis der letzte Stift im Behälter landet.","mess":{"reliab":"Parkinson ICC 0,88 dominante, 0,91 nicht dominante Hand (Earhart 2011); Schlaganfall ICC 0,85 bis 0,98 (Chen 2009)","mdc":"Schlaganfall, betroffene Hand 32,8 s (54 % des Mittelwerts, unzuverlässig), weniger betroffene Hand 6,2 s (Chen 2009)","mcid":"Multiple Sklerose: 20 % Verschlechterung gilt als klinisch bedeutsam (Kragt 2006; Übersicht Feys 2017)","grenzwert":"Multiple Sklerose: über 33,3 s trennt leichte von deutlicher bis schwerer Funktionsstörung; 18 s als Grenze zur normalen Handfunktion (Feys 2017)"},"evidenz":"stark","quellen":["Feys P et al. 2017, The Nine-Hole Peg Test as a manual dexterity performance measure for multiple sclerosis. Mult Scler – https://pmc.ncbi.nlm.nih.gov/articles/PMC5405844/","Oxford Grice K et al. 2003, Adult norms for a commercially available Nine Hole Peg Test for finger dexterity. Am J Occup Ther – https://pubmed.ncbi.nlm.nih.gov/14527120/","Earhart GM et al. 2011, The 9-hole PEG test of upper extremity function in people with Parkinson disease. J Neurol Phys Ther – https://pubmed.ncbi.nlm.nih.gov/22020457/","Kragt JJ et al. 2006, Clinical impact of 20% worsening on Timed 25-foot Walk and 9-hole Peg Test in multiple sclerosis. Mult Scler – https://pubmed.ncbi.nlm.nih.gov/17086905/","Chen HM et al. 2009, Test-retest reproducibility and smallest real difference of 5 hand function tests in patients with stroke. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/19261767/"]},"ash":{"name":"Ashworth-Skala","was":"Muskeltonus, Spastik","einheit":"Grad","kurz":"Der Untersucher bewegt ein Gelenk passiv durch und beurteilt den Widerstand der Muskulatur. Die Einstufung erfolgt in Graden.","ziel":"Muskeltonus beziehungsweise Spastik erkennen und den Grad dokumentieren.","norm":["Stufen 0, 1, 1+, 2, 3, 4 (Modifizierte Ashworth-Skala nach Bohannon & Smith 1987). Höhere Stufe = mehr Muskeltonus. 0 = kein Tonusanstieg.","1 = leichter Anstieg mit kurzer Blockade und Nachlassen oder minimalem Widerstand am Ende der Bewegung. 1+ = leichter Anstieg mit Blockade, danach minimaler Widerstand über weniger als die Hälfte des Bewegungsausmaßes. 2 = deutlicher Anstieg über den größten Teil des Bewegungsausmaßes, Teil lässt sich noch leicht bewegen. 3 = deutlicher Anstieg, passive Bewegung schwierig. 4 = Teil starr in Beugung oder Streckung.","Zuverlässiger am Arm als am Bein (Meseguer-Henarejos 2018). Normwerte und Grenzwerte gibt es nicht."],"normQuelle":"Q123","durch":"Das Gelenk wird passiv durch eine schnelle Dehnung mit hoher Geschwindigkeit bewegt, nach dem Widerstand wird die Stufe vergeben. Untersuchung auf einer Liege. Zur Lagerung und genauen Geschwindigkeit sagt die Seite nichts, das Vorgehen bei jeder Messung gleich halten.","mess":{"reliab":"Modifizierte Ashworth-Skala, Metaanalyse 33 Studien: Interrater ICC 0,78 Arm, 0,69 Bein; Kappa 0,63 Arm, 0,36 Bein (Meseguer-Henarejos 2018). Ellenbogenbeuger 86,7 % Übereinstimmung (Bohannon & Smith 1987)."},"evidenz":"mäßig","quellen":["Bohannon RW, Smith MB 1987, Interrater reliability of a modified Ashworth scale of muscle spasticity. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/3809245/","Meseguer-Henarejos AB et al. 2018, Inter- and intra-rater reliability of the Modified Ashworth Scale: a systematic review and meta-analysis. Eur J Phys Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/28901119/"]},"tis":{"name":"Trunk Impairment Scale","was":"Rumpfkontrolle","einheit":"Punkte von 23","kurz":"Der Patient sitzt und löst Aufgaben zur statischen und dynamischen Rumpfkontrolle sowie zur Koordination des Rumpfes.","ziel":"Rumpfkontrolle erfassen, die Gleichgewicht und Armfunktion mitbestimmt.","norm":["Gesamt 0 bis 23 (statisches Sitzen 0–7, dynamisches Sitzen 0–10, Koordination 0–6). Gesunde: Median 23, aber 45 % der Gesunden erreichen nicht die Höchstpunktzahl (Verheyden 2005).","Subakuter Schlaganfall (rund 61 Tage): Median 14, Bereich 0–21 (Verheyden 2004). Chronisch: Median 11; nicht gehfähig 8, gehfähig 14 (Verheyden 2006).","Veränderungen unter etwa 3 Punkten können Messfehler sein (Verheyden 2004)."],"normQuelle":"Q124","durch":"Der Patient sitzt auf der Bettkante oder Liege ohne Rücken- und Armstütze, Oberschenkel gestützt, Knie 90°, Füße flach auf dem Boden, Arme auf den Beinen, Kopf und Rumpf in Mittelstellung. Jede Aufgabe darf dreimal versucht werden, das beste Ergebnis zählt. Aufgaben mündlich erklären und bei Bedarf vormachen. Material: Liege ohne Rücken- und Armstütze, Protokollbogen, Stoppuhr. Bis etwa 20 Minuten.","mess":{"reliab":"Test-Retest ICC 0,96, Interrater 0,99; Übereinstimmungsgrenzen Test-Retest −2,90 bis 3,68 Punkte (Verheyden 2004)"},"evidenz":"mäßig","quellen":["Verheyden G et al. 2004, The Trunk Impairment Scale: a new tool to measure motor impairment of the trunk after stroke. Clin Rehabil – https://pubmed.ncbi.nlm.nih.gov/15137564/","Verheyden G et al. 2005, Discriminant ability of the Trunk Impairment Scale: a comparison between stroke patients and healthy individuals. Disabil Rehabil – https://pubmed.ncbi.nlm.nih.gov/16096256/","Verheyden G et al. 2006, Trunk performance after stroke and the relationship with balance, gait and functional ability. Clin Rehabil – https://pubmed.ncbi.nlm.nih.gov/16774097/"]},"mrs":{"name":"Modifizierte Rankin-Skala","was":"Selbstständigkeit insgesamt","einheit":"Grad 0 bis 6","kurz":"Einstufung der Selbstständigkeit im Alltag in Graden von 0 (keine Symptome) bis 6 (verstorben). Sie beruht auf Gespräch und Beobachtung.","ziel":"Gesamteindruck von Behinderung und Selbstständigkeit festhalten und im Verlauf vergleichen.","norm":["Höhere Stufe = stärkere Behinderung. 0 = keine Symptome. 1 = trotz Symptomen keine wesentliche Behinderung. 2 = leichte Behinderung, eigene Angelegenheiten ohne Hilfe. 3 = mittelgradig, etwas Hilfe nötig, Gehen ohne Unterstützung möglich. 4 = mittelschwer bis schwer, ohne Hilfe weder Gehen noch Körperpflege. 5 = schwer, bettlägerig, inkontinent, ständige Pflege. 6 = verstorben (in Studien ergänzt).","Stufe ≤ 1 gilt als gutes Ergebnis (Schlaganfall, 3 Monate, Ali 2013). Ein strukturiertes Interview macht die Einstufung zuverlässiger (Banks 2007)."],"normQuelle":"Q125","durch":"Der Patient wird zu Alltagsaktivitäten befragt, auch zu Aktivitäten außer Haus. Neurologische Ausfälle wie Aphasie und kognitive Einschränkungen werden zusätzlich berücksichtigt. Eine einzige Einstufung, 5 bis 15 Minuten, auch telefonisch oder als strukturiertes Interview möglich.","mess":{"reliab":"Interrater gewichtetes Kappa 0,90, ungewichtet 0,46 (systematische Übersicht, 10 Studien, Quinn 2009); strukturiertes Interview verbessert Kappa von 0,56 auf 0,78; Test-Retest Kappa 0,81 bis 0,95 (Banks 2007)","grenzwert":"Stufe ≤ 1 gilt als gutes Ergebnis nach 3 Monaten, ≥ 3 als schlechtes (Ali 2013)"},"evidenz":"stark","quellen":["Quinn TJ et al. 2009, Reliability of the modified Rankin Scale: a systematic review. Stroke – https://pubmed.ncbi.nlm.nih.gov/19679846/","Banks JL, Marotta CA 2007, Outcomes validity and reliability of the modified Rankin scale: a literature review and synthesis. Stroke – https://pubmed.ncbi.nlm.nih.gov/17272767/","Ali M et al. 2013, How well do standard stroke outcome measures reflect quality of life? Stroke – https://pubmed.ncbi.nlm.nih.gov/24052510/","van Swieten JC et al. 1988, Interobserver agreement for the assessment of handicap in stroke patients. Stroke – https://pubmed.ncbi.nlm.nih.gov/3363593/"]},"updrs":{"name":"MDS-UPDRS","was":"Parkinson-Symptome, Motorik","einheit":"Punkte","kurz":"Standardisierte Untersuchung der Parkinson-Symptome. Der motorische Teil prüft unter anderem Rigor, Tremor, Verlangsamung, Gang und Haltung.","ziel":"Schweregrad der Motorik bestimmen und den Verlauf unter Therapie und Medikation beobachten.","norm":["Je Item 0 = normal, 1 = leicht, 2 = mild, 3 = mäßig, 4 = schwer. Höhere Werte = stärkere Beeinträchtigung. Teilsummen sind aussagekräftiger als die Gesamtsumme (Goetz 2008).","Parkinson, Mittelwert (Goetz 2008): Teil I 11,5; Teil II 16,0; Teil III 36,8; Teil IV 4,0; gesamt 68,4.","Teil III: Verbesserung ab etwa 3,3 Punkten, Verschlechterung ab etwa 4,6 Punkten klinisch bedeutsam (Horváth 2015)."],"normQuelle":"Q132","durch":"Vier Teile mit zusammen 50 Items. Teil I: nicht-motorischer Alltag (13 Fragen), im Gespräch mit Patient und Pflegeperson. Teil II: motorischer Alltag (13 Fragen), Fragebogen für den Patienten. Teil III: motorische Untersuchung durch den Untersucher (33 Werte aus 18 Aufgaben), ON- oder OFF-Zustand auf dem Bogen vermerken. Teil IV: motorische Komplikationen (6 Fragen). Etwa 30 Minuten. Laut Seite ist eine Schulung erforderlich.","mess":{"reliab":"Interne Konsistenz Cronbach α 0,79 bis 0,93 je Teil; Korrelation mit alter UPDRS 0,96 (Goetz 2008, n = 877)","mcid":"Teil III (Motorik): Verbesserung −3,25 Punkte, Verschlechterung +4,63 Punkte (Horváth 2015)"},"evidenz":"stark","quellen":["Goetz CG et al. 2008, Movement Disorder Society-sponsored revision of the Unified Parkinson's Disease Rating Scale (MDS-UPDRS): scale presentation and clinimetric testing results. Mov Disord – https://pubmed.ncbi.nlm.nih.gov/19025984/","Horváth K et al. 2015, Minimal clinically important difference on the Motor Examination part of MDS-UPDRS. Parkinsonism Relat Disord – https://pubmed.ncbi.nlm.nih.gov/26578041/"]},"moca":{"name":"Montreal Cognitive Assessment (MoCA)","was":"Kognition","einheit":"Punkte von 30","kurz":"Kurzer Test zu Aufmerksamkeit, Gedächtnis, Sprache, Orientierung und Planen.","ziel":"Kognitive Einschränkungen erkennen, die Anleitung und Therapieplanung beeinflussen. Es ist ein Screening und keine Diagnose.","norm":["Höchstwert 30. 26 oder mehr gilt als normal; mit Grenzwert 26 erkennt der Test 90 % der leichten kognitiven Störungen, Spez 87 % (Nasreddine 2005). Bei 12 oder weniger Ausbildungsjahren 1 Punkt addieren.","Parkinson: unter 26 = leichte kognitive Störung (Sens 90 %, Spez 75 %); unter 21 = Demenz (Sens 81 %, Spez 95 %) (Dalrymple-Alford 2010)."],"normQuelle":"Q126","durch":"16 Aufgaben in 11 Bereichen: visuell-räumlich und exekutiv, Benennen, Gedächtnis, Aufmerksamkeit, Sprache, Abstraktion, Orientierung. Papier, Bleistift, Stoppuhr, Bogen. Etwa 10 Minuten. Es gibt drei Parallelversionen gegen Lerneffekte. Laut Seite ist seit dem 1. September 2019 eine Schulung mit Zertifizierung erforderlich.","pos":"Auffällig, wenn der Wert unter 26 liegt.","mess":{"grenzwert":"Unter 26: leichte kognitive Störung, Sens 90 %, Spez 87 % (Nasreddine 2005). Parkinson: unter 26 leichte kognitive Störung (Sens 90 %, Spez 75 %), unter 21 Demenz (Sens 81 %, Spez 95 %) (Dalrymple-Alford 2010)."},"evidenz":"mäßig","quellen":["Nasreddine ZS et al. 2005, The Montreal Cognitive Assessment, MoCA: a brief screening tool for mild cognitive impairment. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/15817019/","Dalrymple-Alford JC et al. 2010, The MoCA: well-suited screen for cognitive impairment in Parkinson disease. Neurology – https://pubmed.ncbi.nlm.nih.gov/21060094/"]},"mbest":{"name":"Mini-BESTest","was":"Gleichgewicht, mehrere Systeme","einheit":"Punkte von 28","kurz":"14 Aufgaben aus vier Bereichen: vorausschauende Anpassung, Reaktion auf Störungen, sensorische Orientierung und dynamisches Gehen.","ziel":"Gleichgewichtsprobleme nach Teilsystem unterscheiden, auch bei leichteren Einschränkungen.","norm":["Höchstwert 28 (14 Items, je 0 bis 2). Parkinson: Grenzwert 21 trennt Personen mit und ohne Defizit der Haltungsreaktionen, Sens 89 %, Spez 81 % (King 2012); unter 19 erhöhtes Risiko wiederholter Stürze, Sens 79 % (Mak 2013).","Chronischer Schlaganfall: ≤ 17,5 mit Sturzanamnese (Tsang 2013); die BBS trennt Stürzer dort etwas besser.","Echte Veränderung ab 3 bis 3,5 Punkten, bedeutsame Verbesserung ab 4 Punkten (Godi 2013)."],"normQuelle":"Q127","durch":"14 Aufgaben in vier Bereichen: vorausschauende Haltungsanpassung, Reaktion auf Störungen, sensorische Orientierung, dynamisches Gehen. Je Aufgabe 0 bis 2. Bei seitengetrennten Aufgaben zählt nach dem Original der niedrigere Wert. Material: Schaumstoffblock 60 × 60 cm, 10°-Rampe, zwei Stühle, 23 cm hohe Box, Stoppuhr, Markierung bei 3 m. Dauer 10 bis 15 Minuten.","pos":"Auffällig, wenn der Wert bei Parkinson unter 19 bis 21 liegt.","mess":{"reliab":"Chronischer Schlaganfall Intrarater ICC 0,97, Interrater 0,96 (Tsang 2013); Gleichgewichtsstörungen Test-Retest 0,96, Interrater 0,98 (Godi 2013)","mdc":"3,0 Punkte chronischer Schlaganfall (Tsang 2013); 3,5 Punkte Gleichgewichtsstörungen (Godi 2013)","mcid":"4 Punkte (Godi 2013)","grenzwert":"Parkinson: 21 trennt Personen mit und ohne Defizit der Haltungsreaktionen, Sens 89 %, Spez 81 % (King 2012); 19 für wiederholte Stürze in 6 Monaten, Sens 79 % (Mak 2013)"},"evidenz":"stark","quellen":["Franchignoni F et al. 2010, Using psychometric techniques to improve the Balance Evaluation Systems Test: the mini-BESTest. J Rehabil Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC3228839/","King LA et al. 2012, Comparing the Mini-BESTest with the Berg Balance Scale to Evaluate Balance Disorders in Parkinson's Disease. Parkinsons Dis – https://pmc.ncbi.nlm.nih.gov/articles/PMC3202113/","Mak MK, Auyeung MM 2013, The mini-BESTest can predict parkinsonian recurrent fallers: a 6-month prospective study. J Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/23673397/","Tsang CS et al. 2013, Psychometric properties of the Mini-BESTest in community-dwelling individuals with chronic stroke. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/23559522/","Godi M et al. 2013, Comparison of reliability, validity, and responsiveness of the mini-BESTest and Berg Balance Scale. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/23023812/"]},"pdq":{"name":"PDQ-39 oder PDQ-8","was":"Lebensqualität bei Parkinson","einheit":"Punkte","kurz":"Fragebogen zur Lebensqualität bei Parkinson. Es gibt eine Kurzform mit 8 und eine Langform mit 39 Fragen.","ziel":"Auswirkungen auf Alltag, Stimmung und Lebensqualität aus Patientensicht erfassen.","norm":["PDQ-39: je Item 0 = nie bis 4 = immer. 8 Bereiche mit je 0 bis 100, höher = stärker belastet. Gesamtwert (Summenindex) = Mittel der 8 Bereiche (Jenkinson 1997).","Parkinson, Mittelwert (Hagell 2007, n = 202): Mobilität 43,0; Alltag 38,9; Emotion 37,9; Stigma 27,5; soziale Unterstützung 14,8; Kognition 33,0; Kommunikation 28,0; Körperbeschwerden 40,9.","Bedeutsame Veränderung im Summenindex: Verbesserung ab etwa 4,7 Punkten, Verschlechterung ab etwa 4,2 (Horváth 2017). PDQ-8: etwa 5,9 bzw. 4,9 Punkte."],"normQuelle":"Q128","durch":"Fragebogen zum Selbstausfüllen, bezieht sich auf den letzten Monat, 10 bis 20 Minuten. Alle Items müssen beantwortet sein. Bereichswert = Summe der Items geteilt durch den möglichen Höchstwert, mal 100. Kostenlos nur für nichtkommerzielle akademische Nutzung oder öffentlich finanzierte Versorgung, sonst Lizenz nötig.","mess":{"mcid":"PDQ-39-Summenindex: Verbesserung −4,72, Verschlechterung +4,22; PDQ-8: −5,94 bzw. +4,91 Punkte (Horváth 2017, n = 365)"},"evidenz":"stark","quellen":["Jenkinson C et al. 1997, The Parkinson's Disease Questionnaire (PDQ-39): development and validation of a Parkinson's disease summary index score. Age Ageing – https://pubmed.ncbi.nlm.nih.gov/9351479/","Horváth K et al. 2017, Changes in Quality of Life in Parkinson's Disease: How Large Must They Be to Be Relevant? Neuroepidemiology – https://pubmed.ncbi.nlm.nih.gov/28161701/","Peto V et al. 2001, Determining minimally important differences for the PDQ-39 Parkinson's disease questionnaire. Age Ageing – https://pubmed.ncbi.nlm.nih.gov/11509307/","Hagell P, Nygren C 2007, The 39 item Parkinson's disease questionnaire (PDQ-39) revisited. J Neurol Neurosurg Psychiatry – https://pmc.ncbi.nlm.nih.gov/articles/PMC2117601/"]},"fog":{"name":"Freezing of Gait Questionnaire","was":"Gangblockaden","einheit":"Punkte","kurz":"Fragebogen zu Gangblockaden im Alltag, zum Beispiel wie oft sie auftreten und wann.","ziel":"Gangblockaden erkennen und im Verlauf vergleichen.","norm":["Gesamt 0 bis 24 (6 Items, je 0 bis 4), höher = schwereres Freezing. Cut-off steht auf der Seite nicht. Item 3 gilt als gute Einzelfrage zur Häufigkeit.","Parkinson, Hoehn & Yahr II–IV (Nieuwboer 2007, n = 153): Median 7 bis 9 über vier Messzeitpunkte, Quartile etwa 3 bis 14."],"normQuelle":"Q129","durch":"Fragebogen mit 6 Items, 5 bis 10 Minuten. Ausfüllen im besten Zustand (ON-Phase). Nach der Seite führt die Therapeutin oder der Therapeut das Freezing vor. Die meisten Items beziehen sich auf die letzte Woche.","mess":{"reliab":"Cronbach α 0,94 (Giladi 2000); neue Version NFOG-Q: Übereinstimmung Patient und Angehörige ICC 0,78 (Nieuwboer 2009)"},"evidenz":"mäßig","quellen":["Giladi N et al. 2000, Construction of freezing of gait questionnaire for patients with Parkinsonism. Parkinsonism Relat Disord – https://pubmed.ncbi.nlm.nih.gov/10817956/","Nieuwboer A et al. 2009, Reliability of the new freezing of gait questionnaire: agreement between patients with Parkinson's disease and their carers. Gait Posture – https://pubmed.ncbi.nlm.nih.gov/19660949/"]},"t25":{"name":"Timed 25-Foot Walk (T25FW)","was":"Gehgeschwindigkeit bei MS","einheit":"Sekunden","kurz":"Der Patient geht 25 Fuß (7,62 m) so schnell wie sicher möglich. Gemessen wird die Zeit, Mittelwert aus zwei Durchgängen.","ziel":"Gehfähigkeit bei MS einfach und vergleichbar erfassen.","norm":["MS, Median 4,4 s (Spannweite 2,9 bis 20,7); Gesunde 3,7 s (2,8 bis 5,2) (Phan-Ba 2011). Leicht Betroffene gehen 25 Fuß meist in 3 bis 5 s (Kaufman 2000).","Eine Verschlechterung um mehr als 20 % gilt als bedeutsam (Kaufman 2000, Kragt 2006).","MS EDGE: in allen Settings stark empfohlen, EDSS 0 bis 7,5."],"durch":"Gerade Strecke von 7,62 m markieren, Start im Stand hinter der Linie. Zwei Durchgänge direkt nacheinander, höchstens 5 Minuten Pause. Hilfsmittel erlaubt, immer gleich dokumentieren.","quellen":["Kaufman M et al. 2000, The significant change for the Timed 25-foot Walk in the multiple sclerosis functional composite. Mult Scler – https://pubmed.ncbi.nlm.nih.gov/10962550/","Kragt JJ et al. 2006, Clinical impact of 20% worsening on Timed 25-foot Walk and 9-hole Peg Test in multiple sclerosis. Mult Scler – https://pubmed.ncbi.nlm.nih.gov/17086905/","Phan-Ba R et al. 2011, Comparison of the timed 25-foot and the 100-meter walk as performance measures in multiple sclerosis. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/21436388/","Shirley Ryan AbilityLab, Rehabilitation Measures Database – https://www.sralab.org/rehabilitation-measures/timed-25-foot-walk"],"mess":{"reliab":"Abweichung zwischen den zwei schnellsten von drei Durchgängen meist höchstens 10 % (Kaufman 2000)","mcid":"Verschlechterung um mehr als 20 % gilt als bedeutsam (Kaufman 2000; im Alltag spürbar laut Kragt 2006, n = 527)"},"evidenz":"stark"},"msws":{"name":"MS Walking Scale (MSWS-12)","was":"Selbst erlebte Gehbehinderung","einheit":"Punkte von 100","kurz":"Fragebogen mit 12 Fragen dazu, wie stark die MS das Gehen in den letzten zwei Wochen eingeschränkt hat.","ziel":"Die Sicht des Patienten auf sein Gehen erfassen und im Verlauf vergleichen.","norm":["Rohwert 12 bis 60, umgerechnet auf 0 bis 100; höher = stärker eingeschränkt.","Bedeutsame Verbesserung ab etwa 8 Punkten (Mehta 2015).","MS EDGE: in allen Settings stark empfohlen, EDSS 0 bis 7,5."],"durch":"Selbst ausfüllen lassen, 5 bis 10 Minuten. Bezugszeitraum sind die letzten 14 Tage.","quellen":["Hobart JC et al. 2003, Measuring the impact of MS on walking ability: the 12-Item MS Walking Scale (MSWS-12). Neurology – https://pubmed.ncbi.nlm.nih.gov/12525714/","Mehta L et al. 2015, Identifying an important change estimate for the Multiple Sclerosis Walking Scale-12. Mult Scler J Exp Transl Clin – https://pmc.ncbi.nlm.nih.gov/articles/PMC5460630/","APTA Test Measures, MSWS-12 – https://www.apta.org/patient-care/evidence-based-practice-resources/test-measures/12-item-multiple-sclerosis-walking-scale-msws-12"],"mess":{"reliab":"Reliabilität ≥ 0,94, Item-Test-Retest ≥ 0,78; empfindlicher für Veränderung als EDSS und T25FW (Hobart 2003)","mcid":"8 Punkte Verbesserung (0 bis 100) (Mehta 2015)"},"evidenz":"mäßig"},"mfis":{"name":"Modified Fatigue Impact Scale (MFIS)","was":"Erschöpfung bei MS","einheit":"Punkte von 84","kurz":"Fragebogen mit 21 Fragen zu körperlicher, kognitiver und psychosozialer Erschöpfung in den letzten vier Wochen.","ziel":"Fatigue erfassen, um Belastung und Pausen in der Therapie zu planen.","norm":["Gesamt 0 bis 84, höher = stärkere Fatigue.","Ab 38 Punkten relevante Fatigue (Flachenecker 2002)."],"durch":"Selbst ausfüllen lassen, 5 bis 10 Minuten. Kurzform mit 5 Fragen möglich.","quellen":["Flachenecker P et al. 2002, Fatigue in multiple sclerosis: a comparison of different rating scales and correlation to clinical parameters. Mult Scler – https://pubmed.ncbi.nlm.nih.gov/12474995/","Selecting Rehabilitation Outcome Measures for People With MS (Int J MS Care) – https://www.ijmsc.org/view/selecting-rehabilitation-outcome-measures-for-people-with-multiple-sclerosis"],"pos":"Auffällig, wenn der Gesamtwert 38 oder mehr beträgt.","mess":{"grenzwert":"38 Punkte trennt MS mit und ohne relevante Fatigue (Flachenecker 2002, n = 151)"},"evidenz":"mäßig"},"msis":{"name":"MS Impact Scale (MSIS-29)","was":"Folgen der MS im Alltag","einheit":"Punkte von 100","kurz":"Fragebogen mit 29 Fragen zu körperlichen (20) und psychischen (9) Folgen der MS in den letzten zwei Wochen.","ziel":"Teilhabe und Lebensqualität aus Sicht des Patienten erfassen.","norm":["Beide Teile werden auf 0 bis 100 umgerechnet, höher = stärkere Beeinträchtigung.","MS EDGE: empfohlen bei EDSS 0 bis 7,5; in allen Settings stark empfohlen."],"durch":"Selbst ausfüllen lassen, etwa 10 Minuten.","quellen":["Hobart J et al. 2001, The Multiple Sclerosis Impact Scale (MSIS-29): a new patient-based outcome measure. Brain – https://pubmed.ncbi.nlm.nih.gov/11335698/","APTA Test Measures, MSIS-29 – https://www.apta.org/patient-care/evidence-based-practice-resources/test-measures/multiple-sclerosis-impact-scale-msis-29-"],"mess":{"reliab":"Interne Konsistenz Cronbach α ≥ 0,91, Test-Retest ICC ≥ 0,87 (Hobart 2001)"},"evidenz":"mäßig"},"pfs":{"name":"Parkinson-Fatigue-Skala","was":"Erschöpfung","einheit":"Punkte","kurz":"Fragebogen zur Erschöpfung (Fatigue) bei Parkinson.","ziel":"Erschöpfung erfassen, die Belastbarkeit und Dosierung der Therapie beeinflusst.","norm":["PFS-16: Summe 16 bis 80 oder Mittelwert 1 bis 5, höher = mehr Erschöpfung. Mittelwert über 2,95: Fatigue vorhanden; über 3,30: als Problem erlebt (Brown 2005).","Parkinson, Mittelwert (Brown 2005, n = 495): 3,41. Binärer Score 0 bis 16: über 7 bzw. über 8 entsprechend."],"normQuelle":"Q130","durch":"16 Aussagen zur Erschöpfung der letzten 2 Wochen. Zustimmung von 1 (stimme gar nicht zu) bis 5 (stimme voll zu). Fragebogen zum Selbstausfüllen, etwa 5 Minuten.","evidenz":"mäßig","quellen":["Brown RG et al. 2005, The Parkinson fatigue scale. Parkinsonism Relat Disord – https://pubmed.ncbi.nlm.nih.gov/15619463/"]},"t360":{"name":"360°-Drehtest","was":"Drehen im Stand","einheit":"Sekunden oder Schritte","kurz":"Der Patient dreht sich im Stand einmal um die eigene Achse. Gemessen werden Zeit oder Schritte.","ziel":"Drehfähigkeit prüfen, wichtig für Sturzrisiko und Gangblockaden.","norm":["Die Seite nennt keine Richtung. Ältere Selbstständige (Gill 1995): über 3,8 s steigt die Rate der Abhängigkeit deutlich. Mittelwert Nicht-Stürzer 2,2 s, Stürzer 2,7 s (Dai 2012).","Parkinson, Mittelwert Zeit / Schritte (Schenkman 2011): Hoehn & Yahr 1–1,5: 3,33 s / 6,3; 2: 3,91 s / 7,6; 2,5: 4,81 s / 8,7; 3: 7,34 s / 11,0."],"normQuelle":"Q131","durch":"Eine Klebebandmarkierung am Boden zeigt den Start. Der Patient steht mit hängenden Armen, Füße bequem auseinander. Bei „Go“ eine volle Drehung um 360° in beliebige Richtung. Die Zeit endet, wenn die Schultern wieder zum Untersucher zeigen. Zwei Durchgänge, gemittelt. Material: Stoppuhr.","evidenz":"schwach","quellen":["Gill TM et al. 1995, Assessing risk for the onset of functional dependence among older adults: the role of physical performance. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/7775716/","Schenkman M et al. 2011, Profile of functional limitations and task performance among people with early- and middle-stage Parkinson disease. Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC3169785/"]},"painfularc":{"name":"Painful Arc","was":"Schmerz bei der Abduktion","einheit":"positiv oder negativ","kurz":"Schmerzprovokation bei der Abduktion des Arms. Die Durchführung steht in den gelesenen Quellen nicht.","ziel":"Hinweis auf eine subakromiale Schmerzursache gewinnen und im Verlauf vergleichen.","norm":["Gepoolt für Impingement: Sens. 53 %, Spez. 76 %, LR+ 2,25 (Hegedus 2012). Für Rotatorenmanschettenerkrankung einziger Schmerztest mit LR+ über 2 (3,7) und niedrigstem LR− (0,36) (Hermans 2013).","Teil des Michener-Clusters (Neer, Hawkins, Painful Arc, Jobe, Außenrotation gegen Widerstand): ab 3 von 5 positiv Sens. 75 %, Spez. 74 %, LR+ 2,93."],"normQuelle":"Q10","durch":"Patient steht, Arm hängt locker. Arm seitlich langsam bis ganz nach oben heben und wieder senken. Positiv bei Schmerz im mittleren Bogen, darunter und darüber weniger.","weitere":["Q140","Q139"],"pos":"Positiv bei Schmerz im mittleren Bereich der aktiven Abduktion, der zum Ende der Bewegung wieder nachlässt.","kw":[{"ziel":"Subakromiales Impingement","sens":"53 %","spez":"76 %","lrp":"2,25","lrn":"0,62","basis":"Metaanalyse Hegedus 2012, 4 Studien, 756 Patienten"},{"ziel":"Rotatorenmanschettenerkrankung","lrp":"3,7 (1,9–7,0)","lrn":"0,36 (0,23–0,54)","basis":"Systematische Übersicht Hermans 2013 (JAMA), Studien hoher Qualität"},{"ziel":"Subakromiales Impingement","lrp":"2,25","lrn":"0,38","basis":"Michener 2009, 55 Patienten, OP als Referenz; Kappa 0,45–0,67"}],"evidenz":"stark","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Hermans J et al. 2013, Does this patient with shoulder pain have rotator cuff disease? JAMA – https://pubmed.ncbi.nlm.nih.gov/23982370/","Michener LA et al. 2009, Reliability and diagnostic accuracy of 5 physical examination tests and combination of tests for subacromial impingement. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19887215/"]},"hawkins":{"name":"Hawkins-Kennedy-Test","was":"Schmerz bei Innenrotation, Hinweis auf Impingement","einheit":"positiv oder negativ","kurz":"Der Arm wird in 90° Flexion gebracht, der Ellbogen ist 90° gebeugt. Dann rotiert der Untersucher den Arm nach innen.","ziel":"Hinweis auf ein subakromiales Impingement gewinnen.","norm":["Gepoolt für Impingement: Sens. 80 %, Spez. 56 %, LR+ 1,84, LR− 0,35 (Hegedus 2012). Allein kaum aussagekräftig.","Hawkins, Painful Arc und Infraspinatus-Test alle positiv: Nachtestwahrscheinlichkeit 95 % für Impingement jeder Ausprägung (Park 2005).","Reliabilität nur mäßig (Kappa 0,39–0,40, Michener 2009)."],"normQuelle":"Q10","durch":"Patient sitzt oder steht. Der Untersucher bringt den Arm in 90° Flexion bei 90° gebeugtem Ellbogen und rotiert den Arm dann nach innen. Positiv bei Schmerz in der Innenrotation (nach Flynn, Cleland und Whitman 2008).","weitere":["Q139","Q141"],"pos":"Positiv bei Schmerz während passiver Innenrotation in 90° Flexion von Schulter und Ellbogen.","kw":[{"ziel":"Subakromiales Impingement","sens":"80 %","spez":"56 %","lrp":"1,84","lrn":"0,35","basis":"Metaanalyse Hegedus 2012, 7 Studien, 944 Patienten"},{"ziel":"Tendinopathie der Rotatorenmanschette","sens":"65,5 %","spez":"62,8 %","lrp":"1,86","lrn":"0,46","basis":"Metaanalyse Hegedus 2012, 3 Studien, 738 Patienten"}],"evidenz":"stark","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Park HB et al. 2005, Diagnostic accuracy of clinical tests for the different degrees of subacromial impingement syndrome. J Bone Joint Surg Am – https://pubmed.ncbi.nlm.nih.gov/15995110/","Michener LA et al. 2009, Reliability and diagnostic accuracy of 5 physical examination tests for subacromial impingement. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19887215/"]},"neer":{"name":"Neer-Test","was":"Passive Elevation, Hinweis auf Impingement","einheit":"positiv oder negativ","kurz":"Der Untersucher fixiert die Skapula und hebt den innenrotierten Arm passiv nach vorn an. Positiv ist der Test, wenn der vertraute Schmerz auftritt.","ziel":"Hinweis auf ein subakromiales Impingement gewinnen.","norm":["Gepoolt für Impingement: Sens. 72 %, Spez. 60 %, LR+ 1,79, LR− 0,47 (Hegedus 2012). Eher zum Ausschluss bei negativem Test.","Reliabilität nur mäßig (Kappa 0,39–0,40, Michener 2009)."],"normQuelle":"Q139","durch":"Patient sitzt oder steht aufrecht, der Arm hängt entspannt. Der Untersucher steht seitlich und fixiert mit einer Hand den oberen Rand der Skapula, damit sie nicht aufwärts rotiert. Bei gestrecktem Ellbogen wird der Arm nach innen rotiert (Daumen zeigt nach unten) und mit der anderen Hand langsam nach vorn bis zum Endbereich angehoben. Abbruch bei Symptomen, Abwehrspannung oder Einschränkung. Notieren: Schmerzort, Winkel des Schmerzbeginns.","weitere":["Q145"],"pos":"Positiv, wenn passive Elevation des innenrotierten Arms bei fixierter Skapula den bekannten Schmerz auslöst.","kw":[{"ziel":"Subakromiales Impingement","sens":"72 %","spez":"60 %","lrp":"1,79","lrn":"0,47","basis":"Metaanalyse Hegedus 2012, 7 Studien, 946 Patienten"},{"ziel":"Subakromiales Impingement","lrn":"0,35 (0,12–0,97)","basis":"Michener 2009, 55 Patienten, OP als Referenz"}],"evidenz":"stark","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Michener LA et al. 2009, Reliability and diagnostic accuracy of 5 physical examination tests for subacromial impingement. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19887215/"]},"droparm":{"name":"Drop-Arm-Test","was":"Kontrolle beim Absenken, Hinweis auf Supraspinatusruptur","einheit":"positiv oder negativ","kurz":"Der Arm wird passiv auf 90° abduziert und der Patient soll ihn langsam wieder absenken.","ziel":"Hinweis auf eine vollständige Ruptur der Supraspinatussehne gewinnen.","norm":["Eher spezifisch als sensitiv: Spez. 83–93 %, Sens. 24–41 % in Einzelstudien (Hegedus 2012); LR+ 3,3 für Rotatorenmanschettenerkrankung (Hermans 2013). Ein negativer Test schließt eine Ruptur nicht aus.","Reliabilität nach Prävalenzkorrektur gut (PABAK 0,65–0,78, Cadogan 2011)."],"normQuelle":"Q142","durch":"Untersucher steht hinter dem sitzenden Patienten. Der gestreckte Arm wird mit voller Außenrotation passiv auf 90° abduziert und am Ellbogen gestützt. Dann löst der Untersucher die Stütze, und der Patient senkt den Arm langsam zurück in die Neutralstellung.","weitere":["Q140"],"pos":"Positiv, wenn der Patient den passiv auf 90° abduzierten Arm nicht kontrolliert absenken kann oder er plötzlich fällt.","kw":[{"ziel":"Rotatorenmanschettenerkrankung","lrp":"3,3 (1,0–11)","basis":"Systematische Übersicht Hermans 2013 (JAMA)"},{"ziel":"Komplette Supraspinatusruptur","sens":"41 %","spez":"83 %","lrp":"2,41","lrn":"0,71","basis":"Bak, Einzelstudie in Hegedus 2012"},{"ziel":"Supraspinatus-Tendinopathie","sens":"24 %","spez":"93 %","lrp":"3,30","lrn":"0,80","basis":"Chew, Einzelstudie in Hegedus 2012"}],"evidenz":"mäßig","quellen":["Hermans J et al. 2013, Does this patient with shoulder pain have rotator cuff disease? JAMA – https://pubmed.ncbi.nlm.nih.gov/23982370/","Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Cadogan A et al. 2011, Interexaminer reliability of orthopaedic special tests used in the assessment of shoulder pain. Man Ther – https://pubmed.ncbi.nlm.nih.gov/20810303/"]},"erlag":{"name":"Außenrotations-Lag-Sign","was":"Halten der Außenrotation, Hinweis auf Supra- und Infraspinatusruptur","einheit":"positiv oder negativ","kurz":"Der Arm wird bei 90° gebeugtem Ellbogen bis zum Anschlag außenrotiert. Der Patient soll die Stellung halten.","ziel":"Hinweis auf eine vollständige Ruptur von Supra- oder Infraspinatus gewinnen.","norm":["Sehr spezifisch für komplette Rupturen (Spez. 94–98 %), Sensitivität 46–56 % (Castoldi 2009, Miller 2008). Sensitivität steigt, wenn Infraspinatus und Teres minor mitbetroffen sind; das Lag nimmt mit der Rupturgröße zu.","Nach Hermans 2013 zusammen mit dem Innenrotations-Lag-Sign der genaueste Befund für komplette Rupturen."],"normQuelle":"Q140","durch":"Ellbogen 90° gebeugt, Schulter bis zum Anschlag außenrotiert. Der Patient soll diese Stellung halten. Positiv, wenn er es nicht kann. Genauere Handgriffe beschreibt die Quelle nicht.","pos":"Positiv, wenn der Patient die passiv eingestellte, fast maximale Außenrotation bei 90° Ellbogenbeugung nicht halten kann und der Arm zurückfedert.","kw":[{"ziel":"Isolierte komplette Supraspinatusruptur","sens":"56 %","spez":"98 %","lrp":"28","lrn":"0,45","basis":"Castoldi 2009, 406 Schultern, OP als Referenz; LR in Hegedus 2012"},{"ziel":"Komplette Ruptur von Supra- und Infraspinatus","sens":"46 %","spez":"94 %","lrp":"7,2 (1,7–31)","lrn":"0,57","basis":"Miller 2008, 37 Patienten, Ultraschall als Referenz; LR+ aus Hermans 2013"}],"evidenz":"mäßig","quellen":["Castoldi F et al. 2009, External rotation lag sign revisited: accuracy for diagnosis of full thickness supraspinatus tear. J Shoulder Elbow Surg – https://pubmed.ncbi.nlm.nih.gov/19223205/","Miller CA et al. 2008, The validity of the lag signs in diagnosing full-thickness tears of the rotator cuff. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/18503815/","Hermans J et al. 2013, Does this patient with shoulder pain have rotator cuff disease? JAMA – https://pubmed.ncbi.nlm.nih.gov/23982370/"]},"liftoff":{"name":"Lift-off-Test (Gerber)","was":"Abheben der Hand vom Rücken, Hinweis auf Subscapularis","einheit":"positiv oder negativ","kurz":"Die Hand liegt auf dem Rücken. Der Patient soll den Handrücken aktiv vom Rücken abheben.","ziel":"Hinweis auf eine Subscapularisläsion gewinnen.","norm":["Sehr spezifisch (98–100 %), aber wenig sensitiv (18–35 %); positiv erst ab Ruptur von etwa 75 % der Sehne (Barth 2006).","Lag-Kriterium: LR+ 8,50, LR− 0,27 (Lasbleiz 2014). Innenrotations-Lag-Sign: LR− 0,04, ein negativer Befund schließt eine komplette Ruptur weitgehend aus (Hermans 2013)."],"normQuelle":"Q147","durch":"Patient steht. Der Handrücken liegt auf dem Rücken in Höhe der mittleren Lendenwirbelsäule. Der Patient hebt ihn ab und hält dabei Innenrotation und Extension des Arms. Der Test setzt volle passive Innenrotation voraus, Schmerz darf nicht begrenzen. Normal: der Handrücken lässt sich abheben.","weitere":["Q140"],"pos":"Positiv, wenn der Patient den Handrücken nicht aktiv von der Lendenwirbelsäule abheben oder die abgehobene Position nicht halten kann.","kw":[{"ziel":"Subscapularisruptur (Kriterium Lag)","lrp":"8,50","lrn":"0,27","basis":"Lasbleiz 2014, 39 Schultern, Ultraschall als Referenz"},{"ziel":"Subscapularisläsion jeder Art","sens":"35 %","spez":"98 %","lrp":"17,5","lrn":"0,66","basis":"Kappe 2018, 106 Patienten, Arthroskopie als Referenz; LR berechnet"},{"ziel":"Subscapularisruptur","sens":"17,6 %","spez":"100 %","basis":"Barth 2006, 68 Patienten, Arthroskopie als Referenz"},{"ziel":"Komplette Subscapularisruptur (Innenrotations-Lag-Sign)","sens":"100 %","spez":"84 %","lrp":"5,6 (2,6–12)","lrn":"0,04 (0,0–0,58)","basis":"Miller 2008, 37 Patienten; LR aus Hermans 2013"}],"evidenz":"mäßig","quellen":["Lasbleiz S et al. 2014, Diagnostic value of clinical tests for degenerative rotator cuff disease in medical practice. Ann Phys Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/24851697/","Kappe T et al. 2018, Diagnostic performance of clinical tests for subscapularis tendon tears. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/28676889/","Barth JR et al. 2006, The bear-hug test: a new and sensitive test for diagnosing a subscapularis tear. Arthroscopy – https://pubmed.ncbi.nlm.nih.gov/17027405/","Hermans J et al. 2013, Does this patient with shoulder pain have rotator cuff disease? JAMA – https://pubmed.ncbi.nlm.nih.gov/23982370/","Gerber C, Krushell RJ 1991, Isolated rupture of the tendon of the subscapularis muscle. J Bone Joint Surg Br – https://pubmed.ncbi.nlm.nih.gov/1670434/"]},"belly":{"name":"Belly-Press-Test","was":"Druck auf den Bauch, Hinweis auf Subscapularis","einheit":"positiv oder negativ","kurz":"Die Handfläche liegt auf dem Bauch. Der Patient drückt über Innenrotation gegen den Bauch.","ziel":"Hinweis auf eine Subscapularisläsion gewinnen, wenn der Lift-off-Test nicht möglich ist.","norm":["Spezifisch (92–98 %), wenig sensitiv (34–40 %); positiv ab einer Ruptur von etwa 30 % der Sehne (Barth 2006). Ein negativer Test schließt eine Ruptur nicht aus.","Reliabilität nach Prävalenzkorrektur gut (PABAK 0,65–0,78, Cadogan 2011)."],"normQuelle":"Q143","durch":"Patient sitzt oder steht, der Ellbogen ist 90° gebeugt, die Handfläche liegt auf dem Oberbauch unterhalb des Processus xiphoideus. Der Patient drückt die Hand über Innenrotation gegen den Bauch.","pos":"Positiv, wenn der Patient beim Druck auf den Bauch mit Handgelenkbeugung oder Zurückfallen des Ellbogens hinter den Rumpf ausweicht.","kw":[{"ziel":"Subscapularisläsion jeder Art","sens":"34 %","spez":"96 %","lrp":"8,5","lrn":"0,69","basis":"Kappe 2018, 106 Patienten, Arthroskopie als Referenz; LR berechnet"},{"ziel":"Subscapularisruptur Grad 2–4","sens":"37 %","spez":"92 %","lrp":"4,6","lrn":"0,68","basis":"Kappe 2018; LR berechnet"},{"ziel":"Subscapularisruptur","sens":"40 %","spez":"97,9 %","lrp":"19","lrn":"0,61","basis":"Barth 2006, 68 Patienten; LR berechnet"}],"evidenz":"mäßig","quellen":["Kappe T et al. 2018, Diagnostic performance of clinical tests for subscapularis tendon tears. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/28676889/","Barth JR et al. 2006, The bear-hug test: a new and sensitive test for diagnosing a subscapularis tear. Arthroscopy – https://pubmed.ncbi.nlm.nih.gov/17027405/","Cadogan A et al. 2011, Interexaminer reliability of orthopaedic special tests used in the assessment of shoulder pain. Man Ther – https://pubmed.ncbi.nlm.nih.gov/20810303/"]},"apprehension":{"name":"Apprehension-Test","was":"Angst vor Luxation, Hinweis auf vordere Instabilität","einheit":"positiv oder negativ","kurz":"Provokationstest für eine vordere Schulterinstabilität. Die Durchführung steht in den gelesenen Quellen nicht.","ziel":"Hinweis auf eine vordere Instabilität gewinnen.","norm":["Vordere Instabilität gepoolt: Sens. 65,6 %, Spez. 95,4 %, LR+ 17,21, LR− 0,39 (Hegedus 2012).","Apprehension und Relocation zusammen positiv: LR+ 39,68 (Farber, in Hegedus 2012).","Apprehension, Relocation und Surprise sind laut Hegedus 2012 die Schultertests mit dem größten klinischen Nutzen bei vorderer Instabilität."],"normQuelle":"Q139","durch":"Die Durchführung konnte ich in den gelesenen Quellen nicht belegen. Bitte nach deinem Standard ergänzen.","pos":"Positiv, wenn bei 90° Abduktion und zunehmender Außenrotation Angst vor dem Herausspringen oder Abwehrspannung auftritt; Schmerz allein ist weniger spezifisch.","kw":[{"ziel":"Vordere Schulterinstabilität","sens":"65,6 %","spez":"95,4 %","lrp":"17,21","lrn":"0,39","basis":"Metaanalyse Hegedus 2012, 2 Studien, 409 Patienten"},{"ziel":"Vordere Instabilität, Apprehension und Relocation beide positiv","sens":"81 %","spez":"98 %","lrp":"39,68","lrn":"0,19","basis":"Farber, Einzelstudie in Hegedus 2012"}],"evidenz":"stark","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/"]},"lachman":{"name":"Lachman-Test","was":"Vordere Schublade bei 20–30° Beugung","einheit":"positiv oder negativ","kurz":"Der Untersucher zieht die Tibia bei leicht gebeugtem Knie nach vorn und beurteilt Weg und Endgefühl.","ziel":"Hinweis auf eine Ruptur des vorderen Kreuzbands gewinnen.","norm":["Positiv bei weichem Endgefühl und vermehrter vorderer Translation im Seitenvergleich.","Bester Einzeltest für das VKB: Sens. 81-85 %, Spez. 81-94 % (Benjaminse 2006; van Eck 2013; Sokal 2022). Neuere bivariate Auswertungen liegen niedriger, vor allem bei kompletten und älteren Rupturen (Sens. 68-70 %).","Bei frischem Trauma können Schwellung und Abwehrspannung die Beurteilung stören."],"normQuelle":"Q144","durch":"Patient in Rückenlage, Knie 20–30° gebeugt, unterstützt durch ein Handtuch oder das Knie des Untersuchers, Bein leicht außenrotiert. Eine Hand liegt hinter der Tibia, die andere am Oberschenkel, der Daumen an der Tuberositas tibiae. Der Untersucher zieht die Tibia nach vorn. Vorher das hintere Kreuzband prüfen, weil ein Riss das Ergebnis verfälscht.","weitere":["Q148"],"pos":"Positiv bei vermehrter vorderer Tibiatranslation im Seitenvergleich mit weichem Endgefühl.","kw":[{"ziel":"VKB-Ruptur","sens":"85 %","spez":"94 %","lrp":"14,2","lrn":"0,16","basis":"Metaanalyse, 28 Studien, heterogen (Benjaminse 2006); LR berechnet"},{"ziel":"VKB-Ruptur ohne Begleitverletzung der Bänder","sens":"81 %","spez":"85 %","lrp":"5,4","lrn":"0,22","basis":"Bivariate Metaanalyse (Sokal 2022); LR berechnet"},{"ziel":"Akute komplette VKB-Ruptur, Untersuchung ohne Narkose","sens":"81 %","spez":"81 %","lrp":"4,3","lrn":"0,23","basis":"Metaanalyse, 20 Studien (van Eck 2013); LR berechnet"}],"evidenz":"stark","quellen":["Benjaminse A et al. 2006, Clinical diagnosis of an anterior cruciate ligament rupture: a meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/16715828/","Sokal PA et al. 2022, The diagnostic accuracy of clinical tests for anterior cruciate ligament tears are comparable but the Lachman test has been previously overestimated. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/35150292/","van Eck CF et al. 2013, Methods to diagnose acute anterior cruciate ligament rupture: a meta-analysis of physical examinations with and without anaesthesia. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/23085822/","Décary S et al. 2017, Diagnostic validity of physical examination tests for common knee disorders. Phys Ther Sport – https://pubmed.ncbi.nlm.nih.gov/27693100/"]},"schublade":{"name":"Vordere Schublade","was":"Tibiaverschiebung nach vorn bei 90° Beugung","einheit":"positiv oder negativ","kurz":"Der Untersucher zieht die Tibia bei 90° gebeugtem Knie nach vorn und vergleicht mit der Gegenseite.","ziel":"Hinweis auf eine Ruptur des vorderen Kreuzbands gewinnen.","norm":["Positiv bei vermehrter vorderer Tibiatranslation im Seitenvergleich oder fehlendem festen Anschlag.","Bei chronischer Ruptur gut (Sens. 92 %, Spez. 91 %), bei frischer Verletzung ohne Narkose schwach (Sens. 38 %; Benjaminse 2006; van Eck 2013). Akut den Lachman bevorzugen."],"normQuelle":"Q148","durch":"Patient in Rückenlage, Hüfte 45° gebeugt, Knie 90°, Füße flach auf der Liege. Der Untersucher sitzt vor dem Knie und greift die Tibia unterhalb des Gelenkspalts, die Daumen liegen beidseits der Patellasehne. Die Tibia wird nach vorn gezogen.","weitere":["Q149"],"pos":"Positiv bei vermehrter vorderer Tibiatranslation in 90° Beugung im Seitenvergleich oder fehlendem festen Anschlag.","kw":[{"ziel":"VKB-Ruptur, chronisch","sens":"92 %","spez":"91 %","lrp":"10,2","lrn":"0,09","basis":"Metaanalyse (Benjaminse 2006), akut deutlich schlechter; LR berechnet"},{"ziel":"VKB-Ruptur ohne Begleitverletzung der Bänder","sens":"83 %","spez":"85 %","lrp":"5,5","lrn":"0,20","basis":"Bivariate Metaanalyse (Sokal 2022); LR berechnet"},{"ziel":"Akute komplette VKB-Ruptur, ohne Narkose","sens":"38 %","spez":"81 %","lrp":"2,0","lrn":"0,77","basis":"Metaanalyse, 20 Studien (van Eck 2013); LR berechnet"}],"evidenz":"stark","quellen":["Benjaminse A et al. 2006, Clinical diagnosis of an anterior cruciate ligament rupture: a meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/16715828/","van Eck CF et al. 2013, Methods to diagnose acute anterior cruciate ligament rupture: a meta-analysis of physical examinations with and without anaesthesia. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/23085822/","Sokal PA et al. 2022, The diagnostic accuracy of clinical tests for anterior cruciate ligament tears are comparable but the Lachman test has been previously overestimated. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/35150292/"]},"pivotshift":{"name":"Pivot-Shift-Test","was":"Subluxation bei Streckung bis Beugung","einheit":"positiv oder negativ","kurz":"Provokationstest für die Rotationsinstabilität bei VKB-Insuffizienz. Der Untersucher beobachtet die Tibiaposition während der Beugung.","ziel":"Hinweis auf eine VKB-Ruptur mit Instabilität gewinnen.","norm":["Positiv bei spürbarer Reposition der Tibia bei 30-40° Beugung.","Sehr spezifisch (94-98 %), aber wenig sensitiv (24-55 %): positiv bestätigt die Ruptur, negativ schließt sie nicht aus (Benjaminse 2006; Sokal 2022; Tanaka 2022).","Wach oft durch Abwehrspannung verhindert; in Narkose deutlich sensitiver (van Eck 2013)."],"normQuelle":"Q148","durch":"Patient in Rückenlage, Hüfte passiv auf 30° gebeugt und abduziert, damit der Tractus iliotibialis entspannt. Der Untersucher fasst Unterschenkel und Knöchel, hält 20° Tibiainnenrotation und lässt das Knie in volle Streckung sinken. Die andere Hand liegt nahe dem proximalen Tibiofibulargelenk und verstärkt die Innenrotation. Unter Innenrotation wird ein Valgusstress gegeben und das Knie langsam gebeugt.","weitere":["Q150"],"pos":"Positiv bei spürbarer Reposition der subluxierten Tibia bei etwa 30-40° Beugung unter Valgus und Innenrotation.","kw":[{"ziel":"VKB-Ruptur","sens":"24 %","spez":"98 %","lrp":"12,0","lrn":"0,78","basis":"Metaanalyse (Benjaminse 2006); LR berechnet"},{"ziel":"VKB-Ruptur ohne Begleitverletzung der Bänder","sens":"55 %","spez":"94 %","lrp":"9,2","lrn":"0,48","basis":"Bivariate Metaanalyse (Sokal 2022); LR berechnet"},{"ziel":"Akute VKB-Ruptur","sens":"55 %","spez":"96 %","lrp":"11,6","basis":"Metaanalyse, 8 Studien (Tanaka 2022)"},{"ziel":"Akute komplette VKB-Ruptur, in Narkose","sens":"73 %","spez":"98 %","lrp":"36,5","lrn":"0,28","basis":"Metaanalyse (van Eck 2013); ohne Narkose Sens. 28 %, Spez. 81 %; LR berechnet"}],"evidenz":"stark","quellen":["Benjaminse A et al. 2006, Clinical diagnosis of an anterior cruciate ligament rupture: a meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/16715828/","Sokal PA et al. 2022, The diagnostic accuracy of clinical tests for anterior cruciate ligament tears are comparable but the Lachman test has been previously overestimated. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/35150292/","Tanaka S et al. 2022, Diagnostic accuracy of physical examination tests for suspected acute anterior cruciate ligament injury: a systematic review and meta-analysis. Int J Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35949377/","van Eck CF et al. 2013, Methods to diagnose acute anterior cruciate ligament rupture: a meta-analysis of physical examinations with and without anaesthesia. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/23085822/"]},"mcmurray":{"name":"McMurray-Test","was":"Klick und Gelenkspaltschmerz bei Rotation","einheit":"positiv oder negativ","kurz":"Der Untersucher bewegt das Knie mit rotierter Tibia aus der Beugung in die Streckung und tastet den Gelenkspalt.","ziel":"Hinweis auf eine Meniskusläsion gewinnen.","norm":["Positiv bei tastbarem oder hörbarem Klick, der den vertrauten Gelenkspaltschmerz auslöst. Schmerz ohne Klick ist weniger spezifisch.","Eher zum Bestätigen als zum Ausschließen: Sens. 52-61 %, Spez. 84-97 % (Smith 2015; Jackson 2003)."],"normQuelle":"Q148","durch":"Rückenlage, Bein entspannt. Eine Hand hält die Ferse und steuert Beugung, Streckung und Tibiarotation, die andere liegt am Knie, Daumen am medialen, Finger am lateralen Gelenkspalt. Start in maximaler schmerzfreier Beugung, nicht erzwingen. Lateraler Meniskus: Tibia innenrotieren, Varusstress, Knie langsam strecken. Medialer Meniskus: wieder beugen, Tibia außenrotieren, Valgusstress, Knie langsam strecken. Dabei den Gelenkspalt tasten und nach Schmerz, Klick oder Einklemmung fragen.","weitere":["Q146"],"pos":"Positiv bei tastbarem oder hörbarem Klick, der den bekannten Gelenkspaltschmerz auslöst.","kw":[{"ziel":"Meniskusriss","sens":"61 %","spez":"84 %","lrp":"3,8","lrn":"0,46","basis":"Metaanalyse (Smith 2015), geringe Studienqualität; LR berechnet"},{"ziel":"Meniskusriss, Arthroskopie als Referenz","sens":"52 %","spez":"97 %","lrp":"17,3","lrn":"0,49","basis":"Systematische Übersicht (Jackson 2003); LR berechnet"}],"evidenz":"mäßig","quellen":["Smith BE et al. 2015, Special tests for assessing meniscal tears within the knee: a systematic review and meta-analysis. Evid Based Med – https://pubmed.ncbi.nlm.nih.gov/25724195/","Jackson JL et al. 2003, Evaluation of acute knee pain in primary care. Ann Intern Med – https://pubmed.ncbi.nlm.nih.gov/14530229/"]},"slr":{"name":"Straight Leg Raise (Lasègue)","was":"Beinanheben, Hinweis auf lumbale Wurzelreizung","einheit":"positiv oder negativ","kurz":"Das gestreckte Bein wird in Rückenlage passiv angehoben. Gefragt wird, ob Beinschmerz entsteht und bei welchem Winkel.","ziel":"Hinweis auf eine lumbale Radikulopathie gewinnen und im Verlauf vergleichen.","norm":["Positiv bei bekanntem Beinschmerz unterhalb des Knies, typisch zwischen 30° und 70° Hüftflexion.","Cochrane (van der Windt 2010): gepoolte Sens. 92 %, Spez. 28 %, fast nur operierte Kollektive. Mit Bildgebung als Referenz uneinheitlicher und weniger sensitiv.","Bei nicht operierten Patienten eher Sens. 52–69 %, Spez. 84–89 % (Suri 2011, Majlesi 2008). Allein wenig aussagekräftig, mit Neurostatus kombinieren."],"normQuelle":"Q153","durch":"Patient in Rückenlage, beide Beine gestreckt, kein Kissen unter dem Kopf. Das nicht betroffene Bein zuerst. Der Untersucher hebt das gestreckte Bein an der Ferse passiv an (Hüftbeugung), bis Symptome oder Spannung auftreten, notiert Winkel und Schmerzort. Zur Sensibilisierung kann Dorsalextension des Fußes oder Nackenflexion dazukommen. Die Zuverlässigkeit der Gradangabe ist niedrig.","weitere":["Q154"],"pos":"Positiv, wenn das passive Anheben des gestreckten Beins den bekannten Beinschmerz unterhalb des Knies auslöst.","kw":[{"ziel":"Radikulopathie bei Bandscheibenvorfall (operierte Kollektive)","sens":"92 %","spez":"28 %","lrp":"1,3","lrn":"0,29","basis":"Cochrane-Metaanalyse, operierte Kollektive (Prävalenz 58–98 %); LR berechnet"},{"ziel":"Wurzelkompression L5/S1 (MRT)","sens":"69 %","spez":"84 %","lrp":"4,3","lrn":"0,37","basis":"Einzelstudie, 54 Pat., Wirbelsäulenzentrum"},{"ziel":"Bandscheibenvorfall (MRT)","sens":"52 %","spez":"89 %","basis":"Einzelstudie, Fall-Kontroll-Design, 75 Pat."}],"evidenz":"stark","quellen":["van der Windt DA et al. 2010, Physical examination for lumbar radiculopathy due to disc herniation in patients with low-back pain. Cochrane Database Syst Rev – https://pubmed.ncbi.nlm.nih.gov/20166095/","Suri P et al. 2011, The accuracy of the physical examination for the diagnosis of midlumbar and low lumbar nerve root impingement. Spine – https://pubmed.ncbi.nlm.nih.gov/20543768/","Majlesi J et al. 2008, The sensitivity and specificity of the Slump and the Straight Leg Raising tests in patients with lumbar disc herniation. J Clin Rheumatol – https://pubmed.ncbi.nlm.nih.gov/18391677/","Bundesärztekammer, KBV, AWMF 2017, Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Auflage (Lasègue als Basisuntersuchung) – https://www.leitlinien.de/themen/kreuzschmerz"]},"slump":{"name":"Slump-Test","was":"Neurodynamik im Sitzen","einheit":"positiv oder negativ","kurz":"Im Sitzen wird die Wirbelsäule gebeugt, dann Knie gestreckt und Fuß dorsal extendiert. Gefragt wird nach ischialgiformem Schmerz.","ziel":"Hinweis auf eine neurale Mechanosensitivität des N. ischiadicus gewinnen.","norm":["Positiv bei Reproduktion des bekannten ausstrahlenden Beinschmerzes, der sich bei Lösen der Nackenflexion bessert.","Bandscheibenvorfall (MRT): Sens. 84 %, Spez. 83 % (Majlesi 2008, 75 Pat.); im selben Kollektiv SLR Sens. 52 %, Spez. 89 %.","Neuropathischer Schmerz: Sens. 91 %, Spez. 70 %; mit Kriterium Schmerz unterhalb des Knies Spez. 100 % (Urban 2015, nur 21 Pat.). Kleine Studien, mit SLR und Neurostatus kombinieren."],"normQuelle":"Q151","durch":"Patient sitzt am Rand der Liege. Er sackt mit dem Rumpf nach vorn (Schultern gerundet), der Untersucher gibt dem Rumpf leichten Druck. Dann Kinn zur Brust, das Knie wird aktiv gestreckt, der Fuß dorsal extendiert. Bei Schmerz muss der Test nicht weitergeführt werden.","pos":"Positiv, wenn im Slump der bekannte ausstrahlende Beinschmerz auftritt und durch Lösen der Nackenflexion nachlässt.","kw":[{"ziel":"Lumbaler Bandscheibenvorfall (MRT)","sens":"84 %","spez":"83 %","lrp":"4,9","lrn":"0,19","basis":"Einzelstudie, Fall-Kontroll-Design, 75 Pat.; LR berechnet"},{"ziel":"Neuropathischer Beinschmerz bei Kreuzschmerz","sens":"91 %","spez":"70 %","lrp":"3,0","lrn":"0,13","basis":"Einzelstudie, 21 Pat., Referenz neurosensorische Untersuchung"},{"ziel":"Neuropathischer Beinschmerz, Kriterium Schmerz unterhalb des Knies","spez":"100 %","lrp":"11,9","basis":"Einzelstudie, 21 Pat."}],"evidenz":"mäßig","quellen":["Majlesi J et al. 2008, The sensitivity and specificity of the Slump and the Straight Leg Raising tests in patients with lumbar disc herniation. J Clin Rheumatol – https://pubmed.ncbi.nlm.nih.gov/18391677/","Urban LM et al. 2015, Diagnostic accuracy of the Slump test for identifying neuropathic pain in the lower limb. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/26107044/","van der Windt DA et al. 2010, Physical examination for lumbar radiculopathy due to disc herniation in patients with low-back pain. Cochrane Database Syst Rev – https://pubmed.ncbi.nlm.nih.gov/20166095/"]},"spurling":{"name":"Spurling-Test A","was":"Kompression bei seitgeneigtem Nacken","einheit":"positiv oder negativ","kurz":"Der Nacken wird zur betroffenen Seite geneigt und der Untersucher gibt leichten Überdruck. Gefragt wird, ob der vertraute Armschmerz zunimmt.","ziel":"Hinweis auf eine zervikale Radikulopathie gewinnen.","norm":["Hoch spezifisch (84–100 %), Sensitivität stark schwankend (38–98 %) über fünf Studien (Thoomes 2026). Nur Ausstrahlung in den Arm werten, Nackenschmerz allein macht den Test unspezifisch (Grondin 2026: Spez. 59 % bei Nackenschmerz, 98 % bei Armschmerz).","Spurling A nach Wainner 2003: Sens. 50 %, Spez. 86 %.","Wainner-Cluster (Spurling, Distraktion, ULTT A, Rotation unter 60°): 4 von 4 positiv LR+ 30,3 (Wainner 2003); in der externen Validierung 3 von 4 positiv LR+ 7,7 (Grondin 2026)."],"normQuelle":"Q152","durch":"Patient sitzt. Der Nacken wird zur betroffenen Seite geneigt, der Untersucher gibt Überdruck von etwa 7 kg. Eine zweite Quelle beschreibt zusätzlich Extension und axialen Druck, um das Foramen zu verengen.","weitere":["Q133"],"pos":"Positiv, wenn Seitneigung zur betroffenen Seite mit axialem Druck den bekannten Armschmerz auslöst oder verstärkt.","kw":[{"ziel":"Zervikale Radikulopathie (Spurling A, ohne Rotation/Extension)","sens":"50 %","spez":"86 %","lrp":"3,6","lrn":"0,58","basis":"Wainner 2003, 82 Patienten, EMG als Referenz, zitiert in Rubinstein 2007; LR berechnet"},{"ziel":"Zervikale Radikulopathie, Spannweite über Studien","sens":"38–98 %","spez":"84–100 %","basis":"Systematische Übersicht Thoomes 2026, 5 Studien mit Bildgebung als Referenz, Varianten nicht poolbar"},{"ziel":"Zervikale Radikulopathie (Spurling mit Armschmerz als Kriterium)","sens":"59 %","spez":"98 %","lrp":"34,4","lrn":"0,41","basis":"Grondin 2026, 85 Patienten"}],"evidenz":"mäßig","quellen":["Thoomes EJ et al. 2026, Diagnostic accuracy of physical examination tests for painful cervical radiculopathy: update of a systematic review and meta-analysis. BMC Musculoskelet Disord – https://pmc.ncbi.nlm.nih.gov/articles/PMC13088722/","Rubinstein SM et al. 2007, A systematic review of the diagnostic accuracy of provocative tests of the neck for diagnosing cervical radiculopathy. Eur Spine J – https://pmc.ncbi.nlm.nih.gov/articles/PMC2200707/","Wainner RS et al. 2003, Reliability and diagnostic accuracy of the clinical examination for cervical radiculopathy. Spine – https://pubmed.ncbi.nlm.nih.gov/12544957/","Grondin F et al. 2026, An independent validation of a clinical prediction rule for cervical radiculopathy. Braz J Phys Ther – https://pubmed.ncbi.nlm.nih.gov/42070317/"]},"ultt":{"name":"ULTT A (Medianus)","was":"Nervendehnung des Arms","einheit":"positiv oder negativ","kurz":"Der Arm wird in einer Folge von Positionen angespannt (Schulter, Ellbogen, Handgelenk, Finger) und der Nacken zur Gegenseite geneigt.","ziel":"Hinweis auf eine zervikale Radikulopathie gewinnen; vor allem zum Ausschluss.","norm":["ULNT 1 gepoolt: Sens. 70 %, Spez. 71 % (Thoomes 2026, 3 Studien). Wainner 2003: Sens. 97 %, Spez. 22 %.","Am besten zum Ausschluss: Sind alle vier ULNT (Medianus 1 und 2a, Radialis, Ulnaris) negativ, ist eine Radikulopathie unwahrscheinlich (LR− 0,06)."],"normQuelle":"Q152","durch":"Patient in Rückenlage. Schulter niederdrücken, auf 110° abduzieren und außenrotieren, Unterarm supinieren, Handgelenk und Finger strecken, dann den Ellbogen langsam strecken. Zur Bestätigung etwas Ellbogenspannung lösen und den Nacken zur Gegenseite neigen lassen. Eine zweite Quelle beschreibt ihn mit 90° Abduktion.","weitere":["Q133"],"pos":"Positiv bei Reproduktion der Armbeschwerden, Seitendifferenz über 10° Ellbogenextension oder Symptomänderung durch Seitneigung der HWS zur Gegenseite.","kw":[{"ziel":"Zervikale Radikulopathie (ULNT 1, Medianus)","sens":"70 %","spez":"71 %","lrp":"2,45","lrn":"0,42","basis":"Metaanalyse Thoomes 2026, 3 Studien, Bildgebung als Referenz, sehr geringe Vertrauenswürdigkeit"},{"ziel":"Zervikale Radikulopathie (mindestens 1 von 4 ULNT positiv)","sens":"97 %","spez":"51 %","lrp":"1,99","lrn":"0,06","basis":"Metaanalyse Thoomes 2026, 2 Studien"},{"ziel":"Zervikale Radikulopathie (ULTT A, Wainner)","sens":"97 %","spez":"22 %","lrp":"1,24","lrn":"0,14","basis":"Wainner 2003, EMG als Referenz, zitiert in Rubinstein 2007; LR berechnet"}],"evidenz":"stark","quellen":["Thoomes EJ et al. 2026, Diagnostic accuracy of physical examination tests for painful cervical radiculopathy: update of a systematic review and meta-analysis. BMC Musculoskelet Disord – https://pmc.ncbi.nlm.nih.gov/articles/PMC13088722/","Rubinstein SM et al. 2007, A systematic review of the diagnostic accuracy of provocative tests of the neck for diagnosing cervical radiculopathy. Eur Spine J – https://pmc.ncbi.nlm.nih.gov/articles/PMC2200707/","Wainner RS et al. 2003, Reliability and diagnostic accuracy of the clinical examination for cervical radiculopathy. Spine – https://pubmed.ncbi.nlm.nih.gov/12544957/"]},"distraktion":{"name":"Distraktionstest","was":"Längszug am Kopf","einheit":"positiv oder negativ","kurz":"Der Untersucher zieht in Rückenlage mit den Fingern unter dem Hinterkopf in Längsrichtung. Gefragt wird, ob der Armschmerz nachlässt.","ziel":"Hinweis auf eine zervikale Radikulopathie gewinnen; bestätigend.","norm":["Positiv bei Abnahme des Armschmerzes; nur bei aktuellem Armschmerz sinnvoll.","Zwei ältere Studien sehen den Test als spezifisch (Spez. 90–97 %, Sens. 33–44 %), die neuere Validierung findet das Gegenteil (Sens. 89 %, Spez. 38 %, Grondin 2026). Die Werte sind also unsicher."],"normQuelle":"Q152","durch":"Patient in Rückenlage. Der Untersucher hakt die Finger unter das Hinterhaupt und gibt Längszug.","pos":"Positiv, wenn der Längszug am Kopf den bekannten Armschmerz verringert.","kw":[{"ziel":"Zervikale Radikulopathie","sens":"44 %","spez":"90 %","lrp":"4,4","lrn":"0,62","basis":"Wainner 2003, EMG als Referenz, zitiert in Rubinstein 2007; LR berechnet"},{"ziel":"Zervikale Radikulopathie (axiale Traktion)","sens":"33 %","spez":"97 %","lrp":"11,0","lrn":"0,69","basis":"Viikari-Juntura 1989, Myelografie als Referenz, zitiert in Thoomes 2026"},{"ziel":"Zervikale Radikulopathie","sens":"89 %","spez":"38 %","lrp":"1,43","lrn":"0,29","basis":"Grondin 2026, 85 Patienten, MRT plus Klinik"}],"evidenz":"mäßig","quellen":["Rubinstein SM et al. 2007, A systematic review of the diagnostic accuracy of provocative tests of the neck for diagnosing cervical radiculopathy. Eur Spine J – https://pmc.ncbi.nlm.nih.gov/articles/PMC2200707/","Thoomes EJ et al. 2026, Diagnostic accuracy of physical examination tests for painful cervical radiculopathy. BMC Musculoskelet Disord – https://pmc.ncbi.nlm.nih.gov/articles/PMC13088722/","Grondin F et al. 2026, An independent validation of a clinical prediction rule for cervical radiculopathy. Braz J Phys Ther – https://pubmed.ncbi.nlm.nih.gov/42070317/"]},"rotation60":{"name":"HWS-Rotation zur betroffenen Seite","was":"Rotationswinkel unter 60°","einheit":"positiv oder negativ","kurz":"Die aktive Rotation zur betroffenen Seite wird in Grad gemessen. Unter 60° gilt im Cluster als positiv.","ziel":"Hinweis auf eine zervikale Radikulopathie gewinnen; vor allem zum Ausschluss.","norm":["Positiv bei weniger als 60° Rotation zur betroffenen Seite.","Als Einzeltest kaum aussagekräftig: Sens. 63 %, Spez. 50 % (Grondin 2026). Nutzen nur im Wainner-Cluster: 3 von 4 positiv LR+ 7,7 (Grondin 2026); 4 von 4 positiv LR+ 30,3 (Wainner 2003)."],"normQuelle":"Q152","durch":"Der Patient dreht den Kopf aktiv zur betroffenen Seite. Gemessen wird am besten mit Inklinometer oder CROM-Gerät.","pos":"Positiv bei aktiver Rotation zur betroffenen Seite unter 60°.","kw":[{"ziel":"Zervikale Radikulopathie (Einzeltest)","sens":"63 %","spez":"50 %","lrp":"1,26","lrn":"0,74","basis":"Grondin 2026, 85 Patienten, MRT plus Klinik als Referenz"},{"ziel":"Zervikale Radikulopathie, Wainner-Cluster 4 von 4 positiv","lrp":"30,3","basis":"Wainner 2003, 82 Patienten, EMG als Referenz; sehr breites Konfidenzintervall"},{"ziel":"Wainner-Cluster 3 von 4 positiv (externe Validierung)","sens":"68 %","spez":"91 %","lrp":"7,73","lrn":"0,35","basis":"Grondin 2026, 85 Patienten"}],"evidenz":"mäßig","quellen":["Wainner RS et al. 2003, Reliability and diagnostic accuracy of the clinical examination and patient self-report measures for cervical radiculopathy. Spine – https://pubmed.ncbi.nlm.nih.gov/12544957/","Grondin F et al. 2026, An independent validation of a clinical prediction rule for the diagnosis of cervical radiculopathy with radicular pain. Braz J Phys Ther – https://pubmed.ncbi.nlm.nih.gov/42070317/"]},"oeffnungsbahn":{"name":"Öffnungsbahn (Deviation/Deflexion)","was":"Asymmetrische Mundöffnung, Diskus- oder Muskelproblem","einheit":"positiv oder negativ","kurz":"Patient öffnet langsam maximal, Therapeut beobachtet die Unterkiefermitte gegenüber der Oberkiefermitte.","ziel":"Seitabweichung der Öffnungsbahn erkennen.","norm":["Positiv bei mehr als 2 mm Seitabweichung der Inzisalmitte beim Öffnen (Item des CMD-Kurzbefunds nach Ahlers/Jakstat).","Für das Einzelzeichen keine Kennwerte gefunden. Der gesamte CMD-Kurzbefund (ab 2 von 6 Befunden positiv) erreichte gegen DC/TMD Sens. 73,8 %, Spez. 75,0 % (Faulhaber 2026, 121 Patienten).","Die DC/TMD verwenden die Abweichung beim Öffnen nicht mehr als Kriterium für eine Diskusverlagerung, weil sie nicht regelmäßig vorkommt."],"durch":"Sitz, Kopf aufrecht, Zähne locker in Schlussbiss. Der Patient öffnet langsam so weit wie möglich und schließt wieder, mehrmals. Beobachtet wird die Inzisalmitte: Deviation (S-förmig, zurück zur Mitte) oder Deflexion (bleibende Abweichung zur Seite). Positiv ab mehr als 2 mm Abweichung.","position":"Sitz","quellen":["Faulhaber RM et al. 2026, Prospective clinical validation of an optimized TMD screening tool. Clin Oral Investig – https://pubmed.ncbi.nlm.nih.gov/42435088/","Schiffman E et al. 2014, Diagnostic Criteria for Temporomandibular Disorders (DC/TMD). J Oral Facial Pain Headache – https://pubmed.ncbi.nlm.nih.gov/24482784/","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP online, Zusatzquelle) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf"],"pos":"Positiv, wenn der Unterkiefer beim Öffnen mehr als 2 mm zu einer Seite oder nacheinander zu beiden Seiten abweicht.","evidenz":"keine"},"mundoeffnung":{"name":"Maximale Mundöffnung","was":"Eingeschränkte Mundöffnung, Diskusverlagerung ohne Reposition","einheit":"positiv oder negativ","kurz":"Schneidekantendistanz bei maximaler aktiver und passiv unterstützter Öffnung mit Lineal messen.","ziel":"Bewegungseinschränkung des Kiefers objektivieren.","norm":["DC/TMD: assistierte Öffnung (passive Dehnung) unter 40 mm inkl. vertikalem Überbiss bei Kieferklemme in der Anamnese spricht für Diskusverlagerung ohne Reposition mit eingeschränkter Öffnung: Sens. 80 %, Spez. 97 % (Schiffman 2014).","Der CMD-Kurzbefund wertet eine Schneidekantendistanz deutlich unter 38 mm als positiv.","Das Kriterium gilt nur zusammen mit der Anamnese (Kiefer blockiert, Essen behindert); die Messung allein ist kein validierter Test."],"durch":"Sitz. Der Patient öffnet maximal, gemessen wird die Distanz zwischen den Schneidekanten der oberen und unteren mittleren Inzisivi plus vertikalem Überbiss. Danach unterstützt der Therapeut die Öffnung passiv mit Daumen und Zeigefinger (assistierte Öffnung). Positiv bei weniger als 40 mm assistierter Öffnung; Schmerz dabei zusätzlich notieren.","position":"Sitz","quellen":["Schiffman E et al. 2014, Diagnostic Criteria for Temporomandibular Disorders (DC/TMD). J Oral Facial Pain Headache – https://pmc.ncbi.nlm.nih.gov/articles/PMC4478082/","Schiffman E et al. 2016, Executive Summary of the DC/TMD. J Am Dent Assoc – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471/","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP online, Zusatzquelle) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf","Schiffman 2014 (DC/TMD) – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471"],"pos":"Positiv, wenn die maximale assistierte Öffnung einschließlich vertikalem Überbiss unter 40 mm liegt.","kw":[{"ziel":"Diskusverlagerung ohne Reposition mit eingeschränkter Öffnung (DC/TMD-Kriterium mit Anamnese)","sens":"80 %","spez":"97 %","lrp":"26,7","lrn":"0,21","basis":"DC/TMD-Validierungsprojekt, MRT als Referenz; LR berechnet"},{"ziel":"Diskusverlagerung ohne Reposition ohne eingeschränkte Öffnung (≥ 40 mm)","sens":"54 %","spez":"79 %","basis":"DC/TMD-Validierungsprojekt, nur als Screening geeignet"}],"evidenz":"mäßig"},"gelenkgeraeusche":{"name":"Kiefergelenkgeräusche","was":"Diskusverlagerung mit Reposition, Arthrose","einheit":"positiv oder negativ","kurz":"Beim Öffnen und Schließen die Kiefergelenke palpieren und auf Knacken oder Reiben achten.","ziel":"Gelenkgeräusche als Hinweis auf Diskus- oder Gelenkflächenveränderung erfassen.","norm":["Knacken: Diskusverlagerung mit Reposition Sens. 34 %, Spez. 92 %. Krepitation: degenerative Gelenkerkrankung Sens. 55 %, Spez. 61 % (Schiffman 2014).","Ohne Geräusch ist eine Diskusverlagerung nicht ausgeschlossen; beide Kriterien taugen laut DC/TMD nur zum Screening, die Bestätigung erfolgt per Bildgebung."],"durch":"Sitz. Der Therapeut legt die Zeigefinger direkt vor dem Tragus auf beide Kiefergelenke. Der Patient öffnet und schließt mehrfach und bewegt den Unterkiefer zur Seite und nach vorn. Positiv bei tastbarem oder hörbarem Knacken oder Reiben. Geräusche allein sind kein Behandlungsgrund.","position":"Sitz","quellen":["Schiffman E et al. 2014, Diagnostic Criteria for Temporomandibular Disorders (DC/TMD). J Oral Facial Pain Headache – https://pmc.ncbi.nlm.nih.gov/articles/PMC4478082/","Schiffman E et al. 2016, Executive Summary of the DC/TMD. J Am Dent Assoc – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471/","Schiffman 2014 (DC/TMD) – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP 2015) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf"],"pos":"Positiv bei Knacken beim Öffnen und Schließen (Hinweis auf Diskusverlagerung mit Reposition) oder bei Reiben/Krepitation (Hinweis auf degenerative Gelenkerkrankung).","kw":[{"ziel":"Diskusverlagerung mit Reposition (Knacken)","sens":"34 %","spez":"92 %","lrp":"4,3","lrn":"0,72","basis":"DC/TMD-Validierungsprojekt, MRT als Referenz; LR berechnet"},{"ziel":"Degenerative Gelenkerkrankung (Krepitation)","sens":"55 %","spez":"61 %","lrp":"1,4","lrn":"0,74","basis":"DC/TMD-Validierungsprojekt, CT als Referenz; LR berechnet"}],"evidenz":"mäßig"},"okklgeraeusche":{"name":"Okklusale Geräusche","was":"Ungleichmäßige Zahnkontakte beim Zubeißen","einheit":"positiv oder negativ","kurz":"Patient beißt mehrmals kräftig auf die Seitenzähne, Therapeut achtet auf das Klopfgeräusch.","ziel":"Hinweis auf okklusale Störungen als CMD-Faktor.","norm":["Positiv bei mehrzeitigem Okklusionsgeräusch (Item des CMD-Kurzbefunds).","Für das Einzelzeichen keine Kennwerte gefunden; nur der gesamte Kurzbefund ist validiert (Sens. 73,8 %, Spez. 75,0 % gegen DC/TMD, Faulhaber 2026). Kein Bestandteil der DC/TMD."],"durch":"Sitz, Mund leicht geöffnet. Der Patient klappert mehrmals zügig auf die Zähne. Ein gesundes Gebiss erzeugt ein helles, einzelnes Klopfgeräusch. Mehrphasige oder dumpfe Geräusche deuten auf ungleichmäßige Kontakte; die weitere Abklärung erfolgt zahnärztlich.","position":"Sitz","quellen":["Faulhaber RM et al. 2026, Prospective clinical validation of an optimized TMD screening tool. Clin Oral Investig – https://pubmed.ncbi.nlm.nih.gov/42435088/","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP online, Zusatzquelle) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf"],"pos":"Positiv, wenn beim kräftigen Zusammenbeißen ein mehrzeitiges statt eines einzelnen, klaren Okklusionsgeräuschs entsteht.","evidenz":"keine"},"palpkaumuskel":{"name":"Palpation Kaumuskulatur","was":"Myalgie des M. masseter und temporalis","einheit":"positiv oder negativ","kurz":"M. masseter, M. temporalis (anterior) und hinteren Digastricus mit standardisiertem Druck palpieren.","ziel":"Muskulär bedingten Kieferschmerz nachweisen.","norm":["Positiv bei bekanntem Schmerz (familiar pain) bei Palpation von Masseter oder Temporalis; Druck etwa 1 kg für 2 Sekunden, für Übertragungsschmerz 5 Sekunden (DC/TMD).","Myalgie nach DC/TMD: Sens. 90 %, Spez. 99 %; myofaszialer Schmerz mit Übertragung: Sens. 86 %, Spez. 98 % (Schiffman 2014). Reliabilität der Schmerzdiagnosen Kappa ≥ 0,85.","Die Werte gelten für das ganze Kriterium inklusive Anamnese, nicht für die Palpation allein."],"durch":"Sitz, Kiefer entspannt. Der Therapeut palpiert M. masseter (Ursprung, Bauch, Ansatz) und M. temporalis anterior mit gleichmäßigem Druck (im DC/TMD-Protokoll etwa 1 kg) für einige Sekunden. Gefragt wird, ob der Schmerz bekannt ist und ob er ausstrahlt. Positiv bei Reproduktion des bekannten Schmerzes.","position":"Sitz","quellen":["Schiffman E et al. 2014, Diagnostic Criteria for Temporomandibular Disorders (DC/TMD). J Oral Facial Pain Headache – https://pmc.ncbi.nlm.nih.gov/articles/PMC4478082/","Schiffman E et al. 2016, Executive Summary of the DC/TMD. J Am Dent Assoc – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471/","Schiffman 2014 (DC/TMD) – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP 2015) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf"],"pos":"Positiv, wenn die Palpation von M. masseter oder M. temporalis den bekannten Schmerz des Patienten auslöst.","kw":[{"ziel":"Myalgie (DC/TMD-Kriterium: Anamnese plus bekannter Schmerz bei Palpation oder Öffnung)","sens":"90 %","spez":"99 %","lrp":"90","lrn":"0,10","basis":"DC/TMD-Validierungsprojekt; LR berechnet"},{"ziel":"Myofaszialer Schmerz mit Übertragung","sens":"86 %","spez":"98 %","lrp":"43","lrn":"0,14","basis":"DC/TMD-Validierungsprojekt; LR berechnet"}],"evidenz":"mäßig"},"palpkiefergelenk":{"name":"Palpation Kiefergelenk","was":"Arthralgie des Kiefergelenks","einheit":"positiv oder negativ","kurz":"Lateralen Kondylenpol vor dem Tragus palpieren, auch während leichter Protrusion.","ziel":"Gelenkbedingten Kieferschmerz nachweisen.","norm":["Positiv bei bekanntem Schmerz bei Palpation des lateralen Pols oder um den Pol herum.","Arthralgie nach DC/TMD: Sens. 89 %, Spez. 98 % (Schiffman 2014); gilt für das ganze Kriterium inklusive Anamnese."],"durch":"Sitz. Der Therapeut tastet den lateralen Kondylenpol direkt vor dem Tragus, bei leicht geöffnetem Mund oder Protrusion. Druck geringer als bei der Muskulatur (im DC/TMD-Protokoll etwa 0,5 kg). Positiv bei bekanntem Schmerz; Seitenvergleich.","position":"Sitz","quellen":["Schiffman E et al. 2014, Diagnostic Criteria for Temporomandibular Disorders (DC/TMD). J Oral Facial Pain Headache – https://pmc.ncbi.nlm.nih.gov/articles/PMC4478082/","Schiffman E et al. 2016, Executive Summary of the DC/TMD. J Am Dent Assoc – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471/","Schiffman 2014 (DC/TMD) – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471"],"pos":"Positiv, wenn Druck auf den lateralen Kondylenpol oder um ihn herum den bekannten Schmerz auslöst.","kw":[{"ziel":"Arthralgie (DC/TMD-Kriterium: Anamnese plus bekannter Schmerz bei Palpation oder Kieferbewegung)","sens":"89 %","spez":"98 %","lrp":"44,5","lrn":"0,11","basis":"DC/TMD-Validierungsprojekt; LR berechnet"}],"evidenz":"mäßig"},"gangbild":{"name":"Gangbild/Tandemgang","was":"Gangstörung bei zervikaler Myelopathie","einheit":"positiv oder negativ","kurz":"Normales Gehen und Seiltänzergang beobachten.","ziel":"Gangunsicherheit als Myelopathie-Zeichen erfassen.","norm":["Einzeln: Gangabweichung Sens. 19 %, Spez. 94 % (Cook 2010); Tandemgang Sens. 66 %, Spez. 84 % (Einzelstudie).","Cluster (Cook 2010): ab 3 von 5 positiv LR+ 30,9; höchstens 1 von 5 positiv LR− 0,18. Der Cluster ist nicht extern validiert, das Konfidenzintervall ist sehr breit."],"durch":"Stand. Der Patient geht einige Meter in normalem Tempo, danach Fuß vor Fuß auf einer Linie. Beobachtet werden Spurbreite, Rhythmus, Steifigkeit und Gleichgewicht. Positiv bei breitbasigem, ataktischem oder spastischem Gangbild.","position":"Stand","quellen":["Cook C et al. 2010, Clustered clinical findings for diagnosis of cervical spine myelopathy. J Man Manip Ther – https://pubmed.ncbi.nlm.nih.gov/22131790/","Sharma S et al. 2025, Clinical signs and symptoms for degenerative cervical myelopathy: a scoping review. Spinal Cord – https://pmc.ncbi.nlm.nih.gov/articles/PMC11906348/","Jiang Z et al. 2024, The value of clinical signs in the diagnosis of degenerative cervical myelopathy. Global Spine J – https://pubmed.ncbi.nlm.nih.gov/37903098/","Cook 2010 – https://www.physiotutors.com/wiki/cervical-myelopathy-cluster"],"pos":"Positiv bei breitbasigem, ataktischem oder spastischem Gang oder Unsicherheit im Seiltänzergang.","kw":[{"ziel":"Zervikale Myelopathie (Gangabweichung)","sens":"19 %","spez":"94 %","lrp":"3,2","lrn":"0,86","basis":"Cook 2010, 249 Patienten mit HWS-Beschwerden, zitiert in Sharma 2025; LR berechnet"},{"ziel":"Zervikale Myelopathie (Tandemgang)","sens":"66 %","spez":"84 %","lrp":"4,1","lrn":"0,40","basis":"Einzelstudie (Soufi), zitiert in Sharma 2025; LR berechnet"},{"ziel":"Zervikale Myelopathie, Cluster nach Cook 2010 (Gang, Hoffmann, inverses Supinatorzeichen, Babinski, Alter > 45): ab 3 von 5","lrp":"30,9 (5,5–181,8)","basis":"Cook 2010, 249 Patienten"},{"ziel":"Cluster nach Cook 2010: höchstens 1 von 5","lrn":"0,18 (0,12–0,42)","basis":"Cook 2010, 249 Patienten"}],"evidenz":"mäßig"},"hoffmann":{"name":"Hoffmann-Zeichen","was":"Pyramidenbahnzeichen, zervikale Myelopathie","einheit":"positiv oder negativ","kurz":"Endglied des Mittelfingers schnell nach palmar schnipsen und Daumen/Zeigefinger beobachten.","ziel":"Läsion des ersten Motoneurons erkennen.","norm":["In Studien mit Patienten mit Nackenbeschwerden als Kontrollgruppe nur schwach: Sens. 31–44 %, Spez. 73–74 % (Cook 2009, 2010). Studien mit gesunden Kontrollen zeigen deutlich höhere Werte.","Ein negativer Hoffmann schließt eine Myelopathie nicht aus; Bestandteil des Clusters nach Cook 2010."],"durch":"Sitz, Hand entspannt, Handgelenk leicht extendiert. Der Therapeut hält den Mittelfinger im Mittelglied und schnippt den Fingernagel des Endglieds nach palmar. Positiv bei Flexion/Adduktion von Daumen und Zeigefinger. Seitenvergleich.","position":"Sitz","quellen":["Cook C et al. 2009, Reliability and diagnostic accuracy of clinical special tests for myelopathy. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19252263/","Cook C et al. 2010, Clustered clinical findings for diagnosis of cervical spine myelopathy. J Man Manip Ther – https://pubmed.ncbi.nlm.nih.gov/22131790/","Sharma S et al. 2025, Clinical signs and symptoms for degenerative cervical myelopathy: a scoping review. Spinal Cord – https://pmc.ncbi.nlm.nih.gov/articles/PMC11906348/","Cook 2010 – https://www.physiotutors.com/wiki/cervical-myelopathy-cluster"],"pos":"Positiv bei reflektorischer Beugung und Adduktion von Daumen und Zeigefinger nach dem Schnippen am Mittelfinger-Endglied.","kw":[{"ziel":"Zervikale Myelopathie","sens":"44 %","spez":"74 %","lrp":"1,7","lrn":"0,76","basis":"Cook 2009, Patienten mit HWS-Beschwerden, zitiert in Sharma 2025; LR berechnet"},{"ziel":"Zervikale Myelopathie","sens":"31 %","spez":"73 %","lrp":"1,1","lrn":"0,95","basis":"Cook 2010, 249 Patienten, zitiert in Sharma 2025; LR berechnet"},{"ziel":"Zervikale Myelopathie, Spannweite über Studien","sens":"31–89 %","spez":"41–100 %","basis":"Scoping Review Sharma 2025, 10 Studien mit sehr unterschiedlichen Kontrollgruppen"}],"evidenz":"mäßig"},"supinatorzeichen":{"name":"Inverses Supinatorzeichen","was":"Myelopathie auf Höhe C5/C6","einheit":"positiv oder negativ","kurz":"Sehne des M. brachioradialis am distalen Radius beklopfen.","ziel":"Pathologische Reflexantwort als Myelopathie-Zeichen erkennen.","norm":["Eher spezifisch als sensitiv: Spez. 78–99 %, Sens. 18–75 % in vier Studien (Sharma 2025).","Bestandteil des Myelopathie-Clusters nach Cook 2010."],"durch":"Sitz, Unterarm entspannt in Mittelstellung auf dem Oberschenkel. Der Therapeut beklopft die Sehne des M. brachioradialis knapp proximal des Processus styloideus radii. Positiv, wenn die Finger beugen und die normale Ellbogenbeugung ausbleibt oder schwach ist.","position":"Sitz","quellen":["Cook C et al. 2009, Reliability and diagnostic accuracy of clinical special tests for myelopathy. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19252263/","Cook C et al. 2010, Clustered clinical findings for diagnosis of cervical spine myelopathy. J Man Manip Ther – https://pubmed.ncbi.nlm.nih.gov/22131790/","Sharma S et al. 2025, Clinical signs and symptoms for degenerative cervical myelopathy: a scoping review. Spinal Cord – https://pmc.ncbi.nlm.nih.gov/articles/PMC11906348/","Cook 2010 – https://www.physiotutors.com/wiki/cervical-myelopathy-cluster"],"pos":"Positiv, wenn beim Beklopfen der Brachioradialissehne die Finger beugen und die Ellbogenbeugung fehlt oder abgeschwächt ist.","kw":[{"ziel":"Zervikale Myelopathie","sens":"61 %","spez":"78 %","lrp":"2,8","lrn":"0,50","basis":"Cook 2009, zitiert in Sharma 2025 und Jiang 2024; LR berechnet"},{"ziel":"Zervikale Myelopathie","sens":"18 %","spez":"99 %","lrp":"18","lrn":"0,83","basis":"Cook 2010, 249 Patienten, zitiert in Sharma 2025; LR berechnet"},{"ziel":"Zervikale Myelopathie, Spannweite über Studien","sens":"18–75 %","spez":"78–99 %","basis":"Scoping Review Sharma 2025, 4 Studien"}],"evidenz":"mäßig"},"babinski":{"name":"Babinski-Zeichen","was":"Pyramidenbahnzeichen, Läsion erstes Motoneuron","einheit":"positiv oder negativ","kurz":"Lateralen Fußsohlenrand von der Ferse bis zum Großzehenballen bestreichen.","ziel":"Zentrale neurologische Störung erkennen.","norm":["Sehr spezifisch (93–100 %), aber wenig sensitiv (7–44 %): positiv spricht stark für eine Läsion des ersten Motoneurons, negativ schließt nichts aus.","Cook 2009: höchster LR+ der Einzeltests (4,0); Bestandteil des Clusters nach Cook 2010."],"durch":"Rückenlage, Bein entspannt. Mit einem stumpfen Gegenstand wird der laterale Fußsohlenrand von der Ferse nach distal und dann quer zum Großzehenballen bestrichen. Normal ist eine Plantarflexion der Zehen. Positiv bei tonischer Dorsalextension der Großzehe.","position":"Rückenlage","quellen":["Cook C et al. 2009, Reliability and diagnostic accuracy of clinical special tests for myelopathy. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19252263/","Cook C et al. 2010, Clustered clinical findings for diagnosis of cervical spine myelopathy. J Man Manip Ther – https://pubmed.ncbi.nlm.nih.gov/22131790/","Sharma S et al. 2025, Clinical signs and symptoms for degenerative cervical myelopathy: a scoping review. Spinal Cord – https://pmc.ncbi.nlm.nih.gov/articles/PMC11906348/","Cook 2010 – https://www.physiotutors.com/wiki/cervical-myelopathy-cluster"],"pos":"Positiv bei tonischer Dorsalextension der Großzehe, oft mit Spreizen der übrigen Zehen.","kw":[{"ziel":"Zervikale Myelopathie","lrp":"4,0 (1,1–16,6)","lrn":"0,7 (0,6–0,9)","basis":"Cook 2009, Patienten mit HWS-Beschwerden"},{"ziel":"Zervikale Myelopathie","sens":"7 %","spez":"100 %","basis":"Cook 2010, 249 Patienten, zitiert in Sharma 2025"},{"ziel":"Zervikale Myelopathie, Spannweite über Studien","sens":"7–44 %","spez":"93–100 %","basis":"Scoping Review Sharma 2025, 5 Studien"}],"evidenz":"mäßig"},"sharppurser":{"name":"Sharp-Purser-Test","was":"Instabilität atlantoaxial (Lig. transversum)","einheit":"positiv oder negativ","kurz":"Dornfortsatz C2 fixieren, Stirn bei leicht flektierter HWS nach dorsal schieben.","ziel":"Obere zervikale Instabilität vor Mobilisation ausschließen helfen.","norm":["Sens. 19–100 %, Spez. 71–98 %, LR+ zwischen 0,66 und 22 in Einzelstudien (Mansfield 2020). Daten stammen überwiegend von Patienten mit rheumatoider Arthritis.","Die Übersicht bewertet den Test wegen uneinheitlicher Validität, schwacher Inter-Rater-Reliabilität und möglicher Gefährdung als ungeeignet für den Routineeinsatz. Bei Verdacht auf obere zervikale Instabilität ärztliche Abklärung und Bildgebung."],"durch":"Sitz, HWS entspannt leicht flektiert. Der Therapeut fixiert mit Daumen und Zeigefinger den Dornfortsatz von C2 und schiebt mit der anderen Hand über die Stirn den Kopf nach dorsal. Positiv bei vermehrtem Gleiten, Klunk oder Rückgang von Flexionssymptomen. Bei Verdacht keine weiteren provozierenden Tests, ärztliche Abklärung.","position":"Sitz","quellen":["Mansfield CJ et al. 2020, Systematic review of the diagnostic accuracy, reliability, and safety of the Sharp-Purser test. J Man Manip Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC7170372/","Uitvlugt G, Indenbaum S 1988, Clinical assessment of atlantoaxial instability using the Sharp-Purser test. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/3395385/","Hutting N et al. 2013, Diagnostic accuracy of upper cervical spine instability tests: a systematic review. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/23886844/","Hutting 2013 – https://www.physiotutors.com/wiki/sharp-purser-test/"],"pos":"Positiv bei spürbarem Gleiten oder Klunk des Kopfes nach dorsal oder wenn Symptome, die in Flexion bestanden, nachlassen.","kw":[{"ziel":"Atlantoaxiale Instabilität bei rheumatoider Arthritis (Subluxation > 4 mm)","sens":"88 %","spez":"96 %","lrp":"22","lrn":"0,13","basis":"Uitvlugt 1988, 123 RA-Patienten, Röntgen als Referenz; LR berechnet"},{"ziel":"Atlantoaxiale Instabilität, Spannweite","sens":"19–100 %","spez":"71–98 %","basis":"Systematische Übersicht Mansfield 2020, 6 Studien, keine Metaanalyse wegen Heterogenität"}],"evidenz":"mäßig"},"flexionrotation":{"name":"Flexions-Rotations-Test","was":"Zervikogener Kopfschmerz, Dysfunktion C1/C2","einheit":"positiv oder negativ","kurz":"HWS passiv maximal flektieren, dann Kopf passiv nach rechts und links rotieren.","ziel":"Eingeschränkte Rotation im Segment C1/C2 erfassen.","norm":["Positiv bei Rotation von 30° oder weniger zur eingeschränkten Seite (Hall 2010). Mittelwerte: zervikogener Kopfschmerz 25°, Migräne 42°.","Zervikogener Kopfschmerz: Sens. 91 %, Spez. 90 % (Ogince 2007) bzw. Sens. 90 %, Spez. 88 %, Kappa 0,85 (Hall 2008). Alle Studien aus derselben Arbeitsgruppe mit Fall-Kontroll-Design."],"durch":"Rückenlage, Kopf über der Liege. Der Therapeut flektiert die HWS passiv maximal und rotiert den Kopf in dieser Stellung zu beiden Seiten bis zum festen Stopp oder Schmerz. Rotationsweg schätzen oder messen und Seiten vergleichen.","position":"Rückenlage","quellen":["Ogince M et al. 2007, The diagnostic validity of the cervical flexion-rotation test in C1/2-related cervicogenic headache. Man Ther – https://pubmed.ncbi.nlm.nih.gov/17112768/","Hall TM et al. 2008, Intertester reliability and diagnostic validity of the cervical flexion-rotation test. J Manipulative Physiol Ther – https://pubmed.ncbi.nlm.nih.gov/18486750/","Hall TM et al. 2010, Comparative analysis and diagnostic accuracy of the cervical flexion-rotation test. J Headache Pain – https://pubmed.ncbi.nlm.nih.gov/20508964/","Ogince 2007 – https://www.physiotutors.com/wiki/flexion-rotation-test/"],"pos":"Positiv, wenn die Rotation in voller HWS-Flexion zur auffälligen Seite auf 30° oder weniger eingeschränkt ist, meist mit bekanntem Kopfschmerz.","kw":[{"ziel":"Zervikogener Kopfschmerz mit C1/2-Dysfunktion","sens":"91 %","spez":"90 %","lrp":"9,1","lrn":"0,10","basis":"Ogince 2007, 58 Personen (Kopfschmerz, Migräne, Gesunde), Fall-Kontroll-Design; LR berechnet"},{"ziel":"Zervikogener Kopfschmerz mit C1/2-Dysfunktion","sens":"90 %","spez":"88 %","lrp":"7,5","lrn":"0,11","basis":"Hall 2008, 40 Personen; Kappa 0,85; LR berechnet"}],"evidenz":"mäßig"},"faustperkussion":{"name":"Faustschlag-Perkussion","was":"Wirbelkörperfraktur, z. B. osteoporotisch","einheit":"positiv oder negativ","kurz":"Handfläche auf die Dornfortsätze legen und mit der Faust leicht daraufklopfen, segmentweise.","ziel":"Hinweis auf Wirbelkörperfraktur (Red Flag) finden.","norm":["Akute Wirbelkörperfraktur: Sens. 87,5 %, Spez. 90 % (Langdon 2010, 83 Patienten); in einer größeren Kohorte Sens. 75,6 %, Spez. 82,4 % (Ueda 2025, 311 Patienten).","Positiver Befund ist eine Red Flag: ärztliche Abklärung vor Behandlung."],"durch":"Sitz oder Stand, Rücken frei. Der Therapeut legt eine Hand flach auf die Dornfortsätze und klopft mit der Faust der anderen Hand auf den Handrücken, beginnend thorakal, Segment für Segment nach kaudal. Positiv bei scharfem, punktuellem Schmerz. Bei positivem Befund ärztliche Abklärung.","position":"Sitz","quellen":["Langdon J et al. 2010, Vertebral compression fractures – new clinical signs to aid diagnosis. Ann R Coll Surg Engl – https://pubmed.ncbi.nlm.nih.gov/19995486/","Ueda T 2025, Diagnostic accuracy of the head elevation test for vertebral compression fractures in older adults. Spine – https://pubmed.ncbi.nlm.nih.gov/41091674/","Langdon 2010 – https://www.physio-pedia.com/Closed_Fist_Percussion_Sign"],"pos":"Positiv bei scharfem, punktuellem Schmerz auf einer Höhe beim Klopfen mit der Faust.","kw":[{"ziel":"Akute osteoporotische Wirbelkörperfraktur","sens":"87,5 %","spez":"90 %","lrp":"8,8","lrn":"0,14","basis":"Langdon 2010, 83 Patienten mit Verdacht, MRT als Referenz; LR berechnet"},{"ziel":"Wirbelkörperfraktur bei älteren Erwachsenen mit Rückenschmerz","sens":"75,6 %","spez":"82,4 %","lrp":"4,3","lrn":"0,30","basis":"Ueda 2025, 311 Patienten, prospektiv, Bildgebung als Referenz; LR berechnet"}],"evidenz":"mäßig"},"rueckenlagezeichen":{"name":"Rückenlage-Zeichen (Supine Sign)","was":"Wirbelkörperfraktur","einheit":"positiv oder negativ","kurz":"Patient soll sich mit einem Kissen flach auf den Rücken legen.","ziel":"Hinweis auf symptomatische Wirbelkörperfraktur.","norm":["Akute Wirbelkörperfraktur: Sens. 81 %, Spez. 93 % (Langdon 2010); nur eine kleine Studie der Erstbeschreiber, nicht extern bestätigt."],"durch":"Der Patient legt sich mit einem Kopfkissen auf den Rücken. Positiv, wenn das wegen starker Schmerzen nicht möglich ist. Anamnestisch passt dazu oft, dass im Sessel geschlafen wird.","position":"Rückenlage","quellen":["Langdon J et al. 2010, Vertebral compression fractures – new clinical signs to aid diagnosis. Ann R Coll Surg Engl – https://pubmed.ncbi.nlm.nih.gov/19995486/","Langdon 2010 – https://www.physiotutors.com/wiki/supine-sign/"],"pos":"Positiv, wenn der Patient wegen starker Schmerzen nicht flach mit einem Kissen auf dem Rücken liegen kann.","kw":[{"ziel":"Akute osteoporotische Wirbelkörperfraktur","sens":"81 %","spez":"93 %","lrp":"12,2","lrn":"0,20","basis":"Langdon 2010, 83 Patienten mit Verdacht, MRT als Referenz; LR berechnet"}],"evidenz":"schwach"},"ersterippe":{"name":"Zervikaler Rotations-Lateralflexions-Test","was":"Blockierung der ersten Rippe","einheit":"positiv oder negativ","kurz":"HWS maximal von der Seite weg rotieren, dann zur Brust lateralflektieren.","ziel":"Bewegungseinschränkung der ersten Rippe erkennen.","norm":["Positiv bei eingeschränkter Lateralflexion im Seitenvergleich (CRLF-Test nach Lindgren).","In einer kleinen Studie mit 23 Patienten mit Brachialgie stimmte der Test mit der Kineradiografie der ersten Rippe überein; Übereinstimmung zwischen Untersuchern als sehr gut beschrieben. Sensitivität und Spezifität wurden nicht berichtet (Lindgren 1992)."],"durch":"Sitz. Der Therapeut rotiert die HWS passiv maximal von der zu testenden Seite weg und führt dann eine Lateralflexion so, dass das Ohr Richtung Brust geht. Positiv bei festem, früherem Stopp im Seitenvergleich.","position":"Sitz","quellen":["Lindgren KA et al. 1992, Cervical rotation lateral flexion test in brachialgia. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/1642524/","Lindgren KA et al. 1990, Cervical spine rotation and lateral flexion combined motion in the examination of the thoracic outlet. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/2327890/"],"pos":"Positiv, wenn die Lateralflexion nach maximaler Rotation von der Testseite weg im Seitenvergleich deutlich eingeschränkt ist.","evidenz":"schwach"},"slrgekreuzt":{"name":"Gekreuzter Lasègue (Crossed SLR)","was":"Lumbale Radikulopathie bei Bandscheibenvorfall","einheit":"positiv oder negativ","kurz":"Das nicht betroffene Bein gestreckt anheben und auf Schmerz im betroffenen Bein achten.","ziel":"Radikuläre Ursache bestätigen.","norm":["Positiv bei bekanntem, ausstrahlendem Schmerz im betroffenen Bein beim Anheben des gesunden Beins.","Gepoolt Sens. 28 %, Spez. 90 %, LR+ 2,8 (van der Windt 2010, Cochrane). Positiv stützt die Diagnose, negativ schließt nichts aus."],"durch":"Rückenlage. Der Therapeut hebt das nicht betroffene Bein gestreckt im Hüftgelenk an, etwa bis 60-70°. Positiv, wenn im betroffenen Bein der bekannte, ausstrahlende Schmerz auftritt.","position":"Rückenlage","quellen":["van der Windt DA et al. 2010, Physical examination for lumbar radiculopathy due to disc herniation in patients with low-back pain. Cochrane Database Syst Rev – https://pubmed.ncbi.nlm.nih.gov/20166095/","Suri P et al. 2011, The accuracy of the physical examination for the diagnosis of midlumbar and low lumbar nerve root impingement. Spine – https://pubmed.ncbi.nlm.nih.gov/20543768/","van der Windt 2010 (Cochrane) – https://www.physiotutors.com/wiki/crossed-straight-leg-raise-test/"],"pos":"Positiv, wenn das Anheben des gesunden Beins den bekannten Schmerz im betroffenen Bein auslöst.","kw":[{"ziel":"Radikulopathie bei Bandscheibenvorfall","sens":"28 %","spez":"90 %","lrp":"2,8","lrn":"0,80","basis":"Cochrane-Metaanalyse, überwiegend operierte Kollektive; LR berechnet"},{"ziel":"Wurzelkompression L5/S1 (MRT)","sens":"7 %","spez":"96 %","lrp":"1,7","lrn":"0,97","basis":"Einzelstudie, 54 Pat."}],"evidenz":"stark"},"femoralisdehnung":{"name":"Femoralis-Dehnungstest (Prone Knee Bend)","was":"Hohe lumbale Radikulopathie L2-L4","einheit":"positiv oder negativ","kurz":"In Bauchlage Knie passiv beugen, Ferse Richtung Gesäß.","ziel":"Mechanosensitivität des N. femoralis prüfen.","norm":["Positiv bei Reproduktion des bekannten Schmerzes an der Oberschenkelvorderseite bei passiver Knieflexion in Bauchlage.","Mittlere Wurzeln L2–L4: Sens. 50 %, Spez. 100 %; für L3: Sens. 70 %, Spez. 88 %, LR+ 5,7 (Suri 2011, 54 Pat., MRT).","Ein positiver Test spricht stark für eine hohe Wurzelkompression, ein negativer schließt sie nicht aus. Mit Patellarsehnenreflex und Kraft der Knieextension kombinieren."],"durch":"Bauchlage, Becken stabilisiert. Der Therapeut beugt das Kniegelenk passiv, bis die Ferse Richtung Gesäß geht; bei Bedarf zusätzlich Hüftextension. Positiv bei bekanntem Schmerz an der Oberschenkelvorderseite. Reine Dehnung des M. rectus femoris abgrenzen.","position":"Bauchlage","quellen":["Suri P et al. 2011, The accuracy of the physical examination for the diagnosis of midlumbar and low lumbar nerve root impingement. Spine – https://pubmed.ncbi.nlm.nih.gov/20543768/"],"pos":"Positiv, wenn die passive Knieflexion in Bauchlage den bekannten Schmerz an der Oberschenkelvorderseite auslöst.","kw":[{"ziel":"Mittlere Wurzelkompression L2–L4 (MRT)","sens":"50 %","spez":"100 %","lrn":"0,50","basis":"Einzelstudie, 54 Pat., verblindet; LR+ nicht berechenbar (keine falsch Positiven)"},{"ziel":"Wurzelkompression L3 (MRT)","sens":"70 %","spez":"88 %","lrp":"5,7","lrn":"0,34","basis":"Einzelstudie, 54 Pat."}],"evidenz":"mäßig"},"plet":{"name":"Passiver lumbaler Extensionstest","was":"Strukturelle lumbale Instabilität","einheit":"positiv oder negativ","kurz":"Beide gestreckten Beine in Bauchlage etwa 30 cm anheben und leicht ziehen.","ziel":"Lumbale Instabilität erkennen.","norm":["Positiv bei starkem Kreuzschmerz, Schweregefühl oder dem Gefühl, dass der Rücken nachgibt, das beim Ablegen verschwindet.","Sens. 84 %, Spez. 90 %, LR+ 8,8 (Kasai 2006, 122 Pat.). Zwei Übersichten (Alqarni 2011, Ferrari 2015) nennen ihn als genauesten Instabilitätstest, die Werte beruhen aber auf dieser einen Studie.","Interrater-Reliabilität Kappa 0,76 (eine Studie). Bei Spondylolisthesis war er als einziger Test mit Funktionsaufnahmen verknüpft (Ferrari 2014)."],"durch":"Bauchlage. Der Therapeut hebt beide gestreckten Beine gleichzeitig etwa 30 cm von der Liege an und übt leichten Zug aus. Positiv bei starkem Kreuzschmerz, Schweregefühl oder dem Gefühl, der Rücken gebe nach, das beim Zurücklegen nachlässt.","position":"Bauchlage","quellen":["Kasai Y et al. 2006, A new evaluation method for lumbar spinal instability: passive lumbar extension test. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17033040/","Alqarni AM et al. 2011, Clinical tests to diagnose lumbar segmental instability: a systematic review. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/21289452/","Ferrari S et al. 2015, A literature review of clinical tests for lumbar instability in low back pain: validity and applicability in clinical practice. Chiropr Man Therap – https://pubmed.ncbi.nlm.nih.gov/25866618/","Ferrari S et al. 2014, Pain, disability, and diagnostic accuracy of clinical instability and endurance tests in subjects with lumbar spondylolisthesis. J Manipulative Physiol Ther – https://pubmed.ncbi.nlm.nih.gov/25282678/","Kasai 2006, Ferrari 2014 – https://www.physiotutors.com/wiki/passive-lumbar-extension-test/"],"pos":"Positiv, wenn beim Anheben beider Beine starker Kreuzschmerz, Schweregefühl oder Instabilitätsgefühl auftritt und beim Ablegen verschwindet.","kw":[{"ziel":"Radiologische lumbale Instabilität (Funktionsaufnahmen)","sens":"84 %","spez":"90 %","lrp":"8,8","lrn":"0,18","basis":"Einzelstudie, 122 Pat. mit degenerativen LWS-Erkrankungen"}],"evidenz":"mäßig"},"bauchlageinstab":{"name":"Prone Instability Test","was":"Segmentale lumbale Instabilität, Stabilisationsübungen","einheit":"positiv oder negativ","kurz":"Oberkörper liegt auf der Liege, Füße am Boden; PA-Druck auf schmerzhaftes Segment, dann mit angehobenen Beinen wiederholen.","ziel":"Schmerz durch aktive Stabilisierung beeinflussen.","norm":["Positiv, wenn der PA-Druck nur mit Füßen am Boden schmerzt und mit angehobenen Beinen nicht mehr.","Für radiologische Instabilität nur Sens. 71 %, Spez. 57 %, LR+ 1,7 (Fritz 2005). Interrater-Kappa 0,04 bis 0,87 in fünf Studien (Ferrari 2015).","Ein positiver Test war Teil der vorläufigen Regel, die gutes Ansprechen auf Stabilisationsübungen vorhersagt (Hicks 2005). Eher zur Therapieauswahl als zur Diagnose."],"durch":"Der Oberkörper liegt bäuchlings auf der Liege, die Füße stehen auf dem Boden. Der Therapeut gibt PA-Druck auf das schmerzhafte Segment. Danach hebt der Patient die Beine vom Boden und der Druck wird wiederholt. Positiv, wenn der Schmerz nur in der ersten Position auftritt.","position":"Bauchlage","quellen":["Ferrari S et al. 2015, A literature review of clinical tests for lumbar instability in low back pain: validity and applicability in clinical practice. Chiropr Man Therap – https://pubmed.ncbi.nlm.nih.gov/25866618/","Fritz JM et al. 2005, Accuracy of the clinical examination to predict radiographic instability of the lumbar spine. Eur Spine J – https://pubmed.ncbi.nlm.nih.gov/16047211/","Hicks GE et al. 2005, Preliminary development of a clinical prediction rule for determining which patients with low back pain will respond to a stabilization exercise program. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/16181938/","Hicks GE et al. 2003, Interrater reliability of clinical examination measures for identification of lumbar segmental instability. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/14669195/"],"pos":"Positiv, wenn der PA-Druck mit Füßen am Boden schmerzt und der Schmerz bei angehobenen Beinen deutlich nachlässt oder verschwindet.","kw":[{"ziel":"Radiologische lumbale Instabilität (Funktionsaufnahmen)","sens":"71 %","spez":"57 %","lrp":"1,7","lrn":"0,50","basis":"Einzelstudie (Fritz 2005), 49 Pat., zitiert in Übersicht Ferrari 2015"}],"evidenz":"mäßig"},"isgdistraktion":{"name":"ISG-Distraktionstest","was":"Schmerzhaftes Iliosakralgelenk","einheit":"positiv oder negativ","kurz":"Beidseits Druck auf die medialen SIAS nach dorsolateral.","ziel":"ISG-Schmerz provozieren.","norm":["Positiv bei Reproduktion des bekannten Gesäß- bzw. ISG-Schmerzes.","Sens. 60 %, Spez. 81 %, LR+ 3,2 (Laslett 2005); spezifischster Einzeltest der Laslett-Batterie, deshalb zuerst prüfen."],"durch":"Rückenlage. Der Therapeut legt die Handballen gekreuzt auf die medialen Ränder beider SIAS und drückt nach dorsal-lateral, etwa 30 Sekunden oder mehrmals federnd. Positiv bei bekanntem Schmerz im ISG-Bereich.","position":"Rückenlage","quellen":["Laslett M et al. 2005, Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther – https://pubmed.ncbi.nlm.nih.gov/16038856/","Saueressig T et al. 2021, Diagnostic accuracy of clusters of pain provocation tests for detecting sacroiliac joint pain: systematic review with meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/34210160/","Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/"],"pos":"Positiv, wenn der Druck auf beide SIAS den bekannten Gesäß- bzw. ISG-Schmerz reproduziert.","kw":[{"ziel":"ISG-Schmerz (intraartikuläre Anästhesie)","sens":"60 %","spez":"81 %","lrp":"3,2","lrn":"0,49","basis":"Einzelstudie, 48 Pat., Referenz ISG-Injektion"}],"evidenz":"mäßig"},"thighthrust":{"name":"Thigh-Thrust-Test","was":"Schmerzhaftes Iliosakralgelenk","einheit":"positiv oder negativ","kurz":"Hüfte 90° gebeugt, axialer Druck über den Femur nach dorsal.","ziel":"ISG-Schmerz provozieren.","norm":["Positiv bei Reproduktion des bekannten Gesäß- bzw. ISG-Schmerzes.","Sens. 88 %, Spez. 69 %, LR- 0,18 (Laslett 2005); sensitivster Einzeltest, ein negativer Befund spricht gegen das ISG.","Szadek 2009 (Metaanalyse) bestätigt, dass der Thigh Thrust trennscharf ist."],"durch":"Rückenlage, Hüfte der Testseite 90° flektiert und leicht adduziert. Eine Hand liegt unter dem Sakrum, die andere gibt über das Knie axialen Druck entlang des Femurs nach dorsal. Positiv bei bekanntem ISG-Schmerz.","position":"Rückenlage","quellen":["Laslett M et al. 2005, Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther – https://pubmed.ncbi.nlm.nih.gov/16038856/","Szadek KM et al. 2009, Diagnostic validity of criteria for sacroiliac joint pain: a systematic review. J Pain – https://pubmed.ncbi.nlm.nih.gov/19101212/","Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/"],"pos":"Positiv, wenn der axiale Druck über den Femur den bekannten Gesäß- bzw. ISG-Schmerz reproduziert.","kw":[{"ziel":"ISG-Schmerz (intraartikuläre Anästhesie)","sens":"88 %","spez":"69 %","lrp":"2,8","lrn":"0,18","basis":"Einzelstudie, 48 Pat., Referenz ISG-Injektion"}],"evidenz":"mäßig"},"isgkompression":{"name":"ISG-Kompressionstest","was":"Schmerzhaftes Iliosakralgelenk","einheit":"positiv oder negativ","kurz":"In Seitenlage Druck von oben auf die Crista iliaca Richtung Liege.","ziel":"ISG-Schmerz provozieren.","norm":["Positiv bei Reproduktion des bekannten Schmerzes.","Sens. 69 %, Spez. 69 %, LR+ 2,2 (Laslett 2005). Nach Szadek 2009 (Metaanalyse) trennscharf, aber schwächer als der Thigh Thrust."],"durch":"Seitenlage, schmerzhafte Seite oben, Hüften und Knie leicht gebeugt. Der Therapeut gibt über die obere Crista iliaca senkrechten Druck Richtung Liege. Positiv bei bekanntem ISG-Schmerz.","position":"Seitlage","quellen":["Laslett M et al. 2005, Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther – https://pubmed.ncbi.nlm.nih.gov/16038856/","Szadek KM et al. 2009, Diagnostic validity of criteria for sacroiliac joint pain: a systematic review. J Pain – https://pubmed.ncbi.nlm.nih.gov/19101212/","Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/"],"pos":"Positiv, wenn der Druck auf die obere Crista iliaca den bekannten Gesäß- bzw. ISG-Schmerz reproduziert.","kw":[{"ziel":"ISG-Schmerz (intraartikuläre Anästhesie)","sens":"69 %","spez":"69 %","lrp":"2,2","lrn":"0,46","basis":"Einzelstudie, 48 Pat., Referenz ISG-Injektion"}],"evidenz":"mäßig"},"gaenslen":{"name":"Gaenslen-Test","was":"Schmerzhaftes Iliosakralgelenk","einheit":"positiv oder negativ","kurz":"Ein Bein maximal gebeugt halten, das andere über die Liegekante in Hüftextension führen.","ziel":"ISG durch Torsion provozieren.","norm":["Positiv bei Reproduktion des bekannten Schmerzes.","Sens. 50–53 %, Spez. 71–77 %, LR+ unter 2,3 (Laslett 2005). Trägt im Cluster nichts zur Genauigkeit bei und kann weggelassen werden."],"durch":"Rückenlage am Liegenrand. Der Patient hält das liegenferne Knie an die Brust. Der Therapeut führt das liegennahe Bein über die Kante in Hüftextension und gibt am Ende Überdruck. Beide Seiten testen. Positiv bei bekanntem ISG-Schmerz.","position":"Rückenlage","quellen":["Laslett M et al. 2005, Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther – https://pubmed.ncbi.nlm.nih.gov/16038856/","Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/"],"pos":"Positiv, wenn die Torsion des Beckens den bekannten Gesäß- bzw. ISG-Schmerz reproduziert.","kw":[{"ziel":"ISG-Schmerz, rechts getestet","sens":"53 %","spez":"71 %","lrp":"1,84","lrn":"0,66","basis":"Einzelstudie, 48 Pat., Referenz ISG-Injektion"},{"ziel":"ISG-Schmerz, links getestet","sens":"50 %","spez":"77 %","lrp":"2,21","lrn":"0,65","basis":"Einzelstudie, 48 Pat."}],"evidenz":"mäßig"},"sakralthrust":{"name":"Sacral-Thrust-Test","was":"Schmerzhaftes Iliosakralgelenk","einheit":"positiv oder negativ","kurz":"In Bauchlage Druck senkrecht auf die Mitte des Sakrums.","ziel":"ISG-Schmerz provozieren.","norm":["Positiv bei Reproduktion des bekannten Schmerzes.","Sens. 63 %, Spez. 75 %, LR+ 2,5 (Laslett 2005); letzter Test im Laslett-Ablauf."],"durch":"Bauchlage. Der Therapeut legt den Handballen auf die Mitte des Sakrums und gibt senkrecht nach ventral Druck, mehrfach federnd. Positiv bei bekanntem ISG-Schmerz.","position":"Bauchlage","quellen":["Laslett M et al. 2005, Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther – https://pubmed.ncbi.nlm.nih.gov/16038856/","Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/"],"pos":"Positiv, wenn der Druck auf die Mitte des Sakrums den bekannten Gesäß- bzw. ISG-Schmerz reproduziert.","kw":[{"ziel":"ISG-Schmerz (intraartikuläre Anästhesie)","sens":"63 %","spez":"75 %","lrp":"2,5","lrn":"0,50","basis":"Einzelstudie, 48 Pat., Referenz ISG-Injektion"}],"evidenz":"mäßig"},"infraspinatus":{"name":"Infraspinatus-Test (Außenrotation gegen Widerstand)","was":"Läsion der Außenrotatoren, RM-Ruptur","einheit":"positiv oder negativ","kurz":"Arm am Körper, Ellbogen 90°, Außenrotation gegen Widerstand.","ziel":"Kraft und Schmerz der Außenrotatoren prüfen.","norm":["Impingement: LR+ 4,39, LR− 0,50 (Michener 2009); laut Hermans 2013 zusammen mit dem Painful Arc der genaueste Befund für eine Rotatorenmanschettenerkrankung.","Infraspinatusruptur bei Schwäche: LR+ 2,42, LR− 0,5 (Lasbleiz 2014).","Painful Arc, Drop Arm und Infraspinatus-Test alle positiv: Nachtestwahrscheinlichkeit 91 % für eine komplette Rotatorenmanschettenruptur (Park 2005)."],"durch":"Stand oder Sitz, Oberarm am Rumpf, Ellbogen 90° gebeugt, Unterarm in Neutralstellung. Der Patient drückt nach außen, der Therapeut gibt Widerstand am distalen Unterarm. Positiv bei Kraftminderung im Seitenvergleich.","position":"Sitz","quellen":["Michener LA et al. 2009, Reliability and diagnostic accuracy of 5 physical examination tests for subacromial impingement. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19887215/","Hermans J et al. 2013, Does this patient with shoulder pain have rotator cuff disease? JAMA – https://pubmed.ncbi.nlm.nih.gov/23982370/","Lasbleiz S et al. 2014, Diagnostic value of clinical tests for degenerative rotator cuff disease in medical practice. Ann Phys Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/24851697/","Park HB et al. 2005, Diagnostic accuracy of clinical tests for the different degrees of subacromial impingement syndrome. J Bone Joint Surg Am – https://pubmed.ncbi.nlm.nih.gov/15995110/","Park 2005 (zit. in Hospitalist-Review) – https://community.the-hospitalist.org/index.php/content/which-history-and-physical-findings-are-most-useful-identifying-rotator-cuff-tears"],"pos":"Positiv bei Schwäche oder Schmerz bei Außenrotation gegen Widerstand mit Arm am Körper und 90° gebeugtem Ellbogen.","kw":[{"ziel":"Subakromiales Impingement","sens":"56 %","spez":"87 %","lrp":"4,39 (1,74–11,07)","lrn":"0,50 (0,28–0,89)","basis":"Michener 2009, 55 Patienten, OP als Referenz"},{"ziel":"Ruptur des Infraspinatus (Kriterium Schwäche)","lrp":"2,42","lrn":"0,5","basis":"Lasbleiz 2014, 39 Schultern, Ultraschall als Referenz"}],"evidenz":"mäßig"},"relocation":{"name":"Relocation-Test","was":"Vordere Schulterinstabilität","einheit":"positiv oder negativ","kurz":"Aus der Apprehension-Position den Humeruskopf nach dorsal drücken.","ziel":"Apprehension durch Zentrierung des Kopfes beeinflussen.","norm":["Vordere Instabilität gepoolt: Sens. 64,6 %, Spez. 90,2 %, LR+ 5,48, LR− 0,55 (Hegedus 2012). Für SLAP nicht aussagekräftig."],"durch":"Rückenlage, Arm 90° abduziert und außenrotiert wie beim Apprehension-Test. Der Therapeut drückt den Humeruskopf von ventral nach dorsal und rotiert weiter nach außen. Positiv, wenn die Angst oder der Schmerz deutlich nachlässt.","position":"Rückenlage","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Hegedus 2012 – https://upload.orthobullets.com/journalclub/free_pdf/22773322_BrJSportsMed-2012-Hegedus-bjsports-2012-091066.pdf"],"pos":"Positiv, wenn Angst oder Schmerz aus der Apprehension-Position unter dorsalem Druck auf den Humeruskopf deutlich nachlassen.","kw":[{"ziel":"Vordere Schulterinstabilität","sens":"64,6 %","spez":"90,2 %","lrp":"5,48","lrn":"0,55","basis":"Metaanalyse Hegedus 2012, 3 Studien, 509 Patienten"},{"ziel":"SLAP-Läsion","sens":"51,6 %","spez":"52,4 %","lrp":"1,13","lrn":"0,93","basis":"Metaanalyse Hegedus 2012, 3 Studien, 246 Patienten"}],"evidenz":"stark"},"surprise":{"name":"Surprise-/Release-Test","was":"Vordere Schulterinstabilität","einheit":"positiv oder negativ","kurz":"Im Relocation-Test die dorsale Hand plötzlich lösen.","ziel":"Instabilitätsgefühl gezielt provozieren.","norm":["Vordere Instabilität gepoolt: Sens. 81,8 %, Spez. 86,1 %, LR+ 5,42, LR− 0,25 (Hegedus 2012); gepoolt nur aus zwei kleinen Studien."],"durch":"Rückenlage, Fortsetzung des Relocation-Tests. Nach Außenrotation unter dorsalem Druck lässt der Therapeut die Hand am Humeruskopf plötzlich los. Positiv bei Angst oder plötzlichem Schmerz. Vorsicht bei frischer Luxation.","position":"Rückenlage","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Hegedus 2012 – https://upload.orthobullets.com/journalclub/free_pdf/22773322_BrJSportsMed-2012-Hegedus-bjsports-2012-091066.pdf"],"pos":"Positiv bei plötzlichem Schmerz oder Angst, wenn der dorsale Druck aus der Relocation-Position plötzlich gelöst wird.","kw":[{"ziel":"Vordere Schulterinstabilität","sens":"81,8 %","spez":"86,1 %","lrp":"5,42","lrn":"0,25","basis":"Metaanalyse Hegedus 2012, 2 Studien, 128 Patienten"}],"evidenz":"stark"},"crossbody":{"name":"Cross-Body-Adduktionstest","was":"Schmerzhaftes AC-Gelenk","einheit":"positiv oder negativ","kurz":"Arm 90° flektiert passiv horizontal über den Körper adduzieren.","ziel":"AC-Gelenk durch Kompression provozieren.","norm":["Sensitivster AC-Test (77 %, Chronopoulos 2004). Für AC-Arthrose LR+ 3,67, LR− 0,29 (Jia, hohes Bias-Risiko).","Kombinationen mit AC-Resisted-Extension und O'Brien verbessern laut Chronopoulos 2004 die Aussagekraft."],"durch":"Sitz oder Stand. Der Therapeut führt den 90° flektierten Arm passiv in horizontale Adduktion Richtung gegenüberliegende Schulter, mit leichtem Überdruck. Positiv bei Schmerz genau über dem AC-Gelenk; Schmerz hinten in der Schulter zählt nicht.","position":"Sitz","quellen":["Chronopoulos E et al. 2004, Diagnostic value of physical tests for isolated chronic acromioclavicular lesions. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/15090381/","Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Hegedus 2012 – https://upload.orthobullets.com/journalclub/free_pdf/22773322_BrJSportsMed-2012-Hegedus-bjsports-2012-091066.pdf","Chronopoulos 2004 – https://www.physiotutors.com/wiki/ac-joint-cluster/"],"pos":"Positiv bei Schmerz genau über dem AC-Gelenk bei passiver horizontaler Adduktion des 90° flektierten Arms.","kw":[{"ziel":"Chronische isolierte AC-Gelenk-Läsion","sens":"77 %","basis":"Chronopoulos 2004, retrospektiv, 35 operierte Patienten; Spezifität im Abstract nicht genannt, Gesamtgenauigkeit 79 %"},{"ziel":"AC-Gelenk-Arthrose","sens":"77 %","spez":"79 %","lrp":"3,67","lrn":"0,29","basis":"Jia, Einzelstudie mit hohem Bias-Risiko, in Hegedus 2012"}],"evidenz":"schwach"},"obrien":{"name":"O'Brien-Test (Active Compression)","was":"AC-Gelenk oder SLAP-Läsion","einheit":"positiv oder negativ","kurz":"Arm 90° flektiert, 10-15° adduziert, innenrotiert; Widerstand nach kaudal, dann in Außenrotation wiederholen.","ziel":"AC-Gelenk und Labrum superior provozieren.","norm":["AC-Gelenk: spezifischster AC-Test (Spez. 95 %, Sens. 41 %, Chronopoulos 2004).","SLAP: gepoolt Sens. 67 %, Spez. 37 %, LR+ 1,06 (Hegedus 2012), für SLAP nicht aussagekräftig."],"durch":"Stand oder Sitz. Arm 90° flektiert, 10-15° horizontal adduziert, Daumen nach unten. Der Patient hält gegen Druck des Therapeuten nach kaudal. Danach gleiche Prüfung mit Handfläche nach oben. Positiv, wenn die erste Position schmerzt und die zweite deutlich weniger.","position":"Sitz","quellen":["Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/","Chronopoulos E et al. 2004, Diagnostic value of physical tests for isolated chronic acromioclavicular lesions. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/15090381/","Hegedus 2012 – https://upload.orthobullets.com/journalclub/free_pdf/22773322_BrJSportsMed-2012-Hegedus-bjsports-2012-091066.pdf","Chronopoulos 2004 – https://www.physiotutors.com/wiki/ac-joint-cluster/"],"pos":"Positiv bei Schmerz in Innenrotation, der in Außenrotation nachlässt; Schmerz oben über dem AC-Gelenk spricht für das AC-Gelenk, tiefer Schmerz im Gelenk für das Labrum.","kw":[{"ziel":"Chronische isolierte AC-Gelenk-Läsion","sens":"41 %","spez":"95 %","lrp":"8,2","lrn":"0,62","basis":"Chronopoulos 2004, retrospektiv, 35 operierte Patienten; LR berechnet"},{"ziel":"SLAP-Läsion","sens":"67 %","spez":"37 %","lrp":"1,06","lrn":"0,89","basis":"Metaanalyse Hegedus 2012, 6 Studien, 782 Patienten"}],"evidenz":"mäßig"},"ellbogenstreckung":{"name":"Ellbogen-Extensionstest","was":"Fraktur nach Ellbogentrauma ausschließen","einheit":"positiv oder negativ","kurz":"Patient streckt den Ellbogen aktiv vollständig.","ziel":"Knöcherne Verletzung nach Trauma ausschließen.","norm":["Positiv, wenn die volle Streckung nicht möglich ist; dann Röntgen.","Sens. 96,8 %, Spez. 48,5 %, negativer prädiktiver Wert 98 % bei Erwachsenen (Appelboam 2008, n = 1740). Olekranonfraktur bei voller Streckung bedenken."],"durch":"Sitz, Schultern frei. Der Patient beugt beide Schultern auf 90° und streckt beide Ellbogen vollständig. Positiv bei fehlender voller Streckung im Seitenvergleich. Bei vollständiger Streckung kann bei sicherer klinischer Lage auf Röntgen verzichtet werden, Wiedervorstellung bei anhaltenden Beschwerden.","position":"Sitz","quellen":["Appelboam A et al. 2008, Elbow extension test to rule out elbow fracture: multicentre, prospective validation and observational study. BMJ – https://pubmed.ncbi.nlm.nih.gov/19066257/","Breda G et al. 2023, Diagnostic accuracy of clinical tests to rule out elbow fracture: a systematic review. Clin Shoulder Elb – https://pubmed.ncbi.nlm.nih.gov/35971600/","Appelboam 2008 – https://www.physiotutors.com/wiki/elbow-extension-test/"],"pos":"Positiv, wenn der Ellbogen nach Trauma nicht vollständig gestreckt werden kann.","kw":[{"ziel":"Ellbogenfraktur nach Trauma","sens":"96,8 %","spez":"48,5 %","lrp":"1,9","lrn":"0,03 (Erwachsene), 0,11 (Kinder)","basis":"Multizentrische Validierungsstudie, n = 1740; LR+ berechnet, LR- aus der Studie"},{"ziel":"Ellbogenfraktur nach Trauma","sens":"bis 98,6 %","spez":"24–69 %","basis":"Systematische Übersicht, 12 Studien, 4485 Patienten, nicht gepoolt"}],"evidenz":"stark"},"hooktest":{"name":"Hook-Test","was":"Distale Bizepssehnenruptur","einheit":"positiv oder negativ","kurz":"Ellbogen 90° gebeugt, Unterarm supiniert; mit dem Zeigefinger lateral unter die Bizepssehne haken.","ziel":"Intakte distale Bizepssehne nachweisen.","norm":["Positiv, wenn sich die Sehne nicht von lateral unterhaken lässt.","Sens./Spez. 100 % in der Erstbeschreibung (O'Driscoll 2007, n = 45); in einer größeren Serie Sens. 83 % für komplette Rupturen (Luokkala 2020). Ein normaler Test schließt eine Ruptur, besonders eine Teilruptur, nicht aus."],"durch":"Sitz, Schulter abduziert, Ellbogen 90° gebeugt, Unterarm aktiv supiniert. Der Therapeut versucht mit dem Zeigefinger von lateral unter die gespannte distale Bizepssehne zu haken. Positiv, wenn keine Sehne tastbar ist und der Finger keine Struktur umgreift.","position":"Sitz","quellen":["O'Driscoll SW et al. 2007, The hook test for distal biceps tendon avulsion. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/17687121/","Luokkala T et al. 2020, Distal biceps hook test: sensitivity in acute and chronic tears. Shoulder Elbow – https://pubmed.ncbi.nlm.nih.gov/32788933/","Devereaux MW, ElMaraghy AW 2013, Improving the rapid and reliable diagnosis of complete distal biceps tendon rupture. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/23804587/","O'Driscoll 2007, Devereaux 2013 – https://www.physiotutors.com/wiki/hook-test/"],"pos":"Positiv, wenn sich bei aktiver Supination keine Sehne von lateral unterhaken lässt.","kw":[{"ziel":"Komplette distale Bizepssehnenruptur","sens":"100 %","spez":"100 %","basis":"Einzelstudie, n = 45, OP-Befund, ein Untersucher (O'Driscoll 2007)"},{"ziel":"Distale Bizepssehnenruptur (komplett)","sens":"83 %","basis":"Retrospektive Serie, n = 202, nur Erkrankte (Luokkala 2020)"},{"ziel":"Distale Bizepssehnenruptur (alle inkl. Teilrupturen)","sens":"78 %","basis":"Retrospektive Serie, n = 202 (Luokkala 2020)"}],"evidenz":"mäßig"},"movingvalgus":{"name":"Moving-Valgus-Stresstest","was":"Läsion des medialen Kollateralbandes (UCL)","einheit":"positiv oder negativ","kurz":"Valgusstress halten und den Ellbogen zügig von voller Beugung zur Streckung führen.","ziel":"Mediale Bandinsuffizienz provozieren.","norm":["Positiv bei bekanntem medialen Schmerz, meist zwischen 120° und 70° Beugung (Maximum um 90°).","Sens. 100 % (17 von 17), Spez. 75 % (3 von 4), O'Driscoll 2005, n = 21. Spezifität wegen sehr kleiner Kontrollgruppe unsicher."],"durch":"Sitz oder Stand, Schulter 90° abduziert und maximal außenrotiert. Der Therapeut gibt konstanten Valgusstress und führt den Ellbogen schnell aus voller Flexion in Extension. Positiv bei Reproduktion des medialen Schmerzes im mittleren Bewegungsbogen.","position":"Sitz","quellen":["O'Driscoll SW et al. 2005, The \"moving valgus stress test\" for medial collateral ligament tears of the elbow. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/15701609/","Zwerus EL et al. 2018, Physical examination of the elbow, what is the evidence? A systematic literature review. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/28249855/","O'Driscoll 2005 – https://www.physiotutors.com/wiki/moving-valgus-stress-test/"],"pos":"Positiv bei Reproduktion des medialen Schmerzes am Innenband, maximal zwischen 120° und 70° Beugung.","kw":[{"ziel":"Insuffizienz des medialen Kollateralbandes","sens":"100 %","spez":"75 %","lrp":"4,0","basis":"Einzelstudie, n = 21 operierte Werfer, nur 4 ohne Bandläsion; LR berechnet"}],"evidenz":"schwach"},"lateralpivot":{"name":"Lateraler Pivot-Shift-Test","was":"Posterolaterale Rotationsinstabilität des Ellbogens","einheit":"positiv oder negativ","kurz":"Supination, Valgus und axiale Kompression, dann Ellbogen aus Streckung beugen.","ziel":"Posterolaterale Instabilität erkennen.","norm":["Positiv bei Apprehension oder tastbarem Reponieren des Radiuskopfes ab etwa 40° Beugung.","Am wachen Patienten wenig sensitiv (3 von 8 positiv, Regan 2006); in Narkose alle positiv. Spezifität nicht untersucht."],"durch":"Rückenlage, Arm über Kopf, Schulter außenrotiert. Der Therapeut supiniert den Unterarm, gibt Valgusstress und axiale Kompression und beugt den Ellbogen langsam aus der Streckung. Positiv bei Angst des Patienten oder spürbarem Zurückspringen des Radiuskopfes. Am wachen Patienten oft nur Apprehension auslösbar.","position":"Rückenlage","quellen":["O'Driscoll SW et al. 1991, Posterolateral rotatory instability of the elbow. J Bone Joint Surg Am – https://pubmed.ncbi.nlm.nih.gov/2002081/","Regan W, Lapner PC 2006, Prospective evaluation of two diagnostic apprehension signs for posterolateral instability of the elbow. J Shoulder Elbow Surg – https://pubmed.ncbi.nlm.nih.gov/16679236/","Zwerus EL et al. 2018, Physical examination of the elbow, what is the evidence? A systematic literature review. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/28249855/"],"pos":"Positiv bei Apprehension, Subluxationsgefühl oder tastbarem Zurückspringen des Radiuskopfes beim Beugen aus der Streckung (ab etwa 40°).","kw":[{"ziel":"Posterolaterale Rotationsinstabilität (wacher Patient)","sens":"38 %","basis":"Fallserie, n = 8, alle operativ bestätigt, keine Kontrollgruppe; 3 von 8 wach positiv"},{"ziel":"Posterolaterale Rotationsinstabilität (in Narkose)","sens":"100 %","basis":"Fallserie, n = 8; 8 von 8 in Narkose positiv"}],"evidenz":"schwach"},"cozen":{"name":"Cozen-Test","was":"Laterale Epikondylopathie","einheit":"positiv oder negativ","kurz":"Faust, Handgelenkextension und Radialduktion gegen Widerstand bei gebeugtem Ellbogen.","ziel":"Schmerz am lateralen Epikondylus provozieren.","norm":["Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal.","Sens. 84–97 % in kleinen Studien ohne Gesunde; Spezifität unbekannt. Laut JOSPT-Leitlinie 2022 schwach belegt."],"durch":"Sitz, Ellbogen gebeugt, Unterarm proniert, Faust geschlossen. Der Patient extendiert das Handgelenk mit Radialduktion gegen Widerstand des Therapeuten, der den Epicondylus lateralis palpiert. Positiv bei bekanntem lateralem Ellbogenschmerz.","position":"Sitz","quellen":["Lucado AM et al. 2022, Lateral Elbow Pain and Muscle Function Impairments (Clinical Practice Guideline). J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/36453071/","Karanasios S et al. 2022, Diagnostic accuracy of examination tests for lateral elbow tendinopathy: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/33814224/","Factor S et al. 2023, The \"Selfie Test\": A Novel Test for the Diagnosis of Lateral Epicondylitis. Medicina (Kaunas) – https://pubmed.ncbi.nlm.nih.gov/37374364/","Soares MM et al. 2023, Differences in Clinical Tests for Assessing Lateral Epicondylitis Elbow in Adults Concerning Their Physical Activity Level. Int J Environ Res Public Health – https://doi.org/10.3390/ijerph20031794","Soares 2023 – https://www.mdpi.com/1660-4601/20/3/1794"],"pos":"Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal bei Handgelenkstreckung gegen Widerstand.","kw":[{"ziel":"Laterale Epikondylopathie","sens":"91 %","basis":"Einzelstudie (Dones 2014, 95 %-KI 81–96 %), in JOSPT-CPG und systematischer Übersicht Karanasios 2022"},{"ziel":"Laterale Epikondylopathie","sens":"84 %","basis":"Einzelstudie (Saroja 2014), zitiert in JOSPT-CPG 2022"},{"ziel":"Laterale Epikondylopathie (Ultraschall bestätigt)","sens":"97 %","basis":"Einzelstudie, n = 30, nur Erkrankte (Factor 2023)"}],"mess":{"reliab":"Übereinstimmung mit Ultraschall Kappa 0,73–0,80 je nach Aktivitätsniveau (Soares 2023, n = 102)"},"evidenz":"schwach"},"mill":{"name":"Mill-Test","was":"Laterale Epikondylopathie","einheit":"positiv oder negativ","kurz":"Handgelenk passiv flektieren, Unterarm pronieren, Ellbogen strecken.","ziel":"Handgelenkextensoren dehnen und Schmerz provozieren.","norm":["Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal.","Sens. 53–87 %, Spez. 100 % in einer kleinen Studie; laut JOSPT-Leitlinie 2022 schwach belegt."],"durch":"Sitz. Der Therapeut palpiert den lateralen Epikondylus, proniert den Unterarm, flektiert das Handgelenk passiv voll und streckt dann langsam den Ellbogen. Positiv bei bekanntem lateralem Schmerz.","position":"Sitz","quellen":["Lucado AM et al. 2022, Lateral Elbow Pain and Muscle Function Impairments (Clinical Practice Guideline). J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/36453071/","Factor S et al. 2023, The \"Selfie Test\": A Novel Test for the Diagnosis of Lateral Epicondylitis. Medicina (Kaunas) – https://pubmed.ncbi.nlm.nih.gov/37374364/","Soares MM et al. 2023, Differences in Clinical Tests for Assessing Lateral Epicondylitis Elbow in Adults Concerning Their Physical Activity Level. Int J Environ Res Public Health – https://doi.org/10.3390/ijerph20031794","Soares 2023 – https://www.mdpi.com/1660-4601/20/3/1794"],"pos":"Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal beim Strecken des Ellbogens mit flektiertem Handgelenk und proniertem Unterarm.","kw":[{"ziel":"Laterale Epikondylopathie","sens":"53 %","spez":"100 %","basis":"Einzelstudie (Saroja 2014), zitiert in JOSPT-CPG 2022"},{"ziel":"Laterale Epikondylopathie","sens":"76 %","basis":"Einzelstudie (Dones 2014, 95 %-KI 63–85 %), zitiert in JOSPT-CPG 2022"},{"ziel":"Laterale Epikondylopathie (Ultraschall bestätigt)","sens":"87 %","basis":"Einzelstudie, n = 30, nur Erkrankte (Factor 2023)"}],"mess":{"reliab":"Übereinstimmung mit Ultraschall Kappa 0,82–1,0 je nach Aktivitätsniveau (Soares 2023, n = 102)"},"evidenz":"schwach"},"maudsley":{"name":"Maudsley-Test","was":"Laterale Epikondylopathie (M. extensor digitorum)","einheit":"positiv oder negativ","kurz":"Streckung des Mittelfingers gegen Widerstand bei gestrecktem Ellbogen.","ziel":"Schmerz am lateralen Epikondylus provozieren.","norm":["Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal.","Sens. 66–88 % in kleinen Studien; Spezifität nicht bestimmt. Laut JOSPT-Leitlinie 2022 nur schwach belegt."],"durch":"Sitz, Ellbogen gestreckt, Unterarm proniert. Der Patient streckt den Mittelfinger gegen Widerstand des Therapeuten am Grundglied. Positiv bei bekanntem lateralem Ellbogenschmerz.","position":"Sitz","quellen":["Lucado AM et al. 2022, Lateral Elbow Pain and Muscle Function Impairments (Clinical Practice Guideline). J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/36453071/","Factor S et al. 2023, The \"Selfie Test\": A Novel Test for the Diagnosis of Lateral Epicondylitis. Medicina (Kaunas) – https://pubmed.ncbi.nlm.nih.gov/37374364/","Karanasios S et al. 2022, Diagnostic accuracy of examination tests for lateral elbow tendinopathy: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/33814224/"],"pos":"Positiv bei bekanntem Schmerz am Epicondylus lateralis oder bis 2 cm distal davon bei Mittelfingerstreckung gegen Widerstand.","kw":[{"ziel":"Laterale Epikondylopathie","sens":"88 %","basis":"Einzelstudie (Saroja 2014), zitiert in JOSPT-CPG 2022"},{"ziel":"Laterale Epikondylopathie","sens":"66 %","basis":"Einzelstudie (Dones 2014, 95 %-KI 53–76 %), zitiert in JOSPT-CPG 2022"},{"ziel":"Laterale Epikondylopathie (Ultraschall bestätigt)","sens":"83 %","basis":"Einzelstudie, n = 30, nur Erkrankte"}],"evidenz":"schwach"},"medialepi":{"name":"Test Epicondylopathia medialis","was":"Mediale Epikondylopathie (Golferellbogen)","einheit":"positiv oder negativ","kurz":"Handgelenkflexion und Pronation gegen Widerstand bei gestrecktem Ellbogen.","ziel":"Schmerz am medialen Epikondylus provozieren.","norm":["Positiv bei bekanntem Schmerz am Epicondylus medialis.","Keine Studie zur diagnostischen Genauigkeit vorhanden (systematische Übersicht Zwerus 2018). Klinisch üblich, Diagnose aus Gesamtbild."],"durch":"Sitz, Ellbogen gestreckt, Unterarm supiniert. Der Patient beugt das Handgelenk und proniert gegen Widerstand des Therapeuten, der den medialen Epikondylus palpiert. Alternativ passive Dehnung in Handgelenkextension und Supination. Positiv bei bekanntem medialem Schmerz.","position":"Sitz","quellen":["Zwerus EL et al. 2018, Physical examination of the elbow, what is the evidence? A systematic literature review. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/28249855/"],"pos":"Positiv bei bekanntem Schmerz am Epicondylus medialis bei Handgelenkflexion und Pronation gegen Widerstand oder passiver Dehnung.","evidenz":"keine"},"ulnarisdruck":{"name":"Druckprovokationstest Kubitaltunnel","was":"Kubitaltunnelsyndrom (N. ulnaris)","einheit":"positiv oder negativ","kurz":"Ellbogen 20° gebeugt, Unterarm supiniert; Druck auf den N. ulnaris proximal des Kubitaltunnels für 60 s.","ziel":"Kompression des N. ulnaris nachweisen.","norm":["Positiv bei Parästhesien im Versorgungsgebiet des N. ulnaris.","Druck allein 30 s: Sens. 55 %; kombiniert mit voller Beugung: Sens. 91 % (Novak 1994, Gesunde als Vergleich). Bei echten Verdachtsfällen kaum trennscharf (Beekman 2009: Sens. 61 %, Spez. 40 %)."],"durch":"Sitz, Ellbogen 20° gebeugt, Unterarm supiniert. Der Therapeut drückt mit Zeige- und Mittelfinger auf den N. ulnaris knapp proximal des Kubitaltunnels, bis zu 60 Sekunden. Beide Seiten testen. Positiv bei Parästhesien im 4. und 5. Finger.","position":"Sitz","quellen":["Novak CB et al. 1994, Provocative testing for cubital tunnel syndrome. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/7806810/","Beekman R et al. 2009, The diagnostic value of provocative clinical tests in ulnar neuropathy at the elbow is marginal. J Neurol Neurosurg Psychiatry – https://pubmed.ncbi.nlm.nih.gov/19553231/","Novak 1994 – https://www.physiotutors.com/wiki/pressure-provocation-test"],"pos":"Positiv bei Kribbeln oder Taubheit im 4. und 5. Finger während Druck auf den N. ulnaris am Sulcus.","kw":[{"ziel":"Kubitaltunnelsyndrom (Druck allein, 30 s)","sens":"55 %","basis":"Fall-Kontroll-Studie, 32 Patienten (44 Arme) mit ENG-Befund, 33 Gesunde (Novak 1994)"},{"ziel":"Kubitaltunnelsyndrom (Druck plus maximale Ellbogenbeugung, 30 s)","sens":"91 %","basis":"Fall-Kontroll-Studie (Novak 1994); bei Gesunden selten positiv, Spezifität im Abstract nicht beziffert"},{"ziel":"Ulnarisneuropathie am Ellbogen (Flexions-Kompressionstest)","sens":"61 %","spez":"40 %","lrp":"1,0","lrn":"0,98","basis":"Prospektive Kohorte, n = 192 Verdachtsfälle, Referenz ENG + Nervensonografie (Beekman 2009); LR berechnet"}],"evidenz":"mäßig"},"ellbeugetest":{"name":"Ellbogen-Flexionstest","was":"Kubitaltunnelsyndrom (N. ulnaris)","einheit":"positiv oder negativ","kurz":"Ellbogen maximal beugen, Handgelenk extendiert, bis 60 s halten.","ziel":"Kubitaltunnelsyndrom durch Dehnung/Kompression provozieren.","norm":["Positiv bei Parästhesien im Versorgungsgebiet des N. ulnaris.","Allein wenig sensitiv (32 % nach 30 s, Novak 1994); zusammen mit Druck auf den Nerv deutlich empfindlicher (91 %)."],"durch":"Sitz. Der Patient beugt den Ellbogen maximal, Unterarm supiniert, Handgelenk extendiert, und hält bis zu 60 Sekunden. Positiv bei Kribbeln oder Taubheit im 4. und 5. Finger.","position":"Sitz","quellen":["Novak CB et al. 1994, Provocative testing for cubital tunnel syndrome. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/7806810/","Valdes K, LaStayo P 2013, The value of provocative tests for the wrist and elbow: a literature review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/23062797/","Novak 1994 – https://www.physiotutors.com/wiki/pressure-provocation-test"],"pos":"Positiv bei Kribbeln oder Taubheit im 4. und 5. Finger bei maximal gebeugtem Ellbogen innerhalb von 60 s.","kw":[{"ziel":"Kubitaltunnelsyndrom (Beugung allein, 30 s)","sens":"32 %","basis":"Fall-Kontroll-Studie, 44 betroffene Arme, 33 Gesunde (Novak 1994)"}],"evidenz":"schwach"},"tabatiere":{"name":"Druckschmerz Tabatière","was":"Skaphoidfraktur","einheit":"positiv oder negativ","kurz":"Tabatière zwischen den Sehnen des EPL und EPB palpieren.","ziel":"Skaphoidfraktur nach Sturz erkennen.","norm":["Positiv bei Druckschmerz in der Tabatière im Seitenvergleich.","Sehr sensitiv (87–100 %), aber kaum spezifisch. Fehlender Druckschmerz senkt die Frakturwahrscheinlichkeit deutlich (LR- 0,15). Kombination mit Tuberculum und Kompression: Sens. 100 %, Spez. 74 % (Parvizi 1998)."],"durch":"Sitz, Hand in Neutralstellung, leichte Ulnarduktion. Der Therapeut palpiert die Grube zwischen den Sehnen des M. extensor pollicis longus und brevis. Positiv bei deutlichem Druckschmerz. Bei Verdacht ärztliche Abklärung, Bildgebung.","position":"Sitz","quellen":["Mallee WH et al. 2014, Clinical diagnostic evaluation for scaphoid fractures: a systematic review and meta-analysis. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/25091335/","Carpenter CR et al. 2014, Adult scaphoid fracture. Acad Emerg Med – https://pubmed.ncbi.nlm.nih.gov/24673666/","Parvizi J et al. 1998, Combining the clinical signs improves diagnosis of scaphoid fractures. J Hand Surg Br – https://pubmed.ncbi.nlm.nih.gov/9665518/","Parvizi 1998, Chen 1989, Waeckerle 1987 (BestBETs) – https://www.bestbets.org/?p=5060"],"pos":"Positiv bei Druckschmerz in der Tabatière im Seitenvergleich.","kw":[{"ziel":"Skaphoidfraktur","sens":"100 %","spez":"9 %","lrp":"1,1","basis":"Prospektive Studie, n = 215 (Parvizi 1998), LR berechnet"},{"ziel":"Skaphoidfraktur","sens":"87–100 %","spez":"3–98 %","basis":"Systematische Übersicht, 8 Studien, 1164 Patienten, wegen Heterogenität nicht gepoolt (Mallee 2014)"},{"ziel":"Skaphoidfraktur (fehlender Druckschmerz)","lrn":"0,15","basis":"Metaanalyse, Notaufnahme-Patienten mit unauffälligem Röntgen (Carpenter 2014)"},{"ziel":"Skaphoidfraktur (Tabatière + Tuberculum + axiale Kompression kombiniert)","sens":"100 %","spez":"74 %","basis":"Prospektive Studie, n = 215, innerhalb 24 h nach Trauma (Parvizi 1998)"}],"evidenz":"stark"},"tuberculumscaphoidei":{"name":"Druckschmerz Tuberculum ossis scaphoidei","was":"Skaphoidfraktur","einheit":"positiv oder negativ","kurz":"Tuberculum scaphoidei palmar an der distalen Handgelenksfalte palpieren.","ziel":"Skaphoidfraktur erkennen.","norm":["Positiv bei Druckschmerz am Tuberculum im Seitenvergleich.","Sens. 82–100 %, Spez. 17–57 % (Mallee 2014). Allein nicht ausreichend, sinnvoll in Kombination."],"durch":"Sitz, Handgelenk leicht extendiert. Der Therapeut palpiert palmar radial an der distalen Beugefalte das Tuberculum ossis scaphoidei. Positiv bei Druckschmerz.","position":"Sitz","quellen":["Parvizi J et al. 1998, Combining the clinical signs improves diagnosis of scaphoid fractures. J Hand Surg Br – https://pubmed.ncbi.nlm.nih.gov/9665518/","Mallee WH et al. 2014, Clinical diagnostic evaluation for scaphoid fractures: a systematic review and meta-analysis. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/25091335/","Parvizi 1998, Chen 1989, Waeckerle 1987 (BestBETs) – https://www.bestbets.org/?p=5060"],"pos":"Positiv bei Druckschmerz am Tuberculum ossis scaphoidei im Seitenvergleich.","kw":[{"ziel":"Skaphoidfraktur","sens":"100 %","spez":"30 %","lrp":"1,4","basis":"Prospektive Studie, n = 215 (Parvizi 1998), LR berechnet"},{"ziel":"Skaphoidfraktur","sens":"82–100 %","spez":"17–57 %","basis":"Systematische Übersicht (Mallee 2014), nicht gepoolt"}],"evidenz":"mäßig"},"scaphoidkompression":{"name":"Axiale Daumenkompression","was":"Skaphoidfraktur","einheit":"positiv oder negativ","kurz":"Axialen Druck über den Daumen-Längsstrahl Richtung Skaphoid geben.","ziel":"Skaphoidfraktur erkennen.","norm":["Positiv bei Schmerz im Bereich des Skaphoids.","Werte schwanken stark: Sens. 48–100 %, Spez. 22–97 % (Mallee 2014); bei Parvizi 1998 Sens. 100 %, Spez. 48 %."],"durch":"Sitz. Der Therapeut fasst den Daumen und gibt über das erste Metakarpale axialen Druck nach proximal. Positiv bei Schmerz im radialen Handgelenk/Skaphoid.","position":"Sitz","quellen":["Chen SC 1989, The scaphoid compression test. J Hand Surg Br – https://pubmed.ncbi.nlm.nih.gov/2794716/","Parvizi J et al. 1998, Combining the clinical signs improves diagnosis of scaphoid fractures. J Hand Surg Br – https://pubmed.ncbi.nlm.nih.gov/9665518/","Mallee WH et al. 2014, Clinical diagnostic evaluation for scaphoid fractures: a systematic review and meta-analysis. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/25091335/","Parvizi 1998, Chen 1989, Waeckerle 1987 (BestBETs) – https://www.bestbets.org/?p=5060"],"pos":"Positiv bei Schmerz im Bereich des Skaphoids bei axialem Druck über den Daumenstrahl.","kw":[{"ziel":"Skaphoidfraktur","sens":"100 %","spez":"48 %","lrp":"1,9","basis":"Prospektive Studie, n = 215 (Parvizi 1998), LR berechnet"},{"ziel":"Skaphoidfraktur","sens":"48–100 %","spez":"22–97 %","basis":"Systematische Übersicht, 8 Studien, 961 Patienten, nicht gepoolt (Mallee 2014)"}],"evidenz":"mäßig"},"schuettelzeichen":{"name":"Schüttelzeichen (Flick Sign)","was":"Karpaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Fragen, ob Schütteln der Hand die Beschwerden lindert.","ziel":"Typisches KTS-Symptom erfassen.","norm":["Positiv, wenn Schütteln der Hand die Beschwerden lindert.","Sens. 81 %, Spez. 57 %, LR- 0,34 (Wainner 2005); Teil der Prädiktionsregel (4 von 5 positiv: LR+ 4,6; 5 von 5: LR+ 18,3)."],"durch":"Sitz. Der Patient wird gefragt bzw. zeigt, ob Schütteln der Hand die nächtlichen oder belastungsabhängigen Beschwerden bessert. Positiv bei klarer Linderung.","position":"Sitz","quellen":["Wainner RS et al. 2005, Development of a clinical prediction rule for the diagnosis of carpal tunnel syndrome. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/15827908/","Wainner 2005 – https://www.physiotutors.com/wiki/carpal-tunnel-syndrome-cluster/"],"pos":"Positiv, wenn Schütteln oder Bewegen der Hand das Kribbeln oder die Taubheit lindert.","kw":[{"ziel":"Karpaltunnelsyndrom","sens":"81 %","spez":"57 %","lrp":"1,9","lrn":"0,34","basis":"Einzelstudie, n = 82, Referenz Klinik + ENG (Wainner 2005)"},{"ziel":"Karpaltunnelsyndrom, Prädiktionsregel 4 von 5 positiv","sens":"77 %","spez":"83 %","lrp":"4,6","basis":"Wainner 2005, nicht extern validiert"},{"ziel":"Karpaltunnelsyndrom, Prädiktionsregel 5 von 5 positiv","sens":"18 %","spez":"99 %","lrp":"18,3","basis":"Wainner 2005, sehr breites KI (1,0–328)"}],"mess":{"reliab":"Kappa 0,90 (Wainner 2005)"},"evidenz":"mäßig"},"phalen":{"name":"Phalen-Test","was":"Karpaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Handrücken aneinander, Handgelenke maximal flektiert, 60 s halten.","ziel":"N. medianus im Karpaltunnel provozieren.","norm":["Positiv bei Parästhesien im Medianusgebiet innerhalb von 60 s.","Sens. 68 %, Spez. 73 % (Übersicht MacDermid 2004), LR+ etwa 2,5; allein nur mäßig aussagekräftig."],"durch":"Sitz. Der Patient legt die Handrücken aneinander, sodass beide Handgelenke maximal flektiert sind, und hält 60 Sekunden. Positiv bei Parästhesien in Daumen, Zeige-, Mittelfinger und radialem Ringfinger.","position":"Sitz","quellen":["MacDermid JC, Wessel J 2004, Clinical diagnosis of carpal tunnel syndrome: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/15162113/","Núñez de Arenas-Arroyo S et al. 2022, Accuracy of the Most Common Provocation Tests for Diagnosing Carpal Tunnel Syndrome: A Systematic Review With Meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35722757/","Wainner RS et al. 2005, Development of a clinical prediction rule for the diagnosis of carpal tunnel syndrome. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/15827908/","Valdes K, LaStayo P 2013, The value of provocative tests for the wrist and elbow: a literature review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/23062797/","Valdes 2013 – https://www.physiotutors.com/wiki/phalens-test/"],"pos":"Positiv bei Kribbeln oder Taubheit im Medianusgebiet innerhalb von 60 s maximaler Handgelenkflexion.","kw":[{"ziel":"Karpaltunnelsyndrom","sens":"68 %","spez":"73 %","lrp":"2,5","lrn":"0,44","basis":"Systematische Übersicht, gewichtete Mittelwerte (MacDermid 2004), LR berechnet"},{"ziel":"Karpaltunnelsyndrom","basis":"Metaanalyse, 6361 Handgelenke: diagnostische Odds Ratio 7,23 (Núñez de Arenas-Arroyo 2022)"},{"ziel":"Karpaltunnelsyndrom","sens":"77 %","spez":"40 %","lrp":"1,3","lrn":"0,58","basis":"Einzelstudie, n = 82 (Wainner 2005)"}],"mess":{"reliab":"Kappa 0,79 (Wainner 2005)"},"evidenz":"stark"},"tinelhandgelenk":{"name":"Tinel-Zeichen Karpaltunnel","was":"Karpaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Über dem Karpaltunnel auf den N. medianus klopfen.","ziel":"Mechanosensibilität des N. medianus prüfen.","norm":["Positiv bei ausstrahlendem Kribbeln ins Medianusgebiet.","Sens. etwa 50 %, Spez. etwa 77 % (Übersicht MacDermid 2004); allein kaum aussagekräftig, Untersucherübereinstimmung nur mäßig."],"durch":"Sitz, Handgelenk leicht extendiert. Der Therapeut klopft mit Finger oder Reflexhammer palmar über dem Karpaltunnel. Positiv bei elektrisierendem Kribbeln in die radialen Finger.","position":"Sitz","quellen":["MacDermid JC, Wessel J 2004, Clinical diagnosis of carpal tunnel syndrome: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/15162113/","Núñez de Arenas-Arroyo S et al. 2022, Accuracy of the Most Common Provocation Tests for Diagnosing Carpal Tunnel Syndrome: A Systematic Review With Meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35722757/","Wainner RS et al. 2005, Development of a clinical prediction rule for the diagnosis of carpal tunnel syndrome. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/15827908/"],"pos":"Positiv bei Kribbeln, das beim Beklopfen des Karpaltunnels in das Medianusgebiet ausstrahlt.","kw":[{"ziel":"Karpaltunnelsyndrom","sens":"50 %","spez":"77 %","lrp":"2,2","lrn":"0,65","basis":"Systematische Übersicht, gewichtete Mittelwerte vieler Studien (MacDermid 2004), LR berechnet"},{"ziel":"Karpaltunnelsyndrom","basis":"Metaanalyse, 6094 Handgelenke: diagnostische Odds Ratio 5,31 (Núñez de Arenas-Arroyo 2022)"},{"ziel":"Karpaltunnelsyndrom (Tinel Teil B)","sens":"48 %","spez":"67 %","lrp":"1,4","lrn":"0,78","basis":"Einzelstudie, n = 82, Referenz Klinik + ENG (Wainner 2005)"}],"mess":{"reliab":"Kappa 0,35–0,47 zwischen Untersuchern (Wainner 2005)"},"evidenz":"stark"},"durkan":{"name":"Karpalkompressionstest (Durkan)","was":"Karpaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Daumendruck direkt über dem Karpaltunnel für bis zu 30 s.","ziel":"Kompression des N. medianus provozieren.","norm":["Positiv bei Parästhesien im Medianusgebiet innerhalb von 30 s.","Sens. etwa 64 %, Spez. etwa 83 % (Übersicht MacDermid 2004); in der Metaanalyse besser als Phalen und Tinel, aber stark schwankend zwischen Studien."],"durch":"Sitz, Unterarm supiniert, Handgelenk neutral. Der Therapeut drückt mit beiden Daumen gleichmäßig auf den Karpaltunnel, bis zu 30 Sekunden. Positiv bei Parästhesien im Medianusgebiet.","position":"Sitz","quellen":["Durkan JA 1991, A new diagnostic test for carpal tunnel syndrome. J Bone Joint Surg Am – https://pubmed.ncbi.nlm.nih.gov/1796937/","MacDermid JC, Wessel J 2004, Clinical diagnosis of carpal tunnel syndrome: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/15162113/","Núñez de Arenas-Arroyo S et al. 2022, Accuracy of the Most Common Provocation Tests for Diagnosing Carpal Tunnel Syndrome: A Systematic Review With Meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35722757/","Wainner RS et al. 2005, Development of a clinical prediction rule for the diagnosis of carpal tunnel syndrome. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/15827908/"],"pos":"Positiv bei Kribbeln oder Taubheit im Medianusgebiet während direkten Drucks auf den Karpaltunnel (bis 30 s).","kw":[{"ziel":"Karpaltunnelsyndrom","sens":"64 %","spez":"83 %","lrp":"3,8","lrn":"0,43","basis":"Systematische Übersicht, gewichtete Mittelwerte (MacDermid 2004), LR berechnet"},{"ziel":"Karpaltunnelsyndrom","basis":"Metaanalyse, 2662 Handgelenke: diagnostische Odds Ratio 15,84 (Núñez de Arenas-Arroyo 2022)"},{"ziel":"Karpaltunnelsyndrom","sens":"64 %","spez":"30 %","lrp":"0,91","lrn":"1,2","basis":"Einzelstudie, n = 82, gemischtes Zuweiserkollektiv (Wainner 2005)"}],"mess":{"reliab":"Kappa 0,77 (Wainner 2005)"},"evidenz":"stark"},"whattest":{"name":"WHAT-Test","was":"Tendovaginitis de Quervain","einheit":"positiv oder negativ","kurz":"Handgelenk maximal flektiert, Daumen gestreckt und abduziert halten gegen Widerstand.","ziel":"de-Quervain-Tendovaginitis erkennen.","norm":["Positiv bei Schmerz über dem ersten Strecksehnenfach während des Widerstands.","Sens. 99 %, Spez. 29 %, LR- 0,04 gegen Ultraschall (Goubau 2014); die Spezifität beruht auf nur 7 Patienten ohne Befund."],"durch":"Sitz. Der Patient flektiert das Handgelenk maximal (bis zur Schmerzgrenze) und hält den Daumen gestreckt und abduziert. Der Therapeut gibt zunehmend Widerstand gegen die Abduktion. Positiv bei Schmerz über dem ersten Strecksehnenfach.","position":"Sitz","quellen":["Goubau JF et al. 2014, The wrist hyperflexion and abduction of the thumb (WHAT) test: a more specific and sensitive test to diagnose de Quervain tenosynovitis than the Eichhoff's test. J Hand Surg Eur Vol – https://pubmed.ncbi.nlm.nih.gov/23340762/","Goubau 2014 – https://www.physiotutors.com/wiki/what-test/"],"pos":"Positiv bei Schmerz am ersten Strecksehnenfach, wenn der abduzierte Daumen bei maximal flektiertem Handgelenk gegen Widerstand gehalten wird.","kw":[{"ziel":"Tendovaginitis de Quervain","sens":"99 %","spez":"29 %","lrp":"1,4","lrn":"0,04","basis":"Prospektive Studie, n = 100, Referenz Ultraschall, nur 7 Ultraschall-negative (Goubau 2014)"}],"evidenz":"schwach"},"finkelstein":{"name":"Finkelstein-Test","was":"Tendovaginitis de Quervain","einheit":"positiv oder negativ","kurz":"Daumen passiv fassen und Handgelenk nach ulnar duzieren.","ziel":"Sehnen des ersten Strecksehnenfachs dehnen.","norm":["Positiv bei Schmerz über dem Processus styloideus radii bzw. ersten Strecksehnenfach.","Für den Finkelstein-Test im engeren Sinn keine Kennwerte gefunden. Die häufig verwechselte Eichhoff-Variante (Daumen in der Faust): Sens. 89 %, Spez. 14 % (Goubau 2014), also viele falsch Positive."],"durch":"Sitz, Unterarm in Neutralstellung. Der Therapeut fasst den Daumen und führt das Handgelenk passiv in Ulnarduktion. Positiv bei bekanntem Schmerz radial am Handgelenk; Seitenvergleich.","position":"Sitz","quellen":["Goubau JF et al. 2014, The wrist hyperflexion and abduction of the thumb (WHAT) test: a more specific and sensitive test to diagnose de Quervain tenosynovitis than the Eichhoff's test. J Hand Surg Eur Vol – https://pubmed.ncbi.nlm.nih.gov/23340762/","Goubau 2014 – https://www.physiotutors.com/wiki/what-test/"],"pos":"Positiv bei Schmerz über dem ersten Strecksehnenfach bei passiver Ulnarduktion mit gefasstem Daumen.","kw":[{"ziel":"Tendovaginitis de Quervain (Eichhoff-Variante, Daumen in der Faust)","sens":"89 %","spez":"14 %","lrp":"1,04","lrn":"0,75","basis":"Prospektive Studie, n = 100, Referenz Ultraschall, nur 7 Ultraschall-negative (Goubau 2014)"}],"evidenz":"schwach"},"foveazeichen":{"name":"Ulnares Foveazeichen","was":"Läsion des TFCC oder ulnotriquetralen Bandes","einheit":"positiv oder negativ","kurz":"Druck in die Fovea ulnaris zwischen Processus styloideus ulnae und FCU-Sehne.","ziel":"Ulnare Handgelenkverletzung (TFCC) erkennen.","norm":["Positiv bei bekanntem ulnaren Schmerz auf Druck in die Fovea, im Seitenvergleich.","Sens. 95,2 %, Spez. 86,5 % gegen Arthroskopie (Tay 2007, n = 272); unterscheidet nicht zwischen foveolärer Ruptur und ulnotriquetralem Band."],"durch":"Sitz, Unterarm in Neutralrotation. Der Therapeut drückt mit dem Daumen in die weiche Stelle zwischen Processus styloideus ulnae, Sehne des M. flexor carpi ulnaris und Os pisiforme. Positiv bei bekanntem Schmerz. Unterscheidet nicht zwischen foveolärer TFCC-Läsion und ulnotriquetralem Band.","position":"Sitz","quellen":["Tay SC et al. 2007, The \"ulnar fovea sign\" for defining ulnar wrist pain: an analysis of sensitivity and specificity. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/17398352/","Tay 2007 – https://www.patientcareonline.com/view/ulnar-fovea-test-unlocks-tricky-wrist-pain-diagnosis"],"pos":"Positiv, wenn Druck in die Fovea ulnaris den bekannten ulnaren Handgelenkschmerz auslöst, im Seitenvergleich deutlich stärker.","kw":[{"ziel":"Foveoläre TFCC-Ruptur und/oder Läsion des ulnotriquetralen Bandes","sens":"95,2 %","spez":"86,5 %","lrp":"7,1","lrn":"0,06","basis":"Retrospektive Studie, n = 272, Referenz Arthroskopie, ein Untersucher (Tay 2007); LR berechnet"}],"evidenz":"mäßig"},"watson":{"name":"Watson-Test (Scaphoid-Shift)","was":"Skapholunäre Instabilität","einheit":"positiv oder negativ","kurz":"Daumen auf Tuberculum scaphoidei, Handgelenk von ulnar nach radial führen.","ziel":"Skapholunäre Bandläsion erkennen.","norm":["Positiv bei schmerzhaftem Klunk oder Subluxation des Skaphoids im Seitenvergleich.","Sens. 50–69 %, Spez. 66–78 %, LR+ 2–2,9 (drei Arthroskopie-Studien); nur leicht hilfreich, ein negativer Test schließt eine Bandläsion nicht aus."],"durch":"Sitz, Unterarm leicht proniert. Der Therapeut drückt mit dem Daumen palmar auf das Tuberculum ossis scaphoidei und führt das Handgelenk aus Ulnarduktion in Radialduktion. Positiv bei Schmerz dorsal und spürbarem Klunk beim Lösen des Daumens. Seitenvergleich, da auch Gesunde ein Schnappen zeigen können.","position":"Sitz","quellen":["LaStayo P, Howell J 1995, Clinical provocative tests used in evaluating wrist pain: a descriptive study. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/7742888/","Prosser R et al. 2011, Provocative wrist tests and MRI are of limited diagnostic value for suspected wrist ligament injuries: a cross-sectional study. J Physiother – https://pubmed.ncbi.nlm.nih.gov/22093123/","Schmauss D et al. 2022, Relevance of the Scaphoid Shift Test for the Investigation of Scapholunate Ligament Injuries. J Clin Med – https://pubmed.ncbi.nlm.nih.gov/36362552/","Golubev 2023 – https://journals.rcsi.science/0869-8678/article/view/254209"],"pos":"Positiv bei schmerzhaftem Klunk oder dorsaler Subluxation des Skaphoids, die beim Lösen des Daumens zurückspringt.","kw":[{"ziel":"Skapholunäre Bandläsion","sens":"69 %","spez":"66 %","lrp":"2,0","lrn":"0,47","basis":"Einzelstudie, 50 Handgelenke, Referenz Arthroskopie (LaStayo 1995), LR berechnet"},{"ziel":"Skapholunäre Bandläsion","lrp":"2,88","lrn":"0,28","basis":"Querschnittstudie, n = 105, Referenz Arthroskopie (Prosser 2011)"},{"ziel":"Skapholunäre Bandläsion","sens":"50 %","spez":"78 %","lrp":"2,3","lrn":"0,64","basis":"Retrospektive Studie, n = 447, Referenz Arthroskopie (Schmauss 2022), LR berechnet"}],"evidenz":"mäßig"},"fdptest":{"name":"FDP-Test (tiefe Beugesehne)","was":"Ruptur der tiefen Fingerbeugesehne","einheit":"positiv oder negativ","kurz":"Mittelglied fixieren, Patient beugt das Endglied.","ziel":"Funktion des M. flexor digitorum profundus prüfen.","norm":["Positiv bei fehlender aktiver DIP-Flexion bei fixiertem Mittelglied.","Keine Genauigkeitsstudien. Ausriss der tiefen Beugesehne betrifft am häufigsten den Ringfinger; bei Rückzug der Sehne bis in die Hohlhand Versorgung innerhalb von 7 Tagen (Leddy 1977), daher sofort ärztlich vorstellen."],"durch":"Sitz, Hand supiniert auf der Unterlage. Der Therapeut fixiert das Mittelglied in Streckung, der Patient beugt das Endgelenk. Positiv bei fehlender aktiver DIP-Flexion (z. B. Jersey Finger).","position":"Sitz","quellen":["Leddy JP, Packer JW 1977, Avulsion of the profundus tendon insertion in athletes. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/839056/","Shapiro LM, Kamal RN 2020, Evaluation and Treatment of Flexor Tendon and Pulley Injuries in Athletes. Clin Sports Med – https://pubmed.ncbi.nlm.nih.gov/32115085/"],"pos":"Positiv, wenn das Endgelenk bei fixiertem Mittelglied nicht aktiv gebeugt werden kann.","evidenz":"keine"},"fdstest":{"name":"FDS-Test (oberflächliche Beugesehne)","was":"Ruptur der oberflächlichen Fingerbeugesehne","einheit":"positiv oder negativ","kurz":"Nachbarfinger in Streckung halten, Patient beugt den Testfinger im Mittelgelenk.","ziel":"Funktion des M. flexor digitorum superficialis isoliert prüfen.","norm":["Positiv bei fehlender aktiver PIP-Flexion bei gehaltenen Nachbarfingern.","Keine Genauigkeitsstudien. Am Kleinfinger fehlt bei etwa 21 % der Gesunden eine unabhängige FDS-Funktion, bei weiteren 21 % ist sie an den Ringfinger gekoppelt (Austin 1989); dort immer mit der Gegenseite vergleichen."],"durch":"Sitz, Hand supiniert. Der Therapeut hält alle anderen Finger in voller Streckung (blockiert so die tiefe Beugesehne), der Patient beugt den Testfinger. Positiv bei fehlender aktiver PIP-Flexion. Am Kleinfinger kann der FDS physiologisch schwach sein.","position":"Sitz","quellen":["Austin GJ et al. 1989, Variations of the flexor digitorum superficialis of the small finger. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/2703672/"],"pos":"Positiv, wenn das Mittelgelenk bei gestreckt gehaltenen Nachbarfingern nicht aktiv gebeugt werden kann.","evidenz":"keine"},"elson":{"name":"Elson-Test","was":"Ruptur des Tractus intermedius (Central Slip)","einheit":"positiv oder negativ","kurz":"PIP 90° über die Tischkante gebeugt, Mittelglied gegen Widerstand strecken.","ziel":"Frühe Ruptur des Mittelzügels vor Knopflochdeformität erkennen.","norm":["Positiv bei fehlender Streckkraft im PIP und steif gestrecktem DIP.","Keine klinischen Genauigkeitsstudien. Leichenstudie: Zeichen kann direkt nach der Verletzung schwach ausgeprägt sein (Houston 2021); auch falsch negative Fälle beschrieben."],"durch":"Sitz, Finger über eine Tischkante, PIP 90° gebeugt. Der Patient streckt das Mittelglied gegen Widerstand des Therapeuten. Normal: Streckkraft im PIP, DIP bleibt locker. Positiv: keine Streckkraft im PIP, DIP wird steif gestreckt.","position":"Sitz","quellen":["Elson RA 1986, Rupture of the central slip of the extensor hood of the finger: a test for early diagnosis. J Bone Joint Surg Br – https://pubmed.ncbi.nlm.nih.gov/3958008/","Houston T et al. 2021, Experimental Evaluation of the Elson Test Efficiency Following Central Slip Injury. J Hand Surg Glob Online – https://pubmed.ncbi.nlm.nih.gov/35415584/","Janssen P et al. 2022, Central slip and bilateral lateral band laceration with negative Elson's and modified Elson's tests. Trauma Case Rep – https://pubmed.ncbi.nlm.nih.gov/35811612/","ALiEM 2018 – https://www.aliem.com/elsons-test/"],"pos":"Positiv, wenn bei 90° gebeugtem Mittelgelenk keine Streckkraft im PIP aufgebaut werden kann und das Endgelenk dabei steif in Streckung geht.","evidenz":"keine"},"pipseitenband":{"name":"Seitenbandtest Fingermittelgelenk","was":"Läsion Kollateralband PIP","einheit":"positiv oder negativ","kurz":"Grundglied fixieren, Varus- und Valgusstress im PIP in Streckung und leichter Beugung.","ziel":"Seitenbandstabilität der Fingergelenke prüfen.","norm":["Positiv bei vermehrter Aufklappbarkeit oder Schmerz im Seitenvergleich; immer auch in 20–30° Beugung prüfen, sonst falsch negativ.","Mehr als 20° Aufklappung spricht für eine komplette Ruptur des Seitenbands (Leichenstudien Kiefhaber 1986, Minamikawa 1993). Keine klinischen Genauigkeitsstudien."],"durch":"Sitz. Der Therapeut fixiert das Grundglied und gibt über das Mittelglied radialen und ulnaren Stress, in voller Streckung und in etwa 30° Beugung. Positiv bei Aufklappbarkeit im Vergleich zum gleichen Finger der Gegenseite oder bei lokalem Schmerz.","position":"Sitz","quellen":["Kiefhaber TR et al. 1986, Lateral stability of the proximal interphalangeal joint. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/3760491/","Minamikawa Y et al. 1993, Stability and constraint of the proximal interphalangeal joint. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/8463578/"],"pos":"Positiv bei vermehrter seitlicher Aufklappbarkeit oder lokalem Schmerz im Seitenvergleich, geprüft in Streckung und 20–30° Beugung.","evidenz":"schwach"},"ucldaumen":{"name":"Valgusstresstest Daumengrundgelenk","was":"Ruptur ulnares Seitenband Daumen (Skidaumen)","einheit":"positiv oder negativ","kurz":"Daumen-MCP in Streckung und 30° Beugung nach radial aufklappen.","ziel":"Ulnare Seitenbandruptur am Daumengrundgelenk erkennen.","norm":["Positiv bei vermehrter Aufklappbarkeit ohne festen Endpunkt im Seitenvergleich.","Aufklappung über 35° in Streckung spricht für komplette Ruptur mit Stener-Läsion (Heyman 1993). Ohne Betäubung wird die Instabilität oft unterschätzt (Cooper 2005). Bei deutlicher Laxität Entscheidung über OP innerhalb von 2 Wochen (BSSH-Leitlinie 2024)."],"durch":"Sitz. Der Therapeut fixiert das erste Metakarpale und gibt über das Grundglied radial gerichteten Stress, einmal in Streckung und einmal in etwa 30° MCP-Beugung. Positiv bei vermehrter Aufklappbarkeit ohne festen Stopp. Bei Verdacht auf Fraktur vorher Röntgen.","position":"Sitz","quellen":["Heyman P et al. 1993, Injuries of the ulnar collateral ligament of the thumb metacarpophalangeal joint: usefulness of valgus stress testing. Clin Orthop Relat Res – https://pubmed.ncbi.nlm.nih.gov/8519106/","Cooper JG et al. 2005, Local anaesthetic infiltration increases the accuracy of assessment of ulnar collateral ligament injuries. Emerg Med Australas – https://pubmed.ncbi.nlm.nih.gov/15796727/","Dean B et al. 2024, Guideline on managing thumb ulnar collateral ligament injuries: BSSH BEST findings and recommendations. J Hand Surg Eur Vol – https://pubmed.ncbi.nlm.nih.gov/39315553/"],"pos":"Positiv bei deutlich vermehrter radialer Aufklappbarkeit ohne festen Endpunkt im Seitenvergleich, in Streckung und 30° MCP-Beugung.","kw":[{"ziel":"Instabilität ulnares Seitenband Daumen (nach Lokalanästhesie)","sens":"88 %","spez":"100 %","lrn":"0,13","basis":"Einzelstudie, n = 47, Referenz Stress-Röntgen, ca. 1 Woche nach Trauma; LR berechnet"},{"ziel":"Komplette Ruptur mit Stener-Läsion","basis":"Aufklappung > 35° in Streckung: Stener-Läsion in 15 von 17 Fällen (87 %), Heyman 1993"}],"evidenz":"schwach"},"cmcgrind":{"name":"Grind-Test Daumensattelgelenk","was":"Rhizarthrose (Daumensattelgelenk-Arthrose)","einheit":"positiv oder negativ","kurz":"Axiale Kompression des ersten Metakarpale mit gleichzeitiger Rotation.","ziel":"Arthrotische Veränderungen im Daumensattelgelenk provozieren.","norm":["Positiv bei Schmerz oder Krepitation im Daumensattelgelenk.","Spezifisch, aber wenig sensitiv: Sens. 64 %, Spez. 100 % (Sela 2019). Ein negativer Grind-Test schließt Rhizarthrose nicht aus; Lever-Test und Pressure-Shear-Test waren in den Vergleichsstudien sensitiver."],"durch":"Sitz. Der Therapeut fixiert das Trapezium und gibt über das erste Metakarpale axialen Druck mit Rotation. Positiv bei bekanntem Schmerz oder Reiben an der Daumenbasis.","position":"Sitz","quellen":["Sela Y et al. 2019, The diagnostic clinical value of thumb metacarpal grind, pressure-shear, flexion, and extension tests for carpometacarpal osteoarthritis. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/29150383/","Model Z et al. 2016, Evaluation of Physical Examination Tests for Thumb Basal Joint Osteoarthritis. Hand (N Y) – https://pubmed.ncbi.nlm.nih.gov/27418899/","Model 2016 – https://www.physio-pedia.com/Thumb_CMC_Grind_Test"],"pos":"Positiv bei bekanntem Schmerz oder Krepitation an der Daumenbasis bei axialer Kompression mit Rotation.","kw":[{"ziel":"Rhizarthrose","sens":"64 %","spez":"100 %","basis":"Einzelstudie, 127 Daumen (Sela 2019)"},{"ziel":"Rhizarthrose","basis":"Einzelstudie, n = 62: niedrigste Sensitivität und höchste Spezifität der drei geprüften Tests (Model 2016), Zahlen nicht im Abstract"}],"evidenz":"mäßig"},"einbeinstand30":{"name":"Einbeinstand 30 Sekunden","was":"Gluteale Tendinopathie (laterale Hüftschmerzen)","einheit":"positiv oder negativ","kurz":"Auf dem betroffenen Bein bis 30 s stehen, Finger leicht an der Wand.","ziel":"Gluteale Tendinopathie durch Belastung provozieren.","norm":["Positiv bei bekanntem Schmerz über dem Trochanter major von mehr als 2/10 innerhalb von 30 s.","Sens. 38 %, Spez. 100 %, LR+ ca. 12 gegen MRT (Grimaldi 2017, 65 Pat.); Sens. 100 %, Spez. 97,3 % bei Lequesne 2008 (17 Pat. gegen Gesunde, daher zu optimistisch).","Positiv macht eine gluteale Tendinopathie sehr wahrscheinlich, negativ schließt sie nicht aus."],"durch":"Stand neben einer Wand, betroffenes Bein wandfern. Ein Finger berührt zur Balance die Wand. Das andere Knie wird 90° angehoben, die Hüfte bleibt neutral, bis zu 30 Sekunden halten. Positiv bei bekanntem Schmerz über dem Trochanter major ab 2/10.","position":"Stand","quellen":["Grimaldi A et al. 2017, Utility of clinical tests to diagnose MRI-confirmed gluteal tendinopathy in patients presenting with lateral hip pain. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/27633027/","Lequesne M et al. 2008, Gluteal tendinopathy in refractory greater trochanter pain syndrome: diagnostic value of two clinical tests. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/18240186/","Lequesne 2008, Grimaldi 2017 – https://www.physiotutors.com/wiki/single-leg-stance-test/"],"pos":"Positiv, wenn innerhalb von 30 s im Einbeinstand der bekannte Schmerz über dem Trochanter major auftritt.","kw":[{"ziel":"Gluteale Tendinopathie (MRT)","sens":"38 %","spez":"100 %","lrp":"ca. 12","basis":"Einzelstudie, 65 Pat. mit lateralem Hüftschmerz"},{"ziel":"Gluteale Tendinopathie bei therapierefraktärem Trochanterschmerz (MRT)","sens":"100 %","spez":"97,3 %","basis":"Einzelstudie, 17 Pat. gegen gesunde Kontrollen"}],"evidenz":"mäßig"},"trendelenburg":{"name":"Trendelenburg-Zeichen","was":"Insuffizienz der Hüftabduktoren","einheit":"positiv oder negativ","kurz":"Einbeinstand beobachten, Becken auf der Spielbeinseite.","ziel":"Schwäche der Hüftabduktoren erkennen.","norm":["Positiv bei Absinken des Beckens zur Spielbeinseite oder Rumpfneigung zur Standbeinseite.","Gluteale Pathologie: Sens. 61 %, Spez. 92 %, LR+ 6,83 (gepoolt, 3 kleine Studien); bei Hüftarthrose kaum aussagekräftig (LR+ 1,83).","Die Reliabilität ist fraglich: bei Bird 2001 intraindividuell Kappa 0,68, bei Cibere 2008 auch nach Standardisierung als einziger Hüftbefund unzuverlässig."],"durch":"Stand. Der Patient steht etwa 30 Sekunden auf dem Testbein. Der Therapeut beobachtet das Becken von hinten. Positiv bei Absinken des Beckens zur Gegenseite (Trendelenburg) oder Rumpfneigung zur Standbeinseite (Duchenne).","position":"Stand","quellen":["Reiman MP et al. 2015, Physical examination tests for hip dysfunction and injury. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/25736298/","Bird PA et al. 2001, Prospective evaluation of magnetic resonance imaging and physical examination findings in patients with greater trochanteric pain syndrome. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/11592379/","Cibere J et al. 2008, Reliability of the hip examination in osteoarthritis: effect of standardization. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/18311750/","Reiman 2015 – https://bjsm.bmj.com/content/49/6/357.full"],"pos":"Positiv, wenn im Einbeinstand das Becken auf der Spielbeinseite absinkt oder der Rumpf zur Standbeinseite ausweicht.","kw":[{"ziel":"Gluteale Tendinopathie bzw. Glutealsehnenriss","sens":"61 %","spez":"92 %","lrp":"6,83","lrn":"0,25","basis":"Gepoolt, 3 Studien, 78 Pat."},{"ziel":"Riss des M. gluteus medius (MRT)","sens":"72,7 %","spez":"76,9 %","basis":"Einzelstudie, 24 Pat."},{"ziel":"Hüftarthrose","sens":"55 %","spez":"70 %","lrp":"1,83","lrn":"0,82","basis":"Übersicht Reiman 2015, Kriterium Becken-Femur-Winkel ≤ 83° über 30 s"}],"evidenz":"mäßig"},"hockschmerz":{"name":"Schmerz bei tiefer Hocke","was":"Hüftarthrose (Sutlive-Kriterium)","einheit":"positiv oder negativ","kurz":"Patient geht in die tiefe Hocke.","ziel":"Belastungsschmerz des Hüftgelenks erfassen.","norm":["In der Prädiktionsregel nach Sutlive zählt die Angabe in der Anamnese, dass Hocken die Beschwerden verstärkt.","Als Untersuchungstest: Schmerz in der Hocke Sens. 24 %, Spez. 96 %, LR+ 6,1 (Metcalfe 2019 nennt dafür Schmerz an der Hüftrückseite).","Prädiktionsregel: ≥ 3 von 5 Kriterien LR+ 5,2; ≥ 4 von 5 LR+ 24,3 (Sutlive 2008, nicht validiert)."],"durch":"Stand. Der Patient geht so tief wie möglich in die Hocke, Fersen möglichst am Boden. Positiv bei bekanntem Leisten- oder Hüftschmerz.","position":"Stand","quellen":["Sutlive TG et al. 2008, Development of a clinical prediction rule for diagnosing hip osteoarthritis in individuals with unilateral hip pain. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18758047/","Rahman LA et al. 2013, A systematic review of the diagnostic performance of orthopedic physical examination tests of the hip. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/23987589/","Metcalfe D et al. 2019, Does this patient have hip osteoarthritis? The Rational Clinical Examination systematic review. JAMA – https://pubmed.ncbi.nlm.nih.gov/31846019/","Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/"],"pos":"Positiv, wenn die tiefe Hocke den bekannten Hüftschmerz auslöst.","kw":[{"ziel":"Radiologische Hüftarthrose, Schmerz in der Hocke","sens":"24 %","spez":"96 %","lrp":"6,1","lrn":"0,79","basis":"Einzelstudie, 72 Pat. (Sutlive 2008), in Übersichten Rahman 2013 und Metcalfe 2019"},{"ziel":"Radiologische Hüftarthrose, Prädiktionsregel ≥ 3 von 5","sens":"71 %","spez":"86 %","lrp":"5,2","lrn":"0,33","basis":"Einzelstudie, 72 Pat., nicht validiert"}],"evidenz":"mäßig"},"hueftflexionaktiv":{"name":"Aktive Hüftflexion mit lateralem Schmerz","was":"Hüftarthrose (Sutlive-Kriterium)","einheit":"positiv oder negativ","kurz":"Patient beugt die Hüfte aktiv maximal.","ziel":"Bewegungsschmerz des Hüftgelenks erfassen.","norm":["Positiv bei lateralem Hüftschmerz während aktiver Flexion.","Kriterium der Prädiktionsregel nach Sutlive 2008; Einzelkennwerte nicht gefunden. ≥ 3 von 5: LR+ 5,2; ≥ 4 von 5: LR+ 24,3."],"durch":"Rückenlage. Der Patient zieht das Knie aktiv so weit wie möglich zur Brust. Positiv bei Schmerz an der lateralen Hüfte.","position":"Rückenlage","quellen":["Sutlive TG et al. 2008, Development of a clinical prediction rule for diagnosing hip osteoarthritis in individuals with unilateral hip pain. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18758047/","Rahman LA et al. 2013, A systematic review of the diagnostic performance of orthopedic physical examination tests of the hip. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/23987589/","Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/"],"pos":"Positiv, wenn die aktive Hüftflexion lateralen Hüftschmerz auslöst.","kw":[{"ziel":"Radiologische Hüftarthrose, Prädiktionsregel ≥ 3 von 5","sens":"71 %","spez":"86 %","lrp":"5,2","lrn":"0,33","basis":"Einzelstudie, 72 Pat., nicht validiert"}],"evidenz":"schwach"},"irpassiv":{"name":"Passive Hüftinnenrotation ≤ 25°","was":"Hüftarthrose (Sutlive-Kriterium)","einheit":"positiv oder negativ","kurz":"Passive Innenrotation in 90° Hüft- und Knieflexion messen.","ziel":"Kapselmuster der Hüfte erfassen.","norm":["Positiv bei passiver Innenrotation von 25° oder weniger (Sutlive) bzw. deutlich weniger als auf der Gegenseite.","Verminderte Innenrotation: Sens. 66 %, Spez. 79 %, LR+ 3,2 (Metcalfe 2019, JAMA). Teil der Sutlive-Regel."],"durch":"Rückenlage, Hüfte und Knie 90° gebeugt. Der Therapeut führt das Bein passiv in Innenrotation bis zum Bewegungsende und misst mit dem Goniometer. Positiv bei 25° oder weniger.","position":"Rückenlage","quellen":["Metcalfe D et al. 2019, Does this patient have hip osteoarthritis? The Rational Clinical Examination systematic review. JAMA – https://pubmed.ncbi.nlm.nih.gov/31846019/","Sutlive TG et al. 2008, Development of a clinical prediction rule for diagnosing hip osteoarthritis in individuals with unilateral hip pain. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18758047/","Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/"],"pos":"Positiv, wenn die passive Innenrotation in 90° Hüftflexion 25° oder weniger beträgt.","kw":[{"ziel":"Radiologische Hüftarthrose, verminderte passive Innenrotation","sens":"66 %","spez":"79 %","lrp":"3,2","basis":"Systematische Übersicht, 6 Studien, 1110 Pat."},{"ziel":"Radiologische Hüftarthrose, Prädiktionsregel ≥ 3 von 5","sens":"71 %","spez":"86 %","lrp":"5,2","lrn":"0,33","basis":"Einzelstudie, 72 Pat., nicht validiert"}],"evidenz":"mäßig"},"scour":{"name":"Scour-Test","was":"Hüftarthrose, intraartikuläre Pathologie","einheit":"positiv oder negativ","kurz":"Hüfte gebeugt und adduziert, axialer Druck über das Knie bei kreisender Bewegung.","ziel":"Intraartikulären Hüftschmerz provozieren.","norm":["Positiv bei Leisten- oder lateralem Schmerz in Adduktion (Sutlive-Kriterium).","Allein wenig aussagekräftig (intraartikulärer Schmerz: Sens. 50 %, Spez. 29 %). Nur im Sutlive-Cluster sinnvoll."],"durch":"Rückenlage, Hüfte etwa 90° gebeugt. Der Therapeut gibt axialen Druck über das Knie in den Femur und bewegt die Hüfte kreisend von Adduktion in Abduktion. Positiv bei bekanntem Leistenschmerz, besonders in Adduktion.","position":"Rückenlage","quellen":["Rahman LA et al. 2013, A systematic review of the diagnostic performance of orthopedic physical examination tests of the hip. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/23987589/","Maslowski E et al. 2010, The diagnostic validity of hip provocation maneuvers to detect intra-articular hip pathology. PM R – https://pubmed.ncbi.nlm.nih.gov/20359681/","Dhillon J et al. 2025, Sensitivity and specificity for physical examination tests in diagnosing prearthritic intra-articular hip pathology are highly variable: a systematic review. Arthrosc Sports Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/40692936/","Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/"],"pos":"Positiv, wenn der Scour in Adduktion bekannten Leisten- oder lateralen Hüftschmerz auslöst.","kw":[{"ziel":"Radiologische Hüftarthrose, Prädiktionsregel ≥ 3 von 5","sens":"71 %","spez":"86 %","lrp":"5,2","lrn":"0,33","basis":"Einzelstudie, 72 Pat., nicht validiert"},{"ziel":"Intraartikulärer Hüftschmerz (Injektion)","sens":"50 %","spez":"29 %","basis":"Einzelstudie (Maslowski 2010), zitiert in Übersicht Dhillon 2025"}],"evidenz":"schwach"},"fadir":{"name":"FADIR-Test","was":"Femoroazetabuläres Impingement, Labrumläsion","einheit":"positiv oder negativ","kurz":"Hüfte 90° flektieren, dann adduzieren und innenrotieren.","ziel":"FAI oder Labrumläsion ausschließen helfen.","norm":["Positiv bei Reproduktion des bekannten Leistenschmerzes.","Gepoolt Sens. 94–99 %, Spez. 7–8 % (Reiman 2015); gegen Arthroskopie LR- 0,15.","Nur zum Ausschluss geeignet, ein positiver Befund sagt fast nichts. Nur eine Studie mit hoher Qualität."],"durch":"Rückenlage. Der Therapeut flektiert Hüfte und Knie auf 90°, führt dann in Adduktion und Innenrotation bis zum Bewegungsende. Positiv bei Reproduktion des bekannten Leistenschmerzes.","position":"Rückenlage","quellen":["Reiman MP et al. 2015, Diagnostic accuracy of clinical tests for the diagnosis of hip femoroacetabular impingement/labral tear: a systematic review with meta-analysis. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/25515771/","Reiman MP et al. 2015, Physical examination tests for hip dysfunction and injury. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/25736298/","Reiman 2015 – https://www.physiotutors.com/wiki/faddir-test/","Reiman 2015 – https://bjsm.bmj.com/content/49/6/357.full"],"pos":"Positiv, wenn Flexion, Adduktion und Innenrotation den bekannten Leistenschmerz auslösen.","kw":[{"ziel":"FAI/Labrumläsion (MR-Arthrografie)","sens":"94 %","spez":"8 %","lrp":"1,02","lrn":"0,48","basis":"Metaanalyse, 4 Studien, 128 Pat."},{"ziel":"FAI/Labrumläsion (Arthroskopie)","sens":"99 %","spez":"7 %","lrp":"1,06","lrn":"0,15","basis":"Metaanalyse, 2 Studien, 157 Pat."}],"evidenz":"mäßig"},"faber":{"name":"FABER-Test (Patrick)","was":"Hüft- oder ISG-Pathologie","einheit":"positiv oder negativ","kurz":"Ferse aufs gegenseitige Knie (Viererzeichen), Knie Richtung Liege drücken.","ziel":"Hüftgelenk und ISG provozieren und Beweglichkeit vergleichen.","norm":["Positiv bei bekanntem Schmerz oder deutlicher Seitendifferenz; Schmerzort notieren.","Labrumläsion: Sens. 41–82 %, Spez. 18–100 %, stark schwankend (Dhillon 2025).","ISG: gegen intraartikuläre Injektion kein diagnostischer Wert (Schneider 2020). Die NVL Kreuzschmerz nennt das Patrick-Zeichen nur als weiterführende ISG-Untersuchung mit begrenzter Reliabilität."],"durch":"Rückenlage. Die Ferse des Testbeins liegt auf dem gegenseitigen Knie. Der Therapeut fixiert die gegenseitige SIAS und drückt das Knie des Testbeins Richtung Liege. Positiv bei bekanntem Schmerz; Lokalisation notieren (Leiste vs. ISG).","position":"Rückenlage","quellen":["Dhillon J et al. 2025, Sensitivity and specificity for physical examination tests in diagnosing prearthritic intra-articular hip pathology are highly variable: a systematic review. Arthrosc Sports Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/40692936/","Schneider BJ et al. 2020, Validity of physical exam maneuvers in the diagnosis of sacroiliac joint pathology. Pain Med – https://pubmed.ncbi.nlm.nih.gov/31393577/","Bundesärztekammer, KBV, AWMF 2017, Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Auflage – https://www.leitlinien.de/themen/kreuzschmerz","Schneider 2020 – https://www.physiotutors.com/wiki/patricks-test/"],"pos":"Positiv bei bekanntem Schmerz (Leiste spricht für Hüfte, posterior für ISG) oder deutlich eingeschränkter Beweglichkeit im Seitenvergleich.","kw":[{"ziel":"Labrumläsion","sens":"41–82 %","spez":"18–100 %","basis":"Systematische Übersicht, 4 Studien, nicht gepoolt"},{"ziel":"FAI","sens":"81–82 %","spez":"0–25 %","basis":"Systematische Übersicht, 2 Studien"}],"evidenz":"mäßig"},"fader":{"name":"FADER-R-Test","was":"Gluteale Tendinopathie","einheit":"positiv oder negativ","kurz":"Hüfte 90° flektiert, adduziert, außenrotiert; dann Innenrotation gegen Widerstand.","ziel":"Gluteale Sehnen durch Kompression und Spannung provozieren.","norm":["Positiv bei bekanntem lateralem Hüftschmerz über dem Trochanter von mehr als 2/10.","Der Widerstand verbessert die Aussage: LR+ 2,25 für FADER, 6,6 für FADER-R (Grimaldi 2017, 65 Pat., MRT).","FADER-R ist eine Abwandlung des Resisted External Derotation Test nach Lequesne (Sens. 88 %, Spez. 97,3 % bei 17 Pat.)."],"durch":"Rückenlage. Der Therapeut flektiert die Hüfte auf 90°, adduziert und rotiert sie nach außen bis zum Ende. Danach drückt der Patient isometrisch in Innenrotation gegen Widerstand. Positiv bei bekanntem lateralem Schmerz.","position":"Rückenlage","quellen":["Grimaldi A et al. 2017, Utility of clinical tests to diagnose MRI-confirmed gluteal tendinopathy in patients presenting with lateral hip pain. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/27633027/","Lequesne M et al. 2008, Gluteal tendinopathy in refractory greater trochanter pain syndrome: diagnostic value of two clinical tests. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/18240186/","Grimaldi 2017 – https://www.physiotutors.com/wiki/fader-test/"],"pos":"Positiv, wenn die isometrische Innenrotation aus FADER-Stellung den bekannten lateralen Hüftschmerz über 2/10 auslöst.","kw":[{"ziel":"Gluteale Tendinopathie (MRT), FADER-R","lrp":"6,6","basis":"Einzelstudie, 65 Pat."},{"ziel":"Gluteale Tendinopathie (MRT), FADER ohne Widerstand","spez":"86,7 %","lrp":"2,25","basis":"Einzelstudie, 65 Pat."},{"ziel":"Gluteale Tendinopathie, Resisted External Derotation (Ausgangstest nach Lequesne)","sens":"71 %","spez":"84 %","basis":"Gepoolt, 2 Studien, 79 Pat., zitiert in Grimaldi 2017"}],"evidenz":"mäßig"},"thomas":{"name":"Thomas-Test","was":"Verkürzung der Hüftbeuger, Hüftpathologie","einheit":"positiv oder negativ","kurz":"Ein Knie zur Brust ziehen, das andere Bein hängt entspannt; Abheben des Oberschenkels beobachten.","ziel":"Hüftflexionskontraktur erkennen.","norm":["Positiv, wenn der Oberschenkel abhebt (Hüftbeuger) oder das Knie sich streckt (M. rectus femoris).","Als Test für eine Flexionskontraktur nach Standardisierung ausreichend reliabel (Cibere 2008, Hüftarthrose).","Für Labrumläsionen nicht brauchbar: in einer kleinen Studie weder sensitiv noch spezifisch (Narvani 2003, 18 Sportler). Die oft zitierten Werte Sens. 89 %, Spez. 92 % sind keiner prüfbaren Studie zuzuordnen."],"durch":"Rückenlage am Liegenende. Der Patient zieht ein Knie an die Brust, bis die LWS flach aufliegt. Das andere Bein hängt frei. Positiv, wenn der Oberschenkel abhebt (M. iliopsoas) oder das Knie sich streckt (M. rectus femoris).","position":"Rückenlage","quellen":["Cibere J et al. 2008, Reliability of the hip examination in osteoarthritis: effect of standardization. Arthritis Rheum – https://pubmed.ncbi.nlm.nih.gov/18311750/","Narvani AA et al. 2003, A preliminary report on prevalence of acetabular labrum tears in sports patients with groin pain. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/12897984/","Reiman 2015 – https://bjsm.bmj.com/content/49/6/357.full"],"pos":"Positiv, wenn der Oberschenkel des hängenden Beins von der Liege abhebt (Iliopsoas) oder das Knie sich streckt (Rectus femoris).","evidenz":"schwach"},"hueftextensionaktiv":{"name":"Aktive Hüftextension schmerzhaft","was":"Hüftarthrose (Sutlive-Kriterium)","einheit":"positiv oder negativ","kurz":"In Bauchlage das gestreckte Bein aktiv anheben.","ziel":"Bewegungsschmerz des Hüftgelenks erfassen.","norm":["Positiv bei bekanntem Hüftschmerz während aktiver Extension.","Kriterium der Prädiktionsregel nach Sutlive 2008; Einzelkennwerte nicht gefunden."],"durch":"Bauchlage. Der Patient hebt das gestreckte Bein aktiv von der Liege. Positiv bei bekanntem Schmerz in Hüfte oder Leiste.","position":"Bauchlage","quellen":["Sutlive TG et al. 2008, Development of a clinical prediction rule for diagnosing hip osteoarthritis in individuals with unilateral hip pain. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/18758047/","Rahman LA et al. 2013, A systematic review of the diagnostic performance of orthopedic physical examination tests of the hip. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/23987589/","Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/"],"pos":"Positiv, wenn die aktive Hüftextension in Bauchlage bekannten Hüftschmerz auslöst.","kw":[{"ziel":"Radiologische Hüftarthrose, Prädiktionsregel ≥ 3 von 5","sens":"71 %","spez":"86 %","lrp":"5,2","lrn":"0,33","basis":"Einzelstudie, 72 Pat., nicht validiert"}],"evidenz":"schwach"},"wellstvt":{"name":"Wells-Score TVT","was":"Wahrscheinlichkeit einer tiefen Beinvenenthrombose","einheit":"Punkte (−2 bis 9)","kurz":"Neun Kriterien je 1 Punkt, minus 2, wenn eine andere Diagnose mindestens ebenso wahrscheinlich ist. Ab 2 Punkten wahrscheinlich.","ziel":"Vortestwahrscheinlichkeit bei TVT-Verdacht einschätzen und Dringlichkeit begründen.","norm":["2 und mehr Punkte: TVT wahrscheinlich (etwa 28 %), 0–1: unwahrscheinlich (etwa 6 %).","Hoch LR 5,2, niedrig LR 0,25 (Goodacre 2005). Ersetzt keine ärztliche Diagnostik."],"durch":"Abfragen und untersuchen: aktive Krebserkrankung; Lähmung oder Gips am Bein; Bettruhe ab 3 Tagen oder große OP in den letzten 3 Monaten; Druckschmerz entlang der tiefen Venen; Schwellung des ganzen Beins; Unterschenkelumfang mindestens 3 cm größer als auf der Gegenseite; eindrückbares Ödem nur am betroffenen Bein; Kollateralvenen (keine Krampfadern); frühere TVT. Je 1 Punkt, minus 2 bei mindestens ebenso wahrscheinlicher anderer Diagnose.","position":"Sitz oder Rückenlage","quellen":["AWMF 065-002 (2023)","Goodacre 2005, PMID 16027455"]},"ottawaknie":{"name":"Ottawa Knee Rules","was":"Fraktur nach Knietrauma ausschließen","einheit":"positiv oder negativ","kurz":"Fünf Kriterien prüfen: Alter ab 55, isolierter Patelladruckschmerz, Fibulakopf-Druckschmerz, Flexion unter 90°, keine 4 Schritte möglich.","ziel":"Röntgenbedarf nach akutem Knietrauma bestimmen.","norm":["Positiv, wenn mindestens ein Kriterium zutrifft; dann Röntgen.","Sens. 98,5 %, Spez. 48,6 %, LR- 0,05 (Bachmann 2004, 6 Studien). Ein negatives Ergebnis schließt eine Fraktur praktisch aus."],"durch":"Stand und Rückenlage. Abgefragt bzw. geprüft werden: Alter ab 55, isolierter Druckschmerz der Patella, Druckschmerz am Fibulakopf, aktive Flexion unter 90°, Unfähigkeit, direkt nach dem Unfall und bei der Untersuchung 4 Schritte zu gehen. Ein zutreffendes Kriterium reicht für Röntgen.","position":"Stand","quellen":["Bachmann LM et al. 2004, The accuracy of the Ottawa knee rule to rule out knee fractures: a systematic review. Ann Intern Med – https://pubmed.ncbi.nlm.nih.gov/14734335/","Décary S et al. 2017, Diagnostic validity of physical examination tests for common knee disorders: an overview of systematic reviews and meta-analysis. Phys Ther Sport – https://pubmed.ncbi.nlm.nih.gov/27693100/","Bachmann 2004 – https://book.physiotutors.com/?p=125"],"pos":"Positiv, wenn mindestens eines der fünf Kriterien zutrifft; dann Röntgen.","kw":[{"ziel":"Knöcherne Verletzung nach akutem Knietrauma (Erwachsene)","sens":"98,5 %","spez":"48,6 %","lrp":"1,9","lrn":"0,05","basis":"Systematische Übersicht, 6 Studien, 4249 Patienten; LR+ berechnet"}],"evidenz":"stark"},"tanzendepatella":{"name":"Tanzende Patella / Erguss-Test","was":"Kniegelenkerguss","einheit":"positiv oder negativ","kurz":"Recessus suprapatellaris ausstreichen, Patella nach dorsal drücken.","ziel":"Intraartikulären Erguss erkennen.","norm":["Positiv, wenn die Patella spürbar auf den Femur aufschlägt und zurückfedert.","Nach Trauma allein schwach (LR+ 1,6), zusammen mit vom Patienten bemerkter Schwellung LR+ 3,6 (Kastelein 2009).","Gegen Ultraschall sehr spezifisch, aber wenig sensitiv (Sens. 32 %, Spez. 96 %); bei Übergewicht werden Ergüsse häufiger übersehen (Chakyr 2026). Negativ schließt einen Erguss nicht aus."],"durch":"Rückenlage, Knie gestreckt, Muskulatur entspannt. Der Therapeut streicht mit einer Hand den Recessus suprapatellaris nach distal aus und drückt mit der anderen die Patella nach dorsal. Positiv bei federndem Anschlagen der Patella. Kleine Ergüsse eher mit dem Ausstreichtest (Wischtest) erfassen.","position":"Rückenlage","quellen":["Kastelein M et al. 2009, Diagnostic value of history taking and physical examination to assess effusion of the knee in traumatic knee patients in general practice. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19154833/","Chakyr N et al. 2026, Diagnostic performance of clinical examination for detecting knee effusion: impact of obesity and periarticular adiposity. Cureus – https://pubmed.ncbi.nlm.nih.gov/42889892/"],"pos":"Positiv, wenn die Patella nach Ausstreichen des Recessus spürbar auf den Femur aufschlägt und zurückfedert.","kw":[{"ziel":"Erguss im MRT nach Knietrauma (Hausarztpraxis)","lrp":"1,6","basis":"Einzelstudie, 134 Patienten; zusammen mit selbst bemerkter Schwellung LR+ 3,6"},{"ziel":"Erguss im Ultraschall (klinische Untersuchung mit Patellar-Tap)","sens":"31,8 %","spez":"95,5 %","lrp":"7,0","lrn":"0,71","basis":"Querschnittstudie, 400 Knie"}],"evidenz":"mäßig"},"thessaly":{"name":"Thessaly-Test","was":"Meniskusläsion","einheit":"positiv oder negativ","kurz":"Einbeinstand mit 20° Knieflexion, Rumpf dreimal nach innen und außen rotieren.","ziel":"Meniskusläsion unter Belastung provozieren.","norm":["Positiv bei Gelenkspaltschmerz oder Blockierungs-/Schnappgefühl.","20° Flexion: Sens. 75 %, Spez. 87 % (Smith 2015, gepoolt, geringe Studienqualität).","Eine große Primärstudie fand deutlich schlechtere Werte (Sens. 62-66 %, Spez. 39-55 %) und keinen Vorteil gegenüber McMurray oder Gelenkspalt-Druckschmerz (Blyth 2015)."],"durch":"Stand auf dem Testbein, Knie 20° gebeugt, der Therapeut hält beide Hände des Patienten. Der Patient dreht Knie und Körper dreimal nach innen und außen. Zuerst das gesunde Bein testen. Positiv bei Schmerz im Gelenkspalt oder Blockierungsgefühl.","position":"Stand","quellen":["Smith BE et al. 2015, Special tests for assessing meniscal tears within the knee: a systematic review and meta-analysis. Evid Based Med – https://pubmed.ncbi.nlm.nih.gov/25724195/","Blyth M et al. 2015, Diagnostic accuracy of the Thessaly test, standardised clinical history and other clinical examination tests for meniscal tears in comparison with MRI. Health Technol Assess – https://pubmed.ncbi.nlm.nih.gov/26243431/","Smith 2015 – https://ebm.bmj.com/content/20/3/88"],"pos":"Positiv bei bekanntem Gelenkspaltschmerz oder Blockierungs- bzw. Schnappgefühl während der Rotation in 20° Beugung.","kw":[{"ziel":"Meniskusriss (Thessaly 20°)","sens":"75 %","spez":"87 %","lrp":"5,8","lrn":"0,29","basis":"Metaanalyse, 9 Studien insgesamt, geringe Studienqualität; LR berechnet"},{"ziel":"Meniskusriss gegen MRT, durch muskuloskelettale Untersucher","sens":"62 %","spez":"55 %","lrp":"1,4","lrn":"0,69","basis":"Prospektive Studie, 292 Patienten (HTA); LR berechnet"},{"ziel":"Meniskusriss gegen MRT, durch Hausärzte","sens":"66 %","spez":"39 %","basis":"Gleiche Studie (HTA)"}],"evidenz":"mäßig"},"gelenkspalt":{"name":"Druckschmerz Gelenkspalt","was":"Meniskusläsion","einheit":"positiv oder negativ","kurz":"Medialen und lateralen Gelenkspalt bei gebeugtem Knie palpieren.","ziel":"Meniskusläsion lokalisieren.","norm":["Positiv bei Druckschmerz im medialen oder lateralen Gelenkspalt.","Sens. 83 %, Spez. 83 % (Smith 2015, gepoolt); in einer älteren Übersicht sensitiv, aber kaum spezifisch (Sens. 75 %, Spez. 27 %, Jackson 2003). Die Werte schwanken stark."],"durch":"Rückenlage oder Sitz, Knie etwa 90° gebeugt. Der Therapeut palpiert den medialen und lateralen Gelenkspalt von ventral nach dorsal. Positiv bei bekanntem, lokalem Druckschmerz.","position":"Rückenlage","quellen":["Smith BE et al. 2015, Special tests for assessing meniscal tears within the knee: a systematic review and meta-analysis. Evid Based Med – https://pubmed.ncbi.nlm.nih.gov/25724195/","Jackson JL et al. 2003, Evaluation of acute knee pain in primary care. Ann Intern Med – https://pubmed.ncbi.nlm.nih.gov/14530229/","Smith 2015 – https://ebm.bmj.com/content/20/3/88"],"pos":"Positiv bei bekanntem, lokalem Druckschmerz im medialen oder lateralen Gelenkspalt.","kw":[{"ziel":"Meniskusriss","sens":"83 %","spez":"83 %","lrp":"4,9","lrn":"0,20","basis":"Metaanalyse (Smith 2015), geringe Studienqualität, hohe Heterogenität; LR berechnet"},{"ziel":"Meniskusriss, Arthroskopie als Referenz","sens":"75 %","spez":"27 %","lrp":"1,0","lrn":"0,93","basis":"Systematische Übersicht (Jackson 2003); LR berechnet"}],"evidenz":"mäßig"},"valgusstress":{"name":"Valgusstresstest Knie","was":"Läsion des medialen Kollateralbandes","einheit":"positiv oder negativ","kurz":"Valgusstress in voller Streckung und in 20-30° Beugung.","ziel":"Mediale Bandstabilität prüfen.","norm":["Positiv bei Schmerz oder vermehrter medialer Aufklappbarkeit in 20-30° Beugung; Aufklappbarkeit in Streckung spricht für zusätzliche Kapsel- oder Kreuzbandläsion.","Schmerz bei Valgusstress in 30°: LR+ 2,3; zusammen mit Aufklappbarkeit und passender Anamnese (Gewalt von außen, Rotationstrauma) LR+ 6,4 (Kastelein 2008)."],"durch":"Rückenlage. Der Therapeut fixiert den Oberschenkel, gibt am distalen Unterschenkel Valgusstress und palpiert den medialen Gelenkspalt. Zuerst in 20-30° Flexion, dann in voller Streckung. Seitenvergleich.","position":"Rückenlage","quellen":["Kastelein M et al. 2008, Assessing medial collateral ligament knee lesions in general practice. Am J Med – https://pubmed.ncbi.nlm.nih.gov/18954845/","Malanga GA et al. 2003, Physical examination of the knee: a review of the original test description and scientific validity of common orthopedic tests. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/12690600/"],"pos":"Positiv bei Schmerz oder vermehrter medialer Aufklappbarkeit in 30° Beugung im Seitenvergleich.","kw":[{"ziel":"Läsion des medialen Kollateralbandes im MRT (Hausarztpraxis, bis 5 Wochen nach Trauma)","lrp":"2,3","basis":"Einzelstudie, 134 Patienten; Kriterium Schmerz bei Valgusstress in 30°"},{"ziel":"Läsion des medialen Kollateralbandes, Anamnese plus Schmerz und Aufklappbarkeit in 30°","lrp":"6,4","basis":"Gleiche Studie, Kombination"}],"evidenz":"mäßig"},"varusstress":{"name":"Varusstresstest Knie","was":"Läsion des lateralen Kollateralbandes","einheit":"positiv oder negativ","kurz":"Varusstress in voller Streckung und in 20-30° Beugung.","ziel":"Laterale Bandstabilität prüfen.","norm":["Positiv bei vermehrter lateraler Aufklappbarkeit oder Schmerz im Seitenvergleich.","Keine Studien zur diagnostischen Genauigkeit gefunden. Bei Aufklappbarkeit an eine Verletzung der posterolateralen Ecke denken; Experten empfehlen dann Stressröntgen (LaPrade 2025, Konsens)."],"durch":"Rückenlage. Der Therapeut fixiert den Oberschenkel, gibt am distalen Unterschenkel Varusstress und palpiert den lateralen Gelenkspalt. In 20-30° Flexion und in voller Streckung. Seitenvergleich.","position":"Rückenlage","quellen":["Malanga GA et al. 2003, Physical examination of the knee: a review of the original test description and scientific validity of common orthopedic tests. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/12690600/","LaPrade RF et al. 2025, A contemporary international expert consensus statement on the evaluation, diagnosis, treatment, and rehabilitation of injuries to the posterolateral corner of the knee. Arthroscopy – https://pubmed.ncbi.nlm.nih.gov/40414466/"],"pos":"Positiv bei Schmerz oder vermehrter lateraler Aufklappbarkeit im Seitenvergleich.","evidenz":"keine"},"hinteresag":{"name":"Hinteres Schubladenzeichen in Ruhe (Sag Sign)","was":"Ruptur des hinteren Kreuzbandes","einheit":"positiv oder negativ","kurz":"Hüfte und Knie 90° gebeugt, Tibiaplateau von der Seite beobachten.","ziel":"Spontane hintere Tibiasubluxation erkennen.","norm":["Positiv, wenn die Tibia im Vergleich zur Gegenseite nach dorsal durchhängt.","Keine belastbaren Einzelwerte gelesen. Laut systematischer Übersicht ist die Genauigkeit der HKB-Tests weitgehend unbekannt (Kopkow 2013); das Sag Sign ergänzt die hintere Schublade (Malanga 2003)."],"durch":"Rückenlage, Hüften und Knie beidseits 90° gebeugt, Unterschenkel unterstützt oder Füße aufgestellt (45°). Der Therapeut vergleicht die Kontur der Tuberositas tibiae von der Seite. Positiv bei sichtbarem Durchhängen. Vor der vorderen Schublade prüfen, sonst wird eine hintere Instabilität als vordere fehlgedeutet.","position":"Rückenlage","quellen":["Kopkow C et al. 2013, Physical examination tests for the diagnosis of posterior cruciate ligament rupture: a systematic review. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/24175598/","Malanga GA et al. 2003, Physical examination of the knee: a review of the original test description and scientific validity of common orthopedic tests. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/12690600/","Rubinstein 1994 – https://ebmconsult.com/articles/physical-exam-posterior-drawer-test"],"pos":"Positiv, wenn die Tibia bei 90° Hüft- und Kniebeugung im Seitenvergleich sichtbar nach dorsal durchhängt.","evidenz":"keine"},"hintereschublade":{"name":"Hintere Schublade","was":"Ruptur des hinteren Kreuzbandes","einheit":"positiv oder negativ","kurz":"Knie 90° gebeugt, Fuß fixiert, Tibia nach dorsal schieben.","ziel":"Hintere Kreuzbandstabilität prüfen.","norm":["Positiv bei vermehrter dorsaler Verschiebung der Tibia ohne festen Anschlag.","Klinische Untersuchung bei chronischer isolierter HKB-Ruptur: Sens. 90 %, Spez. 99 % (Rubinstein 1994, n = 39); die hintere Schublade mit Tasten der Tibiastufe war dabei der beste Einzeltest. Bei akuter Verletzung und Grad I deutlich unsicherer (Kopkow 2013)."],"durch":"Rückenlage, Hüfte 45°, Knie 90° gebeugt, Fuß fixiert. Der Therapeut umfasst den proximalen Unterschenkel und schiebt die Tibia nach dorsal. Positiv bei vermehrter Translation und weichem Endgefühl im Seitenvergleich.","position":"Rückenlage","quellen":["Rubinstein RA Jr et al. 1994, The accuracy of the clinical examination in the setting of posterior cruciate ligament injuries. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/7943523/","Kopkow C et al. 2013, Physical examination tests for the diagnosis of posterior cruciate ligament rupture: a systematic review. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/24175598/","Rubinstein 1994 – https://ebmconsult.com/articles/physical-exam-posterior-drawer-test"],"pos":"Positiv bei vermehrter dorsaler Tibiaverschiebung ohne festen Anschlag oder verlorener Stufe zwischen Tibiaplateau und Femurkondylen.","kw":[{"ziel":"Chronische isolierte HKB-Ruptur (klinische Gesamtuntersuchung, Schwerpunkt hintere Schublade mit Stufentastung)","sens":"90 %","spez":"99 %","lrp":"90","lrn":"0,10","basis":"Verblindete Einzelstudie, 39 Probanden, Fachärzte; LR berechnet"}],"evidenz":"mäßig"},"leversign":{"name":"Lever-Sign-Test (Lelli)","was":"Ruptur des vorderen Kreuzbandes","einheit":"positiv oder negativ","kurz":"Faust unter proximalen Unterschenkel, Druck auf distalen Oberschenkel, Ferse beobachten.","ziel":"VKB-Ruptur auch bei abwehrgespanntem Patienten erkennen.","norm":["Positiv, wenn die Ferse bei Druck auf den Oberschenkel nicht von der Liege abhebt.","Sens. 77-79 %, Spez. 90-92 % (Abruscato 2019; Hesmerg 2024). In der akuten Primärversorgung nur Sens. 61 % (Bucher 2022), dort Lachman deutlich sensitiver."],"durch":"Rückenlage, Bein gestreckt. Der Therapeut legt eine Faust unter das proximale Drittel des Unterschenkels und drückt mit der anderen Hand auf das distale Drittel des Oberschenkels. Bei intaktem VKB hebt die Ferse ab. Positiv, wenn die Ferse liegen bleibt.","position":"Rückenlage","quellen":["Abruscato K et al. 2019, Diagnostic accuracy of the lever sign in detecting anterior cruciate ligament tears: a systematic review and meta-analysis. Int J Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/30746288/","Hesmerg MK et al. 2024, Lever sign test shows high diagnostic accuracy for anterior cruciate ligament injuries: a systematic review and meta-analysis of 3299 observations. Knee – https://pubmed.ncbi.nlm.nih.gov/38310817/","Bucher C et al. 2022, Validity of the lever sign test for the clinical diagnosis of anterior cruciate ligament tears: assessments in ski resorts. Orthop Traumatol Surg Res – https://pubmed.ncbi.nlm.nih.gov/35183758/","Metaanalyse 2019 (zit. nach Physiotutors) – https://www.physiotutors.com/research/lever-sign-test-for-acl-tears/"],"pos":"Positiv, wenn die Ferse bei Druck auf den distalen Oberschenkel nicht von der Liege abhebt.","kw":[{"ziel":"VKB-Ruptur","sens":"77 %","spez":"90 %","lrp":"6,6","lrn":"0,22","basis":"Metaanalyse, 8 Studien (Abruscato 2019)"},{"ziel":"VKB-Ruptur, ohne Narkose","sens":"79 %","spez":"92 %","lrp":"9,9","lrn":"0,23","basis":"Metaanalyse, 23 Studien, 3299 Untersuchungen (Hesmerg 2024); LR berechnet"},{"ziel":"Akute VKB-Ruptur, Skiunfälle, Allgemeinärzte","sens":"61 %","basis":"Prospektive Kohorte, 258 Patienten (Bucher 2022)"}],"evidenz":"stark"},"ottawafuss":{"name":"Ottawa Ankle Rules","was":"Fraktur Sprunggelenk/Mittelfuß ausschließen","einheit":"positiv oder negativ","kurz":"Druckschmerz an Malleolen-Hinterkante, Os naviculare, Basis Metatarsale V und Gehfähigkeit prüfen.","ziel":"Röntgenbedarf nach Supinationstrauma bestimmen.","norm":["Positiv bei Knochendruckschmerz an einem Prüfpunkt oder Unfähigkeit, 4 Schritte zu gehen; dann Röntgen.","Sens. nahezu 100 %, LR- 0,08 für Sprunggelenk und Mittelfuß; bei 15 % Frakturprävalenz bleibt nach negativem Test ein Restrisiko unter 1,4 % (Bachmann 2003). Spart 30-40 % der Röntgenbilder."],"durch":"Stand und Sitz. Palpiert werden die hinteren 6 cm und die Spitze von Außen- und Innenknöchel, die Basis des Metatarsale V und das Os naviculare. Zusätzlich wird geprüft, ob der Patient direkt nach dem Unfall und jetzt 4 Schritte gehen kann. Ein positiver Punkt reicht für Röntgen.","position":"Stand","quellen":["Bachmann LM et al. 2003, Accuracy of Ottawa ankle rules to exclude fractures of the ankle and mid-foot: systematic review. BMJ – https://pubmed.ncbi.nlm.nih.gov/12595378/","Zusatz: Ottawa rules simplify the management of ankle injuries, AAFP-Zusammenfassung 2003. Am Fam Physician – https://www.aafp.org/pubs/afp/issues/2003/0815/p745a.html"],"pos":"Positiv bei Knochendruckschmerz an einem Prüfpunkt oder Unfähigkeit, 4 Schritte zu gehen; dann Röntgen.","kw":[{"ziel":"Fraktur Sprunggelenk","lrn":"0,08","basis":"Systematische Übersicht, 27 Studien, 15 581 Patienten"},{"ziel":"Fraktur Mittelfuß","lrn":"0,08","basis":"Gleiche Übersicht"},{"ziel":"Fraktur Sprunggelenk oder Mittelfuß, gesamt","sens":"97,6 %","spez":"31,5 %","basis":"Gleiche Übersicht, Angaben laut AAFP-Zusammenfassung"}],"evidenz":"stark"},"lfapalpation":{"name":"Druckschmerz Lig. fibulotalare anterius","was":"Läsion des Außenbandes (LFTA)","einheit":"positiv oder negativ","kurz":"Lig. fibulotalare anterius vor dem Außenknöchel palpieren, Hämatom beobachten.","ziel":"Außenbandverletzung lokalisieren.","norm":["Positiv bei Druckschmerz über dem LFTA, besonders mit Hämatom.","Allein sehr sensitiv, kaum spezifisch: kein Druckschmerz spricht gegen eine LFTA-Verletzung (Netterström-Wedin 2022).","Zusammen mit Hämatom und vorderer Schublade nach 4-5 Tagen: Sens. 96 %, Spez. 84 % (van Dijk 1996)."],"durch":"Sitz oder Rückenlage. Der Therapeut palpiert das Band vom Vorderrand des Außenknöchels zum Talushals. Zusätzlich auf Hämatomverfärbung achten. Positiv bei lokalem Druckschmerz.","position":"Sitz","quellen":["Netterström-Wedin F et al. 2022, Diagnostic accuracy of clinical tests assessing ligamentous injury of the talocrural and subtalar joints: a systematic review with meta-analysis. Sports Health – https://pubmed.ncbi.nlm.nih.gov/34286639/","van Dijk CN et al. 1996, Physical examination is sufficient for the diagnosis of sprained ankles. J Bone Joint Surg Br – https://pubmed.ncbi.nlm.nih.gov/8951015/","van Dijk CN et al. 1996, Diagnosis of ligament rupture of the ankle joint: physical examination, arthrography, stress radiography and sonography compared in 160 patients after inversion trauma. Acta Orthop Scand – https://pubmed.ncbi.nlm.nih.gov/9065068/","van Dijk 1996 – https://boneandjoint.org.uk/Article/10.1302/0301-620X.78B6.0780958"],"pos":"Positiv bei Druckschmerz über dem Lig. fibulotalare anterius, besonders zusammen mit Hämatom.","kw":[{"ziel":"Verletzung des LFTA (Palpation allein)","sens":"95-100 %","spez":"0-32 %","basis":"Systematische Übersicht, 6 Studien, Spannweite"},{"ziel":"Bandruptur, verzögerte Untersuchung nach etwa 5 Tagen (Druckschmerz, Hämatom, vordere Schublade zusammen)","sens":"96 %","spez":"84 %","lrp":"6,0","lrn":"0,05","basis":"Prospektive Studie, 160 Patienten (van Dijk 1996); LR berechnet"}],"evidenz":"stark"},"schubladeosg":{"name":"Vordere Schublade OSG","was":"Ruptur Lig. fibulotalare anterius","einheit":"positiv oder negativ","kurz":"Unterschenkel fixieren, Ferse in leichter Plantarflexion nach ventral ziehen.","ziel":"Anteriore Instabilität des OSG prüfen.","norm":["Positiv bei vermehrter Ventralverschiebung des Talus, oft mit Sulcus-Zeichen, im Seitenvergleich.","Gepoolt Sens. 54 %, Spez. 87 %: positiv spricht für eine LFTA-Verletzung, negativ schließt sie nicht aus (Netterström-Wedin 2022). Am besten zusammen mit der Palpation und verzögert nach 4-5 Tagen (van Dijk 1996)."],"durch":"Sitz mit hängendem Unterschenkel oder Rückenlage, Fuß in etwa 10-20° Plantarflexion. Der Therapeut fixiert die distale Tibia und zieht die Ferse nach ventral. Positiv bei vermehrter Verschiebung und weichem Endgefühl. Am besten 4-5 Tage nach dem Trauma, wenn die Schwellung abnimmt.","position":"Sitz","quellen":["Netterström-Wedin F et al. 2022, Diagnostic accuracy of clinical tests assessing ligamentous injury of the talocrural and subtalar joints: a systematic review with meta-analysis. Sports Health – https://pubmed.ncbi.nlm.nih.gov/34286639/","Croy T et al. 2013, Anterior talocrural joint laxity: diagnostic accuracy of the anterior drawer test of the ankle. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/24175608/","van Dijk CN et al. 1996, Physical examination is sufficient for the diagnosis of sprained ankles. J Bone Joint Surg Br – https://pubmed.ncbi.nlm.nih.gov/8951015/","van Dijk 1996, Croy 2013 – https://www.physio-pedia.com/Anterior_Drawer_of_the_Ankle","van Dijk 1996 – https://boneandjoint.org.uk/Article/10.1302/0301-620X.78B6.0780958"],"pos":"Positiv bei vermehrter Ventralverschiebung des Talus mit weichem Endgefühl oder Sulcus-Zeichen im Seitenvergleich.","kw":[{"ziel":"Verletzung des LFTA nach Supinationstrauma","sens":"54 %","spez":"87 %","lrp":"4,2","lrn":"0,53","basis":"Metaanalyse, 6 Studien, 885 Untersuchungen (Netterström-Wedin 2022); LR berechnet"},{"ziel":"Vermehrte Laxität im Stress-Ultraschall (ab 2,3 mm)","sens":"74 %","spez":"38 %","lrp":"1,2","lrn":"0,66","basis":"Prospektive Einzelstudie, 66 Patienten (Croy 2013)"},{"ziel":"Vermehrte Laxität im Stress-Ultraschall (ab 3,7 mm)","sens":"83 %","spez":"40 %","lrp":"1,4","lrn":"0,41","basis":"Gleiche Studie"}],"evidenz":"stark"},"squeeze":{"name":"Squeeze-Test (Syndesmose)","was":"Läsion der Syndesmose","einheit":"positiv oder negativ","kurz":"Tibia und Fibula in Unterschenkelmitte zusammendrücken.","ziel":"Syndesmosenverletzung provozieren.","norm":["Positiv bei Schmerz distal im Bereich der Syndesmose.","Sens. 26 %, Spez. 88 %, LR+ 2,15 (Sman 2015). Eher zum Bestätigen; frühere Studien widersprüchlich, kein Einzeltest sicher (Sman 2013)."],"durch":"Rückenlage oder Sitz. Der Therapeut umfasst den Unterschenkel in der Mitte und drückt Fibula und Tibia zusammen. Positiv bei Schmerz distal über der Syndesmose, nicht an der Druckstelle.","position":"Rückenlage","quellen":["Sman AD et al. 2015, Diagnostic accuracy of clinical tests for ankle syndesmosis injury. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/24255766/","Sman AD et al. 2013, Diagnostic accuracy of clinical tests for diagnosis of ankle syndesmosis injury: a systematic review. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/23222193/","Sman 2013 – https://www.physiotutors.com/wiki/syndesmosis-squeeze-test/","Sman 2013 – https://bjsm.bmj.com/content/47/10/620.abstract"],"pos":"Positiv bei Schmerz distal über der Syndesmose beim Zusammendrücken von Tibia und Fibula in Unterschenkelmitte.","kw":[{"ziel":"Syndesmosenverletzung im MRT (bis 2 Wochen nach Trauma)","sens":"26 %","spez":"88 %","lrp":"2,15","lrn":"0,84","basis":"Prospektive Studie, 87 Patienten (Sman 2015)"}],"evidenz":"mäßig"},"kleiger":{"name":"Außenrotations-Stresstest (Kleiger)","was":"Läsion der Syndesmose","einheit":"positiv oder negativ","kurz":"Unterschenkel fixieren, Fuß in Dorsalextension nach außen rotieren.","ziel":"Syndesmosenverletzung provozieren.","norm":["Positiv bei Schmerz über der Syndesmose.","Sens. 71 %, Spez. 63 %, LR- 0,46 (Sman 2015): eher zum Ausschließen, zusammen mit Druckschmerz über dem vorderen Syndesmosenband (Sens. 92 %). Gute Interrater-Reliabilität (Sman 2013)."],"durch":"Sitz mit hängendem Unterschenkel, Knie 90° gebeugt. Der Therapeut fixiert den Unterschenkel, bringt den Fuß in Neutral- bis Dorsalextension und rotiert ihn nach außen. Positiv bei Schmerz an der vorderen Syndesmose.","position":"Sitz","quellen":["Sman AD et al. 2015, Diagnostic accuracy of clinical tests for ankle syndesmosis injury. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/24255766/","Sman AD et al. 2013, Diagnostic accuracy of clinical tests for diagnosis of ankle syndesmosis injury: a systematic review. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/23222193/","Sman 2013 – https://bjsm.bmj.com/content/47/10/620.abstract"],"pos":"Positiv bei Schmerz über der vorderen Syndesmose bei Außenrotation des Fußes in Dorsalextension.","kw":[{"ziel":"Syndesmosenverletzung im MRT (Dorsalextensions-Außenrotations-Stresstest)","sens":"71 %","spez":"63 %","lrp":"1,93","lrn":"0,46","basis":"Prospektive Studie, 87 Patienten (Sman 2015)"}],"mess":{"reliab":"Interrater ICC > 0,70 (Sman 2013)"},"evidenz":"mäßig"},"raldt":{"name":"Reverse anterolateraler Schubladentest","was":"Chronische laterale Sprunggelenksinstabilität","einheit":"positiv oder negativ","kurz":"Fuß fixieren, Tibia und Fibula nach dorsal schieben, Delle vor dem LFTA tasten.","ziel":"Insuffizienz des LFTA erkennen.","norm":["Positiv bei vermehrter Verschiebung mit tastbarer Delle anterolateral.","Sens. 87-92 %, Spez. 88-91 % gegen Ultraschall, je nach Untersucher; deutlich besser als die klassische Schublade in derselben Studie (Li 2020, Einzelstudie)."],"durch":"Rückenlage, Ferse auf der Liege, Fuß in leichter Plantarflexion fixiert. Der Therapeut schiebt Tibia und Fibula nach dorsal und tastet anterolateral eine Delle zwischen Fibula und Talus. Positiv bei vermehrter Translation und tastbarer Einziehung im Seitenvergleich.","position":"Rückenlage","quellen":["Li Q et al. 2020, Reverse anterolateral drawer test is more sensitive and accurate for diagnosing chronic anterior talofibular ligament injury. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/31559464/","Übersicht chron. Instabilität (Li 2020, Jolman 2017) – https://aoj.amegroups.org/article/view/8912/html"],"pos":"Positiv bei vermehrter Translation mit tastbarer Delle anterolateral zwischen Fibula und Talus im Seitenvergleich.","kw":[{"ziel":"Chronische LFTA-Verletzung (Ultraschall), erfahrener Untersucher","sens":"86,8 %","spez":"91,2 %","lrp":"9,9","lrn":"0,14","basis":"Einzelstudie, 72 Sprunggelenke (Li 2020); LR berechnet"},{"ziel":"Chronische LFTA-Verletzung (Ultraschall), unerfahrener Untersucher","sens":"92,1 %","spez":"88,2 %","lrp":"7,8","lrn":"0,09","basis":"Gleiche Studie; LR berechnet"}],"mess":{"reliab":"Kappa 0,64 zwischen den Untersuchern"},"evidenz":"mäßig"},"taluskippung":{"name":"Talar-Tilt-Test","was":"Läsion Lig. calcaneofibulare, Außenbandinstabilität","einheit":"positiv oder negativ","kurz":"Kalkaneus in Neutralstellung umfassen und in Inversion kippen.","ziel":"Stabilität des Lig. calcaneofibulare prüfen.","norm":["Positiv bei vermehrter Inversionskippung oder weichem Endgefühl im Seitenvergleich.","Spezifisch (82-100 %), aber wenig sensitiv (17-66 %): positiv spricht für eine Verletzung des Lig. calcaneofibulare, negativ schließt sie nicht aus (Netterström-Wedin 2022).","Für die Einteilung des Schweregrads mäßige Übereinstimmung mit Ultraschall (Kappa 0,51; Wagemans 2026)."],"durch":"Rückenlage oder Sitz, OSG in Neutralstellung. Der Therapeut fixiert den distalen Unterschenkel, umfasst den Kalkaneus und kippt Rückfuß und Talus in Inversion. Positiv bei vermehrter Aufklappbarkeit lateral.","position":"Rückenlage","quellen":["Netterström-Wedin F et al. 2022, Diagnostic accuracy of clinical tests assessing ligamentous injury of the talocrural and subtalar joints: a systematic review with meta-analysis. Sports Health – https://pubmed.ncbi.nlm.nih.gov/34286639/","Wagemans J et al. 2026, Clinical assessments are valid to grade ligament injury severity compared to ultrasound imaging in patients with acute lateral ankle sprains. Phys Ther Sport – https://pubmed.ncbi.nlm.nih.gov/41448038/","Übersicht chron. Instabilität (Li 2020, Jolman 2017) – https://aoj.amegroups.org/article/view/8912/html"],"pos":"Positiv bei vermehrter Inversionskippung des Talus oder weichem Endgefühl im Seitenvergleich.","kw":[{"ziel":"Verletzung des Lig. calcaneofibulare oder des lateralen Bandapparats","sens":"17-66 %","spez":"82-100 %","basis":"Systematische Übersicht, 4 Studien, Spannweite (Netterström-Wedin 2022)"}],"evidenz":"mäßig"},"toomanytoes":{"name":"Too-many-toes-Zeichen","was":"Insuffizienz der Tibialis-posterior-Sehne, Plattfuß","einheit":"positiv oder negativ","kurz":"Stehenden Patienten von hinten betrachten und sichtbare Zehen lateral der Ferse zählen.","ziel":"Rückfußvalgus und Vorfußabduktion erkennen.","norm":["Positiv, wenn lateral des Unterschenkels mehr Zehen sichtbar sind als auf der Gegenseite.","Keine Kennwerte zur Genauigkeit gefunden. Das Ergebnis hängt stark von der Blickhöhe ab; im Stand aus gleicher Augenhöhe beurteilen (Oyamada 2026, kleine Studie)."],"durch":"Stand, Füße hüftbreit. Der Therapeut steht hinter dem Patienten und zählt die lateral der Ferse sichtbaren Zehen. Positiv bei mehr sichtbaren Zehen als auf der Gegenseite.","position":"Stand","quellen":["Oyamada C et al. 2026, Impact of imaging height on diagnostic accuracy of the too many toes sign in flatfoot. Prog Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/42416517/","Lubcke 2019 (Review-Abstract) – https://apodc-2019.p.asnevents.com.au/days/2019-05-22/abstract/59729"],"pos":"Positiv, wenn von hinten lateral der Ferse mehr Zehen sichtbar sind als auf der Gegenseite.","evidenz":"keine"},"einbeinfersenstand":{"name":"Einbeiniger Fersenstand","was":"Tibialis-posterior-Dysfunktion","einheit":"positiv oder negativ","kurz":"Einbeinig auf die Zehenspitzen gehen, Rückfußbewegung und Wiederholungen beobachten.","ziel":"Funktion der Tibialis-posterior-Sehne prüfen.","norm":["Positiv, wenn das Anheben nicht gelingt, Schmerz auftritt oder die Ferse dabei nicht in Varus geht.","Zuverlässigster Test für die Tibialis-posterior-Tendinopathie (Kappa 0,74) mit dem engsten Zusammenhang zum Ultraschallbefund (Ross 2021); Sens./Spez. fehlen."],"durch":"Stand auf einem Bein, Hände leicht an der Wand. Der Patient hebt die Ferse so hoch wie möglich, mehrere Wiederholungen. Der Therapeut beobachtet von hinten, ob die Ferse in Varus dreht. Positiv bei Unfähigkeit, ausbleibender Varisierung oder bekanntem medialem Schmerz.","position":"Stand","quellen":["Ross MH et al. 2021, Clinical tests of tibialis posterior tendinopathy: are they reliable, and how well are they reflected in structural changes on imaging? J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/33779216/","Hébert-Losier K et al. 2017, Updated reliability and normative values for the standing heel-rise test in healthy adults. Physiotherapy – https://pubmed.ncbi.nlm.nih.gov/28886865/","Ross 2021 (Reliabilität) – https://www.physio-network.com/?p=45243","Lubcke 2019 (Review-Abstract) – https://apodc-2019.p.asnevents.com.au/days/2019-05-22/abstract/59729"],"pos":"Positiv, wenn das einbeinige Anheben nicht gelingt, bekannter medialer Schmerz auftritt oder die Ferse dabei nicht in Varus dreht.","kw":[{"ziel":"Strukturelle Veränderung der Tibialis-posterior-Sehne im Ultraschall","basis":"Einzelstudie, 52 Patienten; Odds Ratio 5,8 (95 %-KI 1,7 bis 20,4), keine Sens./Spez. angegeben"}],"mess":{"reliab":"Interrater Kappa 0,74 (Ross 2021); Wiederholungsanzahl bei Gesunden ICC 1,0 (Hébert-Losier 2017)","grenzwert":"Gesunde Erwachsene: Median 24 (Männer) bzw. 21 (Frauen) Wiederholungen auf 10° Schräge (Hébert-Losier 2017)"},"evidenz":"mäßig"},"jacktest":{"name":"Jack-Test (Hubscher)","was":"Flexibler versus rigider Plattfuß","einheit":"positiv oder negativ","kurz":"Im Stand die Großzehe passiv dorsalextendieren und Längsgewölbe beobachten.","ziel":"Flexibilität des Längsgewölbes beurteilen.","norm":["Auffällig, wenn sich das Längsgewölbe bei Großzehenextension nicht aufrichtet (eher rigider Plattfuß).","Keine Studien zur Genauigkeit oder Reliabilität gefunden; klinisch übliche Beobachtung nach Erstbeschreibung (Jack 1953)."],"durch":"Stand, Gewicht auf beiden Füßen. Der Therapeut hebt die Großzehe passiv in Dorsalextension. Normal richtet sich das Längsgewölbe über den Windlass-Mechanismus auf und die Tibia rotiert nach außen. Positiv (rigide), wenn das ausbleibt.","position":"Stand","quellen":["Jack EA 1953, Naviculo-cuneiform fusion in the treatment of flat foot. J Bone Joint Surg Br – https://pubmed.ncbi.nlm.nih.gov/13034876/","Cass AD et al. 2010, A review of tarsal coalition and pes planovalgus: clinical examination, diagnostic imaging, and surgical planning. J Foot Ankle Surg – https://pubmed.ncbi.nlm.nih.gov/20356770/"],"pos":"Auffällig (eher rigide), wenn sich das Längsgewölbe bei passiver Großzehenextension im Stand nicht aufrichtet.","evidenz":"keine"},"colemanblock":{"name":"Coleman-Block-Test","was":"Flexibilität des Rückfußvarus beim Hohlfuß","einheit":"positiv oder negativ","kurz":"Patient steht mit Ferse und lateralem Fußrand auf einem Brettchen, erster Strahl frei.","ziel":"Prüfen, ob der Rückfußvarus vorfußbedingt und flexibel ist.","norm":["Positiv (flexibel), wenn sich der Rückfußvarus auf dem Block in Neutral- oder Valgusstellung korrigiert.","Keine Kennwerte zur Genauigkeit gefunden. Gilt als Standardtest beim Hohlfuß und steuert die OP-Planung (Coleman 1977; Cristofaro 2026)."],"durch":"Stand. Ein 2-3 cm hohes Brettchen liegt unter Ferse und lateralem Fußrand, der erste Strahl hängt frei nach medial. Der Therapeut beobachtet den Rückfuß von hinten. Korrigiert er sich, ist der Rückfuß flexibel und der Varus vorfußbedingt.","position":"Stand","quellen":["Coleman SS, Chesnut WJ 1977, A simple test for hindfoot flexibility in the cavovarus foot. Clin Orthop Relat Res – https://pubmed.ncbi.nlm.nih.gov/852192/","Cristofaro C et al. 2026, Utility of the Coleman block test. Curr Opin Pediatr – https://pubmed.ncbi.nlm.nih.gov/41036730/"],"pos":"Positiv (flexibel), wenn sich der Rückfußvarus auf dem Block in Neutral- oder Valgusstellung korrigiert.","evidenz":"keine"},"sinustarsi":{"name":"Druckschmerz Sinus tarsi","was":"Sinus-tarsi-Syndrom, Läsion subtalarer Bänder","einheit":"positiv oder negativ","kurz":"Weichteilgrube vor dem Außenknöchel über dem Sinus tarsi palpieren.","ziel":"Subtalare Schmerzquelle lokalisieren.","norm":["Positiv bei bekanntem Druckschmerz im Sinus tarsi, im Seitenvergleich.","Keine Kennwerte gefunden. Schmerz im Sinus tarsi ist unspezifisch (Impingement, subtalare Instabilität u. a.); die Ursache gezielt weiter abklären (Willegger 2023). Für subtalare Bandtests fehlen Genauigkeitsstudien (Netterström-Wedin 2022)."],"durch":"Sitz oder Rückenlage, Fuß leicht invertiert. Der Therapeut palpiert die Grube anterior-inferior des Außenknöchels. Positiv bei lokalem, bekanntem Schmerz.","position":"Sitz","quellen":["Willegger M et al. 2023, The evolution of sinus tarsi syndrome: what is the underlying pathology? A critical review. J Clin Med – https://pubmed.ncbi.nlm.nih.gov/37959343/","Netterström-Wedin F et al. 2022, Diagnostic accuracy of clinical tests assessing ligamentous injury of the talocrural and subtalar joints. Sports Health – https://pubmed.ncbi.nlm.nih.gov/34286639/"],"pos":"Positiv bei bekanntem Druckschmerz in der Grube anterior-inferior des Außenknöchels im Seitenvergleich.","evidenz":"keine"},"peronealsubluxation":{"name":"Peronealsehnen-Subluxationstest","was":"Instabilität der Peronealsehnen","einheit":"positiv oder negativ","kurz":"Eversion und Dorsalextension gegen Widerstand, Retromalleolarregion beobachten.","ziel":"Luxierende Peronealsehnen erkennen.","norm":["Positiv bei tastbarem oder sichtbarem Herausspringen der Sehnen über den Außenknöchel.","Keine Kennwerte gefunden. Peronealsehnenverletzungen werden oft übersehen; bei Verdacht Ultraschall oder MRT (Klos 2017)."],"durch":"Bauchlage oder Sitz, Knie gebeugt. Der Patient führt den Fuß gegen Widerstand in Dorsalextension und Eversion. Der Therapeut palpiert hinter dem Außenknöchel. Positiv bei Subluxation oder Schnappen der Sehnen, oft mit Schmerz.","position":"Sitz","quellen":["Klos K et al. 2017, Verletzungen der Peronealsehnen: häufig übersehen. Unfallchirurg – https://pubmed.ncbi.nlm.nih.gov/28819784/"],"pos":"Positiv bei tastbarem oder sichtbarem Herausspringen der Peronealsehnen über den Außenknöchel bei Dorsalextension und Eversion gegen Widerstand.","evidenz":"keine"},"fersenpalpation":{"name":"Druckschmerz medialer Kalkaneus","was":"Plantarfasziopathie","einheit":"positiv oder negativ","kurz":"Ansatz der Plantarfaszie am Tuberculum mediale calcanei palpieren.","ziel":"Plantarfasziopathie lokalisieren.","norm":["Positiv bei bekanntem Druckschmerz am medialen Fersenhöcker.","Keine Kennwerte zur Genauigkeit gefunden. Laut JOSPT-Leitlinie gehört der Druckschmerz am proximalen Faszienansatz zu den Diagnosekriterien, zusammen mit Anamnese, positivem Windlass-Test und negativen Tarsaltunneltests (Empfehlungsgrad B; Koc 2023)."],"durch":"Rückenlage oder Sitz, Zehen leicht dorsalextendiert. Der Therapeut palpiert plantar-medial am Fersenbein den Ursprung der Plantarfaszie. Positiv bei bekanntem Schmerz, oft typisch mit Anlaufschmerz morgens.","position":"Rückenlage","quellen":["Koc TA Jr et al. 2023, Heel pain – plantar fasciitis: revision 2023. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/38037331/","Martin RL et al. 2014, Heel pain – plantar fasciitis: revision 2014. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/25361863/"],"pos":"Positiv bei bekanntem Druckschmerz am Ursprung der Plantarfaszie am medialen Fersenhöcker.","evidenz":"keine"},"windlass":{"name":"Windlass-Test","was":"Plantarfasziopathie","einheit":"positiv oder negativ","kurz":"Im Stand die Großzehe passiv maximal dorsalextendieren.","ziel":"Plantarfaszie unter Spannung provozieren.","norm":["Positiv bei Reproduktion des bekannten Fersenschmerzes.","Im Stand Sens. 32 %, Spez. 100 %, ohne Belastung nur Sens. 14 % (De Garceau 2003): gut zum Bestätigen, nicht zum Ausschließen. Im Stand testen.","Teil der Diagnosekriterien der JOSPT-Leitlinie (Empfehlungsgrad B; Koc 2023)."],"durch":"Stand, Gewicht auf dem Testbein (z. B. auf einem Hocker). Der Therapeut dorsalextendiert die Großzehe im Grundgelenk passiv bis zum Ende oder bis Schmerz auftritt. Positiv bei bekanntem plantarem Fersenschmerz.","position":"Stand","quellen":["De Garceau D et al. 2003, The association between diagnosis of plantar fasciitis and Windlass test results. Foot Ankle Int – https://pubmed.ncbi.nlm.nih.gov/12793489/","Koc TA Jr et al. 2023, Heel pain – plantar fasciitis: revision 2023. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/38037331/","De Garceau 2003 – https://www.physiotutors.com/wiki/windlass-test/"],"pos":"Positiv bei Reproduktion des bekannten plantaren Fersenschmerzes bei passiver Dorsalextension der Großzehe.","kw":[{"ziel":"Plantarfasziopathie, Test im Stand","sens":"31,8 %","spez":"100 %","basis":"Kleine Fall-Kontroll-Studie, 22 Patienten mit Plantarfasziitis, 53 Vergleichspersonen"},{"ziel":"Plantarfasziopathie, Test ohne Belastung","sens":"13,6 %","spez":"100 %","basis":"Gleiche Studie"}],"evidenz":"schwach"},"dorsalextevers":{"name":"Dorsalextensions-Eversions-Test","was":"Tarsaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Fuß maximal dorsalextendiert und evertiert, Zehen extendiert, 5-10 s halten.","ziel":"Kompression des N. tibialis im Tarsaltunnel provozieren.","norm":["Positiv bei Zunahme der Druckdolenz oder der bekannten Beschwerden hinter dem Innenknöchel.","Erstbeschreibung: Druckdolenz in 42 von 43 Füßen verstärkt, bei Gesunden nie auslösbar (Kinoshita 2001). Über mehrere Studien Median-Sens. nur 62 % (Boers 2026)."],"durch":"Seitenlage oder Sitz. Der Therapeut bringt das OSG in maximale Dorsalextension, den Fuß in maximale Eversion und die Zehen in Extension und hält 5-10 Sekunden. Gleichzeitig palpiert er den N. tibialis hinter dem Innenknöchel. Positiv bei Zunahme der Druckdolenz.","position":"Seitlage","quellen":["Kinoshita M et al. 2001, The dorsiflexion-eversion test for diagnosis of tarsal tunnel syndrome. J Bone Joint Surg Am – https://pubmed.ncbi.nlm.nih.gov/11741063/","Boers N et al. 2026, Differences in diagnosing tarsal tunnel syndrome across the literature: a systematic review and a call for standardization. JBJS Rev – https://pubmed.ncbi.nlm.nih.gov/41662474/","Kinoshita 2001 – https://www.physiotutors.com/wiki/dorsiflexion-eversion-test/"],"pos":"Positiv bei Zunahme der Druckdolenz, des Tinel-Zeichens oder der bekannten Beschwerden während 5-10 s maximaler Dorsalextension, Eversion und Zehenextension.","kw":[{"ziel":"Tarsaltunnelsyndrom (operierte Patienten): Zunahme der lokalen Druckdolenz","sens":"98 %","basis":"Einzelstudie, 44 Füße; bei 100 gesunden Füßen keine Symptome auslösbar"},{"ziel":"Tarsaltunnelsyndrom: Sensitivität über mehrere Studien","sens":"62 % (Median, Spanne 29-86 %)","basis":"Systematische Übersicht, 4 Studien, Spezifität nicht berechenbar (Boers 2026)"}],"evidenz":"schwach"},"tineltarsal":{"name":"Tinel-Zeichen Tarsaltunnel","was":"Tarsaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Hinter dem Innenknöchel auf den N. tibialis klopfen.","ziel":"Mechanosensibilität des N. tibialis prüfen.","norm":["Positiv bei Kribbeln in die Fußsohle.","Häufigster Provokationstest beim Tarsaltunnelsyndrom; Median-Sens. 78,5 %, aber Spannweite 1-100 % und keine Spezifität bekannt (Boers 2026). Nur zusammen mit Anamnese und weiteren Befunden werten."],"durch":"Seitenlage oder Sitz. Der Therapeut klopft hinter und unter dem Innenknöchel entlang des N. tibialis. Positiv bei Parästhesien plantar.","position":"Seitlage","quellen":["Boers N et al. 2026, Differences in diagnosing tarsal tunnel syndrome across the literature: a systematic review and a call for standardization. JBJS Rev – https://pubmed.ncbi.nlm.nih.gov/41662474/","Koc TA Jr et al. 2023, Heel pain – plantar fasciitis: revision 2023. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/38037331/"],"pos":"Positiv bei Kribbeln oder Elektrisieren in die Fußsohle beim Beklopfen des N. tibialis hinter dem Innenknöchel.","kw":[{"ziel":"Tarsaltunnelsyndrom","sens":"78,5 % (Median, Spanne 1-100 %)","basis":"Systematische Übersicht, 28 Studien, uneinheitliche Referenzstandards, Spezifität nicht berechenbar (Boers 2026)"}],"evidenz":"schwach"},"achillespalpation":{"name":"Palpation Achillessehne","was":"Achillestendinopathie","einheit":"positiv oder negativ","kurz":"Achillessehne im Verlauf zwischen den Fingern palpieren.","ziel":"Tendinopathie der mittleren Sehne oder des Ansatzes lokalisieren.","norm":["Positiv bei bekanntem lokalem Druckschmerz, oft mit tastbarer Verdickung.","Sens. 64 %, Spez. 81 %, LR+ 3,15, LR- 0,48 (Reiman 2014, gepoolt aus 2 Studien)."],"durch":"Bauchlage, Füße über dem Liegenende. Der Therapeut palpiert die Sehne von 2-6 cm über dem Ansatz bis zum Kalkaneus. Positiv bei bekanntem Schmerz.","position":"Bauchlage","quellen":["Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv bei bekanntem lokalem Druckschmerz der Sehne, oft mit tastbarer Verdickung.","kw":[{"ziel":"Achillestendinopathie","sens":"64 %","spez":"81 %","lrp":"3,15","lrn":"0,48","basis":"Metaanalyse aus 2 Studien (Reiman 2014)"}],"evidenz":"mäßig"},"arcsign":{"name":"Arc Sign","was":"Achillestendinopathie (Midportion)","einheit":"positiv oder negativ","kurz":"Verdickung der Sehne tasten, Patient bewegt das OSG aktiv.","ziel":"Intratendinöse Verdickung von Paratenon-Schwellung abgrenzen.","norm":["Positiv, wenn die tastbare Verdickung bei Fußbewegung mit der Sehne mitwandert.","Sens. 42 %, Spez. 88 %, LR- 0,68 (Reiman 2014, gepoolt). Negativ schließt eine Tendinopathie nicht aus."],"durch":"Bauchlage, Füße über dem Liegenende. Der Therapeut tastet die Verdickung und der Patient bewegt den Fuß aktiv in Dorsalextension und Plantarflexion. Positiv, wenn die Verdickung mitwandert (Sehne), negativ, wenn sie ortsfest bleibt (Paratenon).","position":"Bauchlage","quellen":["Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv, wenn die tastbare Verdickung bei aktiver Fußbewegung mit der Sehne mitwandert.","kw":[{"ziel":"Achillestendinopathie (Midportion)","sens":"42 %","spez":"88 %","lrn":"0,68","basis":"Metaanalyse aus 2 Studien (Reiman 2014)"}],"evidenz":"mäßig"},"royallondon":{"name":"Royal-London-Hospital-Test","was":"Achillestendinopathie (Midportion)","einheit":"positiv oder negativ","kurz":"Schmerzpunkt in leichter Plantarflexion palpieren, dann in Dorsalextension erneut.","ziel":"Tendinopathie bestätigen.","norm":["Positiv, wenn der Druckschmerz in Dorsalextension deutlich nachlässt oder verschwindet.","LR+ 3,84 (Reiman 2014, gepoolt). Zusammen mit Palpation und Arc Sign: Sens. 59 %, Spez. 83 % (Maffulli 2003, in Reiman 2014)."],"durch":"Bauchlage. Der Therapeut sucht in leichter Plantarflexion den schmerzhaftesten Punkt. Danach dorsalextendiert der Patient aktiv maximal und der Punkt wird erneut palpiert. Positiv bei deutlich weniger Schmerz in Dorsalextension.","position":"Bauchlage","quellen":["Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv, wenn der Druckschmerz in maximaler Dorsalextension deutlich nachlässt oder verschwindet.","kw":[{"ziel":"Achillestendinopathie (Midportion)","lrp":"3,84","basis":"Metaanalyse aus 2 Studien (Reiman 2014); Sens./Spez. nicht einzeln angegeben"}],"evidenz":"mäßig"},"thompson":{"name":"Thompson-Test (Wadenkompression)","was":"Achillessehnenruptur","einheit":"positiv oder negativ","kurz":"Wade in Bauchlage zusammendrücken und Plantarflexion beobachten.","ziel":"Vollständige Achillessehnenruptur erkennen.","norm":["Positiv, wenn beim Zusammendrücken der Wade keine Plantarflexion auftritt.","Sens. 96 %, Spez. 93 %, LR+ 13,7, LR- 0,04 (Maffulli 1998; Reiman 2014). Bester Einzeltest; bei allen Rupturen waren mindestens zwei Tests positiv."],"durch":"Bauchlage, Füße über dem Liegenende. Der Therapeut drückt den Wadenbauch kräftig zusammen. Normal bewegt sich der Fuß in Plantarflexion. Positiv, wenn sie ausbleibt. Seitenvergleich.","position":"Bauchlage","quellen":["Maffulli N 1998, The clinical diagnosis of subcutaneous tear of the Achilles tendon: a prospective study in 174 patients. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/9548122/","Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv, wenn beim Zusammendrücken der Wade keine Plantarflexion des Fußes auftritt.","kw":[{"ziel":"Komplette Achillessehnenruptur","sens":"96 %","spez":"93 %","lrp":"13,7","lrn":"0,04","basis":"Einzelstudie, 174 Rupturen und 28 Kontrollen (Maffulli 1998), ausgewertet in Reiman 2014"}],"evidenz":"mäßig"},"matles":{"name":"Matles-Test","was":"Achillessehnenruptur","einheit":"positiv oder negativ","kurz":"Knie in Bauchlage auf 90° beugen und Fußstellung vergleichen.","ziel":"Achillessehnenruptur erkennen.","norm":["Positiv, wenn der betroffene Fuß nicht in leichter Plantarflexion bleibt.","Sens. 88 %, Spez. 85 %, LR+ 6,3, LR- 0,14 (Maffulli 1998; Reiman 2014)."],"durch":"Bauchlage. Der Patient beugt beide Knie aktiv auf 90°. Der Therapeut vergleicht die Fußstellung. Positiv, wenn der betroffene Fuß nicht in leichter Plantarflexion bleibt.","position":"Bauchlage","quellen":["Maffulli N 1998, The clinical diagnosis of subcutaneous tear of the Achilles tendon: a prospective study in 174 patients. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/9548122/","Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv, wenn der Fuß der betroffenen Seite bei 90° Kniebeugung in Neutral- oder Dorsalextension fällt statt in leichter Plantarflexion zu bleiben.","kw":[{"ziel":"Komplette Achillessehnenruptur","sens":"88 %","spez":"85 %","lrp":"6,3","lrn":"0,14","basis":"Einzelstudie (Maffulli 1998), ausgewertet in Reiman 2014"}],"evidenz":"mäßig"},"achillesdelle":{"name":"Tastbare Delle Achillessehne","was":"Achillessehnenruptur","einheit":"positiv oder negativ","kurz":"Sehnenverlauf auf eine Lücke abtasten.","ziel":"Ruptur lokalisieren.","norm":["Positiv bei tastbarer Lücke im Sehnenverlauf.","Sens. 73 %, Spez. 89 %, LR+ 6,6, LR- 0,30 (Maffulli 1998; Reiman 2014). Am wenigsten sensitiv der Rupturtests, weil Schwellung die Lücke verdeckt."],"durch":"Bauchlage, Füße über dem Liegenende. Der Therapeut tastet die Sehne vom Muskel-Sehnen-Übergang bis zum Ansatz. Positiv bei einer Lücke, typischerweise 2-6 cm über dem Ansatz. Frühe Schwellung kann die Lücke verdecken.","position":"Bauchlage","quellen":["Maffulli N 1998, The clinical diagnosis of subcutaneous tear of the Achilles tendon: a prospective study in 174 patients. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/9548122/","Reiman M et al. 2014, The utility of clinical measures for the diagnosis of Achilles tendon injuries: a systematic review with meta-analysis. J Athl Train – https://pubmed.ncbi.nlm.nih.gov/25243736/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"pos":"Positiv bei tastbarer Lücke im Sehnenverlauf, typischerweise 2-6 cm über dem Ansatz.","kw":[{"ziel":"Komplette Achillessehnenruptur","sens":"73 %","spez":"89 %","lrp":"6,6","lrn":"0,30","basis":"Einzelstudie (Maffulli 1998), ausgewertet in Reiman 2014; in Narkose Sens. 81 %"}],"evidenz":"mäßig"},"fingerkompression":{"name":"Daumen-Zeigefinger-Kompression","was":"Morton-Neurom","einheit":"positiv oder negativ","kurz":"Zwischenmetatarsalraum dorsal und plantar zwischen Daumen und Zeigefinger zusammendrücken.","ziel":"Morton-Neurom lokalisieren.","norm":["Positiv bei bekanntem Schmerz im betroffenen Zwischenraum.","Sens. 95-96 %, LR- 0,04 (Mahadevan 2015; Owens 2011): negativ spricht gegen ein Neurom. Spezifität praktisch unbekannt, weil kaum Personen ohne Neurom untersucht wurden (Pitcher 2024)."],"durch":"Rückenlage oder Sitz. Der Therapeut drückt den Intermetatarsalraum (meist 3/4 oder 2/3) zwischen Daumen plantar und Zeigefinger dorsal zusammen. Positiv bei bekanntem, oft brennendem Schmerz.","position":"Rückenlage","quellen":["Mahadevan D et al. 2015, Diagnostic accuracy of clinical tests for Morton's neuroma compared with ultrasonography. J Foot Ankle Surg – https://pubmed.ncbi.nlm.nih.gov/25432459/","Pitcher M et al. 2024, Diagnostic accuracy of subjective features and physical examination tests for Morton neuroma: a systematic review. Foot Ankle Orthop – https://pubmed.ncbi.nlm.nih.gov/39564390/","Pitcher 2024 – https://uhra.herts.ac.uk/id/eprint/9649/1/pitcher-et-al-2024-diagnostic-accuracy-of-subjective-features-and-physical-examination-tests-for-morton-neuroma-a.pdf"],"pos":"Positiv bei bekanntem, oft brennendem Schmerz beim Zusammendrücken des betroffenen Zwischenraums zwischen Daumen und Zeigefinger.","kw":[{"ziel":"Morton-Neurom (Ultraschall)","sens":"96 %","lrn":"0,04","basis":"Einzelstudie, 54 Füße (Mahadevan 2015), Spezifität nur aus einem einzigen Fuß ohne Neurom"},{"ziel":"Morton-Neurom (OP-Befund)","sens":"95 %","basis":"Retrospektive Studie, 76 Neurome (Owens 2011, in Pitcher 2024)"}],"evidenz":"schwach"},"mulder":{"name":"Mulder-Klick","was":"Morton-Neurom","einheit":"positiv oder negativ","kurz":"Mittelfußköpfchen seitlich zusammendrücken und gleichzeitig den Zwischenraum plantar drücken.","ziel":"Morton-Neurom durch tastbaren Klick bestätigen.","norm":["Positiv bei tastbarem Klick mit bekanntem Schmerz.","Sens. 29-94 %, Spez. 17-100 % je nach Studie, insgesamt wenig aussagekräftig (Pitcher 2024). Der Klick tritt eher bei größeren Neuromen auf (Mahadevan 2015)."],"durch":"Rückenlage. Eine Hand drückt die Mittelfußköpfchen von medial und lateral zusammen, die andere drückt plantar in den betroffenen Zwischenraum. Positiv bei tastbarem Klick und bekanntem Schmerz.","position":"Rückenlage","quellen":["Pitcher M et al. 2024, Diagnostic accuracy of subjective features and physical examination tests for Morton neuroma: a systematic review. Foot Ankle Orthop – https://pubmed.ncbi.nlm.nih.gov/39564390/","Mahadevan D et al. 2015, Diagnostic accuracy of clinical tests for Morton's neuroma compared with ultrasonography. J Foot Ankle Surg – https://pubmed.ncbi.nlm.nih.gov/25432459/","Pitcher 2024 – https://uhra.herts.ac.uk/id/eprint/9649/1/pitcher-et-al-2024-diagnostic-accuracy-of-subjective-features-and-physical-examination-tests-for-morton-neuroma-a.pdf"],"pos":"Positiv bei tastbarem Klick mit bekanntem Schmerz beim seitlichen Zusammendrücken der Mittelfußköpfchen.","kw":[{"ziel":"Morton-Neurom","sens":"29-94 %","spez":"17-100 %","basis":"Systematische Übersicht, mehrere kleine Studien, Spannweite (Pitcher 2024)"},{"ziel":"Morton-Neurom (Ultraschall)","sens":"61 %","basis":"Einzelstudie, 54 Füße (Mahadevan 2015)"}],"evidenz":"schwach"},"plantarplatte":{"name":"Vertikaler Stresstest MTP (Schublade)","was":"Läsion der Plantarplatte","einheit":"positiv oder negativ","kurz":"Mittelfußknochen fixieren, Grundglied der Zehe nach dorsal schieben.","ziel":"Instabilität der Plantarplatte erkennen.","norm":["Positiv bei vermehrter dorsaler Verschiebung oder bekanntem Schmerz im Seitenvergleich.","Sens. 80,6 %, Spez. 99,8 % (Klein 2013, retrospektiv, nur operierte Patienten). Zusammen mit schleichendem Beginn und Schwellung am Köpfchen MT 2 typisch."],"durch":"Rückenlage oder Sitz. Der Therapeut fixiert das Metatarsale, hält das Grundglied in leichter Dorsalextension und schiebt es nach dorsal. Positiv bei vermehrter Translation oder bekanntem plantarem Schmerz unter dem Mittelfußköpfchen.","position":"Rückenlage","quellen":["Klein EE et al. 2013, Clinical examination of plantar plate abnormality: a diagnostic perspective. Foot Ankle Int – https://pubmed.ncbi.nlm.nih.gov/23696184/","Knight (Übersicht Plantarplatte) – https://www.physio-network.com/blog/plantar-plate-injury-assessment-and-management-by-nick-knight/"],"pos":"Positiv bei vermehrter dorsaler Verschiebung des Grundglieds oder bekanntem Schmerz unter dem Mittelfußköpfchen im Seitenvergleich.","kw":[{"ziel":"Plantarplattenriss (intraoperativer Befund), Schubladentest MTP 2","sens":"80,6 %","spez":"99,8 %","basis":"Retrospektive Studie, 90 operierte Patienten (109 Füße)"}],"evidenz":"schwach"},"papiertest":{"name":"Papier-Zieh-Test (Digital Purchase)","was":"Läsion der Plantarplatte","einheit":"positiv oder negativ","kurz":"Papierstreifen unter der Zehe herausziehen, während der Patient festhält.","ziel":"Bodenkontakt und Greifkraft der Zehe prüfen.","norm":["Positiv, wenn der Patient den Streifen nicht mit der Zehe halten kann.","Keine Studien zur Genauigkeit gefunden; nur als Ergänzung zum vertikalen Stresstest werten."],"durch":"Stand. Ein schmaler Papierstreifen liegt unter der zu testenden Zehe. Der Patient drückt die Zehe auf den Boden, der Therapeut zieht am Papier. Positiv, wenn das Papier ohne Widerstand herausgleitet.","position":"Stand","quellen":["Zusatz: Knight N, Plantar plate injury, assessment and management. Physio Network (Blog) – https://www.physio-network.com/blog/plantar-plate-injury-assessment-and-management-by-nick-knight/"],"pos":"Positiv, wenn der Patient den Papierstreifen nicht mit der Zehe gegen den Boden halten kann.","evidenz":"keine"},"pf_stroke":{"name":"Stroke-Test (Wischtest)","was":"Kniegelenkerguss, Grad 0 bis 3+","einheit":"0, Spur, 1+, 2+, 3+","kurz":"Medial nach oben ausstreichen, lateral nach unten streichen, Flüssigkeitswelle medial beurteilen.","ziel":"Erguss graduieren und den Verlauf vergleichen.","norm":["0: keine Welle. Spur: kleine Welle medial. 1+: größere Vorwölbung medial. 2+: Erguss füllt die mediale Mulde ganz oder kehrt ohne Streichen zurück. 3+: Erguss lässt sich medial nicht ausstreichen.","Aufrücken nach der OP ab höchstens Spur, für Laufen und Sport kein Erguss."],"durch":"Rückenlage, Knie gestreckt, Muskulatur locker. Mit der Hand zwei- bis dreimal medial vom Gelenkspalt nach proximal in den Recessus suprapatellaris streichen. Dann lateral von proximal nach distal streichen und medial auf die zurücklaufende Welle achten.","position":"Rückenlage","quellen":["Sturgill LP et al. 2009, Interrater reliability of a clinical scale to assess knee joint effusion. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/20032559/","Sturgill 2009, modifizierter Stroke-Test – https://pmc.ncbi.nlm.nih.gov/articles/PMC3158982/table/T8"],"mess":{"reliab":"Interrater Kappa 0,75, Übereinstimmung 73 %; keine Abweichung über 2 Stufen (Sturgill 2009, n = 75)"},"evidenz":"mäßig"},"pf_slr":{"name":"Beinheben ohne Streckdefizit (20 ×)","was":"Quadrizeps-Ansteuerung","einheit":"ja oder nein","kurz":"Gestrecktes Bein 20 × heben, ohne dass das Knie einknickt.","ziel":"Aktive volle Streckung gegen die Schwerkraft prüfen.","norm":["Erfüllt, wenn das Knie bei allen 20 Wiederholungen gestreckt bleibt (kein Extension-Lag)."],"durch":"Rückenlage, anderes Bein angestellt. Quadrizeps anspannen, Knie durchstrecken und das Bein etwa bis zur Höhe des anderen Knies heben. Achte darauf, ob das Knie beim Heben nachgibt.","position":"Rückenlage","quellen":["MOON ACL Guidelines – https://www.vumc.org/sports-medicine/sites/vumc.org.sports-medicine/files/public_files/documents/MOON%20VSM%20ACL%20Guidelines.pdf"],"evidenz":"keine"},"pf_sls":{"name":"Einbeinige Kniebeuge (Qualität)","was":"Bewegungskontrolle Bein und Becken","einheit":"gut oder nicht","kurz":"5 einbeinige Kniebeugen, Knie über dem Fuß, Becken waagerecht.","ziel":"Dynamische Knieachse und Rumpfkontrolle beurteilen.","norm":["Gut: Knie bleibt über dem zweiten Zeh, Becken kippt nicht, Rumpf bleibt aufrecht, gleichmäßiges Tempo."],"durch":"Barfuß auf dem Testbein, Arme vor der Brust oder an der Hüfte. Fünfmal langsam bis etwa 60° Beugung und zurück. Von vorn beobachten.","position":"Stand","quellen":["Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"evidenz":"schwach"},"pf_bruecke":{"name":"Einbeinige Brücke (Wiederholungen)","was":"Kraftausdauer Hamstrings und Gesäß","einheit":"Wiederholungen je Seite","kurz":"Ferse auf erhöhter Unterlage, einbeinig Becken heben bis zur Erschöpfung.","ziel":"Seitenvergleich ohne Kraftmessgerät.","norm":["Ziel: LSI ab 90 % und mindestens 20 Wiederholungen."],"durch":"Rückenlage, Ferse des Testbeins auf einer Bank oder Box, Knie leicht gebeugt, anderes Bein in der Luft. Becken bis zur gestreckten Hüfte heben und absenken, gleichmäßiges Tempo. Zählen bis zum Abbruch oder bis die Ausführung unsauber wird. Beide Seiten gleich aufbauen.","position":"Rückenlage","quellen":["Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"evidenz":"schwach"},"pf_wade":{"name":"Wadenheben einbeinig (Wiederholungen)","was":"Kraftausdauer Wade","einheit":"Wiederholungen je Seite","kurz":"Einbeinig auf der Stufenkante, volle Bewegung, bis zur Erschöpfung.","ziel":"Seitenvergleich ohne Kraftmessgerät.","norm":["Ziel: LSI ab 90 % und mindestens 20 Wiederholungen (Melbourne Guide).","Gesunde Erwachsene: Median 25 (dominant) bzw. 24 Wiederholungen (nicht dominant), weniger bei Frauen, höherem BMI und geringer Aktivität (Visser 2025, n = 500)."],"durch":"Vorfuß auf einer Stufe, Ferse frei, Knie gestreckt, leichte Hand an der Wand. Ferse ganz hoch und ganz tief, gleichmäßiges Tempo. Zählen bis zum Abbruch.","position":"Stand","quellen":["Visser TSO et al. 2025, Normative values for calf muscle strength-endurance in the general population assessed with the Calf Raise Application. Braz J Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC11923623/","Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"evidenz":"schwach"},"pf_stuhl":{"name":"Einbeinig vom Stuhl aufstehen (Wiederholungen)","was":"Kraftausdauer Quadrizeps","einheit":"Wiederholungen je Seite","kurz":"Einbeinig von einem Stuhl aufstehen und hinsetzen, bis zur Erschöpfung.","ziel":"Quadrizeps im Seitenvergleich ohne Gerät.","norm":["Phase 2: LSI ab 90 % und mindestens 10 Wiederholungen.","Phase 3: LSI ab 90 % und mehr als 22 Wiederholungen je Seite."],"durch":"Normaler Stuhl, Arme vor der Brust verschränkt. Einbeinig aufstehen bis zum Stand und kontrolliert hinsetzen, ohne Schwung. Zählen bis zum Abbruch oder bis das Knie nach innen fällt.","position":"Sitz","quellen":["Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"evidenz":"schwach"},"pf_seit":{"name":"Seitstütz (Haltezeit)","was":"Rumpf- und Hüftstabilität","einheit":"Sekunden je Seite","kurz":"Unterarmstütz seitlich, Körper in einer Linie, halten bis zum Abbruch.","ziel":"Seitenvergleich der Rumpfkraft.","norm":["Ziel: LSI ab 90 % und mindestens 30 s."],"durch":"Seitlage, Ellenbogen unter der Schulter, Beine gestreckt übereinander. Becken heben, bis Kopf, Rumpf und Beine eine Linie bilden. Zeit stoppen, bis das Becken absinkt.","position":"Seitlage","quellen":["McGill SM et al. 1999, Endurance times for low back stabilization exercises: clinical targets for testing and training from a normal database. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/10453772/","Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"mess":{"reliab":"Wiederholungstests über 5 Tage und nach 8 Wochen: Reliabilität über 0,97 bei jungen Gesunden (McGill 1999)"},"evidenz":"schwach"},"pf_presse":{"name":"Beinpresse einbeinig (Keiser, 10 Wdh.)","was":"Kraft Quadrizeps und Gesäß","einheit":"Resistance je Seite","kurz":"Resistance, mit der 10 saubere Wiederholungen einbeinig gehen.","ziel":"Grober Kraftvergleich an der KGG-Beinpresse.","norm":["Richtwert: LSI ab 90 %.","Ersetzt keine Messung mit Dynamometer oder Isokinetik."],"durch":"Aufwärmen mit Ergometer und 2 leichten Sätzen beidbeinig. Einbeinig an der Keiser, Sitzposition und Fuß beidseits gleich, Bewegung von etwa 90° bis fast gestreckt. Resistance in Stufen steigern, bis gerade noch 10 saubere Wiederholungen gelingen, etwa 2 Minuten Pause. Gesunde Seite zuerst, operierte Seite bei etwa zwei Dritteln beginnen. Arztvorgaben zur Freigabe beachten.","position":"Sitz","quellen":["Melbourne ACL Rehabilitation Guide 2.0 (Kraft im Seitenvergleich) – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"evidenz":"schwach"},"pf_keiser":{"name":"Beinpresse einbeinig, Keiser (Spitzenleistung)","was":"Beinstreckkraft, schnell","einheit":"Watt je Seite","kurz":"Gleiche Resistance beidseits, 3 Versuche je Bein so schnell wie möglich strecken, Bestwert.","ziel":"Seitenvergleich der Leistung an der KGG-Beinpresse.","norm":["Richtwert: LSI ab 90 %.","Misst die Beinstrecker gesamt, nicht den Quadrizeps allein. Ersetzt keine Messung mit Dynamometer oder Isokinetik."],"durch":"Aufwärmen mit 2 Sätzen beidbeinig leicht. Sitz und Fußposition für beide Seiten gleich, Knie zu Beginn etwa 90°, gleiche Resistance. Gesunde Seite zuerst. Auf Kommando so schnell wie möglich strecken, langsam zurück. 3 Versuche je Bein, 30 bis 60 s Pause, Spitzenleistung vom Display, Bestwert.","position":"Sitz","quellen":["Eigener Test an der Keiser Air300, angelehnt an den Kraftvergleich im Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"]},"pf_stand":{"name":"Einbeinstand (Zeit)","was":"Gleichgewicht","einheit":"Sekunden","kurz":"Barfuß auf einem Bein, Hände an der Hüfte, Zeit bis zum Abbruch.","ziel":"Gleichgewicht auf dem betroffenen Bein.","norm":["Gesunde, Mittel aus 3 Versuchen, Höchstzeit 45 s (Springer 2007): 18–39 J. Augen offen 43 s, Augen zu 9 s; 40–49 J. 40 / 7 s; 50–59 J. 37 / 5 s; 60–69 J. 27 / 3 s.","Für jüngere Sportler gelten daher Augen offen über 43 s und Augen zu über 9 s als Zielwert. Ältere Patienten nach Alter vergleichen.","Mit Kopfbewegung über 15 s: Zielwert des Melbourne Guide ohne Studienbeleg."],"durch":"Barfuß, Hände an der Hüfte, anderes Bein angehoben ohne Kontakt zum Standbein. Zeit stoppen, bis der Fuß verrutscht, das andere Bein absetzt oder die Hände die Hüfte verlassen.","position":"Stand","quellen":["Springer BA et al. 2007, Normative values for the unipedal stance test with eyes open and closed. J Geriatr Phys Ther – https://pubmed.ncbi.nlm.nih.gov/19839175/","Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"mess":{"reliab":"Interrater ICC 0,994 Augen offen, 0,998 Augen zu (bester Versuch, Springer 2007)"},"evidenz":"mäßig"},"pf_ybal":{"name":"Y-Balance nach vorn","was":"Dynamisches Gleichgewicht","einheit":"cm je Seite","kurz":"Einbeinstand, mit dem anderen Fuß so weit wie möglich nach vorn tippen.","ziel":"Seitenvergleich der Reichweite.","norm":["Seitenunterschied nach vorn über 4 cm gilt als auffällig: 2,5-fach höheres Risiko für Verletzungen der unteren Extremität bei jungen Basketballspielern (Plisky 2006). Für VKB-Patienten nicht eigens geprüft."],"durch":"Stand auf dem Testbein, Hände an der Hüfte. Mit dem anderen Fuß entlang eines Maßbands nach vorn schieben, leicht antippen und zurück, ohne abzusetzen. Drei gültige Versuche, Bestwert.","position":"Stand","quellen":["Plisky PJ et al. 2006, Star Excursion Balance Test as a predictor of lower extremity injury in high school basketball players. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17193868/","VBG Return to Competition – https://cdn.vbg.de/media/d3e512a8c8ab4e1fa05cfe7c27afad8b/dld:attachment/return_to_competition_Kreuzbandrupturen.pdf"],"mess":{"reliab":"ICC 0,82 bis 0,87 für die Reichrichtungen (Plisky 2006)","grenzwert":"Seitenunterschied nach vorn über 4 cm: 2,5-fach höheres Verletzungsrisiko der unteren Extremität (Basketballspieler, Plisky 2006)"},"evidenz":"mäßig"},"pf_hop1":{"name":"Single Hop for Distance","was":"Sprungkraft und Landung","einheit":"cm je Seite","kurz":"Einbeinig so weit wie möglich springen, auf demselben Bein stabil landen.","ziel":"Sprungleistung im Seitenvergleich.","norm":["Ziel: LSI über 90 % (Grindem 2016). LSI = betroffen geteilt durch gesund mal 100.","Ein einzelner Hop-Test ist wenig sensitiv, aber spezifisch: Bei VKB-Ruptur sind 50 % auffällig, mit zwei Tests 62 % (Noyes 1991).","Echte Veränderung des LSI erst ab etwa 7 bis 13 Prozentpunkten (Reid 2007)."],"durch":"Start auf dem Testbein, Zehen an der Linie, Hände frei. Weitsprung nach vorn, Landung auf demselben Bein, 2 s stabil halten. Gemessen von Zehen beim Start bis Ferse bei Landung. Ein Probeversuch, dann drei gültige Versuche, Bestwert.","position":"Stand","quellen":["Noyes FR et al. 1991, Abnormal lower limb symmetry determined by function hop tests after anterior cruciate ligament rupture. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/1962720/","Reid A et al. 2007, Hop testing provides a reliable and valid outcome measure during rehabilitation after anterior cruciate ligament reconstruction. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17311886/","Grindem H et al. 2016, Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction: the Delaware-Oslo ACL cohort study. Br J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC4912389/","Gustavsson A et al. 2006, A test battery for evaluating hop performance in patients with an ACL injury and patients who have undergone ACL reconstruction. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/16525796/","Müller U et al. 2015, Predictive parameters for return to pre-injury level of sport 6 months following ACL reconstruction surgery. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/25178537/","Noyes 1991, Hop-Testbatterie (zit. nach Grindem 2016) – https://bjsm.bmj.com/content/50/13/804"],"mess":{"reliab":"LSI ICC 0,82 bis 0,93 nach VKB-Plastik (Reid 2007); 0,85 bis 0,97 bei Gesunden (Gustavsson 2006)","mdc":"LSI 7,05 bis 12,96 Prozentpunkte über die vier Hop-Tests (MDC90, Reid 2007)","grenzwert":"Rückkehrkriterium LSI über 90 % (Grindem 2016); 6 Monate nach OP trennt LSI 75,4 % Rückkehrer von Nicht-Rückkehrern, Sens 74 %, Spez 88 % (Müller 2015)"},"evidenz":"stark"},"pf_hop3":{"name":"Triple Hop for Distance","was":"Sprungkraft und Kontrolle","einheit":"cm je Seite","kurz":"Drei Sprünge hintereinander auf einem Bein, Gesamtweite.","ziel":"Sprungleistung im Seitenvergleich.","norm":["Ziel: LSI über 90 % (Grindem 2016). Echte Veränderung des LSI erst ab etwa 7 bis 13 Prozentpunkten (Reid 2007)."],"durch":"Start auf dem Testbein an der Linie. Drei Sprünge hintereinander nach vorn ohne Pause, letzte Landung 2 s halten. Gesamtweite bis zur Ferse. Drei gültige Versuche, Bestwert.","position":"Stand","quellen":["Reid A et al. 2007, Hop testing provides a reliable and valid outcome measure during rehabilitation after anterior cruciate ligament reconstruction. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17311886/","Noyes FR et al. 1991, Abnormal lower limb symmetry determined by function hop tests after anterior cruciate ligament rupture. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/1962720/","Grindem H et al. 2016, Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction. Br J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC4912389/","Noyes 1991, Hop-Testbatterie (zit. nach Grindem 2016) – https://bjsm.bmj.com/content/50/13/804"],"mess":{"reliab":"LSI ICC 0,82 bis 0,93 nach VKB-Plastik (Reid 2007)","mdc":"LSI 7,05 bis 12,96 Prozentpunkte über die vier Hop-Tests (MDC90, Reid 2007)","grenzwert":"Rückkehrkriterium LSI über 90 % (Grindem 2016)"},"evidenz":"stark"},"pf_hopx":{"name":"Crossover Hop for Distance","was":"Sprungkraft mit Richtungswechsel","einheit":"cm je Seite","kurz":"Drei Sprünge im Zickzack über eine 15 cm breite Linie.","ziel":"Sprungleistung unter seitlicher Belastung.","norm":["Ziel: LSI über 90 % (Grindem 2016). Echte Veränderung des LSI erst ab etwa 7 bis 13 Prozentpunkten (Reid 2007)."],"durch":"Auf dem Boden ein 15 cm breiter Streifen. Start neben dem Streifen, dann drei Sprünge vorwärts, jedes Mal über den Streifen auf die andere Seite. Letzte Landung 2 s halten. Gesamtweite. Drei gültige Versuche, Bestwert.","position":"Stand","quellen":["Reid A et al. 2007, Hop testing provides a reliable and valid outcome measure during rehabilitation after anterior cruciate ligament reconstruction. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17311886/","Noyes FR et al. 1991, Abnormal lower limb symmetry determined by function hop tests after anterior cruciate ligament rupture. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/1962720/","Grindem H et al. 2016, Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction. Br J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC4912389/","Noyes 1991, Hop-Testbatterie (zit. nach Grindem 2016) – https://bjsm.bmj.com/content/50/13/804"],"mess":{"reliab":"LSI ICC 0,82 bis 0,93 nach VKB-Plastik (Reid 2007)","mdc":"LSI 7,05 bis 12,96 Prozentpunkte über die vier Hop-Tests (MDC90, Reid 2007)","grenzwert":"Rückkehrkriterium LSI über 90 % (Grindem 2016)"},"evidenz":"stark"},"pf_hop6":{"name":"6-m-Hop auf Zeit","was":"Sprungschnelligkeit","einheit":"Sekunden je Seite","kurz":"6 m einbeinig so schnell wie möglich hüpfen.","ziel":"Schnelligkeit im Seitenvergleich.","norm":["Ziel: LSI über 90 % (Grindem 2016). Bei Zeiten rechnet die App gesund durch betroffen mal 100 (so auch Grindem 2016 und Moksnes 2008).","Delaware-Screening nach Ruptur ohne OP: mindestens 80 % (Fitzgerald 2000). Der 6-m-Hop war der einzige Test, der die selbst eingeschätzte Kniefunktion beeinflusste (Hurd 2008)."],"durch":"6-m-Strecke markieren. Fliegender Start auf dem Testbein, so schnell wie möglich bis über die Ziellinie hüpfen. Zeit stoppen. Zwei gültige Versuche, Mittelwert oder Bestwert, beidseits gleich.","position":"Stand","quellen":["Fitzgerald GK et al. 2000, A decision-making scheme for returning patients to high-level activity with nonoperative treatment after anterior cruciate ligament rupture. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/10795668/","Moksnes H et al. 2008, Individuals with an ACL-deficient knee classified as noncopers may be candidates for nonsurgical rehabilitation. J Orthop Sports Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC2801138/","Hurd WJ et al. 2008, A 10-year prospective trial of a patient management algorithm and screening examination for highly active individuals with ACL injury: Part 2. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/17932399/","Reid A et al. 2007, Hop testing provides a reliable and valid outcome measure during rehabilitation after ACL reconstruction. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/17311886/","Grindem H et al. 2016, Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction. Br J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC4912389/","Noyes 1991, Hop-Testbatterie (zit. nach Grindem 2016) – https://bjsm.bmj.com/content/50/13/804"],"mess":{"reliab":"LSI ICC 0,82 bis 0,93 nach VKB-Plastik (Reid 2007)","mdc":"LSI 7,05 bis 12,96 Prozentpunkte über die vier Hop-Tests (MDC90, Reid 2007)","grenzwert":"Nach VKB-Plastik: LSI über 90 % (Grindem 2016). Ohne OP, Delaware-Screening: LSI mindestens 80 % (Fitzgerald 2000; identische Kriterien bei Moksnes 2008)."},"evidenz":"stark"},"pf_side":{"name":"Side Hop (30 s)","was":"Seitliche Sprungausdauer","einheit":"Sprünge in 30 s je Seite","kurz":"30 s seitlich über zwei 40 cm auseinanderliegende Linien springen.","ziel":"Seitliche Belastbarkeit im Seitenvergleich.","norm":["Ziel: LSI ab 90 %. Der Side Hop gehört mit Hop for Distance und Vertical Jump zur Testbatterie von Gustavsson 2006: Ist mindestens ein Test auffällig, erkennt die Batterie nach VKB-Plastik 91 % der Patienten mit Defizit."],"durch":"Zwei Klebestreifen im Abstand von 40 cm. Einbeinig so oft wie möglich hin und her springen, 30 s lang. Sprünge auf oder vor der Linie zählen nicht.","position":"Stand","quellen":["Gustavsson A et al. 2006, A test battery for evaluating hop performance in patients with an ACL injury and patients who have undergone ACL reconstruction. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/16525796/","Melbourne ACL Rehabilitation Guide 2.0 – https://www.stgeorges.nhs.uk/wp-content/uploads/2025/10/THE_ACL_01.pdf"],"mess":{"reliab":"Test-Retest ICC 0,85 bis 0,97 über fünf Hop-Tests bei Gesunden (Gustavsson 2006)"},"evidenz":"mäßig"},"pf_aclrsi":{"name":"ACL-RSI","was":"Psychische Bereitschaft für die Rückkehr zum Sport","einheit":"Punkte 0 bis 100","kurz":"12 Fragen zu Gefühlen, Vertrauen und Risikoeinschätzung, je 0 bis 100.","ziel":"Angst vor erneuter Verletzung und Vertrauen ins Knie erfassen.","norm":["Mittelwert der 12 Fragen, 0 bis 100, höher = mehr Bereitschaft.","Grenzwerte: über 56 (Ardern 2013, als Kriterium bei Welling 2018); 6 Monate nach OP 51 Punkte für Rückkehr auf Vorniveau, Sens 97 %, Spez 63 % (Müller 2015). Die VBG-Grenze 51 entspricht diesem Wert.","Bedeutsame Veränderung: etwa 13 Punkte (Webster 2021).","Kein Grenzwert sagt eine erneute VKB-Verletzung sicher voraus (Piussi 2022)."],"durch":"Der Patient füllt den Originalbogen aus. Jede Frage hat eine Skala von 0 bis 100 in Zehnerschritten. Gesamtwert = Mittelwert. Höher heißt mehr Bereitschaft.","position":"Fragebogen","quellen":["Webster KE et al. 2008, Development and preliminary validation of a scale to measure the psychological impact of returning to sport following ACL reconstruction surgery. Phys Ther Sport – https://pubmed.ncbi.nlm.nih.gov/19083699/","Ardern CL et al. 2013, Psychological responses matter in returning to preinjury level of sport after ACL reconstruction surgery. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/23733635/","Müller U et al. 2015, Predictive parameters for return to pre-injury level of sport 6 months following ACL reconstruction surgery. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/25178537/","Webster KE, Feller JA 2021, Evaluation of the Responsiveness of the ACL-RSI Scale. Orthop J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC8377323/","Webster KE, Feller JA 2018, Development and Validation of a Short Version of the ACL-RSI Scale. Orthop J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC5894922/","Welling W et al. 2018, Low rates of patients meeting return to sport criteria 9 months after ACL reconstruction. Knee Surg Sports Traumatol Arthrosc – https://pmc.ncbi.nlm.nih.gov/articles/PMC6267144/","Piussi R et al. 2022, Psychological patient-reported outcomes cannot predict a second ACL injury in patients who return to sports. Int J Sports Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC9718686/","Webster 2018, KSSTA – https://link.springer.com/article/10.1007/s00167-018-4916-4","Physiotutors, deutscher Bogen – https://www.physiotutors.com/de/questionnaires/acl-rsi-short-form/"],"pos":"Auffällig, wenn der Wert unter etwa 51 bis 56 Punkten liegt.","mess":{"reliab":"Cronbach α 0,92 (Webster 2008), 0,96 (Webster 2018)","mcid":"13,4 Punkte Vollversion, 15,1 Punkte Kurzform (Webster 2021, n = 441)","grenzwert":"6 Monate nach OP: 51,3 Punkte für Rückkehr auf Vorniveau, Sens 97 %, Spez 63 % (Müller 2015); 56 Punkte nach Ardern 2013 (als Kriterium zitiert bei Welling 2018)"},"evidenz":"mäßig"},"pf_ikdc":{"name":"IKDC Subjective Knee Form","was":"Subjektive Kniefunktion","einheit":"Punkte 0 bis 100","kurz":"18 Fragen zu Symptomen, Sport und Alltag.","ziel":"Kniefunktion aus Sicht des Patienten im Verlauf.","norm":["0 bis 100, höher ist besser.","Normwerte Allgemeinbevölkerung, Mittelwert (Anderson 2006, n = 5246 Knie): Männer 18–34 J. 89, 35–50 J. 85, ab 51 J. 77; Frauen 18–34 J. 86, 35–50 J. 80, 51–65 J. 71.","Echte Veränderung ab 9 Punkten (Irrgang 2001), bedeutsame Verbesserung ab etwa 11,5 Punkten (Irrgang 2006)."],"durch":"Der Patient füllt den Originalbogen aus. Den Gesamtwert nach Auswertungsanleitung des Bogens eintragen.","position":"Fragebogen","quellen":["Irrgang JJ et al. 2001, Development and validation of the International Knee Documentation Committee Subjective Knee Form. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/11573919/","Irrgang JJ et al. 2006, Responsiveness of the International Knee Documentation Committee Subjective Knee Form. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/16870824/","Anderson AF et al. 2006, The International Knee Documentation Committee Subjective Knee Evaluation Form: normative data. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/16219941/","Welling W et al. 2018, Low rates of patients meeting return to sport criteria 9 months after ACL reconstruction. Knee Surg Sports Traumatol Arthrosc – https://pmc.ncbi.nlm.nih.gov/articles/PMC6267144/","Aspetar Guideline 2023 (IKDC als PROM) – https://www.aspetar.com/en/professionals/aspetar-clinical-guidelines/recommendations-on-rehabilitation-after-aclr"],"mess":{"reliab":"Test-Retest 0,95, interne Konsistenz 0,92 (Irrgang 2001, n = 533)","mdc":"9,0 Punkte (Irrgang 2001)","mcid":"11,5 Punkte (höchste Sensitivität) bzw. 20,5 Punkte (höchste Spezifität) für Verbesserung (Irrgang 2006)","grenzwert":"Rückkehrkriterium: mindestens 15. Perzentile gesunder Gleichaltriger (Welling 2018)"},"evidenz":"stark"},"pf_gw":{"name":"Giving-way-Episoden","was":"Instabilität im Alltag","einheit":"Anzahl","kurz":"Wie oft ist das Knie seit der Verletzung weggeknickt?","ziel":"Dynamische Stabilität ohne Kreuzband einschätzen.","norm":["Delaware-Screening (Fitzgerald 2000): höchstens 1 Giving-way-Episode seit der Verletzung. Als Episode zählt ein erlebtes Wegknicken mit Schmerz und anschließendem Erguss (Moksnes 2008).","Weitere Kriterien: 6-m-Hop auf Zeit mindestens 80 %, KOS-ADLS mindestens 80 %, globale Selbsteinschätzung mindestens 60. Durchführung nach Abklingen von Erguss und Bewegungseinschränkung, im Mittel 6 Wochen nach der Verletzung (Hurd 2008).","Vorhersagekraft begrenzt: positiver Vorhersagewert 60 %; 70 % der als Non-Coper Eingestuften kamen ohne OP nach 1 Jahr zurecht (Moksnes 2008)."],"durch":"Fragen nach Ereignissen, bei denen das Knie tatsächlich nachgegeben hat, nicht nur nach Unsicherheit.","position":"Anamnese","quellen":["Fitzgerald GK et al. 2000, A decision-making scheme for returning patients to high-level activity with nonoperative treatment after ACL rupture. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/10795668/","Moksnes H et al. 2008, Individuals with an ACL-deficient knee classified as noncopers may be candidates for nonsurgical rehabilitation. J Orthop Sports Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC2801138/","Hurd WJ et al. 2008, A 10-year prospective trial of a patient management algorithm and screening examination for highly active individuals with ACL injury: Part 1, outcomes. Am J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC2891099/","Fitzgerald 2000, Delaware-Screening (zit. nach Sekundärquellen)"],"mess":{"grenzwert":"Delaware-Screening: höchstens 1 Giving-way-Episode seit der Verletzung, zusammen mit 6-m-Hop mindestens 80 %, KOS-ADLS mindestens 80 % und globaler Kniefunktion mindestens 60 (Fitzgerald 2000; Moksnes 2008)"},"evidenz":"mäßig"},"pf_grs":{"name":"Selbsteinschätzung Kniefunktion","was":"Globale Kniefunktion","einheit":"0 bis 100 %","kurz":"Wie gut funktioniert das Knie heute im Vergleich zu vor der Verletzung (100 %)?","ziel":"Teil des Delaware-Screenings.","norm":["Delaware-Screening: mindestens 60 % (Fitzgerald 2000). Skala 0 bis 100, 100 = Funktion vor der Verletzung, 0 = keine Alltagsaktivität möglich (Moksnes 2008).","Nach VKB-Plastik gilt für die Rückkehr zum Sport über 90 (Grindem 2016)."],"durch":"Frage an den Patienten, Antwort in Prozent.","position":"Anamnese","quellen":["Fitzgerald GK et al. 2000, A decision-making scheme for returning patients to high-level activity with nonoperative treatment after ACL rupture. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/10795668/","Moksnes H et al. 2008, Individuals with an ACL-deficient knee classified as noncopers may be candidates for nonsurgical rehabilitation. J Orthop Sports Phys Ther – https://pmc.ncbi.nlm.nih.gov/articles/PMC2801138/","Grindem H et al. 2016, Simple decision rules can reduce reinjury risk by 84% after ACL reconstruction. Br J Sports Med – https://pmc.ncbi.nlm.nih.gov/articles/PMC4912389/","Fitzgerald 2000, Delaware-Screening (zit. nach Sekundärquellen)"],"mess":{"grenzwert":"Delaware-Screening: mindestens 60 auf der Skala 0 bis 100 (100 = Kniefunktion vor der Verletzung) (Fitzgerald 2000; Moksnes 2008)"},"evidenz":"mäßig"},"jobe":{"name":"Jobe-Test (Empty Can)","was":"Supraspinatus","einheit":"positiv oder negativ","kurz":"Arme in 90° Abduktion in der Skapulaebene, innenrotiert (Daumen nach unten); Druck nach kaudal gegen Widerstand.","ziel":"Hinweis auf Supraspinatusruptur oder subakromiales Schmerzsyndrom gewinnen.","position":"Sitz","durch":"Sitz oder Stand. Beide Arme in 90° Abduktion, etwa 30° vor der Frontalebene (Skapulaebene), voll innenrotiert. Der Therapeut drückt am distalen Unterarm nach kaudal, der Patient hält dagegen. Seitenvergleich von Kraft und Schmerz. Full-Can-Variante mit Daumen nach oben provoziert weniger Schmerz und ist gleich genau.","norm":["Positiv bei Schwäche im Seitenvergleich; Schmerz allein ist weniger aussagekräftig.","Supraspinatusruptur, Kriterium Schwäche: LR+ 2,08, LR− 0,31 (Lasbleiz 2014). Impingement: LR+ 3,90 (Michener 2009).","Empty Can und Full Can sind mit Kriterium Schwäche gleich genau (70 bzw. 75 %, Itoi 1999)."],"pos":"Positiv bei Kraftminderung gegen Widerstand im Seitenvergleich.","kw":[{"ziel":"Supraspinatusruptur (Kriterium Schwäche)","lrp":"2,08","lrn":"0,31","basis":"Lasbleiz 2014, 39 Schultern, Ultraschall als Referenz"},{"ziel":"Subakromiales Impingement","lrp":"3,90 (1,5–10,12)","basis":"Michener 2009, 55 Patienten, OP als Referenz"},{"ziel":"Komplette Supraspinatusruptur (Kriterium Schwäche)","basis":"Itoi 1999, 143 Schultern, MRT: Genauigkeit 70 % (Empty Can) bzw. 75 % (Full Can)"}],"evidenz":"mäßig","quellen":["Itoi E et al. 1999, Which is more useful, the full can test or the empty can test, in detecting the torn supraspinatus tendon? Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/9934421/","Michener LA et al. 2009, Reliability and diagnostic accuracy of 5 physical examination tests for subacromial impingement. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/19887215/","Lasbleiz S et al. 2014, Diagnostic value of clinical tests for degenerative rotator cuff disease in medical practice. Ann Phys Rehabil Med – https://pubmed.ncbi.nlm.nih.gov/24851697/","Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/"],"neu":true},"bearhug":{"name":"Bear-Hug-Test","was":"Subscapularis, vor allem oberer Sehnenanteil","einheit":"positiv oder negativ","kurz":"Handfläche auf die Gegenschulter, Ellbogen vor dem Körper; der Patient drückt gegen den Versuch des Therapeuten, die Hand in Außenrotation abzuheben.","ziel":"Hinweis auf eine Subscapularisläsion gewinnen, auch bei kleinen Rupturen am oberen Rand.","position":"Sitz","durch":"Sitz oder Stand. Die Handfläche der betroffenen Seite liegt auf der Gegenschulter, Finger gestreckt, Ellbogen vor dem Körper angehoben. Der Patient hält in Innenrotation, der Therapeut versucht, die Hand senkrecht zum Unterarm von der Schulter wegzuziehen. Seitenvergleich.","norm":["Positiv, wenn der Patient die Hand nicht auf der Schulter halten kann oder im Seitenvergleich deutlich schwächer ist.","Sensitivster Subscapularistest: Sens. 52–60 %, Spez. 85–92 % (Barth 2006, Kappe 2018); bei Rupturen Grad 2–4 Sens. 72 %, Spez. 84 %.","Positiv schon ab etwa 30 % Rupturgröße (Barth 2006)."],"pos":"Positiv, wenn die Hand gegen Widerstand nicht auf der Gegenschulter gehalten werden kann oder deutlich schwächer ist als auf der Gegenseite.","kw":[{"ziel":"Subscapularisruptur","sens":"60 %","spez":"91,7 %","lrp":"7,2","lrn":"0,44","basis":"Barth 2006, 68 Patienten, Arthroskopie als Referenz; LR berechnet"},{"ziel":"Subscapularisläsion jeder Art","sens":"52 %","spez":"85 %","lrp":"3,5","lrn":"0,56","basis":"Kappe 2018, 106 Patienten, Arthroskopie; LR berechnet"},{"ziel":"Subscapularisruptur Grad 2–4","sens":"72 %","spez":"84 %","lrp":"4,5","lrn":"0,33","basis":"Kappe 2018; LR berechnet"}],"evidenz":"mäßig","quellen":["Barth JR et al. 2006, The bear-hug test: a new and sensitive test for diagnosing a subscapularis tear. Arthroscopy – https://pubmed.ncbi.nlm.nih.gov/17027405/","Kappe T et al. 2018, Diagnostic performance of clinical tests for subscapularis tendon tears. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/28676889/"],"neu":true},"speed":{"name":"Speed-Test","was":"Lange Bizepssehne","einheit":"positiv oder negativ","kurz":"Gestreckter, supinierter Arm in etwa 90° Flexion; der Patient hält gegen Druck nach kaudal.","ziel":"Hinweis auf eine Tendinopathie der langen Bizepssehne gewinnen.","position":"Sitz","durch":"Sitz oder Stand. Ellbogen gestreckt, Unterarm supiniert, Schulter in etwa 90° Flexion. Der Therapeut drückt am distalen Unterarm nach kaudal, der Patient hält dagegen. Positiv bei Schmerz im Sulcus intertubercularis.","norm":["Positiv bei Schmerz über dem Sulcus intertubercularis.","Bizepssehnen-Tendinopathie: Spez. 81–85 %, Sens. 54–71 %, LR+ 2,8–4,6 in zwei Einzelstudien (Hegedus 2012).","Für SLAP-Läsionen nutzlos: gepoolt Sens. 20 %, Spez. 78 %, LR+ 0,90. Zusammen mit dem Upper-Cut-Test am besten für Bizepsläsionen (Kibler 2009)."],"pos":"Positiv bei Schmerz im Sulcus intertubercularis gegen Widerstand.","kw":[{"ziel":"Tendinopathie der langen Bizepssehne","sens":"54 %","spez":"81 %","lrp":"2,77","lrn":"0,58","basis":"Kibler 2009, 101 operierte Patienten, in Hegedus 2012"},{"ziel":"Tendinopathie der langen Bizepssehne","sens":"71 %","spez":"85 %","lrp":"4,6","lrn":"0,34","basis":"Goyal, Einzelstudie in Hegedus 2012"},{"ziel":"SLAP-Läsion","sens":"20 %","spez":"78 %","lrp":"0,90","lrn":"1,03","basis":"Metaanalyse Hegedus 2012, 4 Studien, 327 Patienten"}],"evidenz":"mäßig","quellen":["Kibler WB et al. 2009, Clinical utility of traditional and new tests in the diagnosis of biceps tendon injuries and SLAP lesions. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/19509414/","Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/"],"neu":true},"uppercut":{"name":"Upper-Cut-Test","was":"Lange Bizepssehne","einheit":"positiv oder negativ","kurz":"Aus Neutralstellung mit 90° gebeugtem Ellbogen und supinierter, zur Faust geschlossener Hand führt der Patient eine Aufwärtshaken-Bewegung gegen Widerstand aus.","ziel":"Hinweis auf eine Läsion der langen Bizepssehne gewinnen.","position":"Stand","durch":"Stand. Arm am Körper, Ellbogen 90° gebeugt, Unterarm supiniert, Hand zur Faust. Der Patient führt die Faust wie bei einem Aufwärtshaken nach oben Richtung Kinn, der Therapeut hält mit der Hand auf der Faust dagegen. Positiv bei Schmerz oder schmerzhaftem Schnappen vorn an der Schulter.","norm":["Positiv bei Schmerz oder schmerzhaftem Schnappen an der vorderen Schulter.","Bizepsläsion: Sens. 73 %, Spez. 78 %, LR+ 3,38 (Kibler 2009, Einzelstudie); genauester Einzeltest dieser Studie, zusammen mit dem Speed-Test am besten."],"pos":"Positiv bei Schmerz oder schmerzhaftem Schnappen an der vorderen Schulter während der Bewegung gegen Widerstand.","kw":[{"ziel":"Läsion der langen Bizepssehne","sens":"73 %","spez":"78 %","lrp":"3,38","lrn":"0,34","basis":"Kibler 2009, 325 Patienten untersucht, 101 operiert; Spez. und LR− aus Hegedus 2012"},{"ziel":"SLAP-Läsion","sens":"22 %","spez":"56 %","lrp":"0,49","lrn":"1,40","basis":"Kibler 2009, in Hegedus 2012"}],"evidenz":"mäßig","quellen":["Kibler WB et al. 2009, Clinical utility of traditional and new tests in the diagnosis of biceps tendon injuries and SLAP lesions. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/19509414/","Hegedus EJ et al. 2012, Which physical examination tests provide clinicians with the most value when examining the shoulder? Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/22773322/"],"neu":true},"canadiancspine":{"name":"Canadian C-Spine Rule","was":"Klinisch relevante HWS-Verletzung nach Trauma","einheit":"positiv oder negativ","kurz":"Entscheidungsregel mit drei Fragen (Hochrisikofaktor, Niedrigrisikofaktor, aktive Rotation 45°), ob nach einem Trauma eine Bildgebung nötig ist.","ziel":"Nach einem Unfall entscheiden, ob die HWS vor Behandlung ärztlich und radiologisch abgeklärt werden muss.","position":"Sitz","durch":"Gilt für wache, stabile Erwachsene nach stumpfem Trauma an Kopf oder Nacken. 1. Hochrisikofaktor vorhanden (Alter ab 65, gefährlicher Unfallmechanismus, Kribbeln in den Extremitäten)? Ja: Bildgebung. 2. Niedrigrisikofaktor vorhanden (einfacher Auffahrunfall, sitzt aufrecht, seit dem Unfall gehfähig, verzögert einsetzender Nackenschmerz, kein Druckschmerz in der Mittellinie)? Nein: Bildgebung. 3. Aktive Rotation 45° nach rechts und links möglich? Nein: Bildgebung; ja: keine Bildgebung nötig.","norm":["Positiv (Bildgebung nötig) bei Hochrisikofaktor, fehlendem Niedrigrisikofaktor oder nicht möglicher aktiver Rotation von 45° zu beiden Seiten.","Klinisch relevante HWS-Verletzung: Sens. 99,4–100 %, Spez. 40–45 % (Stiell 2001, 2003; zusammen über 17.000 Patienten). Auch durch Rettungsdienst zuverlässig anwendbar (Kappa 0,93).","Ein negatives Ergebnis schließt eine relevante Verletzung praktisch aus."],"pos":"Positiv (Bildgebung nötig) bei einem Hochrisikofaktor, ohne Niedrigrisikofaktor oder wenn die aktive Rotation von 45° zu einer Seite nicht gelingt.","kw":[{"ziel":"Klinisch relevante HWS-Verletzung (Ableitung)","sens":"100 % (98–100)","spez":"42,5 % (40–44)","basis":"Stiell 2001, 8924 Patienten, 10 Notaufnahmen"},{"ziel":"Klinisch relevante HWS-Verletzung (Validierung)","sens":"99,4 %","spez":"45,1 %","lrp":"1,8","lrn":"0,01","basis":"Stiell 2003, 8283 Patienten; LR berechnet"},{"ziel":"Klinisch relevante HWS-Verletzung (Anwendung durch Rettungsdienst)","sens":"100 % (74–100)","spez":"37,7 %","basis":"Vaillancourt 2009, 1949 Patienten; Kappa 0,93"}],"evidenz":"stark","quellen":["Stiell IG et al. 2001, The Canadian C-spine rule for radiography in alert and stable trauma patients. JAMA – https://pubmed.ncbi.nlm.nih.gov/11597285/","Stiell IG et al. 2003, The Canadian C-spine rule versus the NEXUS low-risk criteria in patients with trauma. N Engl J Med – https://pubmed.ncbi.nlm.nih.gov/14695411/","Vaillancourt C et al. 2009, The out-of-hospital validation of the Canadian C-Spine Rule by paramedics. Ann Emerg Med – https://pubmed.ncbi.nlm.nih.gov/19394111/"],"neu":true},"kraniozervikalflexion":{"name":"Kraniozervikaler Flexionstest (CCFT)","was":"Aktivierung und Ausdauer der tiefen Nackenflexoren","einheit":"mmHg (höchste sauber gehaltene Stufe)","kurz":"In Rückenlage mit Druck-Biofeedback unter der HWS führt der Patient ein Kopfnicken in fünf Stufen aus und hält jede Stufe.","ziel":"Motorische Kontrolle der tiefen Nackenflexoren bei Nackenschmerz erfassen und im Verlauf vergleichen.","position":"Rückenlage","durch":"Rückenlage, Knie angestellt, Kopf neutral. Ein Druck-Biofeedback-Gerät liegt unter der oberen HWS und wird vorgefüllt. Der Patient nickt langsam ohne Kopfheben und erreicht nacheinander fünf Druckstufen, jede wird kurz gehalten. Gewertet wird die höchste Stufe, die ohne Ausweichen (oberflächliche Halsmuskulatur, Kopfheben, Druckabfall) gehalten wird.","norm":["Gewertet wird die höchste Stufe, die ohne Ausweichbewegung gehalten wird.","Reliabilität: Inter-Rater ICC ≥ 0,85, Intra-Rater ICC ≥ 0,69 (Juul 2013). Die Übersicht Romeo 2022 hält die meisten Versionen nur auf Gruppenebene für ausreichend reliabel; Veränderungen im Verlauf bildet der Test schlecht ab.","Kein diagnostischer Test, sondern Messung der Muskelfunktion."],"pos":"Auffällig, wenn die Zielstufen nicht ohne Ausweichen über die oberflächlichen Halsmuskeln oder Druckabfall gehalten werden.","mess":{"reliab":"Inter-Rater ICC ≥ 0,85, Intra-Rater ICC ≥ 0,69 (Juul 2013, 63 Personen); systematische Übersicht: auf Individualebene nur Performance-Index-Versionen ausreichend reliabel (Romeo 2022)","mcid":"Responsivität in der Übersicht negativ bewertet, keine MCID belegt"},"evidenz":"mäßig","quellen":["Jull GA et al. 2008, Clinical assessment of the deep cervical flexor muscles: the craniocervical flexion test. J Manipulative Physiol Ther – https://pubmed.ncbi.nlm.nih.gov/18804003/","Juul T et al. 2013, The intra- and inter-rater reliability of five clinical muscle performance tests in patients with and without neck pain. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/24299621/","Romeo A et al. 2022, Reliability, validity, and responsiveness of the craniocervical flexion test: a systematic review and meta-analysis. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35554598/"],"neu":true},"nackenflexorenausdauer":{"name":"Deep Neck Flexor Endurance Test","was":"Haltezeit der tiefen Nackenflexoren","einheit":"Sekunden","kurz":"In Rückenlage hält der Patient mit eingezogenem Kinn den Kopf knapp über der Unterlage; gemessen wird die Haltezeit.","ziel":"Ausdauer der Nackenflexoren erfassen und mit Normwerten vergleichen.","position":"Rückenlage","durch":"Rückenlage, Knie angestellt. Der Patient zieht das Kinn ein (Doppelkinn) und hebt den Kopf knapp von der Unterlage. Der Therapeut stoppt die Zeit, bis das Kinn nach vorn geht oder der Kopf die Unterlage bzw. die Hand des Therapeuten berührt.","norm":["Normwerte Gesunder: Männer 38,9 ± 20,1 s, Frauen 29,4 ± 13,7 s (Domenech 2011, 126 Erwachsene, kein Alterseffekt zwischen 20 und 80 Jahren).","Reliabilität mäßig (ICC 0,66–0,71); die kleinste nachweisbare Veränderung liegt bei mindestens 23 s (Martins 2018). Kleinere Verbesserungen im Verlauf sind also nicht sicher echt."],"pos":"Auffällig bei deutlich kürzerer Haltezeit als die Normwerte; im Verlauf zählt erst eine Änderung von mindestens 23 s als sicher.","mess":{"reliab":"Inter-Rater ICC 0,66 (Domenech 2011), ICC 0,71 (Jarman 2017), Rückenlage ICC ≥ 0,68–0,70 (Juul 2013)","mdc":"MDC95 ≥ 23 s (Martins 2018)","grenzwert":"Normwerte: Männer 38,9 ± 20,1 s, Frauen 29,4 ± 13,7 s (Domenech 2011)"},"evidenz":"mäßig","quellen":["Domenech MA et al. 2011, The deep neck flexor endurance test: normative data scores in healthy adults. PM R – https://pubmed.ncbi.nlm.nih.gov/21333948/","Martins F et al. 2018, Within-session and between-session reliability, construct validity, and comparison between individuals with and without neck pain of four neck muscle tests. PM R – https://pubmed.ncbi.nlm.nih.gov/28736327/","Juul T et al. 2013, The intra- and inter-rater reliability of five clinical muscle performance tests in patients with and without neck pain. BMC Musculoskelet Disord – https://pubmed.ncbi.nlm.nih.gov/24299621/","Jarman NF et al. 2017, Deep neck flexor endurance in the adolescent and young adult: normative data. PM R – https://pubmed.ncbi.nlm.nih.gov/28214618/"],"neu":true},"schmerzfreiegriffkraft":{"name":"Schmerzfreie Griffkraft (Pain-free Grip)","was":"Laterale Epikondylopathie, Verlauf","einheit":"kg","kurz":"Griffkraft mit dem Dynamometer bis zum ersten Schmerz messen.","ziel":"Belastbarkeit bei lateraler Epikondylopathie messen und den Verlauf dokumentieren.","position":"Sitz","durch":"Sitz, Ellbogen gestreckt, Unterarm proniert, Handgelenk leicht extendiert. Der Patient drückt den Handdynamometer langsam zu und hört beim ersten Schmerz auf. Drei Versuche mit kurzer Pause, Mittelwert notieren, gleiche Griffstufe bei jeder Messung. Gegenseite zum Vergleich.","norm":["Kraft in kg bis zum Schmerzbeginn, Mittelwert aus 3 Versuchen, Seitenvergleich.","Echte Veränderung zwischen zwei Terminen ab etwa 9 kg (MDC, Hill 2022); klinisch relevante Veränderung etwa 7 kg (JOSPT-CPG 2022)."],"pos":"Auffällig bei deutlich geringerer schmerzfreier Kraft als auf der Gegenseite; im Verlauf zählt eine Änderung über der MDC.","kw":[{"ziel":"Laterale Epikondylopathie (Griffkraftdifferenz 5–10 % zwischen gebeugtem und gestrecktem Ellbogen)","sens":"78–83 %","spez":"80–90 %","basis":"Systematische Übersicht, nur 2 Studien zu klinischen Tests, überwiegend hohes oder unklares Bias-Risiko (Karanasios 2022); laut Abstract Griffkraftmessung allgemein, ob schmerzfrei oder maximal, nicht angegeben"}],"mess":{"reliab":"ICC 0,86–0,97 (zwischen Untersuchern und Terminen)","mdc":"Zwischen Terminen 9,2 kg (gebeugt) bzw. 9,4 kg (gestreckt), Mittelwert aus 3 Versuchen","mcid":"7 kg (Stratford & Levy 1994, zitiert in JOSPT-CPG)"},"evidenz":"stark","quellen":["Lucado AM et al. 2022, Lateral Elbow Pain and Muscle Function Impairments (Clinical Practice Guideline). J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/36453071/","Hill CE et al. 2022, Pain-free grip strength in individuals with lateral elbow tendinopathy: between- and within-session reliability of one versus three trials. Physiother Theory Pract – https://pubmed.ncbi.nlm.nih.gov/35114892/","Karanasios S et al. 2022, Diagnostic accuracy of examination tests for lateral elbow tendinopathy: a systematic review. J Hand Ther – https://pubmed.ncbi.nlm.nih.gov/33814224/"],"neu":true},"handkraftjamar":{"name":"Handkraft mit Dynamometer (Jamar)","was":"Maximale Griffkraft","einheit":"kg","kurz":"Maximale Griffkraft im standardisierten Sitz mit dem Handdynamometer messen.","ziel":"Kraftdefizit der Hand messen, mit Norm und Gegenseite vergleichen und den Verlauf erfassen.","position":"Sitz","durch":"Sitz, Schulter adduziert und neutral rotiert, Ellbogen 90° gebeugt, Unterarm und Handgelenk neutral, Griffstufe 2. Der Patient drückt drei Mal maximal, kurze Pause dazwischen, Mittelwert notieren. Beide Seiten messen.","norm":["Mittelwert aus 3 Versuchen in kg, Seitenvergleich und alters- und geschlechtsbezogene Normwerte.","Spitzenwerte im jungen Erwachsenenalter: Median etwa 51 kg (Männer, 29–39 J.) und 31 kg (Frauen, 26–42 J.), danach Abnahme (Dodds 2014). Klinisch relevante Änderung nach distaler Radiusfraktur 6,5 kg (Bobos 2020)."],"pos":"Auffällig bei deutlich geringerer Kraft als auf der Gegenseite oder unter der Altersnorm.","mess":{"reliab":"Gepoolt ICC 0,92 (Gesunde), 0,95 (Erkrankungen der oberen Extremität), 0,96 (neurologisch), 25 Studien","mcid":"6,5 kg nach distaler Radiusfraktur; 5,0–6,2 kg nach Schlaganfall","grenzwert":"Normwerte nach Alter und Geschlecht (Mathiowetz 1985, Peters 2011, Dodds 2014)"},"evidenz":"stark","quellen":["Bobos P et al. 2020, Measurement Properties of the Hand Grip Strength Assessment: A Systematic Review With Meta-analysis. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/31730754/","Dodds RM et al. 2014, Grip strength across the life course: normative data from twelve British studies. PLoS One – https://pubmed.ncbi.nlm.nih.gov/25474696/","Mathiowetz V et al. 1985, Grip and pinch strength: normative data for adults. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/3970660/","Mathiowetz V et al. 1984, Reliability and validity of grip and pinch strength evaluations. J Hand Surg Am – https://pubmed.ncbi.nlm.nih.gov/6715829/","Peters MJ et al. 2011, Revised normative values for grip strength with the Jamar dynamometer. J Peripher Nerv Syst – https://pubmed.ncbi.nlm.nih.gov/21504502/"],"neu":true},"handelevation":{"name":"Hand-Elevationstest","was":"Karpaltunnelsyndrom","einheit":"positiv oder negativ","kurz":"Beide Arme locker über den Kopf heben und eine Minute halten.","ziel":"Typische KTS-Beschwerden durch Hochhalten der Hände provozieren.","position":"Sitz","durch":"Sitz. Der Patient hebt beide Arme über den Kopf, Schultern und Ellbogen locker, ohne Anstrengung, und hält die Position bis zu einer Minute. Positiv, wenn dabei die bekannten Beschwerden (Kribbeln, Taubheit im Medianusgebiet) auftreten.","norm":["Positiv bei Reproduktion der bekannten KTS-Beschwerden innerhalb von 1 Minute.","In der Metaanalyse 2022 der Test mit der höchsten diagnostischen Odds Ratio (128,6; 864 Handgelenke). Erstbeschreibung: Sens. 75,5 %, Spez. 98,5 % gegen Gesunde (Ahn 2001)."],"pos":"Positiv, wenn das Hochhalten der Arme innerhalb einer Minute die bekannten Parästhesien im Medianusgebiet auslöst.","kw":[{"ziel":"Karpaltunnelsyndrom","basis":"Metaanalyse, 864 Handgelenke: diagnostische Odds Ratio 128,63 (95 %-KI 40,6–407,1), Núñez de Arenas-Arroyo 2022"},{"ziel":"Karpaltunnelsyndrom","sens":"75,5 %","spez":"98,5 %","lrp":"50","lrn":"0,25","basis":"Fall-Kontroll-Studie, 200 betroffene vs. 200 gesunde Hände (Ahn 2001); LR berechnet, durch Gesunde als Vergleich vermutlich überschätzt"}],"evidenz":"mäßig","quellen":["Núñez de Arenas-Arroyo S et al. 2022, Accuracy of the Most Common Provocation Tests for Diagnosing Carpal Tunnel Syndrome: A Systematic Review With Meta-analysis. J Orthop Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/35722757/","Ahn DS 2001, Hand elevation: a new test for carpal tunnel syndrome. Ann Plast Surg – https://pubmed.ncbi.nlm.nih.gov/11216604/"],"neu":true},"movingpatellaapprehension":{"name":"Moving Patellar Apprehension Test","was":"Laterale Patellainstabilität","einheit":"positiv oder negativ","kurz":"Patella während Beugung und Streckung nach lateral, dann nach medial schieben und Reaktion beobachten.","ziel":"Laterale Patellainstabilität nach Luxation erkennen.","position":"Rückenlage","durch":"Rückenlage, Knie gestreckt. Der Therapeut schiebt die Patella mit dem Daumen nach lateral und beugt das Knie unter gehaltenem Druck bis 90° und zurück. Danach derselbe Ablauf mit Druck nach medial. Positiv, wenn im ersten Teil Angst oder Quadrizepsanspannung auftritt und im zweiten Teil nicht.","norm":["Positiv bei Apprehension im lateralen Teil und freier Bewegung im medialen Teil.","Sens. 100 %, Spez. 88,4 % gegen Luxierbarkeit in Narkose (Ahmad 2009, n = 51); ähnliche Werte für die umgekehrte dynamische Variante (Sens. 93,7 %, Spez. 88,2 %; Zimmermann 2019)."],"pos":"Positiv, wenn bei lateralem Druck auf die Patella während der Beugung Angst oder Abwehrspannung auftritt und bei medialem Druck nicht.","kw":[{"ziel":"Laterale Patellainstabilität (Luxierbarkeit in Narkose)","sens":"100 %","spez":"88,4 %","lrp":"8,6","basis":"Einzelstudie, 51 Patienten (Ahmad 2009); LR berechnet"},{"ziel":"Rezidivierende laterale Patellainstabilität (umgekehrte dynamische Variante)","sens":"93,7 %","spez":"88,2 %","lrp":"7,9","lrn":"0,07","basis":"Prospektive Studie, 78 Patienten und 35 Kontrollen (Zimmermann 2019); LR berechnet"}],"evidenz":"mäßig","quellen":["Ahmad CS et al. 2009, The moving patellar apprehension test for lateral patellar instability. Am J Sports Med – https://pubmed.ncbi.nlm.nih.gov/19193601/","Zimmermann F et al. 2019, The reversed dynamic patellar apprehension test mimics anatomical complexity in lateral patellar instability. Knee Surg Sports Traumatol Arthrosc – https://pubmed.ncbi.nlm.nih.gov/30293182/","Abelleyra Lastoria DA et al. 2023, Is the patella apprehension test a valid diagnostic test for patellar instability? A systematic review. J Orthop – https://pubmed.ncbi.nlm.nih.gov/37483643/"],"neu":true},"singlelegdeclinesquat":{"name":"Single Leg Decline Squat (SLDS)","was":"Belastungsschmerz bei Patellasehnen-Tendinopathie","einheit":"Schmerz 0-10","kurz":"Einbeinige Kniebeuge auf einem 25°-Keilbrett, Schmerz an der Patellasehne auf 0-10 angeben.","ziel":"Belastungsschmerz der Patellasehne messen und im Verlauf vergleichen.","position":"Stand","durch":"Stand auf dem Testbein auf einem etwa 25° abfallenden Keilbrett, Hände an den Hüften oder leicht abgestützt. Der Patient beugt das Knie langsam so weit wie möglich und richtet sich wieder auf, mehrere Wiederholungen. Danach gibt er den Schmerz an der Patellasehne auf einer Skala von 0 bis 10 an. Beim nächsten Termin mit gleicher Durchführung wiederholen.","norm":["Messgröße ist der angegebene Schmerz (0-10) an der Patellasehne.","Test-Retest ICC 0,86-0,92, MDC95 0,9-2,5 Punkte (Hjortshoej 2026); MCID etwa 1,2-1,6 Punkte (Ruffino 2024)."],"pos":"Auffällig bei bekanntem Schmerz am unteren Patellapol; im Verlauf bedeutsam ab etwa 1,5 Punkten Änderung.","mess":{"reliab":"ICC 0,86-0,92 (Test-Retest, 30 Athleten)","mdc":"0,9-2,5 Punkte (MDC95, je nach Berechnung)","mcid":"1,6 Punkte (ankerbasiert), 1,2 Punkte (verteilungsbasiert)"},"evidenz":"mäßig","quellen":["Hjortshoej MH et al. 2026, Test-retest reliability and the minimal detectable change of clinical and structural outcomes in athletes with patellar tendinopathy. Phys Ther Sport – https://pubmed.ncbi.nlm.nih.gov/42826611/","Ruffino D et al. 2024, Sensitivity to change and responsiveness of provocative load tests among athletes with patellar tendinopathy. Braz J Phys Ther – https://pubmed.ncbi.nlm.nih.gov/38696973/"],"neu":true},"weightbearinglunge":{"name":"Weight-Bearing Lunge Test (Knee-to-Wall)","was":"Dorsalextension im OSG unter Belastung","einheit":"cm oder Grad","kurz":"Im Ausfallschritt das Knie zur Wand führen, Ferse bleibt am Boden; Abstand Großzehe-Wand oder Tibiawinkel messen.","ziel":"Dorsalextension im OSG unter Belastung messen und im Verlauf vergleichen.","position":"Stand","durch":"Stand vor einer Wand, Testfuß in Schrittstellung vorne, Fuß gerade. Der Patient bewegt das Knie zur Wand, die Ferse bleibt am Boden. Der Fuß wird so weit zurückgesetzt, bis das Knie die Wand gerade noch berührt. Gemessen wird der Abstand Großzehe-Wand in cm oder der Winkel der Tibia zur Senkrechten mit Inklinometer, Seitenvergleich.","norm":["Messgröße: Abstand Großzehe-Wand (cm) oder Tibiawinkel (°), im Seitenvergleich.","Interrater ICC 0,80-0,99; Änderung erst ab etwa 1,6-1,9 cm bzw. 4,6-4,7° sicher über dem Messfehler (Powden 2015, 12 Studien)."],"pos":"Auffällig bei Seitendifferenz oder Einschränkung über dem Messfehler (etwa 1,6 cm oder 4,6°).","mess":{"reliab":"Interrater ICC 0,80-0,99, Intrarater ICC 0,65-0,99 (Powden 2015, systematische Übersicht)","mdc":"1,6 cm bzw. 4,6° (Interrater), 1,9 cm bzw. 4,7° (Intrarater)"},"evidenz":"stark","quellen":["Powden CJ et al. 2015, Reliability and minimal detectable change of the weight-bearing lunge test: a systematic review. Man Ther – https://pubmed.ncbi.nlm.nih.gov/25704110/","Konor MM et al. 2012, Reliability of three measures of ankle dorsiflexion range of motion. Int J Sports Phys Ther – https://pubmed.ncbi.nlm.nih.gov/22666642/","Bennell KL et al. 1998, Intra-rater and inter-rater reliability of a weight-bearing lunge measure of ankle dorsiflexion. Aust J Physiother – https://pubmed.ncbi.nlm.nih.gov/11676731/"],"neu":true},"heelraiseausdauer":{"name":"Heel-Rise-Ausdauertest (Wadenheben bis zur Ermüdung)","was":"Kraftausdauer der Wadenmuskulatur","einheit":"Anzahl Wiederholungen","kurz":"Einbeinig im Takt auf die Zehenspitzen gehen bis zur Ermüdung, Wiederholungen zählen.","ziel":"Kraftausdauer der Plantarflexoren messen und mit Gegenseite und Normwerten vergleichen.","position":"Stand","durch":"Einbeinstand, Fingerspitzen leicht an der Wand, nach Möglichkeit auf einem 10°-Keil. Der Patient hebt die Ferse im gleichmäßigen Takt so hoch wie möglich, bis er nicht mehr kann oder die Höhe deutlich nachlässt. Gezählt werden die vollständigen Wiederholungen, beide Seiten im Vergleich.","norm":["Messgröße: Anzahl vollständiger Wiederholungen je Bein.","Gesunde Erwachsene auf 10°-Keil: Median 24 (Männer) und 21 (Frauen) Wiederholungen; Test-Retest ICC 1,0 (Hébert-Losier 2017). Ohne Keil mit App gemessen Median 24-25 (Visser 2025)."],"pos":"Auffällig bei deutlich weniger Wiederholungen als auf der Gegenseite oder unter dem alters- und geschlechtsbezogenen Normwert.","mess":{"reliab":"ICC 1,0 (Test-Retest, 32 Gesunde); Übereinstimmungsgrenzen etwa ±6 Wiederholungen","grenzwert":"Median 24 (Männer), 21 (Frauen) auf 10°-Keil, abhängig von Alter, BMI und Aktivität"},"evidenz":"mäßig","quellen":["Hébert-Losier K et al. 2017, Updated reliability and normative values for the standing heel-rise test in healthy adults. Physiotherapy – https://pubmed.ncbi.nlm.nih.gov/28886865/","Visser TSS et al. 2025, Normative values for calf muscle strength-endurance in the general population assessed with the Calf Raise Application. Braz J Phys Ther – https://pubmed.ncbi.nlm.nih.gov/40020545/","Hébert-Losier K et al. 2009, Raising the standards of the calf-raise test: a systematic review. J Sci Med Sport – https://pubmed.ncbi.nlm.nih.gov/19231286/"],"neu":true},"zentralisation":{"name":"Zentralisationsphänomen (McKenzie)","was":"Diskogener Kreuzschmerz, Ansprechen auf Richtungspräferenz","einheit":"positiv oder negativ","kurz":"Wiederholte Bewegungen der LWS testen und beobachten, ob ausstrahlender Schmerz zur Mitte der Wirbelsäule zurückweicht.","ziel":"Hinweis auf eine diskogene Schmerzquelle gewinnen und eine passende Bewegungsrichtung für die Behandlung finden.","position":"Stand","durch":"Ausgangsschmerz und dessen Ausbreitung erfragen. Der Patient führt wiederholt (etwa 10-mal je Serie) Flexion und Extension im Stand, bei Bedarf in Rückenlage bzw. Bauchlage, sowie seitliche Verschiebungen aus. Nach jeder Serie wird erneut nach Schmerzort und -stärke gefragt.","norm":["Positiv, wenn der am weitesten distal gelegene Schmerz während der Testung schrittweise zur Mitte zurückweicht oder verschwindet.","Diskogener Schmerz (Diskografie): Sens. 40 %, Spez. 94 %, LR+ 6,9 (Laslett 2005); gepoolt LR+ 3,06, LR- 0,66 (Han 2023).","Spricht für den Diskus, das Fehlen schließt ihn nicht aus. Bei starker Beeinträchtigung oder Distress sinkt die Spezifität."],"pos":"Positiv, wenn sich der distalste Schmerz durch wiederholte Bewegungen zur Wirbelsäulenmitte zurückzieht oder verschwindet.","kw":[{"ziel":"Diskus als Schmerzquelle","lrp":"3,06","lrn":"0,66","basis":"Systematische Übersicht, gepoolt"},{"ziel":"Diskogener Schmerz (Provokationsdiskografie)","sens":"40 %","spez":"94 %","lrp":"6,9","basis":"Einzelstudie, 69 Pat. mit chronischem Kreuzschmerz"},{"ziel":"Diskus als Schmerzquelle","lrp":"2,8","basis":"Systematische Übersicht, einziges informatives klinisches Zeichen"}],"evidenz":"stark","quellen":["Han CS et al. 2023, Low back pain of disc, sacroiliac joint, or facet joint origin: a diagnostic accuracy systematic review. EClinicalMedicine – https://pubmed.ncbi.nlm.nih.gov/37096189/","Laslett M et al. 2005, Centralization as a predictor of provocation discography results in chronic low back pain, and the influence of disability and distress on diagnostic power. Spine J – https://pubmed.ncbi.nlm.nih.gov/15996606/","Hancock MJ et al. 2007, Systematic review of tests to identify the disc, SIJ or facet joint as the source of low back pain. Eur Spine J – https://pubmed.ncbi.nlm.nih.gov/17566796/"],"neu":true},"caudaequina":{"name":"Cauda-equina-Screening","was":"Kaudasyndrom, Notfall-Ausschluss","einheit":"positiv oder negativ","kurz":"Gezielte Fragen nach Blasen- und Mastdarmstörung, Reithosenanästhesie, beidseitiger Ischialgie und zunehmender Lähmung.","ziel":"Ein Kaudasyndrom früh erkennen und sofort ärztlich abklären lassen.","position":"Fragebogen","durch":"Bei Kreuzschmerz mit Beinausstrahlung gezielt fragen: neu aufgetretene Probleme beim Wasserlassen (Harnverhalt, Inkontinenz), Stuhlinkontinenz, Taubheit im Gesäß-, Damm- oder Genitalbereich, Ausstrahlung in beide Beine, zunehmende Schwäche. Bei Hinweisen Sensibilität perianal und Kennmuskeln prüfen und sofort ärztliche Abklärung veranlassen.","norm":["Positiv bei neu aufgetretener Blasen- oder Mastdarmstörung, Reithosenanästhesie oder rasch zunehmendem neurologischem Defizit: sofortige ärztliche Abklärung.","Einzelzeichen sind eher spezifisch als sensitiv: gepoolte Sens. 19–43 %, Spez. 62–88 % (Dionne 2019, 7 Studien, 569 Pat.).","Ein unauffälliges Screening schließt ein Kaudasyndrom nicht aus; bei Verdacht im Verlauf erneut fragen."],"pos":"Positiv, wenn mindestens ein Warnhinweis neu auftritt, zum Beispiel Blasen- oder Mastdarmstörung oder Taubheit im Reithosenbereich.","kw":[{"ziel":"Kaudasyndrom (MRT), einzelne Warnzeichen","sens":"19–43 %","spez":"62–88 %","basis":"Metaanalyse, 7 Studien, 569 Pat."},{"ziel":"Kaudasyndrom, Sattelanästhesie","sens":"38 %","spez":"64 %","basis":"NVL Kreuzschmerz, Anhang 1"},{"ziel":"Kaudasyndrom, beidseitige Ischialgie","sens":"63 %","spez":"72 %","basis":"NVL Kreuzschmerz, Anhang 1"},{"ziel":"Kaudasyndrom, Stuhlinkontinenz","sens":"25 %","spez":"86 %","basis":"NVL Kreuzschmerz, Anhang 1"}],"evidenz":"mäßig","quellen":["Dionne N et al. 2019, What is the diagnostic accuracy of red flags related to cauda equina syndrome (CES), when compared to MRI? A systematic review. Musculoskelet Sci Pract – https://pubmed.ncbi.nlm.nih.gov/31132655/","Bundesärztekammer, KBV, AWMF 2017, Nationale VersorgungsLeitlinie Nicht-spezifischer Kreuzschmerz, 2. Auflage, Tabelle Warnhinweise und Anhang 1 – https://www.leitlinien.de/themen/kreuzschmerz"],"neu":true},"trochanterpalpation":{"name":"Palpation Trochanter major","was":"Gluteale Tendinopathie (Ausschluss)","einheit":"positiv oder negativ","kurz":"Druck auf die Sehnenansätze am Trochanter major und nach bekanntem Schmerz fragen.","ziel":"Gluteale Tendinopathie bei lateralem Hüftschmerz wahrscheinlich machen oder ausschließen helfen.","position":"Seitlage","durch":"Seitlage, betroffene Seite oben. Der Therapeut palpiert mit festem Druck die Ansätze von M. gluteus medius und minimus an den Facetten des Trochanter major (vorn, lateral, hinten oben). Gefragt wird nach dem bekannten Schmerz und seiner Stärke.","norm":["Positiv bei bekanntem Schmerz über 2/10 bei Palpation der Sehnenansätze am Trochanter major.","Sens. 80 %, Spez. 47 %, LR- 0,43 gegen MRT (Grimaldi 2017, 65 Pat.). Fehlender Druckschmerz macht eine gluteale Tendinopathie unwahrscheinlich.","Allein zu unspezifisch; zur Bestätigung mit Einbeinstand 30 s oder FADER-R kombinieren."],"pos":"Positiv, wenn der Druck auf die Sehnenansätze am Trochanter den bekannten Schmerz über 2/10 auslöst.","kw":[{"ziel":"Gluteale Tendinopathie (MRT)","sens":"80 %","spez":"47 %","lrp":"1,5","lrn":"0,43","basis":"Einzelstudie, 65 Pat.; LR+ berechnet"}],"evidenz":"mäßig","quellen":["Grimaldi A et al. 2017, Utility of clinical tests to diagnose MRI-confirmed gluteal tendinopathy in patients presenting with lateral hip pain. Br J Sports Med – https://pubmed.ncbi.nlm.nih.gov/27633027/"],"neu":true},"adduktionpassiv":{"name":"Passive Hüftadduktion eingeschränkt","was":"Hüftarthrose","einheit":"positiv oder negativ","kurz":"Passive Adduktion der Hüfte in Rückenlage messen oder mit der Gegenseite vergleichen.","ziel":"Hüftarthrose wahrscheinlich machen oder bei normaler Adduktion ausschließen helfen.","position":"Rückenlage","durch":"Rückenlage, Becken fixiert. Der Therapeut führt das gestreckte Bein passiv in Adduktion bis zum Bewegungsende und misst mit dem Goniometer oder vergleicht mit der Gegenseite. Dabei auch nach Leistenschmerz fragen.","norm":["Positiv bei verminderter passiver Adduktion, gemessen oder im Seitenvergleich.","Sens. 80 %, Spez. 81 %, LR+ 4,2; normale Adduktion LR- 0,25 (Metcalfe 2019, JAMA, 6 Studien).","Leistenschmerz bei passiver Ab- oder Adduktion: Sens. 33 %, Spez. 94 %, LR+ 5,7."],"pos":"Positiv, wenn die passive Adduktion im Vergleich zur Gegenseite oder gemessen vermindert ist.","kw":[{"ziel":"Radiologische Hüftarthrose","sens":"80 %","spez":"81 %","lrp":"4,2","lrn":"0,25","basis":"Systematische Übersicht, 6 Studien, 1110 Pat."},{"ziel":"Radiologische Hüftarthrose, Leistenschmerz bei passiver Ab- oder Adduktion","sens":"33 %","spez":"94 %","lrp":"5,7","basis":"Systematische Übersicht"}],"evidenz":"mäßig","quellen":["Metcalfe D et al. 2019, Does this patient have hip osteoarthritis? The Rational Clinical Examination systematic review. JAMA – https://pubmed.ncbi.nlm.nih.gov/31846019/"],"neu":true},"tinetti":{"name":"Tinetti-Test (POMA)","was":"Gleichgewicht und Gang","einheit":"Punkte von 28","kurz":"Beobachtung von Gleichgewichtsaufgaben im Sitzen und Stehen und des Gangbilds, getrennt in Gleichgewichts- und Gangteil.","ziel":"Mobilität und Gangsicherheit älterer oder neurologischer Patienten einschätzen und im Verlauf vergleichen.","position":"Stand","durch":"Gleichgewichtsteil: unter anderem Sitzen, Aufstehen, Stehen, Stoß gegen das Brustbein, Augen schließen, Drehung um 360° und Hinsetzen. Gangteil: Gehen auf einer Strecke von etwa 4,5 m mit Beurteilung von Gangbeginn, Schrittlänge und -höhe, Symmetrie, Gangspur und Rumpf. Material: Stuhl ohne Armlehnen, Stoppuhr. Dauer 10 bis 15 Minuten.","norm":["Höchstwert 28 (Gleichgewicht 16, Gang 12), höher = besser.","Echte Veränderung beim Einzelnen ab 5 Punkten (Faber 2006), nach Schlaganfall ab 6 Punkten (Canbek 2013).","Als alleiniger Sturzprädiktor ungenau: Sens und Spez 62 bis 66 % (Faber 2006)."],"pos":"Auffällig, wenn der Wert im Verlauf um mindestens 5 Punkte sinkt oder deutlich unter dem Höchstwert liegt.","mess":{"reliab":"Ältere Interrater und Test-Retest R 0,74 bis 0,93 (Faber 2006); Schlaganfall Test-Retest ICC 0,84 (Canbek 2013)","mdc":"5 Punkte Einzelperson, 0,8 Punkte Gruppe (Faber 2006); 6 Punkte nach Schlaganfall (Canbek 2013)","grenzwert":"Sturzvorhersage auch mit optimalen Grenzwerten nur Sens und Spez 62,5 bis 66,1 % (Faber 2006)"},"evidenz":"stark","quellen":["Tinetti ME 1986, Performance-oriented assessment of mobility problems in elderly patients. J Am Geriatr Soc – https://pubmed.ncbi.nlm.nih.gov/3944402/","Faber MJ et al. 2006, Clinimetric properties of the performance-oriented mobility assessment. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/16813475/","Canbek J et al. 2013, Test-retest reliability and construct validity of the Tinetti POMA in people with stroke. J Neurol Phys Ther – https://pubmed.ncbi.nlm.nih.gov/23389388/","Shirley Ryan AbilityLab, RehabMeasures: Tinetti Performance Oriented Mobility Assessment (Zusatz, Aufbau 16/12) – https://www.sralab.org/rehabilitation-measures/tinetti-performance-oriented-mobility-assessment"],"neu":true},"barthel":{"name":"Barthel-Index","was":"Selbstständigkeit im Alltag","einheit":"Punkte von 100","kurz":"Zehn Alltagsbereiche wie Essen, Waschen, Anziehen, Toilette, Transfer, Gehen und Treppe werden nach Hilfebedarf bewertet.","ziel":"Selbstständigkeit in den Grundaktivitäten erfassen und den Verlauf dokumentieren.","position":"Fragebogen","durch":"Bewertung von 10 Bereichen: Essen, Baden, Körperpflege, An- und Auskleiden, Stuhlkontrolle, Harnkontrolle, Toilettenbenutzung, Bett-Stuhl-Transfer, Gehen, Treppensteigen. Einschätzung durch Beobachtung oder Befragung von Patient, Angehörigen oder Pflege. Befragung einer gut informierten Pflegekraft oder eines Angehörigen ist ähnlich zuverlässig wie Testen und schneller (Collin 1988). Es gibt eine Version mit 0 bis 20 Punkten, die Werte sind nicht direkt vergleichbar.","norm":["0 bis 100, höher = selbstständiger. In Schlaganfallstudien gelten 95 oder mehr als gutes, 60 oder weniger als schlechtes Ergebnis (Ali 2013).","Version 0 bis 20: Unterschied von 4 Punkten spricht für echte Veränderung (Collin 1988); bedeutsame Veränderung nach Schlaganfall etwa 1,85 Punkte im Gruppenmittel (Hsieh 2007)."],"pos":"Auffällig, wenn der Wert unter 95 liegt (Hilfebedarf in mindestens einem Bereich).","mess":{"reliab":"Interrater gewichtetes Kappa 0,93 nach Schlaganfall (Metaanalyse, 10 Studien, Duffy 2013)","mdc":"4 von 20 Punkten (Collin 1988)","mcid":"1,85 Punkte auf der 20-Punkte-Version, Schlaganfall (Hsieh 2007)","grenzwert":"≥ 95 gutes, ≤ 60 schlechtes Ergebnis nach 3 Monaten (Schlaganfallstudien, Ali 2013)"},"evidenz":"stark","quellen":["Mahoney FI, Barthel DW 1965, Functional evaluation: the Barthel Index. Md State Med J – https://pubmed.ncbi.nlm.nih.gov/14258950/","Duffy L et al. 2013, Reliability (inter-rater agreement) of the Barthel Index for assessment of stroke survivors: systematic review and meta-analysis. Stroke – https://pubmed.ncbi.nlm.nih.gov/23299497/","Collin C et al. 1988, The Barthel ADL Index: a reliability study. Int Disabil Stud – https://pubmed.ncbi.nlm.nih.gov/3403500/","Hsieh YW et al. 2007, Establishing the minimal clinically important difference of the Barthel Index in stroke patients. Neurorehabil Neural Repair – https://pubmed.ncbi.nlm.nih.gov/17351082/","Ali M et al. 2013, How well do standard stroke outcome measures reflect quality of life? Stroke – https://pubmed.ncbi.nlm.nih.gov/24052510/"],"neu":true},"fac":{"name":"Functional Ambulation Categories (FAC)","was":"Gehfähigkeit und Hilfebedarf beim Gehen","einheit":"Stufe 0 bis 5","kurz":"Einstufung des Gehens nach benötigter Hilfe, von nicht gehfähig bis selbstständig überall.","ziel":"Gehfähigkeit auch bei Patienten einstufen, die für Gehtests zu schwach sind, und den Verlauf dokumentieren.","position":"Stand","durch":"Der Patient geht, der Therapeut beobachtet und vergibt eine Stufe: 0 = kann nicht gehen oder braucht 2 Helfer; 1 = braucht dauernde feste Hilfe einer Person; 2 = braucht zeitweise leichte Hilfe einer Person für Gleichgewicht; 3 = braucht nur Aufsicht oder Bereitschaft ohne Berührung; 4 = selbstständig auf ebenem Boden, Hilfe bei Treppe, Rampe oder unebenem Gelände; 5 = selbstständig überall. Dauer etwa 1 Minute, kein Material nötig.","norm":["Stufe 0 bis 5, höher = selbstständiger.","Nach Schlaganfall: FAC 4 oder mehr nach 4 Wochen Reha sagt Gehen außer Haus nach 6 Monaten voraus, Sens 100 %, Spez 78 % (Mehrholz 2007)."],"pos":"Auffällig, wenn die Stufe unter 4 liegt (Hilfe oder Aufsicht beim Gehen auf ebenem Boden).","mess":{"reliab":"Test-Retest Kappa 0,95, Interrater Kappa 0,905 (Schlaganfall, videogestützt, Mehrholz 2007)","grenzwert":"FAC ≥ 4 nach 4 Wochen: Gehen außer Haus nach 6 Monaten, Sens 100 %, Spez 78 % (Mehrholz 2007)"},"evidenz":"mäßig","quellen":["Mehrholz J et al. 2007, Predictive validity and responsiveness of the functional ambulation category in hemiparetic patients after stroke. Arch Phys Med Rehabil – https://pubmed.ncbi.nlm.nih.gov/17908575/","Holden MK et al. 1984, Clinical gait assessment in the neurologically impaired. Reliability and meaningfulness. Phys Ther – https://pubmed.ncbi.nlm.nih.gov/6691052/","Shirley Ryan AbilityLab, RehabMeasures: Functional Ambulation Category (Zusatz, Stufenbeschreibung) – https://www.sralab.org/rehabilitation-measures/functional-ambulation-category"],"neu":true}},"cluster":[{"id":"kern","name":"Kernset Neurologie","gilt":"Alle neurologischen Erkrankungen","hoch":["bbs","fga","abc","t10","t6","sts5"],"empf":[],"neuro":true,"hinweis":"Sortiert nach Beleglage, oben am besten belegt. Beim Testen: Fragebogen zuerst, dann Gleichgewicht und Aufstehen, Gehtests zuletzt, den 6-Minuten-Gehtest ganz am Ende. Messen bei Aufnahme und Abschluss, bei Bedarf dazwischen. Ist ein Test nicht möglich (zum Beispiel kein Gehen), 0 dokumentieren.","quellen":["Q99"],"oquellen":["Moore JL et al. 2018, Core Set of Outcome Measures for Adults With Neurologic Conditions (J Neurol Phys Ther) – https://pmc.ncbi.nlm.nih.gov/articles/PMC6023606/"],"gruppen":[{"id":"kern_gg","name":"Gleichgewicht","tests":["bbs","fga","abc"],"hinweis":"Alle drei mit Evidenzlevel I und starker Empfehlung für akute, chronisch stabile und fortschreitende Erkrankungen (FGA bei fortschreitenden Erkrankungen moderat). Wer bei BBS oder FGA nahe der Höchstpunktzahl liegt, muss nicht erneut getestet werden."},{"id":"kern_gehen","name":"Gehen","tests":["t10","t6"],"hinweis":"Chronisch stabil und fortschreitend: Level I, starke Empfehlung (6-Minuten-Gehtest bei chronisch stabil moderat). In der Akutphase Expertenkonsens."},{"id":"kern_transfer","name":"Transfer","tests":["sts5"],"hinweis":"Expertenkonsens (Best Practice), kann bei Zielen zum Aufstehen genutzt werden."}]},{"id":"schlaganfall","name":"Schlaganfall","gilt":"Schlaganfall, Hirnblutung, Hemiparese","hoch":["t10","t6","bbs","tug","dgi","fr","abc","fmal","tis","sts5","fmao","arat","bbt","nhpt","sis","mrs","ash","tinetti","barthel","fac"],"empf":[],"neuro":true,"hinweis":"Sortiert nach Beleglage und Bedeutung für die Physiotherapie, oben am besten belegt. Die Einstufung gilt für die subakute und chronische Phase, in der Akutphase weichen einzelne Tests ab (zum Beispiel ist die Stroke Impact Scale dort nicht empfohlen). Beim Testen: Fragebogen zuerst, Gehtests zuletzt.","quellen":["Q100","Q99"],"oquellen":["Sullivan JE et al. 2013, StrokEDGE (Phys Ther 93:1383) – https://www.neuropt.org/practice-resources/anpt-outcome-measures-recommendations/stroke","Moore JL et al. 2018, Core Set of Outcome Measures for Adults With Neurologic Conditions (J Neurol Phys Ther) – https://pmc.ncbi.nlm.nih.gov/articles/PMC6023606/"],"gruppen":[{"id":"sa_gehen","name":"Gehen","tests":["t10","t6","fac"],"hinweis":"Beide stark empfohlen (StrokEDGE) und Teil des neurologischen Kernsets mit Level-I-Evidenz. Die Gehgeschwindigkeit ist der am breitesten belegte Einzelwert nach Schlaganfall. Die FAC beschreibt schnell, wie viel Hilfe beim Gehen nötig ist."},{"id":"sa_gg","name":"Gleichgewicht und Mobilität","tests":["bbs","tug","dgi","fr","abc","tinetti"],"hinweis":"BBS, TUG, Dynamic Gait Index und Functional Reach stark empfohlen, ABC empfohlen (StrokEDGE). Der Tinetti-Test ist in Deutschland verbreitet, gehört aber nicht zu den StrokEDGE-Empfehlungen."},{"id":"sa_bein","name":"Motorik Bein und Rumpf","tests":["fmal","tis","sts5"],"hinweis":"Fugl-Meyer untere Extremität stark empfohlen, Trunk Impairment Scale und 5xSTS empfohlen."},{"id":"sa_arm","name":"Arm und Hand","tests":["fmao","arat","bbt","nhpt"],"hinweis":"Alle empfohlen. Fugl-Meyer obere Extremität für die Motorik, ARAT und Box and Blocks für die Funktion, 9-Loch-Steckbrett nur bei guter Fingerfunktion."},{"id":"sa_teilhabe","name":"Alltag und Teilhabe","tests":["sis","mrs","barthel"],"hinweis":"Stroke Impact Scale stark empfohlen (nicht in der Akutphase), Modifizierte Rankin-Skala empfohlen. Der Barthel-Index ist in der deutschen Reha Standard und oft schon ärztlich oder pflegerisch erhoben."},{"id":"sa_tonus","name":"Tonus","tests":["ash"],"hinweis":"Empfohlen, aber schwächer belegt: Die (modifizierte) Ashworth-Skala ist zwischen Untersuchern nur mäßig zuverlässig."}]},{"id":"parkinson","name":"Parkinson","gilt":"Parkinson-Syndrom","hoch":["mbest","fga","tug","abc","t10","t6","fog","t360","sts5","updrs","moca","nhpt","pdq","pfs"],"empf":[],"neuro":true,"hinweis":"Sortiert nach Beleglage und Bedeutung für die Physiotherapie, oben am besten belegt. Die Empfehlung hängt vom Hoehn-und-Yahr-Stadium ab; im Stadium V bleiben vor allem MDS-UPDRS und PDQ. Beim Testen: Fragebogen und MoCA zuerst, Gehtests zuletzt.","quellen":["Q101","Q99"],"oquellen":["ANPT Parkinson Disease EDGE, Empfehlungen nach Hoehn-und-Yahr-Stadium – https://www.neuropt.org/docs/default-source/parkinson-edge/pdedge-all-documents-combined.pdf","Moore JL et al. 2018, Core Set of Outcome Measures for Adults With Neurologic Conditions (J Neurol Phys Ther) – https://pmc.ncbi.nlm.nih.gov/articles/PMC6023606/"],"gruppen":[{"id":"pk_gg","name":"Gleichgewicht und Sturzrisiko","tests":["mbest","fga","tug","abc"],"hinweis":"Mini-BESTest und FGA in den Stadien I bis IV stark empfohlen, TUG in I bis III. ABC empfohlen."},{"id":"pk_gehen","name":"Gehen, Drehen und Freezing","tests":["t10","t6","fog","t360"],"hinweis":"10-Meter- und 6-Minuten-Gehtest stark empfohlen. Freezing-Fragebogen und 360°-Drehtest empfohlen, vor allem bei Gangblockaden."},{"id":"pk_transfer","name":"Transfer","tests":["sts5"],"hinweis":"In den Stadien I bis IV stark empfohlen."},{"id":"pk_schwere","name":"Krankheitsschwere und Kognition","tests":["updrs","moca"],"hinweis":"MDS-UPDRS in allen Stadien stark empfohlen, MoCA in den Stadien I bis IV. Beide oft auch ärztlich erhoben, dann übernehmen."},{"id":"pk_hand","name":"Feinmotorik","tests":["nhpt"],"hinweis":"Insgesamt stark empfohlen, je nach Stadium empfohlen."},{"id":"pk_lq","name":"Lebensqualität und Erschöpfung","tests":["pdq","pfs"],"hinweis":"PDQ-39 oder PDQ-8 in allen Stadien stark empfohlen, Parkinson-Fatigue-Skala empfohlen."}]},{"id":"ms","name":"Multiple Sklerose","gilt":"Multiple Sklerose (Encephalomyelitis disseminata)","hoch":["t25","msws","t6","bbs","fga","abc","tug","mfis","nhpt","bbt","msis","sts5"],"empf":[],"neuro":true,"hinweis":"Sortiert nach Beleglage und Bedeutung für die Physiotherapie, oben am besten belegt. Fast alle Tests gelten bis EDSS 7,5; darüber (Rollstuhl, Bettlägerigkeit) sind sie meist nicht mehr sinnvoll. Wegen der Fatigue mit Pausen testen: Fragebogen zuerst, Gehtests zuletzt, den 6-Minuten-Gehtest nur bei ausreichender Belastbarkeit.","quellen":["Q99"],"oquellen":["Potter K et al. 2014, Outcome Measures for Individuals With Multiple Sclerosis, MS EDGE (Phys Ther 94:593) – https://academic.oup.com/ptj/article/94/5/593/2735536","APTA Test Measures, MSWS-12 – https://www.apta.org/patient-care/evidence-based-practice-resources/test-measures/12-item-multiple-sclerosis-walking-scale-msws-12","APTA Test Measures, MSIS-29 – https://www.apta.org/patient-care/evidence-based-practice-resources/test-measures/multiple-sclerosis-impact-scale-msis-29-","Shirley Ryan AbilityLab, Rehabilitation Measures Database – https://www.sralab.org/rehabilitation-measures/timed-25-foot-walk","Selecting Rehabilitation Outcome Measures for People With MS (Int J MS Care) – https://www.ijmsc.org/view/selecting-rehabilitation-outcome-measures-for-people-with-multiple-sclerosis","Moore JL et al. 2018, Core Set of Outcome Measures for Adults With Neurologic Conditions (J Neurol Phys Ther) – https://pmc.ncbi.nlm.nih.gov/articles/PMC6023606/"],"gruppen":[{"id":"ms_gehen","name":"Gehen","tests":["t25","msws","t6"],"hinweis":"T25FW und MSWS-12 laut MS EDGE in allen Settings stark empfohlen (EDSS 0 bis 7,5). 6-Minuten-Gehtest im Kernset für fortschreitende Erkrankungen mit Level I und starker Empfehlung, gut für die Gehausdauer."},{"id":"ms_gg","name":"Gleichgewicht","tests":["bbs","fga","abc","tug"],"hinweis":"BBS, FGA und ABC im Kernset mit Level-I-Evidenz. MS EDGE stuft BBS und ABC bei EDSS 0 bis 7,5 als empfohlen ein, weil Daten zur Veränderungsempfindlichkeit bei MS fehlen. TUG empfohlen."},{"id":"ms_fatigue","name":"Fatigue","tests":["mfis"],"hinweis":"MFIS empfohlen bis EDSS 7,5. Fatigue bestimmt bei MS oft, wie viel Training möglich ist."},{"id":"ms_arm","name":"Arm und Hand","tests":["nhpt","bbt"],"hinweis":"9-Loch-Steckbrett und Box and Blocks mit etwa gleich guter Beleglage. Das Steckbrett ist bei MS der Standard, Box and Blocks bei schwächerer Hand."},{"id":"ms_teilhabe","name":"Alltag und Lebensqualität","tests":["msis"],"hinweis":"MSIS-29 in allen Settings stark empfohlen, nach EDSS-Stufe empfohlen (0 bis 7,5)."},{"id":"ms_transfer","name":"Transfer","tests":["sts5"],"hinweis":"Aus dem Kernset, Expertenkonsens."}]},{"id":"o_kiefer","name":"Kiefer, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"KIEFER","ortho":true,"hoch":["oeffnungsbahn","mundoeffnung","gelenkgeraeusche","okklgeraeusche","palpkaumuskel","palpkiefergelenk"],"empf":[],"hinweis":"Erst Bewegung und Geräusche beobachten, weil das nicht provoziert, dann palpieren. Alles im Sitz; die HWS sollte bei CMD immer mit untersucht werden.","quellen":[],"oquellen":["Schiffman 2014 (DC/TMD) – https://pmc.ncbi.nlm.nih.gov/articles/PMC4884471","CMD-Kurzbefund nach Ahlers/Jakstat (ZWP 2015) – https://www.zwp-online.info/fachgebiete/kieferorthopaedie/diagnostik/cmd-screening-erkennt-untersuchungsbedarf"],"gruppen":[{"id":"kiefer_bewegung","name":"Bewegung und Geräusche (CMD-Kurzbefund)","tests":["oeffnungsbahn","mundoeffnung","gelenkgeraeusche","okklgeraeusche"],"hinweis":"Zusammen mit Muskelpalpation und dem zahnärztlichen Befund Attrition/traumatische Exzentrik bilden diese Punkte den CMD-Kurzbefund: ab 2 von 6 positiven Befunden ist eine CMD wahrscheinlich und eine Funktionsanalyse angezeigt."},{"id":"kiefer_schmerz","name":"Schmerzprovokation (DC/TMD)","tests":["palpkaumuskel","palpkiefergelenk"],"hinweis":"Bekannter Schmerz bei Muskelpalpation spricht für Myalgie, bei Gelenkpalpation für Arthralgie; beide zusammen sind häufig."}]},{"id":"o_hws","name":"HWS, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"HWS","ortho":true,"hoch":["gangbild","hoffmann","supinatorzeichen","babinski","sharppurser","flexionrotation","rotation60","spurling","distraktion","ultt","canadiancspine","kraniozervikalflexion","nackenflexorenausdauer"],"empf":[],"hinweis":"Sicherheit zuerst: nach Trauma die Canadian C-Spine Rule, dann Myelopathiezeichen und obere zervikale Instabilität vor provozierenden Tests. Danach der Wainner-Cluster, vom Sitz (Rotation, Spurling) in die Rückenlage (Distraktion, ULTT). In Rückenlage anschließend Flexions-Rotations-Test und die Tests der tiefen Nackenflexoren.","quellen":[],"oquellen":["Cook 2010 – https://www.physiotutors.com/wiki/cervical-myelopathy-cluster","Wainner 2003 – https://www.physiotutors.com/wiki/cluster-of-wainner/","Hutting 2013 – https://www.physiotutors.com/wiki/sharp-purser-test/","Ogince 2007 – https://www.physiotutors.com/wiki/flexion-rotation-test/"],"gruppen":[{"id":"hws_trauma","name":"Trauma-Screening","tests":["canadiancspine"],"hinweis":"Negativ heißt: keine Bildgebung nötig, eine relevante Verletzung ist praktisch ausgeschlossen (Sens. 99–100 %, Stiell 2001 und 2003). Bei positivem Ergebnis keine weitere Untersuchung der HWS, ärztlich abklären."},{"id":"hws_myelopathie","name":"Zervikale Myelopathie","tests":["gangbild","hoffmann","supinatorzeichen","babinski"],"hinweis":"Cluster nach Cook 2010 mit Alter über 45 als fünftem Kriterium: ab 3 von 5 positiv LR+ 30,9 (Myelopathie wahrscheinlich, ärztlich abklären); höchstens 1 von 5 positiv LR- 0,18."},{"id":"hws_obere","name":"Obere HWS","tests":["sharppurser","flexionrotation"],"hinweis":"Sharp-Purser vor jeder Mobilisation; bei positivem Befund keine weiteren Provokationstests. Flexions-Rotations-Test für zervikogenen Kopfschmerz."},{"id":"hws_radikulopathie","name":"Zervikale Radikulopathie (Wainner)","tests":["rotation60","spurling","distraktion","ultt"],"hinweis":"Wainner-Cluster: 4 von 4 positiv LR+ 30,3 (Wainner 2003), in der externen Validierung 3 von 4 positiv LR+ 7,7 (Grondin 2026). Spurling und Distraktion bestätigen eher, der ULTT A schließt eher aus; seine Sensitivität war in neueren Studien aber deutlich niedriger als die 97 % bei Wainner."},{"id":"hws_nackenflexoren","name":"Tiefe Nackenflexoren","tests":["kraniozervikalflexion","nackenflexorenausdauer"],"hinweis":"Keine Diagnosetests, sondern Messungen der Muskelfunktion für den Verlauf. Beide sind nur mäßig reliabel; kleine Veränderungen nicht überbewerten."}]},{"id":"o_bws","name":"BWS, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"BWS","ortho":true,"hoch":["faustperkussion","rueckenlagezeichen","slump","ersterippe"],"empf":[],"hinweis":"Für die BWS gibt es kaum validierte orthopädische Tests. Zuerst die Red-Flag-Tests auf Wirbelkörperfraktur (bei Osteoporose, Kortison, Trauma), danach Neurodynamik und erste Rippe.","quellen":[],"oquellen":["Langdon 2010 – https://www.physio-pedia.com/Closed_Fist_Percussion_Sign","Langdon 2010 – https://www.physiotutors.com/wiki/supine-sign/"],"gruppen":[{"id":"bws_fraktur","name":"Fraktur-Screening","tests":["faustperkussion","rueckenlagezeichen"],"hinweis":"Positive Befunde sind eine Red Flag: ärztliche Abklärung vor Behandlung (Langdon 2010)."},{"id":"bws_neural_rippe","name":"Neurodynamik und erste Rippe","tests":["slump","ersterippe"],"hinweis":"Der Slump zeigt neurale Mechanosensibilität thorakal und lumbal. Für den Test der ersten Rippe gibt es nur eine kleine Validierungsstudie ohne Kennwerte zur Genauigkeit."}]},{"id":"o_lws","name":"LWS und ISG, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"LWS","ortho":true,"hoch":["slump","slr","slrgekreuzt","femoralisdehnung","isgdistraktion","thighthrust","gaenslen","isgkompression","sakralthrust","plet","bauchlageinstab","zentralisation","caudaequina"],"empf":[],"hinweis":"Zuerst die Warnzeichen erfragen. Dann wiederholte Bewegungen im Stand oder in Bauchlage, radikuläre Tests (Slump im Sitz, dann Rückenlage), ISG-Provokation nach Laslett von Rückenlage über Seitlage zur Bauchlage und zum Schluss die Instabilitätstests in Bauchlage.","quellen":[],"oquellen":["Laslett 2005 – https://www.physiotutors.com/wiki/cluster-of-laslett/","van der Windt 2010 (Cochrane) – https://www.physiotutors.com/wiki/crossed-straight-leg-raise-test/","Kasai 2006, Ferrari 2014 – https://www.physiotutors.com/wiki/passive-lumbar-extension-test/"],"gruppen":[{"id":"lws_warnzeichen","name":"Warnzeichen (Red Flags)","tests":["caudaequina"],"hinweis":"Jeder neue Warnhinweis heißt sofort ärztlich abklären lassen. Die Zeichen sind wenig sensitiv, ein unauffälliges Screening schließt ein Kaudasyndrom also nicht aus (Dionne 2019)."},{"id":"lws_radikulaer","name":"Lumbale Radikulopathie","tests":["slump","slr","slrgekreuzt","femoralisdehnung"],"hinweis":"SLR ist sensitiv (zum Ausschließen), gekreuzter SLR spezifisch (zum Bestätigen); Femoralis-Dehnungstest für hohe Wurzeln L2-L4."},{"id":"lws_isg","name":"Iliosakralgelenk (Laslett)","tests":["isgdistraktion","thighthrust","gaenslen","isgkompression","sakralthrust"],"hinweis":"Ab 2 positiven der Tests Distraktion, Thigh Thrust, Kompression, Sacral Thrust: Sens. 88 %, Spez. 78 % (Laslett 2005). Sind Distraktion und Thigh Thrust negativ, die anderen nachprüfen; sind alle negativ, ist das ISG als Schmerzquelle unwahrscheinlich."},{"id":"lws_instabilitaet","name":"Lumbale Instabilität","tests":["plet","bauchlageinstab"],"hinweis":"Passiver lumbaler Extensionstest hat die besseren Kennwerte; der Prone Instability Test hilft eher bei der Auswahl von Stabilisationsübungen."},{"id":"lws_wiederholt","name":"Wiederholte Bewegungen","tests":["zentralisation"],"hinweis":"Zentralisation spricht für diskogenen Schmerz und eine günstige Prognose; fehlende Zentralisation schließt den Diskus nicht aus."}]},{"id":"o_schulter","name":"Schulter, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"SCHULTER","ortho":true,"hoch":["painfularc","hawkins","neer","infraspinatus","droparm","erlag","liftoff","belly","crossbody","obrien","apprehension","relocation","surprise","jobe","bearhug","speed","uppercut"],"empf":[],"hinweis":"Erst die wenig belastenden Tests im Sitz (Painful Arc, Kraft- und Lagtests, Bizepssehne, AC), dann Impingement-Provokation, zum Schluss die Instabilitätstests in Rückenlage, weil sie Angst und Schmerz auslösen können.","quellen":[],"oquellen":["Hegedus 2012 – https://upload.orthobullets.com/journalclub/free_pdf/22773322_BrJSportsMed-2012-Hegedus-bjsports-2012-091066.pdf","Park 2005 (zit. in Hospitalist-Review) – https://community.the-hospitalist.org/index.php/content/which-history-and-physical-findings-are-most-useful-identifying-rotator-cuff-tears","Chronopoulos 2004 – https://www.physiotutors.com/wiki/ac-joint-cluster/"],"gruppen":[{"id":"schulter_subakromial","name":"Subakromialer Schmerz","tests":["painfularc","hawkins","neer"],"hinweis":"Einzeln schwach (LR+ jeweils unter 2,5 nach Hegedus 2012); Hawkins und Neer sind eher zum Ausschließen geeignet."},{"id":"schulter_rm","name":"Rotatorenmanschettenruptur","tests":["infraspinatus","droparm","erlag","liftoff","belly","jobe","bearhug"],"hinweis":"Lag-Zeichen sind sehr spezifisch für komplette Rupturen: ER-Lag-Sign LR+ 28 für die isolierte komplette Supraspinatusruptur (Castoldi 2009). Bear-Hug ist der sensitivste Subscapularistest. Sind Painful Arc, Drop Arm und Schwäche in Außenrotation zusammen positiv, ist eine komplette Ruptur sehr wahrscheinlich (Park 2005)."},{"id":"schulter_ac","name":"AC-Gelenk","tests":["crossbody","obrien"],"hinweis":"Druckschmerz am AC-Gelenk plus Cross-Body und O'Brien zusammen werten. Der O'Brien-Test ist am AC-Gelenk der spezifischste (Spez. 95 %, Chronopoulos 2004); einzeln sind alle wenig sensitiv."},{"id":"schulter_instabilitaet","name":"Vordere Instabilität","tests":["apprehension","relocation","surprise"],"hinweis":"In einem Ablauf durchführen. Apprehension LR+ 17,2, Relocation LR+ 5,5, Surprise LR+ 5,4 (Hegedus 2012); Apprehension und Relocation zusammen positiv LR+ 39,7. Die drei Tests mit dem besten Nutzen an der Schulter."},{"id":"schulter_bizeps","name":"Lange Bizepssehne","tests":["speed","uppercut"],"hinweis":"Speed und Upper-Cut zusammen werten, einzeln nur mäßig genau (Kibler 2009). Für SLAP-Läsionen sind beide nicht geeignet."}]},{"id":"o_ellenbogen","name":"Ellenbogen, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"ELLENBOGEN","ortho":true,"hoch":["ellbogenstreckung","hooktest","movingvalgus","lateralpivot","cozen","mill","maudsley","medialepi","ulnarisdruck","ellbeugetest","schmerzfreiegriffkraft"],"empf":[],"hinweis":"Nach akutem Trauma zuerst den Extensionstest als Fraktur-Screening, danach die Sehnen- und Bandtests. Ohne Trauma mit den Epikondylus-Tests im Sitz beginnen und die Nerventests anschließen; der laterale Pivot-Shift als stärkste Provokation in Rückenlage zum Schluss.","quellen":[],"oquellen":["Appelboam 2008 – https://www.physiotutors.com/wiki/elbow-extension-test/","O'Driscoll 2007, Devereaux 2013 – https://www.physiotutors.com/wiki/hook-test/","O'Driscoll 2005 – https://www.physiotutors.com/wiki/moving-valgus-stress-test/","Novak 1994 – https://www.physiotutors.com/wiki/pressure-provocation-test","Soares 2023 – https://www.mdpi.com/1660-4601/20/3/1794"],"gruppen":[{"id":"ellenbogen_trauma","name":"Trauma, Bänder und Sehnen","tests":["ellbogenstreckung","hooktest","movingvalgus","lateralpivot"],"hinweis":"Volle Streckung macht eine Fraktur unwahrscheinlich (Sens. 96,8 %); Hook-Test für distale Bizepssehne, Moving-Valgus für das mediale Band."},{"id":"ellenbogen_epikondylus","name":"Epikondylopathie lateral und medial","tests":["cozen","mill","maudsley","medialepi","schmerzfreiegriffkraft"],"hinweis":"Für die Provokationstests gibt es kaum Genauigkeitsdaten; bekannter Schmerz am Epikondylus bei mehreren Tests stützt die Diagnose. Für den Verlauf eignet sich die schmerzfreie Griffkraft (JOSPT-Leitlinie 2022)."},{"id":"ellenbogen_ulnaris","name":"Kubitaltunnel (N. ulnaris)","tests":["ulnarisdruck","ellbeugetest"],"hinweis":"Druck plus volle Ellbogenbeugung war am sensitivsten (91 %, Novak 1994, Vergleich mit Gesunden). Bei echten Verdachtsfällen sind beide Tests kaum trennscharf (Beekman 2009); bei begründetem Verdacht ärztlich abklären."}]},{"id":"o_handgelenk","name":"Handgelenk und Hand, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"HANDGELENK","ortho":true,"hoch":["tabatiere","tuberculumscaphoidei","scaphoidkompression","schuettelzeichen","phalen","tinelhandgelenk","durkan","whattest","finkelstein","foveazeichen","watson","handkraftjamar","handelevation"],"empf":[],"hinweis":"Nach Sturz zuerst Skaphoid-Palpation und Kompression, vor allen Belastungstests. Danach die neurologischen Tests für den Karpaltunnel, die Sehnen- und Instabilitätstests und zum Schluss die Handkraft; alles im Sitz.","quellen":[],"oquellen":["Parvizi 1998, Chen 1989, Waeckerle 1987 (BestBETs) – https://www.bestbets.org/?p=5060","Wainner 2005 – https://www.physiotutors.com/wiki/carpal-tunnel-syndrome-cluster/","Valdes 2013 – https://www.physiotutors.com/wiki/phalens-test/","Goubau 2014 – https://www.physiotutors.com/wiki/what-test/","Tay 2007 – https://www.patientcareonline.com/view/ulnar-fovea-test-unlocks-tricky-wrist-pain-diagnosis","Golubev 2023 – https://journals.rcsi.science/0869-8678/article/view/254209"],"gruppen":[{"id":"handgelenk_skaphoid","name":"Skaphoidfraktur","tests":["tabatiere","tuberculumscaphoidei","scaphoidkompression"],"hinweis":"Alle drei negativ machen eine Skaphoidfraktur unwahrscheinlich; die Kombination erreichte Sens. 100 %, Spez. 74 % (Parvizi 1998)."},{"id":"handgelenk_kts","name":"Karpaltunnelsyndrom","tests":["schuettelzeichen","phalen","tinelhandgelenk","durkan","handelevation"],"hinweis":"Prädiktionsregel nach Wainner 2005 (Schüttelzeichen, Handgelenk-Index > 0,67, Symptom-Schweregrad > 1,9, verminderte Sensibilität Daumenkuppe, Alter > 45): 4 von 5 positiv LR+ 4,6, 5 von 5 LR+ 18,3; nicht extern validiert. Als Einzeltest am genauesten war in der Metaanalyse 2022 der Hand-Elevationstest."},{"id":"handgelenk_radial","name":"Radiales Handgelenk (de Quervain)","tests":["whattest","finkelstein"],"hinweis":"WHAT-Test sehr sensitiv (99 %) zum Ausschließen; Finkelstein zur Bestätigung."},{"id":"handgelenk_instabil","name":"Ulnare und karpale Instabilität","tests":["foveazeichen","watson"],"hinweis":"Foveazeichen für TFCC (Sens. 95 %, Spez. 87 %), Watson-Test für das skapholunäre Band; immer Seitenvergleich."},{"id":"handgelenk_kraft","name":"Kraft","tests":["handkraftjamar"],"hinweis":"Kein Diagnosetest, sondern Messung für den Verlauf. Immer gleiche Position und Griffstufe, Mittelwert aus drei Versuchen, Seitenvergleich."}]},{"id":"o_finger","name":"Finger, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"FINGER","ortho":true,"hoch":["fdptest","fdstest","elson","pipseitenband","ucldaumen","cmcgrind"],"empf":[],"hinweis":"Zu Fingertests gibt es kaum Genauigkeitsstudien; die Auswahl folgt der klinischen Praxis. Erst die Sehnenfunktion aktiv prüfen, dann Bänder und Gelenke unter Stress, weil diese Tests schmerzhafter sind.","quellen":[],"oquellen":["Model 2016 – https://www.physio-pedia.com/Thumb_CMC_Grind_Test","ALiEM 2018 – https://www.aliem.com/elsons-test/"],"gruppen":[{"id":"finger_sehnen","name":"Beuge- und Strecksehnen","tests":["fdptest","fdstest","elson"],"hinweis":"Ein negativer Test bei frischer Verletzung schließt eine Teilruptur nicht aus; bei Verdacht frühe Vorstellung beim Handchirurgen."},{"id":"finger_gelenke","name":"Bänder und Daumensattelgelenk","tests":["pipseitenband","ucldaumen","cmcgrind"],"hinweis":"Instabilität immer im Seitenvergleich werten; der Grind-Test ist spezifischer als sensitiv (Model 2016)."}]},{"id":"o_huefte","name":"Hüfte, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"HUEFTE","ortho":true,"hoch":["einbeinstand30","trendelenburg","fader","hockschmerz","hueftflexionaktiv","irpassiv","scour","hueftextensionaktiv","fadir","faber","thomas","trochanterpalpation","adduktionpassiv"],"empf":[],"hinweis":"Erst die Tests im Stand (Hocke, Einbeinstand, Trendelenburg), dann Rückenlage von wenig zu stark provozierend (aktive Flexion, Innenrotation, Scour, FADIR, FABER, FADER-R, Thomas), zuletzt aktive Extension in Bauchlage.","quellen":[],"oquellen":["Sutlive 2008 – https://www.physiotutors.com/wiki/cluster-of-sutlive/","Reiman 2015 – https://bjsm.bmj.com/content/49/6/357.full","Reiman 2015 – https://www.physiotutors.com/wiki/faddir-test/","Lequesne 2008, Grimaldi 2017 – https://www.physiotutors.com/wiki/single-leg-stance-test/","Grimaldi 2017 – https://www.physiotutors.com/wiki/fader-test/","Schneider 2020 – https://www.physiotutors.com/wiki/patricks-test/"],"gruppen":[{"id":"huefte_lateral","name":"Laterale Hüfte (gluteale Tendinopathie)","tests":["einbeinstand30","trendelenburg","fader","trochanterpalpation"],"hinweis":"Schmerz über 2/10 im Einbeinstand 30 s ist der spezifischste Test, Druckschmerz am Trochanter der sensitivste. Positive Tests stützen die Diagnose, negative schließen sie nicht aus (Grimaldi 2017)."},{"id":"huefte_arthrose","name":"Hüftarthrose (Sutlive)","tests":["hockschmerz","hueftflexionaktiv","irpassiv","scour","hueftextensionaktiv","adduktionpassiv"],"hinweis":"Sutlive-Regel: 3 von 5 positiv LR+ 5,2; 4 von 5 positiv LR+ 24,3 (sehr breites Konfidenzintervall, nicht ausreichend validiert). Eingeschränkte passive Adduktion und Innenrotation sind die besten Einzelzeichen (Metcalfe 2019)."},{"id":"huefte_leiste","name":"Leiste: FAI, Labrum, Hüftbeuger","tests":["fadir","faber","thomas"],"hinweis":"Negativer FADIR macht FAI/Labrumläsion unwahrscheinlich, ein positiver beweist sie nicht (Reiman 2015). Thomas-Test ergänzt bei Verdacht auf verkürzte oder gereizte Hüftbeuger."}]},{"id":"o_knie","name":"Knie, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"KNIE","ortho":true,"hoch":["ottawaknie","tanzendepatella","thessaly","gelenkspalt","mcmurray","valgusstress","varusstress","hinteresag","hintereschublade","lachman","leversign","schublade","pivotshift","movingpatellaapprehension","singlelegdeclinesquat"],"empf":[],"hinweis":"Nach Trauma zuerst Ottawa Knee Rules und Erguss. Im Stand Thessaly und Single Leg Decline Squat, dann Rückenlage: Meniskus, Seitenbänder, hinteres Kreuzband vor dem vorderen (ein durchhängendes Schienbein täuscht sonst eine positive vordere Schublade vor), Patella-Apprehension und zuletzt der Pivot Shift als stärkste Provokation.","quellen":[],"oquellen":["Bachmann 2004 – https://book.physiotutors.com/?p=125","Smith 2015 – https://ebm.bmj.com/content/20/3/88","van Eck 2013 – https://community.the-hospitalist.org/content/accuracy-physical-diagnostic-tests-assessing-ruptures-anterior-cruciate-ligament-meta","Rubinstein 1994 – https://ebmconsult.com/articles/physical-exam-posterior-drawer-test","Metaanalyse 2019 (zit. nach Physiotutors) – https://www.physiotutors.com/research/lever-sign-test-for-acl-tears/"],"gruppen":[{"id":"knie_trauma","name":"Trauma-Screening und Erguss","tests":["ottawaknie","tanzendepatella"],"hinweis":"Ottawa negativ schließt eine Fraktur praktisch aus (LR− 0,05, Bachmann 2004). Erguss kurz nach Trauma spricht für eine intraartikuläre Verletzung."},{"id":"knie_meniskus","name":"Meniskus","tests":["thessaly","gelenkspalt","mcmurray"],"hinweis":"Einzeln mäßig genau (Smith 2015); mehrere positive Tests plus passende Anamnese (Blockade, Verdrehtrauma) erhöhen die Wahrscheinlichkeit."},{"id":"knie_seitenbaender_hkb","name":"Seitenbänder und hinteres Kreuzband","tests":["valgusstress","varusstress","hinteresag","hintereschublade"],"hinweis":"Aufklappbarkeit in 20–30° Beugung spricht für eine isolierte Seitenbandläsion, zusätzlich in Streckung für Kapsel- oder Kreuzbandbeteiligung. Sag Sign und hintere Schublade vor den VKB-Tests prüfen; bei chronischer HKB-Ruptur erreichte die klinische Untersuchung Sens. 90 %, Spez. 99 % (Rubinstein 1994)."},{"id":"knie_vkb","name":"Vorderes Kreuzband","tests":["lachman","leversign","schublade","pivotshift"],"hinweis":"Lachman ist der beste Einzeltest (Metaanalysen Benjaminse 2006, Sokal 2022). Ein positiver Pivot Shift bestätigt (Spez. 94–98 %), im Wachzustand ist er aber oft nicht auslösbar."},{"id":"knie_patella","name":"Patella und Streckapparat","tests":["movingpatellaapprehension","singlelegdeclinesquat"],"hinweis":"Moving Patellar Apprehension für Instabilität der Patella, Single Leg Decline Squat für die Patellasehne. Der Decline Squat misst Schmerz für den Verlauf und ist kein Diagnosetest."}]},{"id":"o_osg","name":"Oberes Sprunggelenk, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"OSG","ortho":true,"hoch":["ottawafuss","lfapalpation","schubladeosg","squeeze","kleiger","raldt","taluskippung","weightbearinglunge"],"empf":[],"hinweis":"Nach Supinationstrauma zuerst Ottawa Ankle Rules, dann Palpation, dann Stabilitätstests. Die vordere Schublade ist 4–5 Tage nach dem Trauma aussagekräftiger als sofort. Syndesmosentests vor den Instabilitätstests, weil eine hohe Sprunggelenksverletzung längere Ausfallzeiten bedeutet. Ohne frisches Trauma die Dorsalextension im Weight-Bearing Lunge messen.","quellen":[],"oquellen":["Bachmann 2003 – https://www.aafp.org/pubs/afp/issues/2003/0815/p745a.html","van Dijk 1996 – https://boneandjoint.org.uk/Article/10.1302/0301-620X.78B6.0780958","van Dijk 1996, Croy 2013 – https://www.physio-pedia.com/Anterior_Drawer_of_the_Ankle","Sman 2013 – https://bjsm.bmj.com/content/47/10/620.abstract","Sman 2013 – https://www.physiotutors.com/wiki/syndesmosis-squeeze-test/","Übersicht chron. Instabilität (Li 2020, Jolman 2017) – https://aoj.amegroups.org/article/view/8912/html"],"gruppen":[{"id":"osg_akut","name":"Akutes Supinationstrauma","tests":["ottawafuss","lfapalpation","schubladeosg"],"hinweis":"Ottawa negativ: Fraktur sehr unwahrscheinlich (LR− 0,08, Bachmann 2003). Druckschmerz LFTA, Hämatom und positive Schublade nach 4–5 Tagen: Sens. 96 %, Spez. 84 % für eine Bandruptur (van Dijk 1996)."},{"id":"osg_syndesmose","name":"Syndesmose","tests":["squeeze","kleiger"],"hinweis":"Kein Einzeltest ist sicher; der Squeeze-Test ist spezifisch, aber wenig sensitiv (Sman 2015). Bei Verdacht Bildgebung."},{"id":"osg_chronisch","name":"Chronische Instabilität","tests":["raldt","taluskippung"],"hinweis":"Reverse anterolaterale Schublade hatte in einer Studie bessere Werte als die klassische Schublade (Li 2020); Talar Tilt für das Lig. calcaneofibulare."},{"id":"osg_beweglichkeit","name":"Beweglichkeit unter Belastung","tests":["weightbearinglunge"],"hinweis":"Messung für Seitenvergleich und Verlauf. Unterschiede erst ab etwa 2 cm bzw. 5° sicher über dem Messfehler (Powden 2015)."}]},{"id":"o_usg","name":"Unteres Sprunggelenk, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"USG","ortho":true,"hoch":["toomanytoes","einbeinfersenstand","jacktest","colemanblock","sinustarsi","peronealsubluxation"],"empf":[],"hinweis":"Für das untere Sprunggelenk gibt es kaum validierte Tests; die Auswahl folgt der klinischen Praxis. Zuerst Beobachtung und Funktion im Stand (Rückfußstellung, Fersenstand, Gewölbe), danach Palpation und Sehnentests im Sitz.","quellen":[],"oquellen":["Ross 2021 (Reliabilität) – https://www.physio-network.com/?p=45243","Lubcke 2019 (Review-Abstract) – https://apodc-2019.p.asnevents.com.au/days/2019-05-22/abstract/59729"],"gruppen":[{"id":"usg_tibpost","name":"Tibialis posterior und Rückfußstellung","tests":["toomanytoes","einbeinfersenstand"],"hinweis":"Fersenstand ist der am besten untersuchte Test (Ross 2021), Kennwerte zur Genauigkeit fehlen."},{"id":"usg_flexibilitaet","name":"Flexibilität des Rückfußes","tests":["jacktest","colemanblock"],"hinweis":"Jack-Test für den Plattfuß, Coleman-Block für den Hohlfuß: unterscheiden flexible von rigiden Fehlstellungen."},{"id":"usg_lateral","name":"Lateraler Rückfuß","tests":["sinustarsi","peronealsubluxation"],"hinweis":"Für beide Tests wurden keine Genauigkeitsdaten gefunden; Befund im Seitenvergleich werten."}]},{"id":"o_fuss","name":"Fuß, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"FUSS","ortho":true,"hoch":["windlass","fersenpalpation","dorsalextevers","tineltarsal","thompson","matles","achillesdelle","achillespalpation","arcsign","royallondon","heelraiseausdauer"],"empf":[],"hinweis":"Zuerst der Windlass-Test im Stand, dann Rückenlage/Seitlage für Ferse und Tarsaltunnel, zum Schluss die Achillessehnentests in Bauchlage. Bei akutem Achillestrauma die Rupturtests vorziehen.","quellen":[],"oquellen":["De Garceau 2003 – https://www.physiotutors.com/wiki/windlass-test/","Kinoshita 2001 – https://www.physiotutors.com/wiki/dorsiflexion-eversion-test/","Reiman 2014 – https://nata.kglmeridian.com/view/journals/attr/49/6/article-p820.xml"],"gruppen":[{"id":"fuss_plantarfaszie","name":"Plantarfaszie","tests":["windlass","fersenpalpation"],"hinweis":"Windlass positiv bestätigt gut (Spez. 100 %), negativ schließt nicht aus (Sens. 32 %); Diagnose stützt sich vor allem auf Palpation und Anamnese."},{"id":"fuss_tarsaltunnel","name":"Tarsaltunnel","tests":["dorsalextevers","tineltarsal"],"hinweis":"Der Dorsalextensions-Eversions-Test ist in vier kleinen Studien untersucht, Sensitivität im Median nur 62 % (Boers 2026). Negative Tests schließen ein Tarsaltunnelsyndrom nicht aus."},{"id":"fuss_achillesruptur","name":"Achillessehnenruptur","tests":["thompson","matles","achillesdelle"],"hinweis":"Thompson positiv: LR+ 13,7; negativ: LR- 0,04 (Reiman 2014). Mehrere positive Tests machen die Ruptur sehr wahrscheinlich."},{"id":"fuss_achillestendinopathie","name":"Achillestendinopathie","tests":["achillespalpation","arcsign","royallondon","heelraiseausdauer"],"hinweis":"Einzeln nur mäßig genau, nicht als alleiniges Kriterium verwenden (Reiman 2014). Der Heel-Rise-Ausdauertest misst die Belastbarkeit im Verlauf."}]},{"id":"o_zehen","name":"Zehen, orthopädische Tests","gilt":"Erscheint, wenn die Region gewählt ist.","region":"ZEHEN","ortho":true,"hoch":["papiertest","plantarplatte","fingerkompression","mulder"],"empf":[],"hinweis":"Für die Zehen gibt es nur wenige und kleine Studien. Erst der Papiertest im Stand, dann in Rückenlage Plantarplatte und Interdigitalraum; der Mulder-Klick als unangenehmster Test zuletzt.","quellen":[],"oquellen":["Pitcher 2024 – https://uhra.herts.ac.uk/id/eprint/9649/1/pitcher-et-al-2024-diagnostic-accuracy-of-subjective-features-and-physical-examination-tests-for-morton-neuroma-a.pdf","Knight (Übersicht Plantarplatte) – https://www.physio-network.com/blog/plantar-plate-injury-assessment-and-management-by-nick-knight/"],"gruppen":[{"id":"zehen_plantarplatte","name":"Plantarplatte (Kleinzehengrundgelenke)","tests":["papiertest","plantarplatte"],"hinweis":"Der vertikale Stresstest ist der aussagekräftigste klinische Test; Kennwerte stammen aus einer Einzelstudie."},{"id":"zehen_morton","name":"Morton-Neurom","tests":["fingerkompression","mulder"],"hinweis":"Negative Daumen-Zeigefinger-Kompression spricht gegen ein Neurom (Sens. 95–96 %, LR− 0,04); die Spezifität ist kaum untersucht. Der Mulder-Klick allein ist schwach (Pitcher 2024)."}]}],"ohneSpezifisch":"Für Multiple Sklerose, Polyneuropathie, Querschnittlähmung und die übrigen neurologischen Erkrankungen gilt hier nur das Kernset. Krankheitsspezifische Zusatztests habe ich nicht belegen können, weil die Original-Empfehlungen (MS-EDGE, SCI-EDGE) nicht abrufbar waren.","quellen":["Q99","Q100","Q101"],"gebiete":[{"id":"selbst","name":"Selbstbericht und Teilhabe","tests":["mrs","sis","pdq","msis","abc","msws","fog","pfs","mfis","barthel"]},{"id":"kognition","name":"Kognition","tests":["moca"]},{"id":"tonus","name":"Muskeltonus","tests":["ash"]},{"id":"motorik","name":"Motorische Funktion","tests":["updrs","fmal"]},{"id":"arm","name":"Arm und Hand","tests":["fmao","arat","bbt","nhpt"]},{"id":"rumpf","name":"Rumpfkontrolle","tests":["tis"]},{"id":"gleichgewicht","name":"Gleichgewicht","tests":["fr","bbs","mbest","tinetti"]},{"id":"transfer","name":"Aufstehen und Transfer","tests":["sts5"]},{"id":"gehen","name":"Gehen","tests":["tug","t10","t25","t360","dgi","fga","t6","fac"]},{"id":"g_kiefer_bewegung","name":"Kiefer, Bewegung und Geräusche (CMD-Kurzbefund)","tests":["oeffnungsbahn","mundoeffnung","gelenkgeraeusche","okklgeraeusche"]},{"id":"g_kiefer_schmerz","name":"Kiefer, Schmerzprovokation (DC/TMD)","tests":["palpkaumuskel","palpkiefergelenk"]},{"id":"g_hws_myelopathie","name":"HWS, Zervikale Myelopathie","tests":["gangbild","hoffmann","supinatorzeichen","babinski"]},{"id":"g_hws_obere","name":"HWS, Obere HWS","tests":["sharppurser","flexionrotation"]},{"id":"g_hws_radikulopathie","name":"HWS, Zervikale Radikulopathie (Wainner)","tests":["rotation60","spurling","distraktion","ultt"]},{"id":"g_bws_fraktur","name":"BWS, Fraktur-Screening","tests":["faustperkussion","rueckenlagezeichen"]},{"id":"g_bws_neural_rippe","name":"BWS, Neurodynamik und erste Rippe","tests":["slump","ersterippe"]},{"id":"g_lws_radikulaer","name":"LWS und ISG, Lumbale Radikulopathie","tests":["slump","slr","slrgekreuzt","femoralisdehnung"]},{"id":"g_lws_isg","name":"LWS und ISG, Iliosakralgelenk (Laslett)","tests":["isgdistraktion","thighthrust","gaenslen","isgkompression","sakralthrust"]},{"id":"g_lws_instabilitaet","name":"LWS und ISG, Lumbale Instabilität","tests":["plet","bauchlageinstab"]},{"id":"g_schulter_subakromial","name":"Schulter, Subakromialer Schmerz","tests":["painfularc","hawkins","neer"]},{"id":"g_schulter_rm","name":"Schulter, Rotatorenmanschettenruptur","tests":["infraspinatus","droparm","erlag","liftoff","belly","jobe","bearhug"]},{"id":"g_schulter_ac","name":"Schulter, AC-Gelenk","tests":["crossbody","obrien"]},{"id":"g_schulter_instabilitaet","name":"Schulter, Vordere Instabilität","tests":["apprehension","relocation","surprise"]},{"id":"g_ellenbogen_trauma","name":"Ellenbogen, Trauma, Bänder und Sehnen","tests":["ellbogenstreckung","hooktest","movingvalgus","lateralpivot"]},{"id":"g_ellenbogen_epikondylus","name":"Ellenbogen, Epikondylopathie lateral und medial","tests":["cozen","mill","maudsley","medialepi","schmerzfreiegriffkraft"]},{"id":"g_ellenbogen_ulnaris","name":"Ellenbogen, Kubitaltunnel (N. ulnaris)","tests":["ulnarisdruck","ellbeugetest"]},{"id":"g_handgelenk_skaphoid","name":"Handgelenk und Hand, Skaphoidfraktur","tests":["tabatiere","tuberculumscaphoidei","scaphoidkompression"]},{"id":"g_handgelenk_kts","name":"Handgelenk und Hand, Karpaltunnelsyndrom","tests":["schuettelzeichen","phalen","tinelhandgelenk","durkan","handelevation"]},{"id":"g_handgelenk_radial","name":"Handgelenk und Hand, Radiales Handgelenk (de Quervain)","tests":["whattest","finkelstein"]},{"id":"g_handgelenk_instabil","name":"Handgelenk und Hand, Ulnare und karpale Instabilität","tests":["foveazeichen","watson"]},{"id":"g_finger_sehnen","name":"Finger, Beuge- und Strecksehnen","tests":["fdptest","fdstest","elson"]},{"id":"g_finger_gelenke","name":"Finger, Bänder und Daumensattelgelenk","tests":["pipseitenband","ucldaumen","cmcgrind"]},{"id":"g_huefte_lateral","name":"Hüfte, Laterale Hüfte (gluteale Tendinopathie)","tests":["einbeinstand30","trendelenburg","fader","trochanterpalpation"]},{"id":"g_huefte_arthrose","name":"Hüfte, Hüftarthrose (Sutlive)","tests":["hockschmerz","hueftflexionaktiv","irpassiv","scour","hueftextensionaktiv","adduktionpassiv"]},{"id":"g_huefte_leiste","name":"Hüfte, Leiste: FAI, Labrum, Hüftbeuger","tests":["fadir","faber","thomas"]},{"id":"g_knie_trauma","name":"Knie, Trauma-Screening und Erguss","tests":["ottawaknie","tanzendepatella"]},{"id":"g_knie_meniskus","name":"Knie, Meniskus","tests":["thessaly","gelenkspalt","mcmurray"]},{"id":"g_knie_seitenbaender_hkb","name":"Knie, Seitenbänder und hinteres Kreuzband","tests":["valgusstress","varusstress","hinteresag","hintereschublade"]},{"id":"g_knie_vkb","name":"Knie, Vorderes Kreuzband","tests":["lachman","leversign","schublade","pivotshift"]},{"id":"g_osg_akut","name":"Oberes Sprunggelenk, Akutes Supinationstrauma","tests":["ottawafuss","lfapalpation","schubladeosg"]},{"id":"g_osg_syndesmose","name":"Oberes Sprunggelenk, Syndesmose","tests":["squeeze","kleiger"]},{"id":"g_osg_chronisch","name":"Oberes Sprunggelenk, Chronische Instabilität","tests":["raldt","taluskippung"]},{"id":"g_usg_tibpost","name":"Unteres Sprunggelenk, Tibialis posterior und Rückfußstellung","tests":["toomanytoes","einbeinfersenstand"]},{"id":"g_usg_flexibilitaet","name":"Unteres Sprunggelenk, Flexibilität des Rückfußes","tests":["jacktest","colemanblock"]},{"id":"g_usg_lateral","name":"Unteres Sprunggelenk, Lateraler Rückfuß","tests":["sinustarsi","peronealsubluxation"]},{"id":"g_fuss_plantarfaszie","name":"Fuß, Plantarfaszie","tests":["windlass","fersenpalpation"]},{"id":"g_fuss_tarsaltunnel","name":"Fuß, Tarsaltunnel","tests":["dorsalextevers","tineltarsal"]},{"id":"g_fuss_achillesruptur","name":"Fuß, Achillessehnenruptur","tests":["thompson","matles","achillesdelle"]},{"id":"g_fuss_achillestendinopathie","name":"Fuß, Achillestendinopathie","tests":["achillespalpation","arcsign","royallondon","heelraiseausdauer"]},{"id":"g_zehen_plantarplatte","name":"Zehen, Plantarplatte (Kleinzehengrundgelenke)","tests":["papiertest","plantarplatte"]},{"id":"g_zehen_morton","name":"Zehen, Morton-Neurom","tests":["fingerkompression","mulder"]},{"id":"g_schulter_bizeps","name":"Schulter, Lange Bizepssehne","tests":["speed","uppercut"]},{"id":"g_hws_trauma","name":"HWS, Trauma-Screening","tests":["canadiancspine"]},{"id":"g_hws_nackenflexoren","name":"HWS, Tiefe Nackenflexoren","tests":["kraniozervikalflexion","nackenflexorenausdauer"]},{"id":"g_handgelenk_kraft","name":"Handgelenk und Hand, Kraft","tests":["handkraftjamar"]},{"id":"g_knie_patella","name":"Knie, Patella und Streckapparat","tests":["movingpatellaapprehension","singlelegdeclinesquat"]},{"id":"g_osg_beweglichkeit","name":"Oberes Sprunggelenk, Beweglichkeit unter Belastung","tests":["weightbearinglunge"]},{"id":"g_lws_wiederholt","name":"LWS und ISG, Wiederholte Bewegungen","tests":["zentralisation"]},{"id":"g_lws_warnzeichen","name":"LWS und ISG, Warnzeichen (Red Flags)","tests":["caudaequina"]},{"id":"vkbreha","name":"VKB-Reha: Funktion, Sprünge, Fragebögen","tests":["pf_stroke","pf_slr","pf_sls","pf_bruecke","pf_wade","pf_stuhl","pf_seit","pf_presse","pf_keiser","pf_stand","pf_ybal","pf_hop1","pf_hop3","pf_hopx","pf_hop6","pf_side","pf_aclrsi","pf_ikdc","pf_gw","pf_grs"]}],"reihenfolgeHinweis":"Reihenfolge von ruhig zu belastend: Fragebögen und Kognition zuerst, dann Tonus und Motorik, Arm und Rumpf, im Stehen Gleichgewicht, Aufstehen, zuletzt Gehen mit dem Ausdauertest am Ende.","beschreibungHinweis":"Kurzbeschreibung und Ziel hat Claude formuliert (Entwurf). Sie sind nicht einzeln gegen die Originalquellen der Tests geprüft."};
